      skip: !currentGroupId || currentGroupId === currentBinId,
    });
  const { data: binData, isFetching: binIsFetching } = useGetBinQuery(
    currentBinId,
    { skip: !currentBinId }
  );
  const loading = binIsFetching || groupIsFetching;

  const currentBin = binData?.[0];
  const onDrop = useCallback(
    (acceptedFiles: File[]) => {
      if (loading || !currentBin?.id) return;

      dispatch(
        fileUploadStage(
          acceptedFiles.map((file) => {
            return {
              file,
              bin_id: currentBin.id,
              group_id: currentGroup?.id || currentBin.id,
            };
          })
        )
      );
    },
    [currentBin, currentGroup, loading]
  );

  const { getRootProps, getInputProps, isDragActive } = useDropzone({ onDrop });
  return (
    <Box
      data-testid="dnd-provider-box"
      sx={{
        display: "flex",
        flex: 1,
        outline: "none",
        ...sx,
      }}
      {...getRootProps({
        onClick: (evt) => evt.stopPropagation(),
        onKeyDown: (evt) => evt.stopPropagation(),
      })}
    >
      <input {...getInputProps()} />
      {isDragActive ? (
        <>
          <DropArea
            isDefaultBin={isDefaultBin}
            currentGroup={currentGroup}
            currentBin={currentBin}
            sx={dropAreaOverrides}
          />
          {children}
        </>
      ) : (
        children
      )}
    </Box>
  );
};

import { useCallback, useMemo } from "react";
import { useLocation, useHistory } from "react-router-dom";
/* 
  This hook serves to easily retrieve and add url parameters to the url.
  params: provides the current URLSearchParams object
  setParams: takes in a val and name parameter to set a new parameter (passing null as a value will remove the parameter)
*/
type UseParams = [URLSearchParams, (val: string | null, name: string) => void];
export const useParams: () => UseParams = () => {
  const history = useHistory();
  const location = useLocation();
  const params = useMemo(
    () => new URLSearchParams(location.search),
    [location.search]
  );

  const setParams = useCallback(
    (val: string | null, name: string) => {
      if (val) {
        params.set(name, val);
      } else {
        params.delete(name);
      }

      history.replace({
        pathname: location.pathname,
        search: params.toString(),
      });
    },
    [history, location.pathname, params]
  );

  return [params, setParams];
};

