const ActionColumn = ({ params }: any) => {
  const [isCopied, setIsCopied] = useState(false);

  const handleCopyClick = (data: string) => {
    navigator?.clipboard
      ?.writeText(data)
      .then(() => {
        setIsCopied(true);
        setTimeout(() => {
          setIsCopied(false);
        }, 1500);
      })
      .catch((err) => {
        console.error(err);
      });
  };

  return (
    <IconButton
      onClick={(evt: any) => {
        evt.stopPropagation();
        handleCopyClick(
          params.row.thumbnail ||
            `${window.location.host}/media/folder/${params.row.id}`
        );
      }}
    >
      {isCopied ? (
        <CheckIcon sx={{ color: "grey.400" }} />
      ) : (
        <LinkRoundedIcon sx={{ color: "grey.400" }} />
      )}
    </IconButton>
  );
};

export const MediaList: FC<Props> = ({ files, groups }) => {
  const imageEl = useRef<HTMLImageElement>();
  const [imageOrientation, setImageOrientation] = useState<string>("");
  const [lazyLoading, setLazyLoading] = useState(true);
  const [isImageError, setIsImageError] = useState(false);
  const [items, setItems] = useState([]);
  const dispatch = useDispatch();
  const selectedFiles = useSelector(
    (state: AppState) => state.mediaRevamp.selectedFiles
  );
  const isSelectDialog = useSelector(
    (state: AppState) => state.mediaRevamp.isSelectDialog
  );
  const isSelecting = isSelectDialog || selectedFiles?.length;

  const location = useLocation();
  const history = useHistory();

  useEffect(() => {
    const newGroups =
      groups?.map((group) => ({
        ...group,
        name: group.name,
        type: "folder",
      })) || [];
    const newFiles =
      files?.map((file) => ({
        ...file,
        name: file.filename,
        type: fileExtension(file.filename),
      })) || [];
    const test = [...newGroups, ...newFiles];
    setItems([...newGroups, ...newFiles]);
  }, [files, groups]);

  const columns = [
    {
      field: "name",
      headerName: "Name",
      sortable: false,
      flex: 1,
      renderCell: (params: any) => {
        return (
          <>
            {params.row.filename ? (
              <NameColumn params={params} />
            ) : (
              <Box sx={{ display: "flex", alignItems: "center" }}>
                <Box sx={{ width: "52px" }}>
                  <FolderIcon sx={{ color: "action.active" }} />
                </Box>
                <Tooltip title={params.row.name}>
                  <Typography variant="body2" sx={{ ml: 3 }}>
                    {params.row.name}
                  </Typography>
                </Tooltip>
              </Box>
            )}
          </>
        );
      },
    },
    {
      field: "created_at",
      headerName: "Added On",
      width: 200,
      sortable: false,
      renderCell: (params: any) => {
        const d = new Date(params.row.created_at);
        return (
          <Box display="flex" height="100%" alignItems="center">
            <Typography variant="body2">
              {isValid(d) && <>{format(d, "MMMM do yyyy")}</>}
            </Typography>
          </Box>
        );
      },
    },
    {
      field: "type",
      headerName: "Type",
      width: 104,
      sortable: false,
      renderCell: (params: any) => {
        return (
          <>
            <Chip
              label={params.row.type}
              sx={{
                textTransform: "uppercase",
                backgroundColor: `${fileTypeToColor(params.row.type)}.100`,
                color: `${fileTypeToColor(params.row.type)}.600`,
              }}
              size="small"
            />
          </>
        );
      },
    },
    {
      field: "action",
      headerName: "",
      width: 72,
      sortable: false,
      renderCell: (params: any) => <ActionColumn params={params} />,
    },
  ];

  return (
    <Box component="main" sx={{ height: "100%", width: "100%", px: 4 }}>
      {files && (
        <AutoSizer>
          {({ width, height }: Size) => (
            <DataGridPro
              sx={{
                backgroundColor: "common.white",
                ".MuiDataGrid-row": {
                  cursor: "pointer",
                },
                ".MuiDataGrid-columnHeaderCheckbox > *": {
                  visibility: "hidden",
                },
                border: "none",
              }}
              style={{
                width: width,
                height: height,
              }}
              columns={columns}
              rows={items}
              rowHeight={52}
              hideFooter
              disableColumnFilter
              disableColumnMenu
              checkboxSelection={Boolean(isSelecting)}
              disableRowSelectionOnClick={!isSelecting}
              isRowSelectable={(params) => params.row.type !== "folder"}
              rowSelectionModel={selectedFiles.map((file) => file.id)}
              onRowSelectionModelChange={(newSelection) => {
                const selection = new Set(newSelection);
                dispatch(clearSelectedFiles());
                items.forEach((row: any) => {
                  if (row.type !== "folder" && selection.has(row.id)) {
                    dispatch(selectFile(row));
                  }
                });
              }}
              onRowClick={(params: any) => {
                if (isSelecting && params.row.type !== "folder") {
                  return;
                }
                if (params.row.type === "folder") {
                  history.replace(`/media/folder/${params.row.id}`);
                } else {
                  const locationParams = new URLSearchParams(location.search);
                  locationParams.set("fileId", params.row.id);
                  history.replace({
                    pathname: location.pathname,
                    search: locationParams.toString(),
                  });
                }
              }}
            />
          )}
        </AutoSizer>
      )}
    </Box>
  );
};

