          loading={isCreatingGroup}
          disabled={loading || !selectedGroup || selectedGroup?.bin_id === null}
          variant="contained"
          onClick={handleCreate}
        >
          Create
        </Button>
      </DialogActions>
    </Dialog>
  );
};

