import { FC, useMemo } from "react";
import { useSelector } from "react-redux";
import { Stack, Typography, SvgIcon, Tooltip } from "@mui/material";
import { FolderGlobal } from "@zesty-io/material";
import { FolderRounded } from "@mui/icons-material";
import { useHistory } from "react-router-dom";

import { CustomBreadcrumbs } from "../../../../../shell/components/CustomBreadcrumbs";
import {
  useGetAllBinGroupsQuery,
  useGetBinsQuery,
} from "../../../../../shell/services/mediaManager";
import { Group } from "../../../../../shell/services/types";

interface Props {
  id: string;
}
export const MediaBreadcrumbs: FC<Props> = ({ id }) => {
  const history = useHistory();
  const instanceId = useSelector((state: any) => state.instance.ID);
  const ecoId = useSelector((state: any) => state.instance.ecoID);
  const { data: bins } = useGetBinsQuery({ instanceId, ecoId });
  const { data: binGroups } = useGetAllBinGroupsQuery(
    bins?.map((bin) => bin.id),
    {
      skip: !bins?.length,
    }
  );

  const crumbs = useMemo(() => {
    if (binGroups?.length) {
      const items = [];

      if (id.startsWith("1")) {
        const binFolder = bins?.find((bin) => bin.id === id);

        items.push({
          node: <Crumb id={id} name={binFolder.name} />,
          onClick: () => history.push(`/media/folder/${id}`),
        });
      } else {
        const activeFolder = binGroups.flat().find((group) => group.id === id);

        let parentFolder = activeFolder?.group_id;

        while (parentFolder) {
          const parent = parentFolder.startsWith("1")
            ? bins?.find((bin) => bin.id === parentFolder)
            : binGroups.flat().find((group) => group.id === parentFolder);

          if (parent) {
            items.unshift({
              node: <Crumb id={parent?.id} name={parent?.name} />,
              onClick: () => history.push(`/media/folder/${parent?.id}`),
            });

            parentFolder = parent?.id.startsWith("1")
              ? null
              : (parent as Group)?.group_id;
          } else {
            parentFolder = null;
          }
        }
      }

      return items;
    }

    return [];
  }, [id, binGroups]);

  return <CustomBreadcrumbs items={crumbs} />;
};

interface CrumbProps {
  id: string;
  name: string;
}
const Crumb: FC<CrumbProps> = ({ id, name }) => {
  return (
    <Tooltip title={name} placement="top" enterDelay={800} enterNextDelay={800}>
      <Stack direction="row" gap={0.5}>
        <SvgIcon
          component={id.startsWith("1") ? FolderGlobal : FolderRounded}
          fontSize="small"
          color="action"
        />
        <Typography
          variant="body2"
          color="text.secondary"
          noWrap
          maxWidth={100}
        >
          {name}
        </Typography>
      </Stack>
    </Tooltip>
  );
};

import { useEffect, useState } from "react";
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  InputLabel,
  TextField,
} from "@mui/material";
import { mediaManagerApi } from "../../../../../shell/services/mediaManager";

interface Props {
  open: boolean;
  onClose: () => void;
  name: string;
  id: string;
  groupId?: string;
}

export const RenameFolderDialog = ({
  open,
  onClose,
  name,
  id,
  groupId,
}: Props) => {
  const [newName, setNewName] = useState(name);

  const [
    updateGroup,
    { isLoading: updateGroupIsLoading, isSuccess: updateGroupIsSuccess },
  ] = mediaManagerApi.useUpdateGroupMutation();
  const [
    updateBin,
    { isLoading: updateBinIsLoading, isSuccess: updateBinIsSuccess },
  ] = mediaManagerApi.useUpdateBinMutation();

  const isLoading = updateGroupIsLoading || updateBinIsLoading;
  const isSuccess = updateGroupIsSuccess || updateBinIsSuccess;

  useEffect(() => {
    setNewName(name);
  }, [name]);

  useEffect(() => {
    if (isSuccess) onClose();
  }, [isSuccess]);

  const handleUpdate = () => {
    if (groupId) {
      updateGroup({ id, body: { name: newName, group_id: groupId } });
    } else {
      updateBin({ id, body: { name: newName } });
    }
  };

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth={"xs"}>
      <DialogTitle>Rename Folder</DialogTitle>
      <DialogContent>
        <InputLabel>New Folder Name</InputLabel>
        <TextField
          autoFocus
          onFocus={(evt) => evt.target.select()}
          value={newName}
          hiddenLabel
          size="small"
          fullWidth
          onChange={(evt) => setNewName(evt.target.value)}
          onKeyPress={(event) => event.key === "Enter" && handleUpdate()}
        />
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} color="inherit">
          Cancel
        </Button>
        <Button disabled={isLoading} variant="contained" onClick={handleUpdate}>
          Update
        </Button>
      </DialogActions>
    </Dialog>
  );
};

