import { FC, useState, useEffect } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  IconButton,
  Box,
  Typography,
} from "@mui/material";
import {
  LocalizationProvider,
  DateRangeCalendar,
  DateRange,
} from "@mui/x-date-pickers-pro";
import { AdapterDateFns } from "@mui/x-date-pickers-pro/AdapterDateFns";
import CloseIcon from "@mui/icons-material/Close";
import { format, isValid, parse } from "date-fns";

import { DateRangeFilterValue, DateFilterModalType } from "./types";

interface DateRangeFilterModal {
  date: DateRangeFilterValue;
  onClose: () => void;
  onDateChange: ({
    type,
    date,
  }: {
    type: DateFilterModalType;
    date: DateRangeFilterValue;
  }) => void;
}
export const DateRangeFilterModal: FC<DateRangeFilterModal> = ({
  date,
  onClose,
  onDateChange,
}) => {
  const [selectedDateRange, setSelectedDateRange] = useState<DateRange<Date>>([
    null,
    null,
  ]);
  const [dateRangeState, setDateRangeState] = useState("");

  useEffect(() => {
    if (date?.from && date?.to) {
      setSelectedDateRange([
        date?.from ? parse(date.from, "yyyy-MM-dd", new Date()) : null,
        date?.to ? parse(date.to, "yyyy-MM-dd", new Date()) : null,
      ]);
    }
  }, [date]);

  useEffect(() => {
    if (dateRangeState === "finish") {
      const formatted: DateRangeFilterValue = {
        from:
          selectedDateRange[0] && isValid(selectedDateRange[0])
            ? format(selectedDateRange[0], "yyyy-MM-dd")
            : null,
        to:
          selectedDateRange[1] && isValid(selectedDateRange[1])
            ? format(selectedDateRange[1], "yyyy-MM-dd")
            : null,
      };

      onDateChange({
        type: "daterange",
        date: formatted,
      });
      setDateRangeState("");
      onClose();
    }
  }, [dateRangeState]);

  return (
    <Dialog open onClose={onClose} maxWidth="md">
      <DialogTitle>
        <Box display="flex" alignItems="center" justifyContent="space-between">
          <Typography variant="h5" textTransform="capitalize" fontWeight={600}>
            Select date range...
          </Typography>
          <IconButton size="small" onClick={onClose}>
            <CloseIcon fontSize="small" />
          </IconButton>
        </Box>
      </DialogTitle>
      <DialogContent sx={{ px: 0, pb: 2.5 }}>
        <LocalizationProvider dateAdapter={AdapterDateFns}>
          <DateRangeCalendar
            disableHighlightToday
            value={selectedDateRange}
            onChange={(newValue, selectionState) => {
              setSelectedDateRange(newValue as DateRange<Date>);
              setDateRangeState(selectionState);
            }}
            data-cy="dateRange_picker"
            disableFuture
          />
        </LocalizationProvider>
      </DialogContent>
    </Dialog>
  );
};

import { Dispatch, FC, useState, useMemo } from "react";
import { Menu, MenuItem, ListItemText, Divider } from "@mui/material";
import ChevronRightOutlinedIcon from "@mui/icons-material/ChevronRightOutlined";
import { format, parse } from "date-fns";

import { FilterButton } from "../FilterButton";
import { DateFilterModal } from "./DateFilterModal";
import {
  PresetType,
  DateFilterModalType,
  DateFilterValue,
  DateRangeFilterValue,
} from "./types";
import { DateRangeFilterModal } from "./DateRangeFilterModal";

const PRESET_DATES: PresetDate[] = [
  { text: "Today", value: "today" },
  { text: "Yesterday", value: "yesterday" },
  { text: "Last 7 days", value: "last_7_days" },
  { text: "Last 14 days", value: "last_14_days" },
  { text: "Last 30 days", value: "last_30_days" },
  { text: "Last 3 months", value: "last_3_months" },
  { text: "Last 12 months", value: "last_12_months" },
];

const CUSTOM_DATES: CustomDate[] = [
  { text: "On...", value: "on" },
  { text: "Before...", value: "before" },
  { text: "After...", value: "after" },
];

const ITEM_HEIGHT = 40;

interface PresetDate {
  text: string;
  value: PresetType;
}
interface CustomDate {
  text: string;
  value: DateFilterModalType;
}
interface FilterSelectParam {
  type: "preset" | DateFilterModalType;
  value: Date | PresetType | DateRangeFilterValue;
}
interface DateFilterProps {
  value: DateFilterValue;
  onChange: (filter: DateFilterValue) => void;
  withDateRange?: boolean;
  defaultButtonText?: string;
  clearable?: boolean;
  hideCustomDates?: boolean;
  extraPresets?: PresetDate[];
}

export const DateFilter: FC<DateFilterProps> = ({
  onChange,
  value,
  withDateRange = false,
  defaultButtonText = "Date Updated",
  clearable = true,
  hideCustomDates = false,
  extraPresets = [],
}) => {
  const [calendarModalType, setCalendarModalType] =
    useState<DateFilterModalType>("");
  const [menuAnchorEl, setMenuAnchorEl] = useState<HTMLButtonElement | null>(
    null
  );
  const isFilterMenuOpen = Boolean(menuAnchorEl);

  const fmt = (yyyyMmDd: string) =>
    format(parse(yyyyMmDd, "yyyy-MM-dd", new Date()), "MMM d, yyyy");

  const activeFilterText = useMemo(() => {
    switch (value?.type) {
      case "preset": {
        const match = [...PRESET_DATES, ...extraPresets].find(
          (date) => date.value === value?.value
        );
        return match?.text;
      }
      case "on":
        return `On ${fmt(value?.value as string)}`;
      case "before":
        return `Before ${fmt(value?.value as string)}`;
      case "after":
        return `After ${fmt(value?.value as string)}`;
      case "daterange": {
        const dateRange = value?.value as DateRangeFilterValue;
        return `${fmt(dateRange?.from)} to ${fmt(dateRange?.to)}`;
      }
      default:
        return defaultButtonText;
    }
  }, [value, defaultButtonText, extraPresets]);

  const handleOpenMenuClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    setMenuAnchorEl(e.currentTarget);
  };

  const handleFilterSelect = ({ type, value }: FilterSelectParam) => {
    if (menuAnchorEl) setMenuAnchorEl(null);

    if (type === "daterange") {
      onChange({
        type,
        value: value as DateRangeFilterValue,
      });
    } else {
      onChange({
        type,
        value:
          typeof value === "object"
            ? format(value as Date, "yyyy-MM-dd")
            : value,
      });
    }
  };

  const handleOpenCalendarModal = (type: DateFilterModalType) => {
    setMenuAnchorEl(null);
    setCalendarModalType(type);
  };

  return (
    <>
      <FilterButton
        clearable={clearable}
        filterId="date"
        isFilterActive={Boolean(activeFilterText !== defaultButtonText)}
        buttonText={activeFilterText}
        onOpenMenu={handleOpenMenuClick}
        onRemoveFilter={() => {
          onChange({ type: "", value: "" });
        }}
      >
        <Menu
          data-cy="DateFilterMenu"
          open={isFilterMenuOpen}
