export const Folders = ({ lockedToGroupId }: Props) => {
  const [folderMenuAnchorEl, setFolderMenuAnchorEl] = useState(null);
  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);
  const history = useHistory();
  const location = useLocation();
  const [hiddenGroups, setHiddenGroups] = useState(
    JSON.parse(localStorage.getItem("zesty:navMedia:hidden"))
  );
  const [value, setValue] = useState(0);
  const [folderMenuData, setFolderMenuData] = useState<{
    id: string;
    groupId: string | null;
    title: string;
    binId: string | null;
  }>(null);
  const [openNewFolderDialog, setOpenNewFolderDialog] = useState(false);
  const [openDndFailedDialog, setOpenDndFailedDialog] = useState(false);
  const instanceId = useSelector((state: any) => state.instance.ID);
  const ecoId = useSelector((state: any) => state.instance.ecoID);
  const { data: bins } = useGetBinsQuery({ instanceId, ecoId });
  const [updateFile] = useUpdateFileMutation();
  const [sort, setSort] = useLocalStorage("zesty:navMedia:sort", "");
  const [hiddenExpanded, setHiddenExpanded] = useState([]);
  const [expanded, setExpanded] = useLocalStorage("zesty:navMedia:open", []);

  const openMenu = (event: MouseEvent<HTMLButtonElement>) => {
    setAnchorEl(event.currentTarget);
  };
  const closeMenu = () => {
    setAnchorEl(null);
  };

  useEffect(() => {
    const handleStorage = () =>
      setHiddenGroups(
        JSON.parse(localStorage.getItem("zesty:navMedia:hidden"))
      );

    window.addEventListener("storage", handleStorage);

    return () => {
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  const { data: binGroups, isLoading } =
    mediaManagerApi.useGetAllBinGroupsQuery(
      bins?.map((bin) => bin.id),
      {
        skip: !bins?.length,
      }
    );

  const renderActions = ({
    id,
    title,
    groupId,
    path,
    binId,
  }: {
    id: string;
    title: string;
    binId: string;
    path: string;
    groupId?: string;
  }) => {
    return [
      <IconButton
        data-cy="tree-item-hide"
        key="tree-item-hide"
        size="xxsmall"
        onClick={(e) => {
          e.stopPropagation();

          setFolderMenuAnchorEl(e.currentTarget);
          setFolderMenuData({ id, groupId, title, binId });
        }}
      >
        <MoreHorizRoundedIcon sx={{ fontSize: 16 }} />
      </IconButton>,
      <IconButtonCustom
        data-cy="tree-item-add-new-content"
        key="tree-item-add-new-content"
        variant="contained"
        size="xxsmall"
        onClick={(e) => {
          e.stopPropagation();
          history.push(`${path}?triggerUpload=true`, { from: path });
        }}
      >
        <FileUploadRoundedIcon sx={{ fontSize: 16 }} />
      </IconButtonCustom>,
    ];
  };

  const sortItems = (rawItems: TreeItemType[], sortBy: string) => {
    if (sortBy === "asc" || sortBy === "desc") {
      return rawItems.sort((a, b) => {
        if (sortBy === "asc") {
          return a.label.localeCompare(b.label);
        } else if (sortBy === "desc") {
          return b.label.localeCompare(a.label);
        }
      });
    } else {
      return rawItems
        .sort((a, b) => a.label.localeCompare(b.label))
        .sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));
    }
  };

  /**
   * It takes an array of items, an id, and a link, and returns a new array of items with the children of
   * the item with the given id nested under it
   * @param {any} items - The array of items to nest.
   * @param {string} id - The id of the group you want to nest
   * @param [link=group_id] - The name of the property that links the items together.
   */
  const nest = (
    items: Group[],
    id: string,
    link: keyof Group,
    sort: string,
    hiddenGroup: string[],
    binId: string
  ): TreeItemType[] => {
    const childItems = items
      ?.filter((item) => item[link] === id)
      ?.map((item) => ({
        icon: FolderRounded,
        children: nest(items, item.id, link, sort, hiddenGroup, binId),
        path: `/media/folder/${item.id}`,
        label: item.name,
        actions: renderActions({
          id: item.id,
          title: item.name,
          groupId: item.group_id,
          binId,
          path: `/media/folder/${item.id}`,
        }),
        hidden: hiddenGroup?.includes(item.id),
        nodeData: item,
        createdAt: item.created_at,
      }));

    return sortItems(childItems, sort);
  };

  const mappedTree: TreeItemType[] = useMemo(() => {
    if (binGroups?.length) {
      if (lockedToGroupId) {
        let rootGroup = [];
        let rootNode: Group;

        rootGroup = binGroups?.filter((groups) =>
          groups?.some((group) => group.id === lockedToGroupId)
        )?.[0];

        if (!rootGroup) return [];

        rootNode = rootGroup?.find((group) => group.id === lockedToGroupId);

        const items = [
          {
            icon: FolderRounded,
            path: `/media/folder/${rootNode?.id}`,
            label: rootNode?.name,
            actions: renderActions({
              id: rootNode?.id,
              title: rootNode?.name,
              binId: rootNode.bin_id,
              path: `/media/folder/${rootNode?.id}`,
            }),
            children: nest(
              rootGroup,
              lockedToGroupId,
              "group_id",
              sort,
              hiddenGroups,
              rootNode.bin_id
            ),
            nodeData: rootNode,
            createdAt: rootNode.created_at,
          },
        ];

        return sortItems(items, sort);
      } else {
        const items = binGroups
          .map((binGroup, idx) => {
            if (!binGroup.length) {
              return {
                icon: FolderGlobal,
                children: [],
                path: `/media/folder/${bins[idx].id}`,
                label: bins[idx].name,
                actions: renderActions({
                  id: bins[idx].id,
                  title: bins[idx].name,
                  binId: bins[idx].id,
                  path: `/media/folder/${bins[idx].id}`,
                }),
                hidden: hiddenGroups?.includes(bins[idx].id),
                nodeData: bins[idx],
                createdAt: bins[idx].created_at,
              };
            } else {
              return {
                icon: FolderGlobal,
                children: nest(
                  binGroup,
                  binGroup[0].bin_id,
                  "group_id",
                  sort,
                  hiddenGroups,
                  bins[idx].id
                ),
                path: `/media/folder/${bins[idx].id}`,
                label: bins[idx].name,
                actions: renderActions({
                  id: bins[idx].id,
                  title: bins[idx].name,
                  binId: bins[idx].id,
                  path: `/media/folder/${bins[idx].id}`,
                }),
                hidden: hiddenGroups?.includes(bins[idx].id),
                nodeData: bins[idx],
                createdAt: bins[idx].created_at,
              };
            }
          })
          .flat();

        return sortItems(items, sort);
      }
    }

    return [];
  }, [binGroups, sort, bins, hiddenGroups]);

  /* Creating a tree structure based on the hidden items. */
  const hiddenTrees: TreeItemType[] = useMemo(() => {
    if (binGroups && hiddenGroups?.length) {
      return hiddenGroups
        ?.map((id: string) => {
          let rootGroup: Group[];
          let rootNode: Group | Bin;
          let binId: string;

          if (id.startsWith("1")) {
            rootGroup = binGroups.find((group: any) => group[0].bin_id === id);
            rootNode = bins.find((bin: any) => bin.id === id);
            binId = rootNode?.id;
          } else {
            rootGroup = binGroups?.filter((groups) =>
              groups?.some((group) => group.id === id)
            )?.[0];
            rootNode = rootGroup?.find((group) => group.id === id);
            binId = rootNode?.bin_id;
          }

          if (!rootNode) return;

          return {
            icon: FolderIcon,
            path: `/media/folder/${rootNode.id}`,
            label: rootNode.name,
            actions: renderActions({
              id: rootNode?.id,
              title: rootNode?.name,
              binId,
              path: `/media/folder/${rootNode.id}`,
            }),
            children: nest(
              rootGroup,
              id,
              "group_id",
              sort,
              hiddenGroups,
              binId
            ),
            nodeData: rootNode,
          };
        })
        .filter((item: TreeItemType) => !!item);
    } else {
      return [];
    }
  }, [binGroups, hiddenGroups, sort]);

  useEffect(() => {
    // Sets ecobins open by default
    if (!!bins?.length) {
      const ecoBins = bins?.map((bin) => `/media/folder/${bin.id}`);

      if (ecoBins?.length) {
        setExpanded([...expanded, ...ecoBins]);
      }
    }
  }, [bins]);

  const handleItemDrop = useCallback((draggedItem, target) => {
    // Allow drag and drop of file when the target folder is in the same eco bin or is the actual eco bin root
    if (
      draggedItem.bin_id === target.bin_id ||
      (target.id.startsWith("1") && draggedItem.bin_id === target.id)
    ) {
      updateFile({
        id: draggedItem.id,
        previousGroupId: draggedItem.group_id,
        body: {
          group_id: target.id,
          filename: draggedItem.filename,
        },
      });
    } else {
      setOpenDndFailedDialog(true);
    }
  }, []);

  return (
    <>
      <NavTree
        id="media-main-nav"
        selected={location.pathname}
        tree={mappedTree}
        expandedItems={expanded}
        onToggleCollapse={(paths) => setExpanded(paths)}
        HeaderComponent={
          <Stack
            direction="row"
            justifyContent="space-between"
            alignItems="center"
            px={1.5}
            pb={1.5}
            sx={{
              color: "text.secondary",
            }}
          >
            <Stack direction="row" alignItems="center" gap={0.5}>
              <Typography variant="body2" textTransform="uppercase">
                Folders
              </Typography>
              <IconButton size="xxsmall" onClick={openMenu}>
                <ArrowDropDownRoundedIcon fontSize="small" />
              </IconButton>
            </Stack>
            <IconButton
              data-cy="createNewMediaFolder"
              onClick={() => setOpenNewFolderDialog(true)}
              size="xxsmall"
            >
              <AddRoundedIcon sx={{ fontSize: 16 }} />
            </IconButton>
          </Stack>
        }
        onItemDrop={handleItemDrop}
        dragAndDrop
      />
      {!lockedToGroupId && (
        <Accordion
          elevation={0}
          sx={{
            mt: 1.5,
            "&.Mui-expanded": {
              mt: 1.5,
            },
            "&:before": {
              display: "none",
            },
            "&.MuiPaper-root": {
              backgroundColor: "transparent",
              backgroundImage: "none",
            },
          }}
        >
          <AccordionSummary
            data-cy="hidden-items-accordion"
            expandIcon={<ArrowDropDownRoundedIcon fontSize="small" />}
            sx={{
              "&.MuiButtonBase-root": {
                minHeight: 20,
                mb: 1.5,
                px: 1.5,
                "&.Mui-expanded": {
                  height: 20,
                },
              },
              "& .MuiAccordionSummary-content": {
                m: 0,
                "&.Mui-expanded": {
                  m: 0,
                },
              },
              "& .MuiAccordionSummary-expandIconWrapper": {
                transform: "rotate(-90deg)",
                "&.Mui-expanded": {
                  transform: "rotate(0deg)",
                },
              },
            }}
          >
            <Typography
              variant="body2"
              textTransform="uppercase"
              color="text.secondary"
            >
              Hidden Items
            </Typography>
          </AccordionSummary>
          <AccordionDetails
            sx={{
              p: 0,
            }}
          >
            <NavTree
              id="media-hidden-nav"
              tree={hiddenTrees}
              selected={location.pathname}
              expandedItems={hiddenExpanded}
              onToggleCollapse={(paths) => setHiddenExpanded(paths)}
              dragAndDrop
              onItemDrop={(draggedItem, target) => {
                if (draggedItem.bin_id === target.bin_id) {
                  updateFile({
                    id: draggedItem.id,
                    previousGroupId: draggedItem.group_id,
                    body: {
                      group_id: target.id,
                      filename: draggedItem.filename,
                    },
                  });
                }
              }}
            />
          </AccordionDetails>
        </Accordion>
      )}

      <Menu anchorEl={anchorEl} open={open} onClose={closeMenu}>
        {SortMenuItems.map((menuItem) => (
          <MenuItem
            key={menuItem.value}
            onClick={() => {
              closeMenu();
              setSort(menuItem.value);
            }}
            selected={sort === menuItem.value}
          >
            {menuItem.label}
          </MenuItem>
        ))}
      </Menu>
      {openNewFolderDialog && (
        <NewFolderDialog open onClose={() => setOpenNewFolderDialog(false)} />
      )}
      <FolderMenu
        anchorEl={folderMenuAnchorEl}
        onCloseMenu={() => {
          setFolderMenuAnchorEl(null);
        }}
        groupId={folderMenuData?.groupId}
        id={folderMenuData?.id}
        title={folderMenuData?.title}
        binId={folderMenuData?.binId}
      />
      {openDndFailedDialog && (
        <Dialog
          open
          onClose={() => setOpenDndFailedDialog(false)}
          fullWidth
          maxWidth={"xs"}
        >
          <DialogTitle>
            <WarningAmberRoundedIcon
              color="warning"
              sx={{
                padding: "8px",
                borderRadius: "20px",
                backgroundColor: "warning.light",
                display: "block",
                mb: 2,
              }}
            />
            Cannot move file to another eco-bin
          </DialogTitle>
          <DialogContent>
            <Typography variant="body2" color="text.secondary">
              Currently Zesty lacks the ability to allow you to move files
              between eco-bins. If you desire this feature please contact
              support@zesty.io.
            </Typography>
          </DialogContent>
          <DialogActions>
            <Button
              variant="contained"
              color="primary"
              onClick={() => setOpenDndFailedDialog(false)}
            >
              Okay
            </Button>
          </DialogActions>
        </Dialog>
      )}
    </>
  );
};

import { FC, useEffect, useState, useRef } from "react";
import { ScheduleRounded, InsightsRounded } from "@mui/icons-material";
import FileUploadRoundedIcon from "@mui/icons-material/FileUploadRounded";
import { useHistory, useLocation } from "react-router";
import { useSelector } from "react-redux";
import { IconButton } from "@zesty-io/material";

import {
  AppSideBar,
  SubMenu,
} from "../../../../../../shell/components/AppSidebar";
import { UploadButton } from "../UploadButton";
import { useParams } from "../../../../../../shell/hooks/useParams";
import { useGetBinsQuery } from "../../../../../../shell/services/mediaManager";
import { AppState } from "../../../../../../shell/store/types";
import { Folders } from "./Folders";
import { Bin } from "../../../../../../shell/services/types";

interface Props {
  lockedToGroupId?: string;
  isSelectDialog?: boolean;
}
export const Sidebar: FC<Props> = ({ lockedToGroupId, isSelectDialog }) => {
  const history = useHistory();
  const [params] = useParams();
  const appSideBarRef = useRef(null);
  const term = (params as URLSearchParams).get("term");
  const clearAndFocus = (params as URLSearchParams).get("cf");
  const [searchTerm, setSearchTerm] = useState("");
  const instanceId = useSelector((state: AppState) => state.instance.ID);
  const ecoId = useSelector((state: AppState) => state.instance.ecoID);

  const { data: bins } = useGetBinsQuery({
    instanceId,
    ecoId,
  });

  useEffect(() => {
    setSearchTerm(term || "");
  }, [term]);

  useEffect(() => {
    if (clearAndFocus) {
      appSideBarRef.current?.clearAndFocusTextField();
    }
  }, [clearAndFocus]);

  const defaultBin = bins?.find((bin) => bin.default) || bins?.[0];
  const subMenu: SubMenu[] = [
    {
      name: "Recents",
      path: "/media",
      icon: ScheduleRounded,
    },
    {
      name: "Insights",
      path: "/media/insights",
      icon: InsightsRounded,
    },
  ];

  return (
    <>
      <AppSideBar
        data-cy="media-nav"
        mode="dark"
        headerTitle={isSelectDialog ? "Insert from Media" : "Media"}
        subMenus={lockedToGroupId ? null : subMenu}
        ref={appSideBarRef}
        searchPlaceholder="Search Media"
        hideSubMenuOnSearch={false}
        filterKeyword={searchTerm}
        onFilterEnter={(keyword) =>
          history.push(`/media/search?term=${keyword}`)
        }
        TitleButtonComponent={
          <TitleButton
            isSelectDialog={isSelectDialog}
            defaultBin={defaultBin}
          />
        }
      >
        <Folders lockedToGroupId={lockedToGroupId} />
      </AppSideBar>
    </>
  );
};

interface TitleButtonProps {
  isSelectDialog: boolean;
  defaultBin: Bin;
}
const TitleButton: FC<TitleButtonProps> = ({ isSelectDialog, defaultBin }) => {
  const location = useLocation();

  if (!!isSelectDialog) {
    return <></>;
  }

  // For the insights page, use the upload button that uploads items to default bin
  if (location.pathname === "/media/insights") {
    return <UploadButton currentBinId={defaultBin?.id} isIconButton />;
  }

  // When in a folder, trigger the upload media to folder button on the folder's header
  return (
    <IconButton
      data-cy="create_new_content_item"
      variant="contained"
      size="xsmall"
      onClick={() => {
        const folderUploadButton: HTMLButtonElement = document.querySelector(
          "[data-cy='fileUploadButton']"
        );

        folderUploadButton?.click();
      }}
    >
      <FileUploadRoundedIcon fontSize="small" />
    </IconButton>
  );
};

import { FC, useEffect, useState, Dispatch } from "react";
import {
  Box,
  Dialog,
  DialogContent,
  DialogTitle,
  Typography,
  TextField,
  DialogActions,
  Button,
  CircularProgress,
  InputLabel,
  Alert,
} from "@mui/material";
import { alpha } from "@mui/material/styles";

import { withCursorPosition } from "../../../../../../shell/components/withCursorPosition";

const TextFieldWithCursorPosition = withCursorPosition(TextField);

interface Props {
  handleUpdateMutation: (renamedFilename: string) => void;
  onClose?: () => void;
  onSetNewFilename: Dispatch<string>;
  newFilename: string;
  isSuccessUpdate: boolean;
  isLoadingUpdate: boolean;
  resetUpdate: any;
  extension: string;
  src: string;
}

export const RenameFileModal: FC<Props> = ({
  handleUpdateMutation,
  onClose,
  onSetNewFilename,
  newFilename,
  isSuccessUpdate,
  isLoadingUpdate,
  resetUpdate,
  extension,
  src,
}) => {
  const [renamedFilename, setRenamedFilename] = useState<string>(newFilename);

  useEffect(() => {
    if (!isLoadingUpdate && isSuccessUpdate) {
      resetUpdate();
      onClose();
    }
  }, [isLoadingUpdate, isSuccessUpdate]);

  const handleUpdate = () => {
    onSetNewFilename(renamedFilename);
    handleUpdateMutation(renamedFilename);
  };

  return (
    <Dialog open={true} fullWidth maxWidth={"xs"} onClose={onClose}>
      <DialogTitle component="div">
        <Box
          component="img"
          src={`${src}?height=120&width=120&fit=bounds`}
          width="120px"
          height="120px"
          bgcolor="grey.100"
          sx={{
            objectFit: "contain",
            borderRadius: "8px",
          }}
          mb={1.5}
        />
        <Typography variant="h5" fontWeight="700">
          Rename File
        </Typography>
      </DialogTitle>
      <DialogContent>
        <InputLabel>New File Name</InputLabel>
        <TextFieldWithCursorPosition
          sx={{
            mt: 1,
            width: "100%",
            "& .MuiInputBase-input": {
              overflow: "hidden",
              textOverflow: "ellipsis",
            },
          }}
          autoFocus
          onFocus={(evt: React.FocusEvent<HTMLInputElement>) =>
            evt.target.select()
          }
          value={renamedFilename}
          onChange={(evt: React.ChangeEvent<HTMLInputElement>) => {
            setRenamedFilename(evt.target.value.replace(" ", "-"));
          }}
          onKeyPress={(event: React.KeyboardEvent<HTMLDivElement>) =>
            event.key === "Enter" && handleUpdate()
          }
          InputProps={{
            endAdornment: (
              <Typography variant="body2" color="text.secondary">
                .{extension}
              </Typography>
            ),
          }}
        />
        <Alert
          severity="warning"
          sx={{
            mt: 2.5,
            bgcolor: (theme) => alpha(theme.palette.warning.main, 0.1),
            color: "#643a03",
            ".MuiAlert-icon": {
              color: "#643a03",
            },
          }}
        >
          This will change the URL path and could break existing links
          referenced in production after a period of time.
        </Alert>
      </DialogContent>
      <DialogActions>
        <Button color="inherit" onClick={() => onClose()}>
          Cancel
        </Button>
        <Button
          variant="contained"
          onClick={handleUpdate}
          disabled={isLoadingUpdate}
        >
          {isLoadingUpdate ? (
            <CircularProgress size="24px" color="inherit" />
          ) : (
            "Update"
          )}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default RenameFileModal;

import { FC, useEffect, useState } from "react";
import {
  Typography,
  Box,
  TextField,
  InputAdornment,
  InputLabel,
  IconButton,
  Menu,
  MenuItem,
  ListItemIcon,
  ListItemText,
  Chip,
  Button,
  Tooltip,
  CircularProgress,
  Stack,
} from "@mui/material";
import CalendarTodayIcon from "@mui/icons-material/CalendarToday";
import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import CheckIcon from "@mui/icons-material/Check";
import CloseIcon from "@mui/icons-material/Close";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import MoreHorizRoundedIcon from "@mui/icons-material/MoreHorizRounded";
import {
  useUpdateFileAltTextMutation,
  useUpdateFileMutation,
  useDeleteFileMutation,
} from "../../../../../../shell/services/mediaManager";
import { fileExtension } from "../../utils/fileUtils";
import { RenameFileModal } from "./RenameFileModal";
import { fileTypeToColor } from "../../utils/fileUtils";

import DriveFileRenameOutlineRoundedIcon from "@mui/icons-material/DriveFileRenameOutlineRounded";
import WidgetsRoundedIcon from "@mui/icons-material/WidgetsRounded";
import DriveFolderUploadRoundedIcon from "@mui/icons-material/DriveFolderUploadRounded";
import DeleteRoundedIcon from "@mui/icons-material/DeleteRounded";
import { FileReplace } from "@zesty-io/material";
import DeleteFileModal from "./DeleteFileModal";
import { MoveFileDialog } from "./MoveFileDialog";
import { useDispatch } from "react-redux";
import { notify } from "../../../../../../shell/store/notifications";
import { FetchBaseQueryError } from "@reduxjs/toolkit/dist/query";
import { format } from "date-fns";

interface Props {
  id?: string;
  src?: string;
  filename?: string;
  groupId?: string;
  binId?: string;
  title?: string;
  user?: {
    email?: string;
    role?: string;
  };
  createdAt?: string;
  updatedAt?: string;
  handleCloseModal: () => void;
  setShowEdit: (show: boolean) => void;
  onOpenReplaceFileModal: () => void;
}

export const FileModalContent: FC<Props> = ({
  id,
  binId,
  src,
  filename,
  groupId,
  title,
  user,
  createdAt,
  updatedAt,
  handleCloseModal,
  setShowEdit,
  onOpenReplaceFileModal,
}) => {
  const dispatch = useDispatch();
  const [newTitle, setNewTitle] = useState(title);
  const [isCopied, setIsCopied] = useState<boolean>(false);
  const [isCopiedZuid, setIsCopiedZuid] = useState<boolean>(false);
  const [newFilename, setNewFilename] = useState<string>(
    filename.substring(0, filename.lastIndexOf(".")) || filename
  );
  const [showRenameFileModal, setShowRenameFileModal] =
    useState<boolean>(false);
  const [showSettingsDropdown, setShowSettingsDropdown] = useState(null);
  const [showMoveFileDialog, setShowMoveFileDialog] = useState(false);
  const openSettings = Boolean(showSettingsDropdown);

  const [deleteFile, { isLoading: isLoadingDelete }] = useDeleteFileMutation();
  const [
    updateFile,
    {
      reset: resetUpdate,
      isSuccess: isSuccessUpdate,
      isLoading: isLoadingUpdate,
    },
  ] = useUpdateFileMutation();
  const [
    updateFileAltTextMutation,
    {
      reset: resetUpdateAltText,
      isSuccess: isSuccessUpdateAltText,
      isLoading: isLoadingUpdateAltText,
    },
  ] = useUpdateFileAltTextMutation();
  const [showDeleteFileModal, setShowDeleteFileModal] =
    useState<boolean>(false);

  /**
   * @description Set initial values for the fields
   */
  // useEffect(() => {
  //   if (newTitle.current) {
  //     newTitle.current.value = title;
  //   }
  //   // if (fileExtension(filename) !== "No Extension") {
  //   //   setFileType(fileExtension(filename));
  //   // }
  // }, [title, filename]);

  /**
   * @description Used for copying the alttext's value
   */
  const handleCopyClick = (data: string, isZuid = false) => {
    navigator?.clipboard
      ?.writeText(data)
      .then(() => {
        if (isZuid) {
          setIsCopiedZuid(true);
        } else {
          setIsCopied(true);
        }
        setTimeout(() => {
          if (isZuid) {
            setIsCopiedZuid(false);
          } else {
            setIsCopied(false);
          }
        }, 1500);
      })
      .catch((err) => {
        console.error(err);
      });
  };

  /**
   * @description Used to call api everytime the filename and alttext is updated
   */
  const handleUpdateMutation = (
    renamedFilename?: string,
    isAltTextUpdate?: boolean,
    newGroupId = groupId
  ) => {
    // construct file type
    let constructedFileType = "";
    if (fileExtension(filename))
      constructedFileType = `.${fileExtension(filename)}`;

    if (isAltTextUpdate) {
      updateFileAltTextMutation({
        id,
        body: {
          group_id: newGroupId,
          title: newTitle,
          filename:
            `${renamedFilename}${constructedFileType}` ||
            `${newFilename}${constructedFileType}`,
        },
      });
    } else {
      updateFile({
        id,
        previousGroupId: groupId,
        body: {
          group_id: newGroupId,
          title: newTitle,
          filename:
            `${renamedFilename}${constructedFileType}` ||
            `${newFilename}${constructedFileType}`,
        },
      });
    }
  };

  const onDeleteFile = () => {
    deleteFile({
      id,
      body: {
        group_id: groupId,
      },
    }).then((deleteResponse: any | FetchBaseQueryError) => {
      if (!deleteResponse?.error) return handleCloseModal();
      setShowDeleteFileModal(false);
      dispatch(
        notify({
          kind: "error",
          message:
            deleteResponse?.error?.data?.message || "Failed to delete file",
        })
      );
    });
    // history.replace(location.path);
  };

  useEffect(() => {
    setNewTitle(title);
    setNewFilename(
      filename.substring(0, filename.lastIndexOf(".")) || filename
    );
  }, [title, filename]);

  return (
    <Box>
      {/* Delete File Modal */}
      {showDeleteFileModal && (
        <DeleteFileModal
          onDeleteFile={onDeleteFile}
          filename={filename}
          onClose={() => setShowDeleteFileModal(false)}
          isLoadingDelete={isLoadingDelete}
        />
      )}

      {/* Rename File Modal */}
      {showRenameFileModal && (
        <RenameFileModal
          src={src}
          handleUpdateMutation={handleUpdateMutation}
          onSetNewFilename={setNewFilename}
          onClose={() => setShowRenameFileModal(false)}
          newFilename={newFilename}
          isSuccessUpdate={isSuccessUpdate}
          isLoadingUpdate={isLoadingUpdate}
          resetUpdate={resetUpdate}
          extension={fileExtension(filename)}
        />
      )}

      {showMoveFileDialog && (
        <MoveFileDialog
          handleGroupChange={(newGroupId: string) => {
            handleUpdateMutation(newFilename, false, newGroupId);
            setShowMoveFileDialog(false);
            handleCloseModal();
          }}
          binId={binId}
          onClose={() => {
            setShowMoveFileDialog(false);
          }}
        />
      )}

      {/* Content Header */}
      <Stack
        direction="row"
        p={2.5}
        borderBottom={1}
        borderColor="border"
        justifyContent="space-between"
        alignItems="flex-start"
      >
        <Stack gap={1}>
          <Tooltip title={newFilename} placement="bottom-start">
            <Box
              sx={{
                width: "235px",
              }}
            >
              <Typography variant="body1" fontWeight={700} noWrap>
                {newFilename}
              </Typography>
            </Box>
          </Tooltip>
          <Chip
            label={fileExtension(filename) || "No Extension"}
            sx={{
              textTransform: "uppercase",
              backgroundColor: `${fileTypeToColor(
                fileExtension(filename)
              )}.100`,
              color: `${fileTypeToColor(fileExtension(filename))}.600`,
              width: "fit-content",
            }}
            size="small"
          />
        </Stack>
        <Box sx={{ display: "flex", flexDirection: "row" }}>
          <Tooltip placement="bottom-start" title="More">
            <IconButton
              onClick={(evt) => setShowSettingsDropdown(evt.currentTarget)}
              aria-controls={openSettings ? "settingsMenu" : undefined}
              aria-haspopup="true"
              aria-label="Open settings menu"
              aria-expanded={openSettings ? "true" : undefined}
              size="small"
            >
              <MoreHorizRoundedIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip placement="bottom-start" title="Rename File">
            <IconButton
              size="small"
              onClick={() => setShowRenameFileModal(true)}
            >
              <EditIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip placement="bottom-start" title="Replace File">
            <IconButton
              size="small"
              aria-label="Replace File Button"
              onClick={onOpenReplaceFileModal}
            >
              <FileReplace fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip placement="bottom-start" title="Delete File">
            <IconButton
              size="small"
              aria-label="Trash Button"
              onClick={() => setShowDeleteFileModal(true)}
            >
              <DeleteIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip placement="bottom-start" title="Close Preview">
            <IconButton
              size="small"
              onClick={() => handleCloseModal()}
              aria-label="Close Icon"
            >
              <CloseIcon fontSize="small" />
            </IconButton>
          </Tooltip>

          {/* Settings Dropdown Menu */}
          <Menu
            id="settingsMenu"
            anchorEl={showSettingsDropdown}
            open={Boolean(showSettingsDropdown)}
            onClose={() => setShowSettingsDropdown(null)}
            anchorOrigin={{
              vertical: "bottom",
              horizontal: "left",
            }}
            transformOrigin={{
              vertical: "top",
              horizontal: "left",
            }}
          >
            <MenuItem
              onClick={() => {
                setShowRenameFileModal(true);
                setShowSettingsDropdown(null);
              }}
            >
              <ListItemIcon>
                <DriveFileRenameOutlineRoundedIcon />
              </ListItemIcon>
              <ListItemText>Rename</ListItemText>
            </MenuItem>
            <MenuItem onClick={() => handleCopyClick(id, true)}>
              <ListItemIcon>
                {isCopied ? <CheckIcon /> : <WidgetsRoundedIcon />}
              </ListItemIcon>
              <ListItemText>Copy ZUID</ListItemText>
            </MenuItem>
            <MenuItem onClick={() => setShowMoveFileDialog(true)}>
              <ListItemIcon>
                <DriveFolderUploadRoundedIcon />
              </ListItemIcon>
              <ListItemText>Move to</ListItemText>
            </MenuItem>
            <MenuItem onClick={() => setShowDeleteFileModal(true)}>
              <ListItemIcon>
                <DeleteRoundedIcon />
              </ListItemIcon>
              <ListItemText>Delete</ListItemText>
            </MenuItem>
          </Menu>
        </Box>
      </Stack>

      {/* Content Form */}
      <Box sx={{ px: 2.5 }}>
        <Box sx={{ mt: 2 }}>
