interface Props {
  src: string;
  filename: string;
  updatedAt?: string;
  imageSettings?: any;
  isMediaThumbnail?: boolean;
}

export const FileTypePreview: FC<Props> = ({
  src,
  filename,
  imageSettings,
  isMediaThumbnail,
  updatedAt,
}) => {
  const theme = useTheme();
  const isLargeScreen = useMediaQuery(theme.breakpoints.up("lg"));
  const isXtraLargeScreen = useMediaQuery(theme.breakpoints.up("xl"));

  const [isImageLoading, setIsImageLoading] = useState(false);
  const [isImageError, setIsImageError] = useState(false);

  useEffect(() => {
    setIsImageLoading(true);
  }, [src, imageSettings]);

  const styledCheckerBoard = {
    backgroundImage:
      (fileExtension(filename) === "png" ||
        fileExtension(filename) === "svg") &&
      `linear-gradient(45deg, ${theme.palette.grey[100]} 25%, transparent 25%), 
      linear-gradient(135deg, ${theme.palette.grey[100]} 25%, transparent 25%),
      linear-gradient(45deg, transparent 75%, ${theme.palette.grey[100]} 75%),
      linear-gradient(135deg, transparent 75%, ${theme.palette.grey[100]} 75%)`,
  };

  const styledDocfileThumbnail = {
    overflow: "hidden",
    width: isMediaThumbnail ? "auto" : "60px",
    height: isMediaThumbnail ? "40px" : "60px",
    m: "auto",
    display: "table-cell",
    verticalAlign: "bottom",
  };

  const styledBox = {
    height: "100%",
    margin: "auto",
    boxSizing: "border-box",
    overflow: "hidden",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  };

  const genImageURL = () => {
    const defaultImageSettings = {
      width: 800,
      optimize: "high",
      // Prevents browser image cache when a certain file has been already replaced
      ...(!!updatedAt &&
        !isNaN(new Date(updatedAt).getTime()) && {
          versionHash: new Date(updatedAt).getTime(),
        }),
    };

    if (isLargeScreen) {
      defaultImageSettings.width = 1000;
    }

    if (isXtraLargeScreen) {
      defaultImageSettings.width = 1600;
    }

    if (isMediaThumbnail) {
      defaultImageSettings.width = 80;
    }

    const imageSettingsToUse = { ...defaultImageSettings, ...imageSettings };
    const params = `${Object.keys(imageSettingsToUse)
      .filter(
        (key: any) =>
          imageSettingsToUse[key] && imageSettingsToUse[key] !== "none"
      )
      .map((key: any) => `${key}=${imageSettingsToUse[key]}`)
      .join("&")}`;
    return `${src}?${params}`;
  };

  const handleImageError = () => {
    setIsImageError(true);
    setIsImageLoading(false);
  };

  switch (fileExtension(src)) {
    case "jpg":
    case "jpeg":
    case "avif":
    case "gif":
    case "webp":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            ...styledCheckerBoard,
            // py: imageOrientation === "horizontal" && 1,
            // px: imageOrientation === "vertical" && "auto",
            overflow: "hidden",
            backgroundColor:
              fileExtension(filename) !== "png" &&
              fileExtension(filename) !== "svg" &&
              "grey.100",
            height: "100%",
            m: "auto",
            backgroundSize: `25px 25px`,
            display: "flex",
            alignItems: "center",
            backgroundPosition: `0 0, 12.5px 0, 12.5px -12.5px, 0px 12.5px`,
            position: "relative",
          }}
        >
          {isImageLoading ? (
            <Stack
              position="absolute"
              top={0}
              bottom={0}
              right={0}
              left={0}
              alignItems="center"
              justifyContent="center"
            >
              <CircularProgress color="primary" />
            </Stack>
          ) : null}
          <CardMedia
            component="img"
            data-src={`${genImageURL()}`}
            image={isImageError ? fileBroken : `${genImageURL()}`}
            loading="lazy"
            onLoad={() => setIsImageLoading(false)}
            onError={handleImageError}
            sx={{
              objectFit: "contain",
              m: "auto",
              width: "inherit",
              maxHeight: "100%", // used to avoid displaying full size of extra large images
              maxWidth: "100%", // used to avoid displaying full size of extra large images
            }}
          />
        </Box>
      );
    case "png":
    case "svg":
    case "ico":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            ...styledCheckerBoard,
            p: isMediaThumbnail ? 0 : 1,
            overflow: "hidden",
            backgroundColor:
              fileExtension(filename) !== "png" &&
              fileExtension(filename) !== "svg" &&
              "grey.100",
            height: "100%",
            m: "auto",
            backgroundSize: `25px 25px`,
            display: "flex",
            alignItems: "center",
            backgroundPosition: `0 0, 12.5px 0, 12.5px -12.5px, 0px 12.5px`,
            position: "relative",
          }}
        >
          {isImageLoading ? (
            <Stack
              position="absolute"
              top={0}
              bottom={0}
              right={0}
              left={0}
              alignItems="center"
              justifyContent="center"
            >
              <CircularProgress color="primary" />
            </Stack>
          ) : null}
          <CardMedia
            component="img"
            data-src={`${genImageURL()}`}
            image={isImageError ? fileBroken : `${genImageURL()}`}
            loading="lazy"
            onError={handleImageError}
            onLoad={() => setIsImageLoading(false)}
            sx={{
              objectFit: "contain",
              m: "auto",
              width: "inherit",
              maxHeight: "100%", // used to avoid displaying full size of extra large images
              maxWidth: "100%", // used to avoid displaying full size of extra large images
            }}
          />
        </Box>
      );
    case "ots":
    case "xls":
    case "xlsx":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "green.200",
            height: "100%",
            margin: "auto",
            boxSizing: "border-box",
            overflow: "hidden",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <CardMedia
            component="img"
            data-src={excelImg}
            image={excelImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "csv":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "green.200",
            height: "100%",
            margin: "auto",
            boxSizing: "border-box",
            overflow: "hidden",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <CardMedia
            component="img"
            data-src={csvImg}
            image={csvImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "docx":
    case "doc":
    case "rtf":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "blue.50",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
            data-src={wordImg}
            image={wordImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "pdf":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "blue.50",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
            data-src={pdfImg}
            image={pdfImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "ppt":
    case "pptx":
    case "pptm":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "red.50",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
            data-src={pptImg}
            image={pptImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "aac":
    case "aiff":
    case "mid":
    case "mp3":
    case "wav":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "purple.100",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
            data-src={mpImg}
            image={mpImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "mp4":
    case "mov":
    case "avi":
    case "wmv":
    case "mkv":
    case "webm":
    case "flv":
    case "f4v":
    case "swf":
    case "avchd":
    case "html5":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "#000",
            ...styledBox,
          }}
        >
          <CardMedia
            component="video"
            controls={!isMediaThumbnail}
            // Prevents the browser cache
            src={`${src}?versionHash=${new Date(updatedAt).getTime()}`}
            sx={{
              backgroundColor: "#000",
              display: "flex",
              alignItems: "center",
              flexWrap: "wrap",
              py: 1,
            }}
          />
        </Box>
      );
    case "iso":
    case "rar":
    case "tgz":
    case "zip":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "grey.100",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
            data-src={zipImg}
            image={zipImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "ai":
    case "bmp":
    case "eps":
    case "psd":
    case "tiff":
    case "tif":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "grey.100",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
            data-src={defaultImg}
            image={defaultImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "numbers":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "green.100",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
            data-src={numberImg}
            image={numberImg}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "js":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "blue.50",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
            data-src={jsIcon}
            image={jsIcon}
            loading="lazy"
            sx={styledDocfileThumbnail}
          />
        </Box>
      );
    case "css":
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "blue.50",
            ...styledBox,
          }}
        >
          <CardMedia
            component="img"
