      );
    default:
      return (
        <Box
          data-cy="file-preview"
          sx={{
            backgroundColor: "grey.100",
            ...styledBox,
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              flexDirection: "column",
              width: "100%",
