import { useEffect, useState } from "react";
import {
  Box,
  InputLabel,
  Stack,
  TextField,
  Select,
  MenuItem,
  InputAdornment,
  IconButton,
  Alert,
  Button,
  Typography,
  Slider,
} from "@mui/material";
import ArrowBackRoundedIcon from "@mui/icons-material/ArrowBackRounded";
import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import RotateRightRoundedIcon from "@mui/icons-material/RotateRightRounded";
import { FlipHorizontal, FlipVertical } from "@zesty-io/material";
import BlurOnRoundedIcon from "@mui/icons-material/BlurOnRounded";
import InfoOutlinedIcon from "@mui/icons-material/InfoOutlined";
import CheckIcon from "@mui/icons-material/Check";
import { isEmpty, omitBy } from "lodash";

interface Props {
  url: string;
  setShowEdit: (show: boolean) => void;
  imageSettings: any;
  setImageSettings: (settings: any) => void;
}

export const OTFEditor = ({
  url,
  setShowEdit,
  imageSettings,
  setImageSettings,
}: Props) => {
  const [isCopied, setIsCopied] = useState(false);

  const newUrl = `${url}?${new URLSearchParams(
    omitBy(imageSettings, isEmpty)
  ).toString()}`;

  const handleCopyClick = (data: string) => {
    navigator?.clipboard
      ?.writeText(data)
      .then(() => {
        setIsCopied(true);
        setTimeout(() => {
          setIsCopied(false);
        }, 1500);
      })
      .catch((err) => {
        console.error(err);
      });
  };

  const handleDone = () => {
    setShowEdit(false);
    setImageSettings(null);
  };

  useEffect(() => setImageSettings({ ...imageSettings, fit: "cover" }), []);

  const handleRotate = () => {
    if (!imageSettings.orient) {
      // TODO: Refactor and find patterns
      setImageSettings({
        ...imageSettings,
        orient: "r",
      });
    } else if (imageSettings.orient === "r") {
      setImageSettings({
        ...imageSettings,
        orient: "vh",
      });
    } else if (imageSettings.orient === "vh") {
      setImageSettings({
        ...imageSettings,
        orient: "l",
      });
    } else if (imageSettings.orient === "l") {
      setImageSettings({
        ...imageSettings,
        orient: "",
      });
    } else if (imageSettings.orient === "h") {
      setImageSettings({
        ...imageSettings,
        orient: "lv",
      });
    } else if (imageSettings.orient === "lv") {
      setImageSettings({
        ...imageSettings,
        orient: "v",
      });
    } else if (imageSettings.orient === "v") {
      setImageSettings({
        ...imageSettings,
        orient: "rv",
      });
    } else if (imageSettings.orient === "rv") {
      setImageSettings({
        ...imageSettings,
        orient: "h",
      });
    }
  };

  return (
    <Box>
      <Box
        sx={{
          p: 2,
          borderBottom: (theme) => `1px solid ${theme.palette.border}`,
        }}
      >
        <Stack
          direction="row"
          justifyContent="space-between"
          alignItems="center"
        >
          <Stack direction="row" alignItems="center" gap={1}>
            <IconButton
              size="small"
              sx={{ height: "fit-content" }}
              onClick={handleDone}
            >
              <ArrowBackRoundedIcon fontSize="small" color="action" />
            </IconButton>
            <Typography variant="body1">On The Fly Image Editor</Typography>
          </Stack>
          <Button size="small" variant="contained" onClick={handleDone}>
            Done
          </Button>
        </Stack>
      </Box>
      <Stack gap={2} sx={{ p: 2 }}>
        <Box>
          <InputLabel>Fit</InputLabel>
          <Select
            fullWidth
            value={imageSettings?.fit || ""}
            onChange={(evt) =>
              setImageSettings({ ...imageSettings, fit: evt.target.value })
            }
            displayEmpty
          >
            <MenuItem value="">None</MenuItem>
            <MenuItem value="bounds">Bounds</MenuItem>
            <MenuItem value="cover">Cover</MenuItem>
            <MenuItem value="crop">Crop</MenuItem>
          </Select>
        </Box>
        <Stack direction="row" gap={2}>
          <Box width="100%">
            <InputLabel>Width</InputLabel>
            <TextField
              fullWidth
              placeholder="Auto"
              value={imageSettings?.width || ""}
              onChange={(evt) =>
                setImageSettings({ ...imageSettings, width: evt.target.value })
              }
            />
          </Box>
          <Box width="100%">
