      const admins = users
        .filter((user) => user.role?.name?.toLowerCase() === "admin")
        .sort((a, b) => a.firstName.localeCompare(b.firstName));

      return [...owners, ...admins];
    }
  }, [users]);

  return (
    <Dialog open onClose={onClose} maxWidth="xs">
      <DialogTitle>
        <ErrorRoundedIcon
          color="error"
          sx={{
            padding: 1,
            borderRadius: "20px",
            backgroundColor: "red.100",
            display: "block",
            width: "40px",
            height: "40px",
            mb: 1.5,
