      </DialogContent>
      <DialogActions>
        <Button color="primary" variant="contained" onClick={onClose}>
          Done
        </Button>
      </DialogActions>
    </Dialog>
  );
};

import { useEffect, useRef, useState } from "react";
import {
  Dialog,
  DialogActions,
