const styledModal = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  width: 1100,
  bgcolor: "background.paper",
  outline: "none",
};

interface Props {
  fileId: string;
  onSetIsFileModalError?: Dispatch<boolean>;
  currentFiles?: string[];
  onClose?: () => void;
  onFileChange?: (fileId: string) => void;
}

export const FileModal: FC<Props> = ({
  fileId,
  onSetIsFileModalError,
  currentFiles,
  onClose,
  onFileChange,
}) => {
  const history = useHistory();
  const location = useLocation();
  const { data, isLoading, isError, isFetching } = useGetFileQuery(fileId);
  const [showEdit, setShowEdit] = useState(false);
  const [showReplaceFileModal, setShowReplaceFileModal] = useState(false);
  const [fileToReplace, setFileToReplace] = useState<File | null>(null);
  const [params, setParams] = useParams();
  const [adjacentFiles, setAdjacentFiles] = useState({
    prevFile: null,
    nextFile: null,
  });

  const [imageSettings, setImageSettings] = useState<any>(null);

  const handleCloseModal = () => {
    if (onClose) {
      onClose();
    } else {
      const queryParams = new URLSearchParams(location.search);
      queryParams.delete("fileId");
      history.replace({
        search: queryParams.toString(),
      });
    }
  };

  useEffect(() => {
    if (isError && onSetIsFileModalError) {
      onSetIsFileModalError(true);
    }
  }, [isError, onSetIsFileModalError]);

  const currentIndex = currentFiles?.indexOf(fileId);

  const handleArrow = (fileId: string) => {
    if (fileId) {
      if (onFileChange) {
        onFileChange(fileId);
      } else {
        setParams(fileId, "fileId");
      }
      setShowEdit(false);
    }
  };

  useEffect(() => {
    if (currentIndex !== -1) {
      const nextFile =
        currentIndex < currentFiles?.length - 1
          ? currentFiles[currentIndex + 1]
          : undefined;

      const prevFile =
        currentIndex > 0 ? currentFiles[currentIndex - 1] : undefined;

      setAdjacentFiles({ prevFile, nextFile });
    }
  }, [currentIndex]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // This will prevent users to use arrowLeft/arrowRight functionality to
      // navigate images while they are currently on focus in a textarea/text
      // to ensure that the users won't encounter any problem navigating through text
      if (
        ["textarea", "text"].includes((event.target as HTMLInputElement)?.type)
      )
        return;

      switch (event.code) {
        case "ArrowLeft":
          setAdjacentFiles((adjacentFiles) => {
            if (adjacentFiles.prevFile) {
              if (onFileChange) {
                onFileChange(adjacentFiles.prevFile);
              } else {
                setParams(adjacentFiles.prevFile, "fileId");
              }
              setShowEdit(false);
            }
            return adjacentFiles;
          });
          break;
        case "ArrowRight":
          setAdjacentFiles((adjacentFiles) => {
            if (adjacentFiles.nextFile) {
              if (onFileChange) {
                onFileChange(adjacentFiles.nextFile);
              } else {
                setParams(adjacentFiles.nextFile, "fileId");
              }
              setShowEdit(false);
            }
            return adjacentFiles;
          });
          break;
        default:
          break;
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  if (isFetching || (!data && !isError)) {
    return (
      <Dialog
        open={true}
        PaperProps={{
          style: {
            backgroundColor: "transparent",
            boxShadow: "none",
            overflow: "hidden",
            display: "flex",
            alignItems: "center",
            textAlign: "center",
          },
        }}
      >
        <CircularProgress color="primary" />
      </Dialog>
    );
  }

  if (showReplaceFileModal) {
    return (
      <ReplaceFileModal
        originalFile={data}
        onCancel={() => setShowReplaceFileModal(false)}
        onClose={handleCloseModal}
      />
    );
  }

  if (!data) {
    return <></>;
  }

  return (
    <Dialog
      open={data?.url && !isLoading}
      fullScreen
      maxWidth={false}
      onClose={handleCloseModal}
      PaperProps={{
        sx: {
          mx: 10,
          my: 2.5,
          maxHeight: "fill-available",
          maxWidth: 3000,
          overflow: "visible",
        },
      }}
    >
      {adjacentFiles.nextFile && (
        <IconButton
          size="large"
          onClick={() => {
            handleArrow(adjacentFiles.nextFile);
          }}
          sx={{
            position: "absolute",
            right: -72,
            top: "50%",
          }}
        >
          <ArrowForwardIosRoundedIcon
            sx={{ color: "common.white", width: 35, height: 35 }}
          />
        </IconButton>
      )}
      {adjacentFiles.prevFile && (
        <Box>
          <IconButton
            size="large"
            onClick={() => {
              handleArrow(adjacentFiles.prevFile);
            }}
            sx={{
              position: "absolute",
              left: -72,
              top: "50%",
            }}
          >
            <ArrowBackIosRoundedIcon
              sx={{ color: "common.white", width: 35, height: 35 }}
            />
          </IconButton>
        </Box>
      )}
      <DialogContent
        sx={{
          display: "flex",
          justifyContent: "space-between",
          p: 0,
          overflow: "hidden",
        }}
      >
        {/* <WithLoader condition={isLoading}> */}
        <Card
          elevation={0}
          sx={{
            width: "100%",
            overflow: "hidden",
            borderRadius: "8px 0px 0px 8px",
          }}
        >
          <FileTypePreview
            src={data.url}
            filename={data.filename}
            imageSettings={imageSettings}
            updatedAt={data.updated_at}
          />
        </Card>

        <Box sx={{ minWidth: "420px", maxWidth: "420px" }}>
          {showEdit ? (
            <OTFEditor
              url={data.url}
              setShowEdit={setShowEdit}
              imageSettings={imageSettings}
              setImageSettings={setImageSettings}
            />
          ) : (
            <FileModalContent
              handleCloseModal={handleCloseModal}
              id={data.id}
              src={data.url}
              filename={data.filename}
              title={data.title}
              groupId={data.group_id}
              createdAt={data.created_at}
              updatedAt={data.updated_at}
              binId={data.bin_id}
              setShowEdit={setShowEdit}
              onOpenReplaceFileModal={() => {
                setShowReplaceFileModal(true);
              }}
            />
          )}
        </Box>
        {/* </WithLoader> */}
      </DialogContent>
    </Dialog>
  );
};

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Box, SvgIcon, IconButton, Tooltip } from "@mui/material";
import { useLocalStorage } from "react-use";
import {
  KeyboardDoubleArrowLeft,
  KeyboardDoubleArrowRight,
} from "@mui/icons-material";

type Props = {
  children: React.ReactNode;
  minWidth: number;
  maxWidth: number;
  defaultWidth: number;
  id: string;
};

export const ResizableContainer = ({
  children,
  minWidth,
  maxWidth,
  defaultWidth,
  id,
}: Props) => {
  const [isResizing, setIsResizing] = useState(false);
  const [initialPos, setInitialPos] = useState(0);
  const [initialWidth, setInitialWidth] = useState(0);
  const [isHoveringCollapseButton, setIsHoveringCollapseButton] =
    useState(false);
  const [width, setWidth] = useLocalStorage(
    `zesty:resizableContainer:${id}`,
    defaultWidth
  );
  const [collapsed, setCollapsed] = useLocalStorage(
    `zesty:collapsedContainer:${id}`,
    false
  );
  const [isTooltipOpen, setIsTooltipOpen] = useState(false);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsResizing(true);
    setInitialPos(e.clientX);
    setInitialWidth(width);
    // set cursor on the document body to handle cursor leaving the container as we resize
    document.body.style.cursor = "col-resize";
    document.body.style.userSelect = "none";
  };

  const handleMouseUp = useCallback(() => {
    setIsResizing(false);
    document.body.style.cursor = "default";
    document.body.style.userSelect = "auto";
  }, []);

  const handleMouseMove = useCallback(
    (e: MouseEvent) => {
      if (!isResizing) return;
      let newWidth = initialWidth + e.clientX - initialPos;
      if (newWidth < minWidth) {
        newWidth = minWidth;
      } else if (newWidth > maxWidth) {
        newWidth = maxWidth;
      }
      setWidth(newWidth);
    },
    [isResizing, initialPos, width, minWidth, maxWidth]
  );

  useEffect(() => {
    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("mouseup", handleMouseUp);
    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("mouseup", handleMouseUp);
    };
  }, [handleMouseMove, handleMouseUp]);

  const MemoizedChildren = useMemo(() => children, [children]);

  return (
    <Box width={collapsed ? 0 : width} position="relative">
      <Box
        overflow={collapsed ? "hidden" : "visible"}
        height="100%"
        width="inherit"
      >
        {MemoizedChildren}
      </Box>
      <Box
        sx={{
          width: "4px",
          height: "100%",
          position: "absolute",
          right: "-2px",
          top: "0",
          zIndex: "2",
          bgcolor: isResizing ? "rgba(255, 93, 10, 0.5)" : "transparent",
          "&:hover": {
            backgroundColor: "rgba(255, 93, 10, 0.5)",
            cursor: "col-resize",
          },
        }}
        onMouseDown={handleMouseDown}
        display={collapsed ? "none" : "block"}
      />
      <Tooltip
        title={collapsed ? "Expand Sidebar" : "Collapse Sidebar"}
        placement="right-start"
        enterDelay={1000}
        enterNextDelay={1000}
        open={isTooltipOpen && isHoveringCollapseButton}
        onOpen={() => setIsTooltipOpen(true)}
        onClose={() => setIsTooltipOpen(false)}
      >
        <IconButton
          data-cy="collapseAppSideBar"
          onClick={() => {
            setIsTooltipOpen(false);
            setCollapsed(!collapsed);
            setIsHoveringCollapseButton(false);
          }}
          onMouseOver={() => setIsHoveringCollapseButton(true)}
          sx={{
            borderRadius: "50%",
            borderColor: "grey.600",
            borderStyle: "solid",
            borderWidth: "1px",
            backgroundColor: "grey.900",

            width: "24px",
            height: "24px",

            position: "absolute",
            top: "32px",
            right: "-12px",
            zIndex: (theme) => theme.zIndex.appBar,

            "&:hover": {
              backgroundColor: "grey.900",

              ".MuiSvgIcon-root": {
                color: "common.white",
              },
            },
          }}
        >
          <SvgIcon
            component={
              collapsed ? KeyboardDoubleArrowRight : KeyboardDoubleArrowLeft
            }
            fontSize="small"
            sx={{
              color: "grey.500",
            }}
          />
        </IconButton>
      </Tooltip>
    </Box>
  );
};

