interface GlobalAccountMenuProps {
  open: boolean;
  anchorEl: HTMLElement;
  onClose: () => void;
  onShowDocsMenu: () => void;
}
export const GlobalAccountMenu: FC<GlobalAccountMenuProps> = ({
  open,
  anchorEl,
  onClose,
  onShowDocsMenu,
}) => {
  const user: User = useSelector((state: AppState) => state.user);
  const auth = useSelector((state: AppState) => state.auth);
  const { data: roles, isLoading: isLoadingRoles } = useGetUsersRolesQuery();

  const userRole = useMemo(() => {
    return roles?.find((role) => role.ZUID === user.ZUID)?.role?.name;
  }, [roles]);

  const dispatch = useDispatch();

  useEffect(() => {
    if (!auth.valid) {
      onClose();
    }
  }, [auth.valid]);

  const handleClickAction = ([action, location]: ClickAction) => {
    switch (action) {
      case "openUrl":
        !!location && handleOpenUrl(location);
        break;

      case "openView":
        onShowDocsMenu();
        break;

      case "openEmail":
        handleOpenUrl("mailto:support@zesty.io");
        break;

      case "logOut":
        dispatch(logout());
        break;

      default:
        break;
    }
  };

  const handleOpenUrl = (url: string) => {
    onClose();
    window.open(url, "_blank", "noopener");
  };

  return (
    <Menu
      open={open}
      anchorEl={anchorEl}
      onClose={onClose}
      PaperProps={{
        sx: {
          height: 395,
          width: 340,
        },
      }}
      MenuListProps={{
        sx: {
          pt: 0,
        },
      }}
      anchorOrigin={{
        vertical: -12,
        horizontal: "left",
      }}
      transformOrigin={{
        vertical: "bottom",
        horizontal: "left",
      }}
    >
      <Stack direction="row" gap={1.5} py={2} px={2} alignItems="center">
        <Avatar
          alt={`${user?.firstName} ${user?.lastName} Avatar`}
          src={`https://www.gravatar.com/avatar/${user?.emailHash}.jpg?&s=40`}
          sx={{
            height: 32,
            width: 32,
          }}
        />
        <Stack>
          <Typography variant="body2" fontWeight={600}>
            {user?.firstName} {user?.lastName}
          </Typography>
          <Typography variant="body2" fontWeight={600} color="text.secondary">
            {isLoadingRoles ? <Skeleton /> : userRole}
          </Typography>
        </Stack>
      </Stack>
      <Divider sx={{ mb: 1 }} />
      {MENU_ITEMS.map((menuItem, index) => (
        <MenuItem
          key={index}
          onClick={() => handleClickAction(menuItem.action)}
          data-cy={menuItem.text.replace(" ", "")}
        >
          <ListItemIcon>
            <SvgIcon component={menuItem.icon} />
          </ListItemIcon>
          <ListItemText>{menuItem.text}</ListItemText>
        </MenuItem>
      ))}
      <Divider />
      <Stack direction="row" gap={1} alignItems="center" px={2}>
        <IconButton
          size="small"
          onClick={() =>
            handleOpenUrl("https://www.youtube.com/c/Zestyio/videos")
          }
        >
          <img src={youtubeIcon} alt="youtube" />
        </IconButton>
        <IconButton
          size="small"
          onClick={() => handleOpenUrl("https://www.zesty.io/chat/")}
        >
          <img src={slackIcon} alt="slack" />
        </IconButton>
      </Stack>
    </Menu>
  );
};

