export const getContentTitle = (
  content: ContentItem,
  languages: any
): string => {
  if (isEmpty(content)) {
    return "";
  }

  const title = content?.web?.metaTitle || "Missing Meta Title";
  const langCode = languages?.find(
    (lang: any) => lang.ID === content?.meta?.langID
  )?.code;
  const langDisplay = langCode ? `(${langCode}) ` : null;

  return langDisplay ? `${langDisplay}${title}` : title;
};

export const getItemIcon = (type: ResourceType, subType?: string) => {
  let icon;

  switch (type) {
    case "content":
      icon = Create;
      break;

    case "schema":
      icon = Database as SvgIconComponent;
      break;

    case "code":
      icon = CodeRounded;
      break;

    case "media":
      if (subType === "item") {
        icon = ImageRounded;
      }

      if (subType === "folder") {
        icon = FolderRounded;
      }

      break;

    default:
      break;
  }

  return icon;
};

export const splitTextAndAccelerator = (
  source: string
): { text: string; resourceType: string | null } => {
  // Matches any string with the format `[in:TEXT HERE]`
  const acceleratorRegex = /\[in:.*?\]/g;
  // Matches anything in between `[in:` and `]`
  const resourceRegex = /(?<=\[in:).*?(?=\])/g;

  /**
   * Remove the accelerator.
   * Example: `[in:schema] Fancy yachts` -> output: Fancy yachts
   */
  const text = source.replace(acceleratorRegex, "").trim();

  /**
   * Get the resource type inside the accelerator.
   * Example: `[in:schema] Fancy yachts` -> output: schema
   */
  const resourceType = source.match(resourceRegex)?.length
    ? source.match(resourceRegex)[0]
    : null;

  return { text, resourceType };
};

export interface SearchResult {
  text: string;
  value: string;
}

export const sortMostRelevantSearch = (
  searchResults: SearchResult[],
  searchString: string
): SearchResult[] => {
  const normalize = (stringVal: string) => stringVal.replace(/^\/|\/$/g, "");

  return searchResults.sort((a, b) => {
    const normalizedSearch = normalize(searchString);
    const normalizedA = normalize(a.text);
    const normalizedB = normalize(b.text);

    // 1. Exact match (normalized)
    const isExactMatchA = normalizedA === normalizedSearch;
    const isExactMatchB = normalizedB === normalizedSearch;

    if (isExactMatchA && !isExactMatchB) return -1;
    if (!isExactMatchA && isExactMatchB) return 1;

    // 2. URLs starting with the search string
    const startsWithSearchA = normalizedA.startsWith(normalizedSearch);
    const startsWithSearchB = normalizedB.startsWith(normalizedSearch);

    if (startsWithSearchA && !startsWithSearchB) return -1;
    if (!startsWithSearchA && startsWithSearchB) return 1;

    // 3. URLs containing the search string
    const containsSearchA = normalizedA.includes(normalizedSearch);
    const containsSearchB = normalizedB.includes(normalizedSearch);

    if (containsSearchA && !containsSearchB) return -1;
    if (!containsSearchA && containsSearchB) return 1;

    // 4. Compare by nested levels (fewer segments come first)
    const nestedLevelA = a.text.split("/").filter(Boolean).length;
    const nestedLevelB = b.text.split("/").filter(Boolean).length;

    if (nestedLevelA !== nestedLevelB) return nestedLevelA - nestedLevelB;

    // 5. Alphabetical order
    return normalizedA.localeCompare(normalizedB);
  });
};

import { useState, useMemo } from "react";
import { isEmpty } from "lodash";

import { ContentModel } from "../services/types";
import { useGetContentModelsQuery } from "../services/instance";
import { useGetUsersQuery } from "../services/accounts";

const templatesetKeywords = [
  "single page model",
  "single page models",
  "singlepage model",
  "singlepage models",
];
const pagesetKeywords = [
  "multi page model",
  "multi page models",
  "multipage model",
  "multipage models",
];
const datasetKeywords = [
  "headless data",
  "headless data models",
  "headless data model",
];

interface UsersList {
  [key: string]: string;
}

/**
 * This hook is used to easily filter content models via a keyword that will
 * match the following:
 * - Model title
 * - Model ZUID
 * - Model type
 * - User ZUID
 * - User full name
 */
type UseSearchModelsByKeyword = [ContentModel[], (searchTerm: string) => void];
export const useSearchModelsByKeyword: () => UseSearchModelsByKeyword = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const { data: models } = useGetContentModelsQuery();
  const { data: users } = useGetUsersQuery();

  const allUsers: UsersList = useMemo(() => {
    let _users: UsersList = {};

    if (!isEmpty(users)) {
      users.forEach((user) => {
        const key = `${user.firstName} ${user.lastName}`.toLowerCase();

        _users = {
          ..._users,
          [key]: user.ZUID,
        };
      });
    }

    return _users;
  }, [users]);

  const filteredModels: ContentModel[] = useMemo(() => {
    let matchedUserZUID = "";
    let modelDatatype = "";
    const term = searchTerm?.toLowerCase();

    // Check if the user's keyword matches a user's full name
    if (allUsers[term]) {
      matchedUserZUID = allUsers[term];
    }

    // Check if the user's keyword is a datatype
    if (templatesetKeywords.includes(term)) {
      modelDatatype = "templateset";
    }

    if (pagesetKeywords.includes(term)) {
      modelDatatype = "pageset";
    }

    if (datasetKeywords.includes(term)) {
      modelDatatype = "dataset";
    }

    // Filter models
    if (!isEmpty(models)) {
      /**
       * Allow users to match models via the ff:
       * - Model title
       * - Model ZUID
       * - Model type
       * - User ZUID
       * - User full name
       */
      return models.filter(
        (model) =>
          model.label?.toLowerCase().includes(term) ||
          model.ZUID === term ||
          model.type === modelDatatype ||
          model.createdByUserZUID === term ||
          model.createdByUserZUID === matchedUserZUID
      );
    }

    return [];
  }, [models, searchTerm]);

  return [filteredModels, setSearchTerm];
};

import { useState, useMemo } from "react";
import { isEmpty } from "lodash";

import { WebView, Script, Stylesheet } from "../services/types";
import {
  useGetWebViewsQuery,
  useGetStylesheetsQuery,
  useGetScriptsQuery,
} from "../services/instance";

/**
 * This hook is used to easily filter code files via a keyword that matches the ff:
 * - File name
 * - File ZUID
 */
export type File = Pick<
  WebView | Script | Stylesheet,
  keyof (WebView | Script | Stylesheet)
>;
type UseSearchCodeFilesByKeywords = [File[], (searchTerm: string) => void];
export const useSearchCodeFilesByKeywords: () => UseSearchCodeFilesByKeywords =
  () => {
    const [searchTerm, setSearchTerm] = useState("");
    const { data: webViews } = useGetWebViewsQuery({ status: "dev" });
    const { data: stylesheets } = useGetStylesheetsQuery();
    const { data: scripts } = useGetScriptsQuery();

    // Create one array with all the files
    const allFiles: File[] = useMemo(() => {
      let files: File[] = [...(stylesheets ?? []), ...(scripts ?? [])];

      if (!isEmpty(webViews)) {
        const views = webViews.map(
          ({ contentModelType, contentModelZUID, customZNode, ...rest }) => {
            return rest;
          }
        );

        files = [...files, ...views];
      }

      return files;
    }, [webViews, stylesheets, scripts]);

    // Filter files based on file name
    const filteredFiles: File[] = useMemo(() => {
      const term = searchTerm?.toLowerCase();

      /**
       * Matches the ff:
       * - File name
       * - File ZUID
       */
      return allFiles?.filter(
        (file) =>
          file.fileName?.toLowerCase().includes(term) || file.ZUID === term
      );
    }, [allFiles, searchTerm]);

    return [filteredFiles, setSearchTerm];
  };

