import { FC, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { AppState } from "../../../store/types";

import { DirtyCodeModal } from "../../DirtyCodeModal";

import {
  saveFile,
  fetchFile,
} from "../../../../apps/code-editor/src/store/files";
import { unpinTab } from "../../../../shell/store/ui";
import { actions } from "../../../../shell/store/ui";

export const GlobalDirtyCodeModal: FC = () => {
  const dispatch = useDispatch();
  const [loading, setLoading] = useState(false);
  const dirtyCodeZuid = useSelector(
    (state: AppState) => state.ui.codeChangesModal?.ZUID
  );
  const dirtyCodeStatus = useSelector(
    (state: AppState) => state.ui.codeChangesModal?.status
  );
  const dirtyCodeFileType = useSelector(
    (state: AppState) => state.ui.codeChangesModal?.fileType
  );

  return (
    <DirtyCodeModal
      title="Unsaved Changes"
      content="Please save or discard your changes before unpinning this tab"
      loading={loading}
      open={Boolean(dirtyCodeZuid)}
      onDiscard={async () => {
        setLoading(true);
        await dispatch(
          fetchFile(dirtyCodeZuid, dirtyCodeFileType, {
            forceSync: true,
          })
        );
        await dispatch({
          type: "UNMARK_FILE_DIRTY",
          payload: { ZUID: dirtyCodeZuid },
        });
        await dispatch(
          unpinTab(
            {
              pathname: `/code/file/${dirtyCodeFileType}/${dirtyCodeZuid}`,
              search: "",
            },
            true
          )
        );
        setLoading(false);
        await dispatch(actions.closeCodeChangesModal());
      }}
      onCancel={() => dispatch(actions.closeCodeChangesModal())}
      onSave={async () => {
        await dispatch(saveFile(dirtyCodeZuid, dirtyCodeStatus));
        await dispatch(
          unpinTab(
            {
              pathname: `/code/file/${dirtyCodeFileType}/${dirtyCodeZuid}`,
              search: "",
            },
            true
          )
        );
        setLoading(false);
        await dispatch(actions.closeCodeChangesModal());
      }}
    />
  );
};

import { FC, useEffect, useMemo, useState, memo } from "react";
import { useLocation, Link as Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";

import PinIcon from "@mui/icons-material/PushPin";
import OutlinedPinIcon from "@mui/icons-material/PushPinOutlined";

import MuiLink from "@mui/material/Link";
import Box from "@mui/material/Box";
import SvgIcon from "@mui/material/SvgIcon";
import Stack from "@mui/material/Stack";

import {
  pinTab,
  unpinTab,
  parsePath,
  Tab,
  createTab,
  tabLocationEquality,
} from "../../../../shell/store/ui";
import { AppState } from "../../../store/types";
import {
  useGetAllBinGroupsQuery,
  useGetBinsQuery,
} from "../../../services/mediaManager";
import { useGetContentModelsQuery } from "../../../services/instance";

export type TopBarTab = {
  tab: Tab;
  tabWidth: number;
  isDarkMode?: boolean;
  isActive?: boolean;
  isPinned?: boolean;
  tabIndex?: number;
};
export const TopBarTab: FC<TopBarTab> = memo(
  ({
    tab,
    tabWidth,
    isDarkMode = false,
    isActive = false,
    isPinned = false,
    tabIndex,
  }) => {
    const dispatch = useDispatch();
    const instanceId = useSelector((state: any) => state.instance.ID);
    const ecoId = useSelector((state: any) => state.instance.ecoID);

    const [styles, setStyles] = useState({
      backgroundColor: "grey.100",
      fontColor: "text.secondary",
      iconColor: "action.active",
    });

    useEffect(() => {
      if (isActive) {
        if (isDarkMode) {
          setStyles({
            backgroundColor: "background.editor",
            fontColor: "common.white",
            iconColor: "grey.500",
          });
        } else {
          setStyles({
            backgroundColor: "common.white",
            fontColor: "text.primary",
            iconColor: "action.active",
          });
        }
      } else {
        // Revert to default style once unselected as active
        setStyles({
          backgroundColor: "grey.100",
          fontColor: "text.secondary",
          iconColor: "action.active",
        });
      }
    }, [isDarkMode, isActive]);

    // RTK QUERY FOR HOOKING INTO ALL MEDIA BIN GROUPS
    const { data: bins } = useGetBinsQuery({ instanceId, ecoId });
    const { data: binGroups } = useGetAllBinGroupsQuery(
      bins?.map((bin) => bin.id),
      {
        skip: !bins?.length,
      }
    );
    const { data: models } = useGetContentModelsQuery();
    const queryData = useMemo(() => {
      return {
        mediaManager: {
          bins,
          binGroups: binGroups?.flat(),
        },
        instance: {
          models,
        },
      };
    }, [binGroups]);

    const Pin = isPinned ? PinIcon : OutlinedPinIcon;

    const handlePinClick = () => {
      // force unpin because we don't want to show the modal on the active tab
      if (isPinned) {
        dispatch(unpinTab(tab, isActive, queryData));
      } else {
        dispatch(pinTab(tab, queryData));
      }
    };

    return (
      <Box
        component="div"
        className="tab-item"
        data-cy={isPinned ? `PinnedTab-${tabIndex}` : "UnpinnedTab"}
        data-active={isActive}
        width={`${tabWidth}px`}
        py={0.5}
        height={34}
        bgcolor={styles.backgroundColor}
        flex="1 0 0"
        borderRadius="8px 8px 0px 0px"
        sx={{
          "&:hover": {
            backgroundColor: isActive ? styles.backgroundColor : "grey.50",
          },
        }}
      >
        <Stack
          component="div"
          direction="row"
          height={24}
          alignItems="center"
          justifyContent="space-between"
          borderLeft={1}
          borderColor={isActive ? "transparent" : "grey.300"}
          sx={{
            "&:hover": {
              borderColor: "transparent",
            },
          }}
        >
          <Box
            display="flex"
            flex="1 0 0"
            component="div"
            whiteSpace="nowrap"
            overflow="hidden"
            textOverflow="ellipsis"
            pl={1.5}
          >
            <Box
              display="inline-block"
              mr={1.25}
              color={styles.iconColor}
              fontSize={16}
            >
              {tab.icon && <SvgIcon component={tab.icon} fontSize="inherit" />}
            </Box>
            <MuiLink
              component={Link}
