import { FC, useMemo } from "react";
import { Create } from "@mui/icons-material";
import { useSelector } from "react-redux";
import { formatDistanceToNow, isValid } from "date-fns";

import { ContentItem } from "../../../services/types";
import {
  useGetAuditsQuery,
  useGetContentModelQuery,
  useGetContentItemQuery,
} from "../../../services/instance";
import { SearchListItem } from "./SearchListItem";

interface Content {
  data: ContentItem;
  loading?: boolean;
  style: any;
}
export const Content: FC<Content> = ({
  data,
  style,
  loading: parentIsLoading = false,
}) => {
  const affectedZUID = data?.meta?.ZUID;
  const { data: auditData, isLoading: auditLoading } = useGetAuditsQuery(
    { affectedZUID, limit: 1, dir: "desc", order: "created" },
    { skip: !affectedZUID }
  );
  const { data: contentData, isLoading: contentLoading } =
    useGetContentItemQuery(affectedZUID, {
      skip: !affectedZUID,
    });
  const { data: modelData, isLoading: modelLoading } = useGetContentModelQuery(
    contentData?.meta.contentModelZUID,
    { skip: !contentData?.meta.contentModelZUID }
  );

  // For logging / debugging purposes
  const auditRes = useGetAuditsQuery(
    { affectedZUID, limit: 1, dir: "desc", order: "created" },
    { skip: !affectedZUID }
  );
  const contentRes = useGetContentItemQuery(auditData?.[0]?.affectedZUID, {
    skip: !auditData?.[0]?.affectedZUID,
  });
  const modelRes = useGetContentModelQuery(contentData?.meta.contentModelZUID, {
    skip: !contentData?.meta.contentModelZUID,
  });

  // Title
  const languages = useSelector((state: any) => state.languages);

  const title = useMemo(() => {
    const langCode = languages.find(
      (lang: any) => lang.ID === data?.meta?.langID
    )?.code;
    const langDisplay = langCode ? `(${langCode}) ` : "";
    const hasSiblings =
      contentData &&
      contentData.siblings &&
      Object.keys(contentData.siblings).length > 0;

    return `${hasSiblings && langDisplay} ${
      data?.web?.metaTitle || "Item missing meta title"
    }`;
  }, [languages, contentData, data]);

  // Chips
  const titleChip =
    modelData?.metaTitle ||
    modelData?.label ||
    contentData?.meta.contentModelZUID;
  const appChip = "Content";

  const rel = (dt?: string) => {
    if (!dt) return "";
    const d = new Date(dt);
    return isValid(d) ? formatDistanceToNow(d, { addSuffix: true }) : "";
  };

  const actionDate = auditData?.[0]?.happenedAt;
  const dateInfo = rel(actionDate);
  const firstName = auditData?.[0]?.firstName;
  const lastName = auditData?.[0]?.lastName;
  const userInfo =
    firstName || lastName ? `${firstName} ${lastName}` : "Unknown User";
  const userDateChip = auditData?.[0]
    ? `${dateInfo} by ${userInfo}`
    : rel(data?.web?.createdAt);
  const chips = [titleChip, appChip, userDateChip].join(" • ");

  // Create url if meta data exists
  const url = contentData?.meta
    ? `/content/${contentData?.meta?.contentModelZUID}/${contentData?.meta?.ZUID}`
    : null;
  const loading =
    auditLoading || contentLoading || modelLoading || parentIsLoading;

  return (
    <SearchListItem
      title={title}
      url={url}
      chips={chips}
      icon={Create}
      style={style}
      loading={loading}
    />
  );
};

import { FC, useMemo } from "react";
import { Database } from "@zesty-io/material";
import { SvgIconComponent } from "@mui/icons-material";
import { formatDistanceToNow, isValid } from "date-fns";

import { ContentModel } from "../../../services/types";
import { SearchListItem } from "./SearchListItem";
import { useGetAuditsQuery } from "../../../services/instance";

interface Model {
  data: ContentModel;
  loading?: boolean;
  style: any;
}
export const Model: FC<Model> = ({
  data,
  style,
  loading: parentIsLoading = false,
}) => {
  const { data: modelAudit, isLoading: loadingModelAudit } = useGetAuditsQuery(
    { affectedZUID: data.ZUID, limit: 1, dir: "desc", order: "created" },
    { skip: !data.ZUID }
  );

  const chips = useMemo(() => {
    const rel = (dt?: string) => {
      if (!dt) return "";
      const d = new Date(dt); // switch to parseISO(dt) if you hit parsing issues
      return isValid(d) ? formatDistanceToNow(d, { addSuffix: true }) : "";
    };

    if (modelAudit?.length) {
      const audit = modelAudit[0];
      const time = rel(audit?.happenedAt);
      const name = [audit?.firstName, audit?.lastName]
        .filter(Boolean)
        .join(" ");
      return `Schema • ${time}${name ? ` by ${name}` : ""}`;
    }

    return `Schema • ${rel(data?.createdAt)}`;
  }, [modelAudit, data?.createdAt]);

  const loading = loadingModelAudit || parentIsLoading;

  return (
    <SearchListItem
      title={data.label}
      url={`/schema/${data.ZUID}`}
      chips={chips}
      icon={Database as SvgIconComponent}
      style={style}
      loading={loading}
    />
  );
};

import { FC, useMemo } from "react";
import { SvgIconComponent, CodeRounded } from "@mui/icons-material";
import { formatDistanceToNow, isValid } from "date-fns";

import { File } from "../../../hooks/useSearchCodeFilesByKeyword";
import { SearchListItem } from "./SearchListItem";
import { useGetAuditsQuery } from "../../../services/instance";

interface Code {
  data: File;
  loading?: boolean;
  style: any;
}

export const Code: FC<Code> = ({
  data,
  style,
  loading: parentIsLoading = false,
}) => {
  const { data: fileAudit, isLoading: loadingFileAudit } = useGetAuditsQuery(
    { affectedZUID: data.ZUID, limit: 1, dir: "desc", order: "created" },
    { skip: !data.ZUID }
  );

  const chips = useMemo(() => {
    const rel = (dt?: string) => {
      if (!dt) return "";
      const d = new Date(dt);
      return isValid(d) ? formatDistanceToNow(d, { addSuffix: true }) : "";
    };

    if (fileAudit?.length) {
      const audit = fileAudit[0];
      const time = rel(audit?.happenedAt);
      const name = `${audit?.firstName} ${audit?.lastName}`;
      return `Code File • ${time} by ${name}`;
    }

    return `Code File • ${rel(data?.createdAt)}`;
  }, [fileAudit, data?.createdAt]);

  const loading = loadingFileAudit || parentIsLoading;

  return (
    <SearchListItem
      title={data.fileName?.split("/").pop()}
      url={`/code/file/views/${data.ZUID}`}
      chips={chips}
      icon={CodeRounded}
      style={style}
      loading={loading}
    />
  );
};

import { FC, useMemo } from "react";
import {
  ImageRounded,
  FolderRounded,
  SvgIconComponent,
} from "@mui/icons-material";
import { formatDistanceToNow, isValid } from "date-fns";

import { File, Group } from "../../../services/types";
import { SearchListItem } from "./SearchListItem";

interface Media {
  data: File | Group;
  loading?: boolean;
  style: any;
  subType: "folder" | "item";
}
export const Media: FC<Media> = ({ data, style, loading = false, subType }) => {
  const config = useMemo(() => {
    let icon: SvgIconComponent;
    let url: string;
    let title: string;
    let chips: string;

    const rel = (dt?: string) => {
      if (!dt) return "";
      const d = new Date(dt); // switch to parseISO(dt) if you hit parsing issues
      return isValid(d) ? formatDistanceToNow(d, { addSuffix: true }) : "";
    };

    switch (subType) {
      case "item": {
        const itemData = data as File;
        icon = ImageRounded;
        url = `/media?fileId=${itemData.id}`;
        title = itemData.filename;
        chips = `Media • ${rel(itemData.created_at)}`;
        break;
      }

      case "folder": {
        const folderData = data as Group;
        icon = FolderRounded;
        url = `/media/folder/${folderData.id}`;
        title = folderData.name;
        chips = `Media`;
        break;
      }

      default:
        icon = ImageRounded;
        url = "";
        title = "";
        chips = "";
        break;
    }

    return { icon, url, title, chips };
  }, [subType, data]);

  return (
    <SearchListItem
      title={config.title}
      url={config.url}
      chips={config.chips}
      icon={config.icon}
      style={style}
      loading={loading}
    />
  );
};

import { FC, useMemo } from "react";
import { Block as BlockIcon } from "@zesty-io/material";
import { SvgIconComponent } from "@mui/icons-material";
import { isValid, formatDistanceToNow } from "date-fns";

import { ContentModel } from "../../../services/types";
import { SearchListItem } from "./SearchListItem";

export type BlockModel = Partial<ContentModel> & {
  ZUID: string;
  label?: string;
  contentModelZUID?: string;
  contentModelLabel?: string;
  createdByUserZUID?: string;
  createdByUserName?: string;
  createdAt?: string;
  updatedAt?: string;
  lang?: string;
  langID?: number;
  title?: string;
};

type Block = {
  data: BlockModel;
  loading?: boolean;
  style: any;
};

export const Block: FC<Block> = ({
  data,
  style,
  loading: parentIsLoading = false,
}) => {
  const isVariant = data?.type === "block" && !!data?.contentModelZUID;
  const createdRelative = useMemo(() => {
    if (!data?.createdAt) return "";
    const d = new Date(data.createdAt);
    return isValid(d) ? formatDistanceToNow(d, { addSuffix: true }) : "";
  }, [data?.createdAt]);

  const chips = useMemo(() => {
    const preFix =
      !!isVariant && !!data?.contentModelLabel
        ? `${data?.contentModelLabel} • `
        : "";

    const userName = !data?.createdByUserName
      ? ""
      : ` by ${data?.createdByUserName}`;
    return `${preFix}Block • created ${createdRelative}${userName}`;
  }, [data]);

  const titlePrefix = !!data?.lang ? `(${data?.lang}) ` : "";
  const urlPath = isVariant
    ? `${data?.contentModelZUID}/${data?.ZUID}`
    : data?.ZUID;

  const loading = parentIsLoading;

  return (
    <SearchListItem
      title={`${titlePrefix}${data?.label}`}
      url={`/blocks/${urlPath}`}
      chips={chips}
      icon={BlockIcon as SvgIconComponent}
      style={style}
      loading={loading}
    />
  );
};

import { FC, useCallback } from "react";
import Stack from "@mui/material/Stack";
import { List } from "react-window";
import AutoSizer, { Size } from "react-virtualized-auto-sizer";

import {
  ContentItem,
  ContentModel,
  File as MediaFile,
  Group,
} from "../../../services/types";
import { SearchPageItem } from "../SearchPage";
import { File } from "../../../hooks/useSearchCodeFilesByKeyword";
import { Content } from "./Content";
import { Model } from "./Model";
import { Code } from "./Code";
import { Media } from "./Media";
import { Block, BlockModel } from "./Block";

type SearchPageList = {
  results: SearchPageItem[];
  loading: boolean;
};

export const SearchPageList: FC<SearchPageList> = ({
  results: backendResults,
  loading,
}) => {
  const results = loading
    ? new Array(10) // arbitrary length array of junk data
    : backendResults;
  const Row = useCallback(
    ({ index, style }) => {
      if (!loading) {
        const result = backendResults[index];

        switch (result.type) {
          case "content":
            return (
              <Content
                key={result.ZUID}
                data={result.data as ContentItem}
                style={style}
              />
            );

          case "schema":
            return (
              <Model
                key={result.ZUID}
                data={result.data as ContentModel}
                style={style}
              />
            );

          case "block":
            return (
              <Block
                key={result.ZUID}
                data={result.data as BlockModel}
                style={style}
              />
            );

          case "code":
            return (
              <Code
                key={result.ZUID}
                data={result.data as File}
                style={style}
              />
            );

          case "media":
            let data: MediaFile | Group;

            if (result.subType === "item") {
              data = result.data as MediaFile;
            }

            if (result.subType === "folder") {
              data = result.data as Group;
            }

            return (
              <Media
                key={result.ZUID}
                data={data}
                style={style}
                subType={result.subType}
              />
            );

          default:
            break;
        }
      } else {
        return (
          <Content
            key={index}
            data={results[index]}
            style={style}
            loading={loading}
          />
        );
      }
    },
    [backendResults, loading]
  );

  return (
    <List
      rowHeight={72}
      rowCount={results.length}
      style={{ borderRadius: "8px" }}
      rowComponent={Row}
      rowProps={{}}
    />
  );
};

