import { DateRangeFilterValue } from "../components/Filters/DateFilter/types";

type UseDateFilterParams = [
  DateFilterValue,
  (dateFilter: DateFilterValue) => void
];
export const useDateFilterParams: () => UseDateFilterParams = () => {
  const [params, setParams] = useParams();

  const setDateFilter = (dateFilter: DateFilterValue) => {
    switch (dateFilter.type) {
      case "daterange": {
        const value = dateFilter.value as DateRangeFilterValue;

        setParams(value.to, "to");
        setParams(value.from, "from");
        setParams(null, "datePreset");
        return;
      }

      case "on": {
        const value = dateFilter.value as string;

        setParams(value, "to");
        setParams(value, "from");
        setParams(null, "datePreset");
        return;
      }
      case "before": {
        const value = dateFilter.value as string;

        setParams(value, "to");
        setParams(null, "from");
        setParams(null, "datePreset");
        return;
      }
      case "after": {
        const value = dateFilter.value as string;

        setParams(value, "from");
        setParams(null, "to");
        setParams(null, "datePreset");
        return;
      }
      case "preset": {
        const value = dateFilter.value as string;

        setParams(value, "datePreset");
        setParams(null, "to");
        setParams(null, "from");
        return;
      }

      default: {
        setParams(null, "to");
        setParams(null, "from");
        setParams(null, "datePreset");
        return;
      }
    }
  };

  const activeDateFilter: DateFilterValue = useMemo(() => {
    const isPreset = !!params.get("datePreset");
    const isBefore = !!params.get("to") && !!!params.get("from");
    const isAfter = !!params.get("from") && !!!params.get("to");
    const isOn =
      !!params.get("to") &&
      !!params.get("from") &&
      params.get("to") === params.get("from");
    const isDateRange =
      !!params.get("to") &&
      !!params.get("from") &&
      params.get("to") !== params.get("from");

    if (isPreset) {
      return {
        type: "preset",
        value: params.get("datePreset"),
      };
    }

    if (isBefore) {
      return {
        type: "before",
        value: params.get("to"),
      };
    }

    if (isAfter) {
      return {
        type: "after",
        value: params.get("from"),
      };
    }

    if (isOn) {
      return {
        type: "on",
        value: params.get("from"),
      };
    }

    if (isDateRange) {
      return {
        type: "daterange",
        value: {
          from: params.get("from"),
          to: params.get("to"),
        },
      };
    }

    return {
      type: "",
      value: "",
    };
  }, [params]);

  return [activeDateFilter, setDateFilter];
};

import { useMemo } from "react";
import { Stack } from "@mui/material";

import { useParams } from "../../../hooks/useParams";
import { SortByFilter, FilterValues } from "./SortByFilter";
import { UserFilter, DateFilter } from "../../../components/Filters/";
import { useGetUsersQuery } from "../../../services/accounts";
import { ResourceTypeFilter } from "./ResourceTypeFilter";
import { ResourceType } from "../../../services/types";
import { LanguageFilter } from "./LanguageFilter";
import { useDateFilterParams } from "../../../hooks/useDateFilterParams";

export const Filters = () => {
  const [params, setParams] = useParams();
  const [activeDateFilter, setActiveDateFilter] = useDateFilterParams();
  const { data: users } = useGetUsersQuery();
  const userOptions = useMemo(() => {
    return users?.map((user) => ({
      firstName: user.firstName,
      lastName: user.lastName,
      ZUID: user.ZUID,
      email: user.email,
    }));
  }, [users]);

  return (
    <Stack direction="row" gap={1.5}>
      <SortByFilter
        value={(params.get("sort") as FilterValues) || "modified"}
        onChange={(value) => setParams(value, "sort")}
      />
      <ResourceTypeFilter
        onChange={(value) => setParams(value, "resource")}
        value={(params.get("resource") as ResourceType) || ""}
      />
      <UserFilter
        value={params.get("user") || ""}
        onChange={(value) => setParams(value, "user")}
        defaultButtonText="Created By"
        options={userOptions}
      />
      <DateFilter
        withDateRange
        defaultButtonText="Date Modified"
        onChange={(value) => setActiveDateFilter(value)}
        value={activeDateFilter}
      />
      <LanguageFilter
        value={params.get("lang") || ""}
        onChange={(value) => setParams(value, "lang")}
      />
    </Stack>
  );
};

import { FC, useMemo, useEffect } from "react";
import { Typography, Box, Stack, Skeleton } from "@mui/material";
import { cloneDeep, isEmpty } from "lodash";
import { useSelector } from "react-redux";
import { parseISO, isValid } from "date-fns";
import { useParams } from "../../../shell/hooks/useParams";
import { NoSearchResults } from "../../components/NoSearchResults";
import {
  useSearchContentQuery,
  useGetLangsQuery,
} from "../../services/instance";
import { SearchPageList } from "./List/SearchPageList";
import { BackButton } from "./BackButton";
import { Filters } from "./Filters";
import { getDateFilterFnByValues } from "../../components/Filters/DateFilter/getDateFilter";
import { useSearchModelsByKeyword } from "../../hooks/useSearchModelsByKeyword";
import {
  ContentItem,
  ContentModel,
  ResourceType,
  File as MediaFile,
  Group,
} from "../../services/types";
import {
  useSearchCodeFilesByKeywords,
  File,
} from "../../hooks/useSearchCodeFilesByKeyword";
import {
  useSearchBinFilesQuery,
  useGetBinsQuery,
} from "../../services/mediaManager";
import { useSearchMediaFoldersByKeyword } from "../../hooks/useSearchMediaFoldersByKeyword";
import { BlockModel } from "./List/Block";
import { useSearchBlocksByKeyword } from "../../hooks/useSearchBlocksByKeyword";
import { AppState } from "shell/store/types";
export interface SearchPageItem {
  ZUID: string;
  title: string;
  type: ResourceType;
  updatedAt: string;
  createdAt: string;
  createdByUserZUID: string;
  data: ContentItem | BlockModel | ContentModel | File | MediaFile | Group;
  subType?: "folder" | "item";
  langID?: number;
}
export const SearchPage: FC = () => {
  const [params, setParams] = useParams();
  const keyword = params.get("q") || "";
  const instanceId = useSelector((state: AppState) => state.instance.ID);
  const ecoId = useSelector((state: AppState) => state.instance.ecoID);
  const allModels = useSelector((state: AppState) => state.models);
  const {
    data: contents,
    isFetching: isFetchingContent,
    isError: isContentFetchingFailed,
  } = useSearchContentQuery({ query: keyword, order: "created", dir: "desc" });
  const [models, setModelKeyword] = useSearchModelsByKeyword();

  const [codeFiles, setCodeFileKeyword] = useSearchCodeFilesByKeywords();
  const [mediaFolders, setMediaFolderKeyword] =
    useSearchMediaFoldersByKeyword();
  const { data: bins } = useGetBinsQuery({ instanceId, ecoId });
  const { data: mediaFiles, isFetching: isFetchingMedia } =
    useSearchBinFilesQuery(
      { binIds: bins?.map((bin) => bin.id), term: keyword },
      {
        skip: !bins?.length || !keyword,
      }
    );
  const { data: langs } = useGetLangsQuery({});

  const { blocks, setBlockKeyword } = useSearchBlocksByKeyword({
    isLoading: isFetchingContent,
  });

  const isLoading = isFetchingContent || isFetchingMedia;

  useEffect(() => {
    let isMounted = true;

    if (isMounted) {
      setModelKeyword(keyword);
      setCodeFileKeyword(keyword);
      setMediaFolderKeyword(keyword);
      setBlockKeyword(keyword);
    }

    return () => {
      isMounted = false;
    };
  }, [keyword]);

  const toTime = (s?: string) => {
    if (!s) return -Infinity;
    const d = parseISO(s);
    return isValid(d) ? d.getTime() : -Infinity;
  };

  // Combine results from contents, models, code files, media files and media folders
  const results: SearchPageItem[] = useMemo(() => {
    const sortBy = params.get("sort") || "";

    //Filter out redundant block model items
    const filteredContents = contents?.filter(
      (item: ContentItem) =>
        allModels?.[item?.meta?.contentModelZUID]?.type !== "block"
    );
    // Content data needs to be reset to [] when api call fails
    const contentResults: SearchPageItem[] =
      isContentFetchingFailed || isEmpty(filteredContents)
        ? []
        : filteredContents?.map((content) => {
            return {
              ZUID: content.meta?.ZUID,
              title: content.web?.metaTitle,
              type: "content",
              updatedAt: content.meta?.updatedAt,
              createdAt: content.meta?.createdAt,
              createdByUserZUID: content.web?.createdByUserZUID,
              data: content,
              langID: content.meta?.langID,
            };
          });

    const modelResults: SearchPageItem[] =
      models?.map((model) => {
        return {
          ZUID: model.ZUID,
          title: model.label,
          type: "schema",
          updatedAt: model.updatedAt,
          createdAt: model.createdAt,
          createdByUserZUID: model.createdByUserZUID,
          data: model,
        };
      }) || [];

    const blockResults: SearchPageItem[] =
      blocks?.map((block) => {
        return {
          ZUID: block?.ZUID,
          title: block?.label,
          type: "block",
          updatedAt: block?.updatedAt,
          createdAt: block?.createdAt,
          createdByUserZUID: block?.createdByUserZUID,
          langID: block?.langID,
          data: block,
        };
      }) || [];

    const fileResults: SearchPageItem[] =
      codeFiles?.map((file) => {
        return {
          ZUID: file.ZUID,
          title: file.fileName,
          type: "code",
          updatedAt: file.updatedAt,
          createdAt: file.createdAt,
          createdByUserZUID: "",
          data: file,
        };
      }) || [];

    const mediaFileResults: SearchPageItem[] =
      mediaFiles?.map((file) => {
        return {
          ZUID: file.id,
          title: file.filename,
          type: "media",
          updatedAt: file.updated_at,
          createdAt: file.created_at,
          createdByUserZUID: file.created_by ?? "",
          data: file,
          subType: "item",
        };
      }) || [];

    const mediaFolderResults: SearchPageItem[] =
      mediaFolders?.map((folder) => {
        return {
          ZUID: folder.id,
          title: folder.name,
          type: "media",
          updatedAt: "",
          createdAt: "",
          createdByUserZUID: "",
          data: folder,
          subType: "folder",
        };
      }) || [];

    const consolidatedResults = [
      ...contentResults,
      ...modelResults,
      ...fileResults,
      ...mediaFileResults,
      ...mediaFolderResults,
      ...blockResults,
    ];

    // Sort the results
    switch (sortBy) {
      case "":
      case "modified":
        return consolidatedResults?.sort(
          (a, b) => toTime(b.updatedAt) - toTime(a.updatedAt)
        );

      case "created":
        return consolidatedResults?.sort(
          (a, b) => toTime(b.createdAt) - toTime(a.createdAt)
        );

      case "AtoZ":
        return consolidatedResults?.sort((a, b) =>
          (a.title || "").localeCompare(b.title || "")
        );

      case "ZtoA":
        return consolidatedResults?.sort((a, b) =>
          (b.title || "").localeCompare(a.title || "")
        );

      default:
        return consolidatedResults;
    }
  }, [
    allModels,
    contents,
    models,
    blocks,
    params,
    codeFiles,
    mediaFiles,
    mediaFolders,
    isContentFetchingFailed,
  ]);

  const filteredResults = useMemo(() => {
    let _results = cloneDeep(results);
    const resourceTypeFilter = params.get("resource") || "";
    const userFilter = params.get("user") || "";
    const languageFilter = params.get("lang") || "";
    const dateFilter = {
      preset: params.get("datePreset") || "",
      from: params.get("from") || "",
      to: params.get("to") || "",
    };
    const dateFilterFn = getDateFilterFnByValues(dateFilter);

    // Filter by user
    if (userFilter) {
      _results = _results.filter(
        (result) => result.createdByUserZUID === userFilter
      );
    }

    // Filter by resource type
    if (resourceTypeFilter) {
      _results = _results.filter(
        (result) => result.type === resourceTypeFilter
      );
    }

    // Filter by language
    if (languageFilter) {
      // Determine the ID of the lang code selected
      const selectedLangID =
        langs?.find((lang) => lang.code === languageFilter)?.ID ?? 0;

      _results = _results.filter((result) => result.langID === selectedLangID);
    }

    // Apply date filter if there is any
    if (dateFilterFn) {
      _results = _results.filter((result) => {
        if (result.updatedAt) {
          return dateFilterFn(result.updatedAt);
        }

        return false;
      });
    }

    return _results;
  }, [results, params]);

  return (
    <Stack
      sx={{
        width: "100%",
        height: "100%",
        backgroundColor: "background.paper",
      }}
    >
      <Box
        sx={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "8px 24px",
          gap: "10px",
          minHeight: "52px",
          boxSizing: "border-box",
          borderColor: "grey.100",
          borderStyle: "solid",
          borderWidth: "0px 1px 1px 1px",
          backgroundColor: "background.paper",
        }}
      >
        <Typography variant="h6" color="text.primary" fontWeight={700}>
          {isLoading ? (
            <Skeleton variant="text" width={200} />
          ) : (
            `${filteredResults?.length} results ${
              Boolean(keyword) ? `for "${keyword}"` : ""
            }`
          )}
        </Typography>
        <BackButton />
      </Box>
      <Box
        py={2}
        px={3}
        sx={{
          backgroundColor: "grey.50",
        }}
      >
        <Filters />
      </Box>
      {!isLoading && !filteredResults?.length ? (
        <NoSearchResults query={keyword} />
      ) : (
        <Box
          sx={{
            px: 3,
            py: 0,
            gap: 2,
            backgroundColor: "grey.50",
            flex: 1,
            overflowY: "scroll",
          }}
          data-cy="SearchPageList"
        >
          <SearchPageList results={filteredResults} loading={isLoading} />
        </Box>
      )}
    </Stack>
  );
};

import { useEffect, useMemo } from "react";
import { addYears, isWithinInterval } from "date-fns";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Typography,
  Stack,
  Button,
  Box,
} from "@mui/material";
import OpenInNewRoundedIcon from "@mui/icons-material/OpenInNewRounded";
import ScheduledRoundedIcon from "@mui/icons-material/ScheduleRounded";
import PlayArrowRoundedIcon from "@mui/icons-material/PlayArrowRounded";
import { useCookie } from "react-use";

import { useGetAnnouncementsQuery } from "../../services/marketing";

export const InAppAnnouncement = () => {
  const { data: announcements } = useGetAnnouncementsQuery();
  const [readAnnouncementsCookie, updateReadAnnouncementsCookie] = useCookie(
    "READ_ANNOUNCEMENTS_ZUID"
  );
  const cookieOptions = {
    // @ts-ignore
    domain: __CONFIG__.COOKIE_DOMAIN,
    expires: addYears(new Date(), 1),
  };

  useEffect(() => {
    // Initializes and keeps on bumping the read announcements cookie to permanently keep it on the browser
    const parsedAnnouncementZuids = readAnnouncementsCookie
      ? JSON.parse(readAnnouncementsCookie)
      : [];

    updateReadAnnouncementsCookie(
      JSON.stringify(parsedAnnouncementZuids),
      cookieOptions
    );
  }, []);

  const latestAnnouncement = useMemo(() => {
    if (announcements?.length) {
      const latest = [...announcements].sort(
        (a, b) =>
          new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
      )[0];

      const now = new Date();
      const start = new Date(latest?.start_date_and_time);
      const end = new Date(latest?.end_date_and_time);
      if (isWithinInterval(now, { start, end })) return latest;
    }
  }, [announcements]);

  const readAnnouncements = useMemo(() => {
    return readAnnouncementsCookie ? JSON.parse(readAnnouncementsCookie) : [];
  }, [readAnnouncementsCookie]);

  const onIgnoreAnnouncement = (zuid: string) => {
    if (!readAnnouncements?.includes(zuid)) {
      updateReadAnnouncementsCookie(
        JSON.stringify([...readAnnouncements, zuid]),
        cookieOptions
      );
    }
  };

  if (
    !latestAnnouncement ||
    readAnnouncements.includes(latestAnnouncement.zuid)
  ) {
    return <></>;
  }

  return (
    <Dialog
      open
      onClose={() => onIgnoreAnnouncement(latestAnnouncement?.zuid)}
      maxWidth="md"
      PaperProps={{ sx: { width: 640 } }}
      data-cy="AnnouncementPopup"
    >
      <DialogContent sx={{ p: 0 }}>
        <Stack
          component="a"
          href={latestAnnouncement?.announcement_link}
          target="_blank"
          m={2.5}
          p={2.5}
          width={600}
          height={340}
          sx={{
            background: "linear-gradient(90deg, #EC4A0A 0%, #FD853A 100%)",
          }}
          alignItems="center"
          justifyContent="center"
          boxSizing="border-box"
        >
          <Box
            component="img"
            alt="announcement-banner-image"
            src={
              `${latestAnnouncement?.feature_image?.data[0]?.url}?fit=cover&width=1280` ??
              ""
            }
            maxWidth="100%"
            maxHeight="100%"
          />
        </Stack>
        <Stack gap={1} px={2.5} pb={2.5}>
          <Typography variant="h4" fontWeight={700}>
            {latestAnnouncement?.title}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {latestAnnouncement?.description}
          </Typography>
        </Stack>
      </DialogContent>
      <DialogActions sx={{ justifyContent: "space-between" }}>
        <Button
          variant="text"
          color="inherit"
          onClick={() => onIgnoreAnnouncement(latestAnnouncement?.zuid)}
          data-cy="IgnoreAnnouncementButton"
        >
          Ignore
        </Button>
        <Stack direction="row" gap={1}>
          <Button
            variant="outlined"
            startIcon={<OpenInNewRoundedIcon />}
            disabled={!latestAnnouncement?.announcement_link}
            href={latestAnnouncement?.announcement_link}
            target="_blank"
          >
            Read Announcement
          </Button>
          {latestAnnouncement?.cta_type === "play_video" &&
            latestAnnouncement?.video_link && (
              <Button
                variant="contained"
                startIcon={<PlayArrowRoundedIcon />}
                href={latestAnnouncement?.video_link}
                target="_blank"
              >
                Show Video
              </Button>
            )}
          {latestAnnouncement?.cta_type === "schedule_training" &&
            latestAnnouncement?.training_link && (
              <Button
                variant="contained"
                startIcon={<ScheduledRoundedIcon />}
                href={latestAnnouncement?.training_link}
                target="_blank"
              >
                Schedule Training
              </Button>
            )}
        </Stack>
      </DialogActions>
    </Dialog>
  );
};

