import { useMemo, useState } from "react";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  InputLabel,
  Autocomplete,
  Typography,
} from "@mui/material";
import EditRoundedIcon from "@mui/icons-material/EditRounded";
import { useHistory } from "react-router";
import { cloneDeep } from "lodash";

import { useGetContentModelsQuery } from "../services/instance";
import { ModelType } from "../services/types";

interface Props {
  open?: boolean;
  onClose: () => void;
  limitTo?: ModelType[];
}

export const CreateContentItemDialog = ({
  open = true,
  onClose,
  limitTo,
}: Props) => {
  const { data: models } = useGetContentModelsQuery();
  const history = useHistory();
  const [selectedModel, setSelectedModel] = useState(null);
  const [hasError, setHasError] = useState(false);

  const sortedModels = useMemo(() => {
    if (models?.length) {
      let _models = cloneDeep(models);
      // Remove special models from the create new item list
      _models = _models.filter(
        (model) =>
          !["dashboard widgets", "clippings", "globals"].includes(
            model.label.toLowerCase()
          )
      );

      // Limit to certain types
      if (!!limitTo?.length) {
        _models = _models.filter((model) => limitTo.includes(model.type));
      }

      // Filter out block models
      _models = _models.filter((model) => model.type !== "block");

      return _models?.sort((a, b) => a.label?.localeCompare(b.label));
    }

    return [];
  }, [models, limitTo]);

  const onCreateClick = () => {
    if (!selectedModel?.ZUID) {
      setHasError(true);
    } else {
      onClose();
      history.push("/content/" + selectedModel.ZUID + "/new");
    }
  };

  return (
    <Dialog
      data-cy="create_new_content_item_dialog"
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth={"xs"}
    >
      <DialogTitle component={Box}>
        <EditRoundedIcon
          color="primary"
          sx={{
            padding: "8px",
            borderRadius: "20px",
            backgroundColor: "deepOrange.50",
            display: "block",
            mb: 1.5,
            width: "40px",
            height: "40px",
          }}
        />
        <Typography variant="h5" fontWeight={700} mb={1}>
          Create Content Item
        </Typography>
        <Typography variant="body2" color="text.secondary">
          You can only create a content item for a pre-existing model
        </Typography>
      </DialogTitle>
      <DialogContent>
        <InputLabel sx={{ mb: 0.5 }}>Select Model</InputLabel>
        <Autocomplete
          data-cy="create_new_content_item_input"
          openOnFocus
          size="small"
          fullWidth
          value={selectedModel}
          disableClearable
          options={
            sortedModels
              ? [
                  {
                    label: "Internal/External Link",
                    ZUID: "link",
                  },
                  ...sortedModels,
                ]
              : []
          }
          renderInput={(params) => (
            <TextField
              {...params}
              placeholder="Select"
              hiddenLabel
              autoFocus
              error={hasError}
              helperText={hasError && "Please select a Model to proceed."}
            />
          )}
          getOptionLabel={(option: any) => option.label}
          isOptionEqualToValue={(option, value) => option.ZUID === value.ZUID}
          onChange={(event, newValue) => {
            if (!!newValue?.ZUID) {
              setHasError(false);
            }

            setSelectedModel(newValue);
          }}
          onKeyDown={(evt) => {
            if (evt.key.toLowerCase() === "enter" && !!selectedModel?.ZUID) {
              evt.preventDefault();
              onCreateClick();
            }
          }}
          ListboxProps={{
            style: {
              height: "250px",
            },
          }}
        />
      </DialogContent>
      <DialogActions>
        <Button
          data-cy="discard_new_content_item_btn"
          onClick={onClose}
          color="inherit"
        >
          Discard
        </Button>
        <Button
          data-cy="create_new_content_item_btn"
          variant="contained"
          color="primary"
          onClick={onCreateClick}
        >
          Create
        </Button>
      </DialogActions>
    </Dialog>
  );
};

import { FC, useEffect, useMemo, useState } from "react";
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  Typography,
  Stack,
  SvgIcon,
} from "@mui/material";
import { VisibilityOffRounded, VisibilityRounded } from "@mui/icons-material";

import { ContentNavItem } from "../../../../../shell/services/types";
import { TreeItem } from "../../../../../shell/components/NavTree";

interface Props {
  isHide: boolean;
  item: TreeItem;
  onClose: () => void;
  onToggleItemHideStatus: (item: TreeItem) => void;
}

export const HideContentItemDialog: FC<Readonly<Props>> = ({
  isHide,
  item,
  onClose,
  onToggleItemHideStatus,
}) => {
  return (
    <Dialog open onClose={onClose} fullWidth maxWidth={"xs"}>
      <DialogContent sx={{ mt: 2.5 }}>
        <Stack>
          <SvgIcon
            component={isHide ? VisibilityOffRounded : VisibilityRounded}
            color="primary"
            sx={{
              padding: "8px",
              borderRadius: "20px",
              backgroundColor: "deepOrange.50",
              display: "block",
              mb: 1.5,
              width: "40px",
              height: "40px",
            }}
          />

          <Typography variant="h5" fontWeight={600} mb={1}>
            {isHide ? `Hide ${item.label}?` : `Unhide ${item.label}?`}
          </Typography>
          {isHide ? (
            <>
              <Typography variant="body2" color="text.secondary" mb={1.5}>
                This will shift the {item.label} content item from the pages
                section to the hidden items section below. We recommend only
                using this feature to declutter up your content navigation tree
                from items you do not access very often.
              </Typography>

              <Typography variant="body2" color="text.secondary">
                This will not hide any of your articles from your live website
                or app.
              </Typography>
            </>
          ) : (
            <Typography variant="body2" color="text.secondary">
              This will shift the {item.label} content item from the Hidden
              Items section to the Pages section above.
            </Typography>
          )}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} color="inherit">
          Cancel
        </Button>
        <Button
          variant="contained"
          color="primary"
          onClick={() => {
            onClose();
            onToggleItemHideStatus(item);
          }}
        >
          {isHide ? `Hide ${item.label}` : `Unhide ${item.label}`}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

import { FC } from "react";
import { Box, Typography } from "@mui/material";

import notFound from "../../../../../../../public/images/notFoundTransparent.png";

interface Props {
  navName: string;
}
export const NavError: FC<Props> = ({ navName }) => {
  return (
    <Box p={1.5} textAlign="center">
      <img src={notFound} alt="Not Found" style={{ width: 112, height: 110 }} />
      <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
        We're sorry we are unable to load your {navName}. Please refresh your
        page and try again.
