import { useState, createContext, useLayoutEffect } from "react";
import { GridSortModel, GridSortItem } from "@mui/x-data-grid-pro";
import { useParams as useRouterParams } from "react-router";

type TableSortContextType = [
  GridSortModel,
  (newSortModel: GridSortModel) => void
];
export const TableSortContext = createContext<TableSortContextType>([
  [],
  () => {},
]);

type TableSortProviderType = {
  children?: React.ReactNode;
};
export const TableSortProvider = ({ children }: TableSortProviderType) => {
  // Note: We always want it to default to lastSaved if no other sorting is applied
  const [sortModel, setSortModel] = useState<GridSortModel>([
    {
      field: "lastSaved",
      sort: "desc",
    },
  ]);
  const { modelZUID } = useRouterParams<{ modelZUID: string }>();

  useLayoutEffect(() => {
    if (!modelZUID) return;

    const stateFromLocalStorage = localStorage?.getItem(
      `${modelZUID}-dataGridState`
    );

    if (stateFromLocalStorage) {
      const { sortModel: sortModelFromLocalStorage } = JSON.parse(
        stateFromLocalStorage
      )?.sorting;

      if (
        Array.isArray(sortModelFromLocalStorage) &&
        sortModelFromLocalStorage?.length
      ) {
        setSortModel(sortModelFromLocalStorage);
      }
    }
  }, [modelZUID]);

  return (
    <TableSortContext.Provider value={[sortModel, setSortModel]}>
      {children}
    </TableSortContext.Provider>
  );
};

import { useMemo } from "react";

export const getCountryCode = (langCode: string) => {
  if (!langCode) return "";

  const splitTag = langCode.split("-");
  const countryCode =
    splitTag.length === 2 ? splitTag[1] : langCode.toUpperCase();

  return countryCode;
};

export const Flag = ({ countryCode }: { countryCode: string }) => {
  const flagEmoji = useMemo(() => {
    if (!countryCode) {
      return null;
    }

    if (countryCode.length !== 2) {
      throw new Error(
        `Country code must be exactly 2 characters, instead received "${countryCode}".`
      );
    }

    // Convert country code to flag emoji.
    // Unicode flag emojis are made up of regional indicator symbols, which are a sequence of two letters.
    const baseOffset = 0x1f1e6;

    return (
      String.fromCodePoint(baseOffset + (countryCode.charCodeAt(0) - 65)) +
      String.fromCodePoint(baseOffset + (countryCode.charCodeAt(1) - 65))
    );
  }, [countryCode]);

  return <>{flagEmoji}</>;
};

