import { Button, Menu, MenuItem } from "@mui/material";
import { GridRenderCellParams } from "@mui/x-data-grid-pro";
import { useState } from "react";
import { KeyboardArrowDownRounded } from "@mui/icons-material";
import { useStagedChanges } from "../StagedChangesContext";

export const DropDownCell = ({ params }: { params: GridRenderCellParams }) => {
  const { stagedChanges, updateStagedChanges } = useStagedChanges();
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const field = params.row.fieldData[params.field];
  const handleChange = (value: any) => {
    setAnchorEl(null);

    if (value !== currVal) {
      updateStagedChanges(
        params.row.id,
        params.field,
        value === "Select" ? null : value
      );
    }
  };

  const currVal =
    stagedChanges?.[params.row.id]?.[params.field] === null ||
    !field?.settings?.options
      ? "Select"
      : field?.settings?.options?.[
          stagedChanges?.[params.row.id]?.[params.field]
        ] ||
        field?.settings?.options?.[params?.value] ||
        "Select";

  return (
    <>
      <Button
        sx={{
          color: "text.disabled",
          height: "24px",
          minWidth: "unset",
          padding: "2px",
          " .MuiButton-endIcon": {
            marginLeft: "4px",
          },
        }}
        color="inherit"
        endIcon={<KeyboardArrowDownRounded color="action" />}
        onClick={(e) => {
          e.stopPropagation();
          setAnchorEl(e.currentTarget);
        }}
      >
        {currVal}
      </Button>
      <Menu
        onClose={() => setAnchorEl(null)}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "left",
        }}
        transformOrigin={{
          vertical: "top",
          horizontal: "left",
        }}
        anchorEl={anchorEl}
        open={!!anchorEl}
      >
        <MenuItem
          dense
          onClick={() => {
            handleChange("Select");
          }}
          sx={{
            textWrap: "wrap",
            wordBreak: "break-word",
          }}
        >
          Select
        </MenuItem>
        {field?.settings?.options &&
          Object.entries(field?.settings?.options)?.map(([key, value]) => (
            <MenuItem
              dense
              key={key}
              onClick={() => {
                handleChange(key);
              }}
              selected={value === currVal}
              sx={{
                textWrap: "wrap",
                wordBreak: "break-word",
              }}
            >
              {value}
            </MenuItem>
          ))}
      </Menu>
    </>
  );
};

import { ChangeEvent } from "react";
import MuiTextField, { OutlinedTextFieldProps } from "@mui/material/TextField";
import { InputAdornment, IconButton } from "@mui/material";
import AddRoundedIcon from "@mui/icons-material/AddRounded";
import RemoveRoundedIcon from "@mui/icons-material/RemoveRounded";

export interface FieldTypeSortProps
  extends Omit<OutlinedTextFieldProps, "variant"> {
  value: string;
  height?: number;
}

export const FieldTypeSort = ({
  value,
  InputProps,
  onChange,
  height,
  ...props
}: FieldTypeSortProps) => {
  const modifyValue = (action: "increment" | "decrement") => {
    let newValue = +value;

    switch (action) {
      case "increment":
        newValue++;
        break;

      case "decrement":
        newValue--;
        break;

      default:
        break;
    }

    // Mocks an event change
    const event = { target: { value: newValue.toString() } };

    onChange &&
      onChange(event as ChangeEvent<HTMLTextAreaElement | HTMLInputElement>);
  };

  return (
    <MuiTextField
      variant="outlined"
      // Only changes how the minus sign is rendered on the input field, doesn't affect the value at all
      value={value.replace("-", "−")}
      onChange={onChange}
      InputProps={{
        startAdornment: (
          <InputAdornment position="start">
            <IconButton
              size="small"
              onClick={(e) => {
                e.stopPropagation();
                modifyValue("decrement");
              }}
            >
              <RemoveRoundedIcon fontSize="small" />
            </IconButton>
          </InputAdornment>
        ),
        endAdornment: (
          <InputAdornment position="end">
            <IconButton
              size="small"
              onClick={(e) => {
                e.stopPropagation();
                modifyValue("increment");
              }}
            >
              <AddRoundedIcon fontSize="small" />
            </IconButton>
          </InputAdornment>
        ),
        // Spread props at the end to allow Input prop overrides
        ...InputProps,
      }}
      inputProps={{
        pattern: "[0-9]-",
      }}
      sx={{
        maxWidth: "100%",
        width: "fit-content",

        "& .MuiInputBase-input.MuiOutlinedInput-input": {
          height: height ?? "auto",
          width: value?.length + "ch",
        },
      }}
      onKeyDown={(evt) => {
        switch (evt.code) {
          case "ArrowUp":
            evt.preventDefault();
            modifyValue("increment");
            break;

          case "ArrowDown":
            evt.preventDefault();
            modifyValue("decrement");
            break;

          default:
            break;
        }
      }}
      // Spread props at the end to allow prop overrides
      {...props}
    />
  );
};

