import { useRef, useEffect, useState, useContext } from "react";
import {
  Stack,
  Typography,
  Avatar,
  IconButton,
  Box,
  Menu,
  MenuItem,
  ListItemIcon,
  ListItemText,
  Tooltip,
} from "@mui/material";
import MoreVertRoundedIcon from "@mui/icons-material/MoreVertRounded";
import CheckRoundedIcon from "@mui/icons-material/CheckRounded";
import DriveFileRenameOutlineRoundedIcon from "@mui/icons-material/DriveFileRenameOutlineRounded";
import LinkRoundedIcon from "@mui/icons-material/LinkRounded";
import DeleteRoundedIcon from "@mui/icons-material/DeleteRounded";
import RestartAltRoundedIcon from "@mui/icons-material/RestartAltRounded";
import { formatDistanceToNow, isValid } from "date-fns";
import { useLocation, useParams } from "react-router";
import { useSelector } from "react-redux";

import { useUpdateCommentStatusMutation } from "../../services/accounts";
import { MD5 } from "../../../utility/md5";
import { InputField } from "./InputField";
import { CommentContext } from "../../contexts/CommentProvider";
import { AppState } from "../../store/types";
import { User } from "../../services/types";
import { ConfirmDeleteModal } from "./ConfirmDeleteModal";
import {
  useDeleteCommentMutation,
  useDeleteReplyMutation,
} from "../../services/accounts";

const URL_REGEX =
  /(?:http[s]?:\/\/.)?(?:www\.)?[-a-zA-Z0-9@%._\+~#=]{2,256}\.[a-z]{2,6}\b(?:[-a-zA-Z0-9@:%_\+.~#?&\/\/=]*)/gm;

type PathParams = {
  modelZUID: string;
  itemZUID: string;
  resourceZUID: string;
  commentZUID: string;
};
type CommentItemProps = {
  commentZUID: string;
  body: string;
  creator: {
    name: string;
    ZUID: string;
    email: string;
  };
  createdOn: string;
  parentCommentZUID: string;
  withResolveButton?: boolean;
  withReopenButton?: boolean;
  onParentCommentDeleted: () => void;
  commentCount: number;
};
export const CommentItem = ({
  commentZUID,
  body,
  creator,
  createdOn,
  parentCommentZUID,
  withResolveButton,
  withReopenButton,
  onParentCommentDeleted,
  commentCount,
}: CommentItemProps) => {
  const { resourceZUID } = useParams<PathParams>();
  const location = useLocation();
  const [_, __, commentZUIDtoEdit, setCommentZUIDtoEdit] =
    useContext(CommentContext);
  const [
    deleteComment,
    { isLoading: isDeletingComment, isSuccess: isCommentDeleted },
  ] = useDeleteCommentMutation();
  const [
    deleteReply,
    { isLoading: isDeletingReply, isSuccess: isReplyDeleted },
  ] = useDeleteReplyMutation();
  const [updateCommentStatus, { isLoading: isUpdatingCommentStatus }] =
    useUpdateCommentStatusMutation();
  const [menuAnchorEl, setMenuAnchorEl] = useState<HTMLElement>();
  const [isCopied, setIsCopied] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const commentBodyRef = useRef<HTMLParagraphElement>();
  const loggedInUser: User = useSelector((state: AppState) => state.user);

  const isLoggedInUserCommentCreator = loggedInUser?.ZUID === creator?.ZUID;

  const createdDate = createdOn ? new Date(createdOn) : null;
  const createdAgo =
    createdDate && isValid(createdDate)
      ? formatDistanceToNow(createdDate, { addSuffix: true })
      : "";

  useEffect(() => {
    if (commentBodyRef.current) {
      const hyperlinkedContent = body?.replaceAll(URL_REGEX, (text) => {
        // Highlights @ mentions
        if (text.includes("@") && text.startsWith("@")) {
          return `<span style="color: #FF5D0A">${text}</span>`;
        }

        // Converts url strings to anchor tags
        if (!text.includes("@")) {
          const url =
            text.includes("http://") || text.includes("https://")
              ? text
              : `https://${text}`;

          return `<a href="${url}" target="_blank" rel="noopener noreferrer" style="color: #FF5D0A; text-decoration: none">${text}</a>`;
        }

        return text;
      });

      commentBodyRef.current.innerHTML = hyperlinkedContent;
    }
  }, [body, commentBodyRef, commentZUIDtoEdit]);

  useEffect(() => {
    if (isCommentDeleted || isReplyDeleted) {
      setIsDeleteModalOpen(false);

      if (commentZUID.startsWith("24")) {
        onParentCommentDeleted();
      }
    }
  }, [isCommentDeleted, isReplyDeleted]);

  const handleCopyClick = () => {
    navigator?.clipboard
      ?.writeText(
        `${window.location.origin}${location.pathname}/${commentZUID}`
      )
      .then(() => {
        setIsCopied(true);
        setTimeout(() => {
          setIsCopied(false);
        }, 500);
      })
      .catch((err) => {
        console.error(err);
      });
  };

  const handleDeleteComment = () => {
    if (commentZUID.startsWith("24")) {
      deleteComment({
        resourceZUID,
        commentZUID,
      });
    } else {
      deleteReply({
        resourceZUID,
        commentZUID,
        parentCommentZUID,
      });
    }
  };

  const handleUpdateCommentStatus = (isResolved: boolean) => {
    updateCommentStatus({
      resourceZUID,
      commentZUID,
      parentCommentZUID,
      isResolved,
    });
  };

  return (
    <>
      <Box data-cy="CommentItem" id={commentZUID}>
        <Stack gap={1.5}>
          <Stack gap={1.5} direction="row">
            <Stack flex={1} direction="row" gap={1.5} alignItems="center">
              <Avatar
                sx={{ width: 32, height: 32 }}
                src={`https://www.gravatar.com/avatar/${MD5(
                  creator?.email || ""
                )}?s=32`}
              />
              <Stack>
                <Typography fontWeight={700} variant="body2">
                  {creator?.name}
                </Typography>
                <Typography
                  variant="body3"
                  fontWeight={600}
                  color="text.secondary"
                >
                  {createdAgo}
                </Typography>
              </Stack>
            </Stack>
            <Box>
              {withResolveButton && (
                <Tooltip
                  title="Mark as Resolved"
                  placement="top-start"
                  disableInteractive
                >
                  <IconButton
                    data-cy="ResolveCommentButton"
                    color="primary"
                    size="small"
                    onClick={() => handleUpdateCommentStatus(true)}
                    disabled={isUpdatingCommentStatus}
                  >
                    <CheckRoundedIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              )}
              <Tooltip
                title="More Options"
                placement="top-start"
                disableInteractive
              >
                <IconButton
                  data-cy="CommentMenuButton"
                  size="small"
                  onClick={(evt) => setMenuAnchorEl(evt.currentTarget)}
                >
                  <MoreVertRoundedIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            </Box>
          </Stack>
          {commentZUIDtoEdit === commentZUID ? (
            <InputField
              isEditMode
              editModeValue={body}
              isFirstComment={false}
              onCancel={() => setCommentZUIDtoEdit(null)}
              commentResourceZUID={resourceZUID}
              parentCommentZUID={parentCommentZUID}
              commentCount={commentCount}
            />
          ) : (
            <Typography
              variant="body2"
              ref={commentBodyRef}
              sx={{
                overflowWrap: "break-word",
                "& ul": {
                  ml: 2,
                },
                "& ol": {
                  ml: 2,
                },
              }}
            ></Typography>
          )}
        </Stack>
        {menuAnchorEl && (
          <Menu
            anchorEl={menuAnchorEl}
            open
            onClose={() => setMenuAnchorEl(null)}
            anchorOrigin={{
              vertical: "bottom",
              horizontal: "right",
            }}
            transformOrigin={{
              vertical: "top",
              horizontal: "right",
            }}
            slotProps={{
              paper: {
                sx: {
                  width: 160,
                },
              },
            }}
          >
            {isLoggedInUserCommentCreator && (
              <MenuItem
                data-cy="EditCommentButton"
                onClick={() => {
                  setMenuAnchorEl(null);
                  setCommentZUIDtoEdit(commentZUID);
                }}
              >
                <ListItemIcon>
                  <DriveFileRenameOutlineRoundedIcon />
                </ListItemIcon>
                <ListItemText>Edit</ListItemText>
              </MenuItem>
            )}
            <MenuItem data-cy="CopyCommentLinkButton" onClick={handleCopyClick}>
              <ListItemIcon>
                {isCopied ? <CheckRoundedIcon /> : <LinkRoundedIcon />}
              </ListItemIcon>
              <ListItemText>Copy Link</ListItemText>
            </MenuItem>
            {withReopenButton && (
              <MenuItem
                onClick={() => {
                  setMenuAnchorEl(null);
                  handleUpdateCommentStatus(false);
                }}
              >
                <ListItemIcon>
                  <RestartAltRoundedIcon />
                </ListItemIcon>
                <ListItemText>Re-open</ListItemText>
              </MenuItem>
            )}
            {isLoggedInUserCommentCreator && (
              <MenuItem
                data-cy="DeleteCommentButton"
                onClick={() => {
                  setMenuAnchorEl(null);
                  setIsDeleteModalOpen(true);
                }}
              >
                <ListItemIcon>
                  <DeleteRoundedIcon />
                </ListItemIcon>
                <ListItemText>Delete</ListItemText>
              </MenuItem>
            )}
          </Menu>
        )}
      </Box>
      {isDeleteModalOpen && (
        <ConfirmDeleteModal
          isDeletingComment={isDeletingComment || isDeletingReply}
          onClose={() => setIsDeleteModalOpen(false)}
          onConfirmDelete={handleDeleteComment}
        />
      )}
    </>
  );
};

import {
  Divider,
  Paper,
  Popper,
  Backdrop,
  PopperPlacementType,
  Stack,
  Skeleton,
  Avatar,
  Typography,
} from "@mui/material";
import { theme } from "@zesty-io/material";
import { Fragment, useContext, useEffect, useRef, useState } from "react";

import { CommentItem } from "./CommentItem";
import { InputField } from "./InputField";
import { useGetCommentThreadQuery } from "../../services/accounts";
import { CommentContext } from "../../contexts/CommentProvider";
import { useParams } from "react-router";
import { User } from "../../services/types";
import { useSelector } from "react-redux";
import { AppState } from "../../store/types";
import { MD5 } from "../../../utility/md5";
import { ItemLockContext } from "../../../apps/content-editor/src/app/views/ItemEdit/ItemEdit";

type PathParams = {
  modelZUID: string;
  itemZUID: string;
  resourceZUID: string;
  commentZUID: string;
};
type CommentsListProps = {
  anchorEl: Element;
  onClose: () => void;
  isResolved: boolean;
  parentCommentZUID: string;
  isLoadingParentCommentZUID: boolean;
};
export const CommentsList = ({
  anchorEl,
  onClose,
  isResolved,
  parentCommentZUID,
  isLoadingParentCommentZUID,
}: CommentsListProps) => {
  const { resourceZUID, commentZUID } = useParams<PathParams>();
  const [_, __, commentZUIDtoEdit] = useContext(CommentContext);
  const isLocked = useContext<boolean>(ItemLockContext);
  const [popperTopOffset, setPopperTopOffset] = useState(0);
  const [popperBottomOffset, setPopperBottomOffset] = useState(0);
  const [placement, setPlacement] =
    useState<PopperPlacementType>("bottom-start");
  const topOffsetRef = useRef<HTMLDivElement>();
  const loggedInUser: User = useSelector((state: AppState) => state.user);

  const {
    data: commentThread,
    isLoading: isLoadingCommentThread,
    isUninitialized: isCommentThreadUninitialized,
  } = useGetCommentThreadQuery(
    { commentZUID: parentCommentZUID },
    { skip: !parentCommentZUID }
  );

  useEffect(() => {
    if (
      window.innerHeight - anchorEl?.getBoundingClientRect().top >
      window.innerHeight * 0.3
    ) {
      setPlacement("bottom-start");
    } else {
      setPlacement("top-start");
    }

    setTimeout(() => {
      if (topOffsetRef.current?.getBoundingClientRect()) {
        const { top, bottom } = topOffsetRef.current.getBoundingClientRect();

        setPopperTopOffset(top);
        setPopperBottomOffset(bottom);
      }
    });

    // HACK: Prevents UI flicker when popper renders and is temporarily out of bounds
    document.body.style.overflow = "hidden";

    return () => {
      document.body.style.overflow = null;
    };
  }, []);

  useEffect(() => {
    // Scrolls to a specific reply indicated in the search params
    if (!isLoadingCommentThread) {
      setTimeout(() => {
        const replyEl = document.getElementById(commentZUID);

        if (replyEl) {
          replyEl.scrollIntoView();
        }
      });
    }
  }, [commentZUID, isLoadingCommentThread]);

  const calculateMaxHeight = () => {
    if (placement === "bottom-start") {
      return window.innerHeight - popperTopOffset - 8;
    } else {
      return popperBottomOffset - 8;
    }
  };

  return (
    <Backdrop
      id="popperBg"
      open
      sx={{
        zIndex: theme.zIndex.modal,
        backgroundColor: "transparent",
      }}
      onClick={(evt) => {
        const element = evt.target as HTMLElement;

        if (element?.id === "popperBg") {
          onClose();
        }
      }}
    >
      <Popper
        open
        disablePortal={isLocked}
        anchorEl={anchorEl}
        placement={placement}
        sx={{
          zIndex: theme.zIndex.modal,
        }}
        ref={topOffsetRef}
        popperOptions={{
          modifiers: [
            {
              name: "offset",
              options: {
                offset: [0, 4],
              },
            },
          ],
        }}
      >
        <Paper
          elevation={8}
          sx={{
            width: 360,
            p: 2,
            maxHeight: calculateMaxHeight(),
            overflow: "auto",
            boxSizing: "border-box",
          }}
        >
          {(isLoadingCommentThread || isLoadingParentCommentZUID) && (
            <CommentItemLoading />
          )}
          {commentThread?.map((comment, index) => (
            <Fragment key={comment.ZUID}>
              <CommentItem
                commentZUID={comment.ZUID}
                body={comment.content}
                createdOn={comment.createdAt}
                creator={{
                  ZUID: comment.createdByUserZUID,
                  name: comment.createdByUserName,
                  email: comment.createdByUserEmail,
                }}
                withResolveButton={index === 0 && !isResolved}
                withReopenButton={index === 0 && isResolved}
                parentCommentZUID={parentCommentZUID}
                onParentCommentDeleted={onClose}
                commentCount={commentThread?.length || 0}
              />
              {index + 1 < commentThread?.length && (
                <Divider sx={{ my: 1.5 }} />
              )}
            </Fragment>
          ))}
          {((!isLoadingCommentThread &&
            !isCommentThreadUninitialized &&
            !commentThread?.length) ||
            (!isLoadingParentCommentZUID && !parentCommentZUID)) && (
            <Stack flex={1} direction="row" gap={1.5} alignItems="center">
              <Avatar
                sx={{ width: 32, height: 32 }}
                src={`https://www.gravatar.com/avatar/${MD5(
                  loggedInUser?.email || ""
                )}?s=32`}
              />
              <Stack>
                <Typography fontWeight={700} variant="body2">
                  {loggedInUser?.firstName} {loggedInUser?.lastName}
                </Typography>
                <Typography
                  variant="body3"
                  fontWeight={600}
                  color="text.secondary"
                >
                  right now
                </Typography>
              </Stack>
            </Stack>
          )}
          {!commentZUIDtoEdit && (
            <InputField
              isFirstComment={!commentThread?.length}
              onCancel={onClose}
              commentResourceZUID={resourceZUID}
              parentCommentZUID={parentCommentZUID}
              commentCount={commentThread?.length || 0}
            />
          )}
        </Paper>
      </Popper>
    </Backdrop>
  );
};

