import { IconButton, Button, alpha, Box, Tooltip } from "@mui/material";
import AddCommentRoundedIcon from "@mui/icons-material/AddCommentRounded";
import CommentRoundedIcon from "@mui/icons-material/CommentRounded";
import { useState, useRef, useEffect, useMemo, useContext } from "react";
import { useParams, useHistory, useLocation } from "react-router";
import { useIntersection } from "react-use";

import { CommentsList } from "./CommentsList";
import { useGetCommentByResourceQuery } from "../../services/accounts";
import { CommentContext } from "../../contexts/CommentProvider";

type PathParams = {
  modelZUID: string;
  itemZUID: string;
  resourceZUID: string;
};
type CommentProps = {
  resourceZUID: string;
};
export const Comment = ({ resourceZUID }: CommentProps) => {
  const history = useHistory();
  const location = useLocation();
  const [_, __, ___, setCommentZUIDtoEdit] = useContext(CommentContext);
  const buttonContainerRef = useRef<HTMLDivElement>();
  const intersection = useIntersection(buttonContainerRef, {
    threshold: 1,
  });
  const isInView = intersection && intersection.intersectionRatio >= 1;
  const { itemZUID, resourceZUID: activeResourceZUID } =
    useParams<PathParams>();
  const { data: comment, isLoading: isLoadingComment } =
    useGetCommentByResourceQuery(
      { itemZUID, resourceZUID },
      { skip: !resourceZUID || !isInView }
    );
  const [isCommentListOpen, setIsCommentListOpen] = useState(false);
  const [isButtonAutoscroll, setIsButtonAutoscroll] = useState(true);

  const parentComment = useMemo(() => {
    return comment?.find((comment) => comment.resourceZUID === itemZUID);
  }, [comment, itemZUID]);

  useEffect(() => {
    if (!!resourceZUID) {
      setIsCommentListOpen(
        activeResourceZUID === resourceZUID && !!buttonContainerRef.current
      );
    }
  }, [buttonContainerRef.current, activeResourceZUID]);

  useEffect(() => {
    // Autoscrolls to the button before opening the comment list popup
    // Only applicable when popup is opened via deeplink
    if (isCommentListOpen && isButtonAutoscroll) {
      buttonContainerRef.current?.scrollIntoView();
    }
  }, [isCommentListOpen, isButtonAutoscroll]);

  const handleOpenCommentsList = () => {
    setIsButtonAutoscroll(false);
    history.replace(`${location.pathname}/comment/${resourceZUID}`);
  };

  if (!resourceZUID) {
    return <></>;
  }

  return (
    <>
      <Box ref={buttonContainerRef}>
        {parentComment ? (
          <Tooltip
            title="View Open Comment"
            disableInteractive
            placement="top-start"
          >
            <Button
              data-cy="OpenCommentsButton"
              size="xsmall"
              endIcon={<CommentRoundedIcon />}
              disabled={isLoadingComment}
              onClick={handleOpenCommentsList}
              sx={{
                backgroundColor: (theme) =>
                  parentComment.resolved
                    ? "action.hover"
                    : alpha(theme.palette.primary.main, 0.04),
                minWidth: 0,
                fontWeight: 600,
                fontSize: 14,
                lineHeight: "14px",
                px: 0.5,
                py: 0.25,
                color: parentComment.resolved
                  ? "text.secondary"
                  : "primary.main",

                "&:hover": {
                  backgroundColor: (theme) =>
                    alpha(theme.palette.primary.main, 0.08),
                  color: "primary.main",
                },

                "&:hover .MuiButton-endIcon .MuiSvgIcon-root": {
                  fill: (theme) => theme.palette.primary.main,
                },

                "& .MuiButton-endIcon": {
                  ml: 0.5,
                  mr: 0,
                },

                "& .MuiButton-endIcon .MuiSvgIcon-root": {
                  fontSize: 16,
                  fill: (theme) =>
                    parentComment.resolved
                      ? theme.palette.action.active
                      : theme.palette.primary.main,
                },
              }}
            >
              {/* NOTE: Adding 1 since we need to include the initial comment **/}
              {parentComment.replyCount + 1}
            </Button>
          </Tooltip>
        ) : (
          <Tooltip
            title="Add New Comment"
            disableInteractive
            placement="top-start"
          >
            <IconButton
              data-cy="OpenCommentsButton"
              size="xxsmall"
              disabled={isLoadingComment}
              onClick={handleOpenCommentsList}
              sx={{
                backgroundColor: isCommentListOpen
                  ? (theme) => alpha(theme.palette.primary.main, 0.08)
                  : "transparent",
                color: isCommentListOpen ? "primary.main" : "action",
                "&:hover": {
                  backgroundColor: (theme) =>
                    alpha(theme.palette.primary.main, 0.08),
                  color: "primary.main",
                },
              }}
            >
              <AddCommentRoundedIcon sx={{ fontSize: 16 }} />
            </IconButton>
          </Tooltip>
        )}
      </Box>
      {isCommentListOpen && (
        <CommentsList
          isLoadingParentCommentZUID={isLoadingComment}
          parentCommentZUID={parentComment?.ZUID}
          anchorEl={buttonContainerRef.current}
          onClose={() => {
            setIsButtonAutoscroll(false);
            setCommentZUIDtoEdit(null);

            // Makes sure that we can properly pop back to the component where the comment was rendered
            const pathnameArr = location.pathname?.split("/");
            const commentIndex = pathnameArr.findIndex(
              (path) => path === "comment"
            );

            history.replace(pathnameArr?.slice(0, commentIndex)?.join("/"));
          }}
          isResolved={parentComment?.resolved}
        />
      )}
    </>
  );
};

import { memo, useState } from "react";
import {
  Stack,
  Typography,
  Tooltip,
  Menu,
  MenuItem,
  Button,
  Box,
} from "@mui/material";
import InfoRoundedIcon from "@mui/icons-material/InfoRounded";
import KeyboardArrowDownRoundedIcon from "@mui/icons-material/KeyboardArrowDownRounded";
import { useLocation } from "react-router";

import { InteractiveTooltip } from "../../../../../../../shell/components/InteractiveTooltip";
import { FieldTooltipBody } from "./FieldTooltipBody";
import { ContentModelField } from "../../../../../../../shell/services/types";
import pluralizeWord from "../../../../../../../utility/pluralizeWord";
import { Comment } from "../../../../../../../shell/components/Comment";

export type EditorType =
  | "markdown"
  | "wysiwyg_basic"
  | "article_writer"
  | "html";
export const EditorTypes: Record<EditorType, string> = {
  markdown: "Markdown",
  wysiwyg_basic: "WYSIWYG",
  article_writer: "Inline",
  html: "HTML",
};
export type Error = {
  MISSING_REQUIRED?: boolean;
  EXCEEDING_MAXLENGTH?: number;
  LACKING_MINLENGTH?: number;
  CUSTOM_ERROR?: string;
  REGEX_PATTERN_MISMATCH?: string;
  REGEX_RESTRICT_PATTERN_MATCH?: string;
  INVALID_RANGE?: string;
  INVALID_BLOCK_VARIANT?: boolean;
};

type FieldShellProps = {
  settings: Partial<ContentModelField>;
  valueLength?: number;
  endLabel?: JSX.Element;
  maxLength?: number;
  minLength?: number;
  withLengthCounter?: boolean;
  missingRequired?: boolean;
  onEditorChange?: (editorType: string) => void;
  editorType?: EditorType;
  customTooltip?: string;
  children: JSX.Element;
  errors: Error;
  withInteractiveTooltip?: boolean;
};
export const FieldShell = ({
  settings,
  endLabel,
  valueLength,
  maxLength = 150,
  minLength = 0,
  withLengthCounter = false,
  onEditorChange,
  editorType = "markdown",
  customTooltip,
  children,
  errors,
  withInteractiveTooltip = true,
}: FieldShellProps) => {
  const location = useLocation();
  const [anchorEl, setAnchorEl] = useState<HTMLButtonElement>(null);

  const getErrorMessage = (errors: Error) => {
    const errorMessages = [];

    if (errors?.MISSING_REQUIRED) {
      errorMessages.push("Required Field. Please enter a value.");
    }

    if (errors?.EXCEEDING_MAXLENGTH > 0) {
      errorMessages.push(
        `Exceeding by ${errors.EXCEEDING_MAXLENGTH} ${pluralizeWord(
          "character",
          errors.EXCEEDING_MAXLENGTH
        )}.`
      );
    }

    if (errors?.LACKING_MINLENGTH > 0) {
      errorMessages.push(
        `Requires ${errors.LACKING_MINLENGTH} more ${pluralizeWord(
          "character",
          errors.LACKING_MINLENGTH
        )}.`
      );
    }

    if (errors?.REGEX_PATTERN_MISMATCH) {
      errorMessages.push(errors.REGEX_PATTERN_MISMATCH);
    }

    if (errors?.REGEX_RESTRICT_PATTERN_MATCH) {
      errorMessages.push(errors.REGEX_RESTRICT_PATTERN_MATCH);
    }

    if (errors?.INVALID_RANGE) {
      errorMessages.push(errors.INVALID_RANGE);
    }

    if (errors?.CUSTOM_ERROR) {
      errorMessages.push(errors.CUSTOM_ERROR);
    }

    if (errors?.INVALID_BLOCK_VARIANT) {
      errorMessages.push("Please select a block variant.");
    }

    if (errorMessages.length === 0) {
      return "";
    }

    if (errorMessages.length === 1) {
      return errorMessages[0];
    }

    return (
      <Box component="ul" ml={3}>
        {errorMessages.map((msg) => (
          <li>{msg}</li>
        ))}
      </Box>
    );
  };

  const isCreateNewItemPage = location?.pathname?.split("/")?.pop() === "new";

  return (
    <Stack gap={0.5}>
      <Stack direction="row" justifyContent="space-between">
        <FieldLabel
          settings={settings}
          customTooltip={customTooltip}
          withInteractiveTooltip={withInteractiveTooltip}
        />
        <Stack
          direction="row"
          gap={0.5}
          flexWrap="wrap"
          justifyContent="flex-end"
        >
          {["article_writer", "markdown"].includes(settings?.datatype) && (
            <>
              <Button
                size="xsmall"
                variant="contained"
                color="inherit"
                endIcon={<KeyboardArrowDownRoundedIcon sx={{ fontSize: 20 }} />}
                sx={{
                  height: 20,
                  backgroundColor: "common.white",
                  p: 0,
                  color: "text.disabled",

                  "&:hover": {
                    backgroundColor: "common.white",
                    boxShadow: "none",
                  },

                  "&:active": {
                    boxShadow: "none",
                  },
                  "& .MuiButton-endIcon": {
                    ml: 0.5,
                  },
                }}
                onClick={(evt) => {
                  setAnchorEl(evt.currentTarget);
                }}
              >
                {EditorTypes[editorType]}
              </Button>
              <Menu
                open={!!anchorEl}
                anchorEl={anchorEl}
                onClose={() => setAnchorEl(null)}
              >
                {Object.entries(EditorTypes).map(([key, value]) => (
                  <MenuItem
                    key={key}
                    onClick={() => {
                      setAnchorEl(null);
                      onEditorChange?.(key);
                    }}
                  >
                    {value}
                  </MenuItem>
                ))}
              </Menu>
            </>
          )}
          {endLabel}
          {!isCreateNewItemPage && <Comment resourceZUID={settings.ZUID} />}
        </Stack>
      </Stack>
      {settings?.description && (
        <Typography
          variant="body2"
          color="text.secondary"
          sx={{ overflowWrap: "break-word", wordBreak: "break-word" }}
        >
          {settings?.description}
        </Typography>
      )}
      {children}
      <Stack direction="row" justifyContent="space-between">
        <Typography variant="body2" color="error.dark">
          {getErrorMessage(errors)}
        </Typography>
        {withLengthCounter && (
          <Typography variant="body2" color="text.disabled">
            {valueLength}
            {!!minLength &&
              ` (min. ${minLength} ${pluralizeWord("character", minLength)})`}
            {!!maxLength && `/${maxLength}`}
          </Typography>
        )}
        {settings?.settings?.minValue !== undefined &&
          settings?.settings?.maxValue !== undefined && (
            <Typography variant="body2" color="text.disabled">
              Min: {settings?.settings?.minValue} | Max:{" "}
              {settings?.settings?.maxValue}
            </Typography>
          )}
      </Stack>
    </Stack>
  );
};

type FieldLabelProps = {
  settings: Partial<ContentModelField>;
  customTooltip?: string;
  withInteractiveTooltip?: boolean;
};
const FieldLabel = memo(
  ({
    settings,
    customTooltip,
    withInteractiveTooltip = true,
  }: FieldLabelProps) => {
    return (
      <Stack direction="row" gap={0.5} alignItems="center">
        {withInteractiveTooltip ? (
          <InteractiveTooltip
            slots={{
              title: (
                <Typography
                  variant="body2"
                  fontWeight={600}
                  color="text.primary"
                  sx={{
                    "&:hover": { textDecoration: "underline" },
                  }}
                >
                  {settings?.label} {settings?.required && "*"}
                </Typography>
              ),
              body: <FieldTooltipBody data={settings} />,
            }}
            TooltipProps={{
              placement: "top-start",
            }}
            PaperProps={{
              sx: {
                width: 400,
                mb: 1.25,
                borderRadius: 2,
              },
            }}
          />
        ) : (
          <Typography variant="body2" fontWeight={600} color="text.primary">
            {settings?.label} {settings?.required && "*"}
