    {
      text: "Code Block",
      icon: "code-sample",
      action: () => {
        editor.execCommand("CodeSample");
      },
    },
    {
      text: "Link",
      icon: "link",
      action: () => {
        editor.execCommand("mceLink");
      },
    },
    {
      text: "Embed Social Media",
      icon: "zesty-embed",
      action: () => {
        editor.execCommand("mceSocialMediaEmbed");
      },
    },
    {
      text: "Table",
      icon: "table",
      action: () => {
        editor.execCommand("mceInsertTableDialog");
      },
    },
    {
      text: "Bulleted list",
      icon: "unordered-list",
      action: () => {
        editor.execCommand("InsertUnorderedList");
