          {!!replace ? "Replace" : "Done"}
        </Button>
        <IconButton size="small" onClick={onClose}>
          <CloseRounded fontSize="small" />
        </IconButton>
      </Stack>
    </DialogTitle>
  );
};

import { GridFilterOperator } from "@mui/x-data-grid-pro";

export const statusFilterOperator: GridFilterOperator = {
  label: "equals",
  value: "statusEquals",
  getApplyFilterFn: (filterItem) => {
    if (!filterItem.value) {
      return null;
    }

    return (params): boolean => {
      const version = params.value;
      const status = filterItem.value;

      if (status === "published") {
        return (
          version?.itemData?.publishing?.publishAt &&
          !version?.itemData?.scheduling?.publishAt
        );
      } else if (status === "scheduled") {
        return version?.itemData?.scheduling?.publishAt;
      } else if (status === "notPublished") {
        return (
          !version?.itemData?.publishing?.publishAt &&
          !version?.itemData?.scheduling?.publishAt
        );
      }
      return true;
    };
  },
};

import { GridFilterOperator } from "@mui/x-data-grid-pro";

export const userFilterOperator: GridFilterOperator = {
  label: "equals",
  value: "userEquals",
  getApplyFilterFn: (filterItem) => {
    if (!filterItem.value) {
      return null;
    }

    return (params): boolean => {
      const version = params.value;
      return version?.itemData?.meta?.createdByUserZUID === filterItem.value;
    };
  },
};

import { GridFilterOperator } from "@mui/x-data-grid-pro";
import { format, isValid } from "date-fns";

export const keywordSearchFilterOperator: GridFilterOperator = {
  label: "contains",
  value: "keywordContains",
  getApplyFilterFn: (filterItem) => {
    if (!filterItem.value) {
      return null;
    }

    const fmtLower = (value?: string) => {
      if (!value) return "";
      const d = new Date(value);
      return isValid(d) ? format(d, "MMM d, yyyy h:mm a").toLowerCase() : "";
    };

    return (params): boolean => {
      const row = params;
      const searchValue = filterItem.value.toLowerCase();

      // Check title
      const title = row.title;
      const titleMatch =
        title?.primary?.toString()?.toLowerCase().includes(searchValue) ||
        title?.secondary?.toString()?.toLowerCase().includes(searchValue) ||
        false;

      // Check version
      const version = row.version;
      const createdBy = version?.itemData?.createdByName?.toLowerCase() || "";
      const publishedBy =
        version?.publishData?.publishedByName?.toLowerCase() || "";
      const scheduledBy =
        version?.scheduleData?.scheduledByName?.toLowerCase() || "";

      const createdAt = fmtLower(version?.itemData?.meta?.createdAt);
      const updatedAt = fmtLower(version?.itemData?.meta?.updatedAt);

      const versionMatch =
        createdBy.includes(searchValue) ||
        publishedBy.includes(searchValue) ||
        scheduledBy.includes(searchValue) ||
        createdAt.includes(searchValue) ||
        updatedAt.includes(searchValue);

      return titleMatch || versionMatch;
    };
  },
};

import { GridFilterOperator } from "@mui/x-data-grid-pro";
import { getDateFilterFnByValues } from "../../Filters/DateFilter/getDateFilter";

export const dateFilterOperator: GridFilterOperator = {
  label: "dateFilter",
  value: "dateFilter",
  getApplyFilterFn: (filterItem) => {
    if (!filterItem.value) {
      return null;
    }

    return (params): boolean => {
      const version = params.value;
      const dateFilterFn = getDateFilterFnByValues(filterItem.value);

      if (!dateFilterFn || !version?.itemData?.meta?.updatedAt) {
        return false;
      }

      return dateFilterFn(version.itemData.meta.updatedAt);
    };
  },
};

