import { useState, useMemo, useRef } from "react";
import {
  MenuList,
  TextField,
  MenuItem,
  Typography,
  Popover,
  Box,
  Stack,
  ListSubheader,
  Tooltip,
} from "@mui/material";
import { Search } from "@mui/icons-material";
import { format, isValid } from "date-fns";

import { ContentItem } from "../../services/types";
import { useGetUsersQuery } from "../../services/accounts";
import { NoSearchResults } from "../NoSearchResults";
import { NoVariant } from "./NoVariant";
import blockPlaceholder from "../../../../public/images/blockPlaceholder.png";

type VariantSelectorProps = {
  anchorEl: Element;
  onClose: () => void;
  variants: ContentItem[];
  blockModelZUID: string;
  blockModelName: string;
  onVariantSelected: (ZUID: string) => void;
};
export const VariantSelector = ({
  anchorEl,
  onClose,
  variants,
  blockModelZUID,
  blockModelName,
  onVariantSelected,
}: VariantSelectorProps) => {
  const { data: users } = useGetUsersQuery();
  const [filterKeyword, setFilterKeyword] = useState("");
  const filterTextField = useRef(null);
  const variantsRef = useRef<HTMLLIElement[]>([]);

  const filteredVariants = useMemo(() => {
    if (!filterKeyword) return variants;

    return variants?.filter((variant) =>
      variant?.web?.metaTitle
        ?.toLowerCase()
        ?.includes(filterKeyword?.toLowerCase()?.trim())
    );
  }, [variants, filterKeyword]);

  const getUserName = (ZUID: string) => {
    const user = users?.find((user) => user.ZUID === ZUID);

    if (!!user) {
      return `${user.firstName} ${user.lastName}`;
    }

    return "";
  };

  return (
    <Popover
      open
      onClose={onClose}
      anchorEl={anchorEl}
      anchorOrigin={{
        vertical: "bottom",
        horizontal: "left",
      }}
      transformOrigin={{
        vertical: "top",
        horizontal: "left",
      }}
      PaperProps={{
        elevation: 8,
        sx: {
          mt: 1,
          width: 436,
          maxHeight: 480,
        },
      }}
    >
      <MenuList sx={{ pt: 0 }}>
        <ListSubheader
          sx={{
            height: 72,
            borderBottom: 1,
            borderColor: "border",
            boxSizing: "border-box",
            p: 2,
          }}
        >
          <TextField
            autoFocus
            fullWidth
            placeholder="Search variants"
            ref={filterTextField}
            value={filterKeyword}
            onChange={(evt) => {
              setFilterKeyword(evt.currentTarget.value);

              if (!!evt.currentTarget.value) {
                variantsRef.current?.[0]?.classList.add("hover");
              } else {
                variantsRef.current?.forEach((element) =>
                  element.classList.remove("hover")
                );
              }
            }}
            InputProps={{
              startAdornment: <Search color="action" />,
            }}
            onKeyDown={(e: React.KeyboardEvent) => {
              const allowedKeys = ["ArrowUp", "ArrowDown", "Escape", "Enter"];

              if (!allowedKeys.includes(e.key)) {
                e.stopPropagation();
              } else if (e.key === "Enter" && !!filterKeyword) {
                variantsRef.current?.[0]?.click();
              }
            }}
          />
        </ListSubheader>
        {!variants?.length ? (
          <NoVariant
            blockModelName={blockModelName}
            blockModelZUID={blockModelZUID}
          />
        ) : filteredVariants?.length ? (
          filteredVariants?.map((variant, index) => {
            const d = variant.web?.updatedAt
              ? new Date(variant.web.updatedAt)
              : null;
            const updatedOn = d && isValid(d) ? format(d, "MMMM d") : "";
            return (
              <MenuItem
                ref={(node) => (variantsRef.current[index] = node)}
                data-cy={`Variant_${index}`}
                key={variant?.meta?.ZUID}
                divider={index + 1 < variants?.length}
                onClick={() => onVariantSelected(variant?.meta?.ZUID)}
                sx={{
                  display: "flex",
                  px: 2,
                  py: 1.75,
                  gap: 1.5,
                  borderColor: "border",

                  "&.hover": {
                    "-webkit-text-decoration": "none",
                    textDecoration: "none",
                    bgcolor: "rgba(16, 24, 40, 0.04)",
                  },
                }}
              >
                <Tooltip
                  enterDelay={500}
                  enterNextDelay={500}
                  disableInteractive
                  placement="left"
                  title={
                    <Box
                      component="img"
                      width={468}
                      src={
                        (variant?.data?.og_image as string) || blockPlaceholder
                      }
                      loading="lazy"
                      borderRadius={2}
                      sx={{
                        objectFit: "contain",
                      }}
                    ></Box>
                  }
                  components={{ Tooltip: Box }}
                  slotProps={{
                    popper: {
                      sx: {
                        maxWidth: "none",
                      },
                    },
                    tooltip: {
                      sx: {
                        mr: 1,
                      },
                    },
                  }}
                >
                  <Box
                    component="img"
                    width={125}
                    src={
                      (variant?.data?.og_image as string) || blockPlaceholder
                    }
                    loading="lazy"
                    sx={{
                      objectFit: "contain",
                    }}
                  ></Box>
                </Tooltip>
                <Stack width={267}>
                  <Typography noWrap variant="body1" fontWeight={700}>
                    {variant?.web?.metaTitle}
                  </Typography>
                  <Typography
                    variant="body3"
                    color="text.secondary"
                    mt={0.5}
                    fontWeight={600}
                    sx={{
                      textWrap: "wrap",
                    }}
                  >
                    Updated on {updatedOn} by{" "}
                    {getUserName(variant?.web?.createdByUserZUID)}
                  </Typography>
                </Stack>
              </MenuItem>
            );
          })
        ) : (
          <Box my={4}>
            <NoSearchResults
              query={filterKeyword}
              imageHeight={109}
              hideBackButton
              onSearchAgain={() => {
                setFilterKeyword("");
                filterTextField.current?.querySelector("input").focus();
              }}
            />
          </Box>
        )}
      </MenuList>
    </Popover>
  );
};

import { useEffect, useMemo, useState, useRef, useReducer } from "react";
import {
  Typography,
  Autocomplete,
  TextField,
  Stack,
  Box,
  IconButton,
  Tooltip,
} from "@mui/material";
import {
  KeyboardArrowDownRounded,
  ModeEditRounded,
  LinkRounded,
  OpenInNewRounded,
  CheckRounded,
} from "@mui/icons-material";
import { useHistory } from "react-router";
import { useSelector } from "react-redux";

import {
  useGetContentModelsQuery,
  useLazyGetContentModelItemsQuery,
} from "../../services/instance";
import { VariantSelector } from "./VariantSelector";
import { AppState } from "../../store/types";
import blockPlaceholder from "../../../../public/images/blockPlaceholder.png";

type BlockValue = {
  model: {
    label: string;
    value: string;
  } | null;
  variant: string;
};
type FieldTypeBlockSelectorProps = {
  value: string;
  onChange: (value: string) => void;
  requiredError: boolean;
  missingVariantError: boolean;
};
export const FieldTypeBlockSelector = ({
  value,
  onChange,
  requiredError,
  missingVariantError,
}: FieldTypeBlockSelectorProps) => {
  const history = useHistory();
  const instance = useSelector((state: AppState) => state.instance);
  const previewLock = useSelector((state: AppState) =>
    state.settings?.instance?.find(
      (setting: any) => setting.key === "preview_lock_password" && setting.value
    )
  );
  const { data: models, isLoading: isLoadingModels } =
    useGetContentModelsQuery();
  const [getContentModelItems, { data: variants }] =
    useLazyGetContentModelItemsQuery();
  const [isVariantSelectorOpen, setIsVariantSelectorOpen] = useState(false);
  const [isLinkCopied, setIsLinkCopied] = useState(false);
  const [enableAutohighlight, setEnableAutohighlight] = useState(false);
  const variantSelectorRef = useRef<HTMLDivElement>(null);

  const [blockValue, updateBlockValue] = useReducer(
    (state: BlockValue, action: Partial<BlockValue>) => {
      return {
        ...state,
        ...action,
      };
    },
    { model: null, variant: null }
  );
  const blockModelData = models?.find(
    (model) => model.name === blockValue.model?.value
  );
  const selectedVariantData = variants?.find(
    (variant) => variant.meta?.ZUID === blockValue.variant
  );

  const blockModelOptions = useMemo(() => {
    if (!models?.length) return [];

    return models
      .filter((model) => model.type === "block")
      .map((model) => ({
        label: model.label,
        value: model.name,
      }));
  }, [models]);

  const url = useMemo(() => {
    if (!blockValue || !variants?.length || !instance || !selectedVariantData)
      return "";

    // @ts-expect-error config not typed
    const domain = `${CONFIG.URL_PREVIEW_PROTOCOL}${instance?.randomHashID}${CONFIG.URL_PREVIEW}`;
    let path = `/-/block/${blockValue.model?.value}.html?variant=${selectedVariantData?.meta?.ZUID}&_bypassError=true`;

    if (previewLock) {
      path = `${path}&zpw=${previewLock.value}`;
    }

    return `${domain}${path}`;
  }, [blockValue, variants, instance, selectedVariantData]);

  useEffect(() => {
    if (!blockModelData) return;

    getContentModelItems({ modelZUID: blockModelData.ZUID });
  }, [blockValue.model, blockModelData]);

  useEffect(() => {
    if (!value) {
      updateBlockValue({
        model: null,
        variant: null,
      });
    } else {
      const blockModelName = value.split("/")?.[3]?.split(".")?.[0];
      const blockVariantZUID = value.split("variant=")?.[1];

      updateBlockValue({
        model: {
          label:
            models?.find((model) => model.name === blockModelName)?.label || "",
          value: blockModelName || "",
        },
        variant: blockVariantZUID,
      });
    }
  }, [value, models]);

  const handleCopyLinkClick = (data: string) => {
    navigator?.clipboard
      ?.writeText(data)
      .then(() => {
        setIsLinkCopied(true);
        setTimeout(() => {
          setIsLinkCopied(false);
        }, 3000);
      })
      .catch((err) => {
        console.error(err);
      });
  };

  return (
    <>
      <Stack direction="row" gap={0.5}>
        <Autocomplete
          autoHighlight={enableAutohighlight}
          onInputChange={(_, value, reason) =>
            setEnableAutohighlight(!!value && reason === "input")
          }
          data-cy="BlockSelectorModelField"
          loading={isLoadingModels}
          renderInput={(params) => (
            <TextField
              {...params}
              error={requiredError}
              placeholder="Model"
              sx={{ width: 200 }}
            />
          )}
          options={blockModelOptions}
          value={blockValue?.model}
          onChange={(_, value) => {
            if (!value) {
              onChange(null);
            } else {
              onChange(`/-/block/${value?.value}.html?variant=`);
            }
          }}
        />

        <Tooltip
          enterDelay={500}
          enterNextDelay={500}
          disableInteractive
          followCursor
          title={
            (!blockValue?.model || !blockValue?.model?.value) &&
            "Please select a model first before selecting a variant"
          }
          PopperProps={{
            sx: {
              maxWidth: "none",
            },
          }}
        >
          <Stack
            data-cy="BlockSelectorVariantField"
            ref={variantSelectorRef}
            direction="row"
            height={40}
            bgcolor="background.paper"
            width="100%"
            justifyContent="space-between"
            alignItems="center"
            px={1}
            borderRadius={2}
            border={1}
            borderColor={
              requiredError || missingVariantError ? "error.main" : "border"
            }
            boxSizing="border-box"
            sx={{
              cursor: "pointer",
            }}
            onClick={() => {
              if (!blockValue?.model || !blockValue?.model?.value) return;

              setIsVariantSelectorOpen(true);
            }}
          >
            <Typography
              variant="body2"
              color={!!blockValue?.variant ? "text.primary" : "text.disabled"}
            >
              {!!blockValue?.variant
                ? variants?.find(
                    (variant) => variant?.meta?.ZUID === blockValue.variant
                  )?.web?.metaTitle
                : "Variant"}
            </Typography>
            <KeyboardArrowDownRounded color="action" />
          </Stack>
        </Tooltip>
        {!!isVariantSelectorOpen && (
          <VariantSelector
            anchorEl={variantSelectorRef?.current}
            onClose={() => setIsVariantSelectorOpen(false)}
            variants={blockValue?.model?.value ? variants : []}
            blockModelName={blockValue?.model?.label}
            blockModelZUID={blockModelData?.ZUID}
            onVariantSelected={(ZUID) => {
              onChange(
                `/-/block/${blockValue?.model?.value}.html?variant=${ZUID}`
              );
              setIsVariantSelectorOpen(false);
            }}
          />
        )}
      </Stack>
      {!!blockValue?.model && !!blockValue?.variant && (
        <Box data-cy="BlockFieldVariantPreview">
          <Stack
            direction="row"
            justifyContent="space-between"
            alignItems="center"
            px={1}
            py={1.5}
            bgcolor="grey.100"
            border={1}
            borderColor="border"
            borderRadius="8px 8px 0px 0px"
            mt={1}
          >
            <Typography variant="body2" fontWeight={600} color="text.primary">
              {variants?.find(
                (variant) => variant?.meta?.ZUID === blockValue.variant
              )?.web?.metaTitle || ""}
            </Typography>
            <Stack direction="row" gap={0.5}>
              <IconButton
                size="small"
                onClick={() =>
                  history.push(
                    `/blocks/${blockModelData?.ZUID}/${blockValue?.variant}`
                  )
                }
              >
                <ModeEditRounded fontSize="small" />
              </IconButton>
              <IconButton size="small" onClick={() => handleCopyLinkClick(url)}>
                {isLinkCopied ? (
                  <CheckRounded fontSize="small" />
                ) : (
                  <LinkRounded fontSize="small" />
                )}
              </IconButton>
              <IconButton
                size="small"
                onClick={() =>
                  window.open(url, "_blank", "noopener=true,noreferrer=true")
                }
              >
                <OpenInNewRounded fontSize="small" />
              </IconButton>
            </Stack>
          </Stack>
          <Box
            component="img"
            width="100%"
            src={
              (selectedVariantData?.data?.og_image as string) ||
              blockPlaceholder
            }
            loading="lazy"
            borderRadius="0px 0px 8px 8px"
            borderRight={1}
            borderLeft={1}
            borderBottom={1}
            borderColor="border"
            boxSizing="border-box"
            sx={{
              objectFit: "contain",
            }}
          ></Box>
        </Box>
      )}
    </>
  );
};

import { memo } from "react";
import { AppLink } from "shell/components/AppLink";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faExclamationTriangle } from "@fortawesome/free-solid-svg-icons";

