export function getKeyValue<T, K extends string>(obj: T, path: K): any {
  if (!obj || !path) return undefined;

  const keys = path?.split(".").flatMap((part) => {
    const arrayMatch = part?.match(/([^\[]+)?\[(\d+)\]/);
    if (arrayMatch) {
      const [, prop, index] = arrayMatch;
      return prop ? [prop, index] : [index];
    }
    return [part];
  });

  return keys?.reduce((acc: any, key) => {
    if (acc === null || acc === undefined) return undefined;
    return acc[key];
  }, obj);
}

export function findUniqueIdKey(data: any[]) {
  if (!Array.isArray(data) || data.length === 0) return null;

  const keys = [...new Set(data.flatMap((item) => Object.keys(item)))];

  const validKeyIds = keys.filter((key) => {
    const values = [];

    for (const item of data) {
      // Must be own top-level property
      if (!Object.prototype.hasOwnProperty.call(item, key)) {
        return false;
      }

      const value = item[key];

      // Must be string or number
      if (typeof value !== "string" && typeof value !== "number") {
        return false;
      }

      // Must not be null/undefined/empty string
      if (value === null || value === undefined || value === "") {
        return false;
      }

      values.push(value);
    }

    // Must be unique
    return new Set(values).size === data.length;
  });

  return validKeyIds.length > 0 ? validKeyIds[0] : null;
}

import { useState } from "react";
import {
  Avatar,
  Box,
  Card,
  CardMedia,
  Skeleton,
  Typography,
} from "@mui/material";
import PlayCircleIcon from "@mui/icons-material/PlayCircle";
import AddPhotoAlternateRoundedIcon from "@mui/icons-material/AddPhotoAlternateRounded";
import VideoCallRoundedIcon from "@mui/icons-material/VideoCallRounded";
import { IntegrationTypes } from "../../../services/types";

export type DisplayCardProps = {
  type: IntegrationTypes;
  heading: string;
  subHeading?: string;
  thumbnail?: string;
  rootPath?: string | null;
  detail?: string;
  details?: Record<string, string | number>[];
  mediaVariant?: "rounded" | "square";
  showPlayIcon?: boolean;
  loading?: boolean;
};

const DisplayCard = ({
  type,
  heading,
  subHeading,
  thumbnail,
  detail,
  details,
  mediaVariant = "square",
  showPlayIcon,
  loading,
}: DisplayCardProps) => {
  const [noImage, setNoImage] = useState(false);
  const isVideoType = ["video", "youtube", "mux"].includes(type);
  const isSpecialType = ["shopify", "youtube", "mux", "classy"].includes(type);
  const withCardMedia = !["classy", "text", "simple", "details"].includes(type);

  const renderMediaIcon = () => {
    if (!withCardMedia) return null;

    if (showPlayIcon) {
      return <PlayCircleIcon fontSize="large" sx={{ color: "common.white" }} />;
    }

    if (isVideoType) {
      return <VideoCallRoundedIcon sx={{ color: "action.active" }} />;
    }
    return (
      <AddPhotoAlternateRoundedIcon
        fontSize="small"
        sx={{ color: "action.active" }}
      />
    );
  };

  const headingValue = loading ? (
    <Skeleton width={type === "simple" ? "90%" : "55%"} height="26px" />
  ) : typeof heading === "boolean" ? (
    String(heading)
  ) : (
    heading || "Add Heading"
  );
  const subHeadingValue = loading ? (
    <Skeleton width="90%" />
  ) : typeof subHeading === "boolean" ? (
    String(subHeading)
  ) : (
    subHeading || "Add Subheading"
  );
  const thumbnailValue = thumbnail || null;
  const detailValue = loading ? (
    <Skeleton width="70px" />
  ) : typeof detail === "boolean" ? (
    String(detail)
  ) : (
    detail || "Add Detail"
  );

  const renderCard = () => {
    if (type === "simple") {
      return (
        <Box
          sx={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "flex-start",
            alignItems: "center",
            width: "100%",
            px: 1.5,
            py: 2,
            rowGap: 0.5,
          }}
        >
          <Typography
            variant="body2"
            width="100%"
            sx={{ fontWeight: 600, color: "text.primary" }}
          >
            {headingValue}
          </Typography>
        </Box>
      );
    }

    if (type === "details") {
      return (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "flex-start",
            width: "100%",
            px: 1.5,
            py: 1.5,
            rowGap: 0.25,
          }}
        >
          <Typography
            variant="body1"
            color="text.primary"
            width="100%"
            fontWeight={700}
          >
            {headingValue}
          </Typography>

          <Box
            display="flex"
            flexDirection="column"
            justifyContent="center"
            alignItems="flex-start"
            sx={{ width: "100%" }}
          >
            {details?.map((item: Record<string, string>, index: number) => (
              <Box
                width="100%"
                display="flex"
                flexDirection="row"
                justifyContent="space-between"
                alignItems="center"
                key={`${item?.key}-${index}`}
              >
                <Typography
                  variant="body2"
                  color="text.secondary"
                  fontWeight={400}
                  flexGrow={1}
                >
                  {loading ? (
                    <Skeleton sx={{ width: "95%" }} />
                  ) : (
                    item?.key || "+ Add Detail"
                  )}
                </Typography>
                <Typography
                  variant="body2"
                  color="text.secondary"
                  fontWeight={400}
                >
                  {loading ? (
                    <Skeleton
                      sx={{
                        width: "100px",
                        height: "16px",
                      }}
                    />
                  ) : typeof item?.value === "boolean" ? (
                    String(item?.value)
                  ) : (
                    item?.value || ""
                  )}
                </Typography>
              </Box>
            ))}
          </Box>
        </Box>
      );
    }

    return (
      <>
        {withCardMedia && (
          <Box
            sx={{
              borderRadius: mediaVariant === "rounded" ? 2 : 0,
              height: "80px",
              width: isVideoType ? "142px" : "80px",
              maxHeight: "80px",
              position: "relative",
              bgcolor: "#F2F4F7",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              overflow: "hidden",
              flexShrink: 0,
              "& .MuiSvgIcon-root": {
                position: "absolute",
              },
            }}
          >
            {loading ? (
              <Skeleton variant="rectangular" width="100%" height="100%" />
            ) : (
              <>
                {!!thumbnailValue && (
                  <CardMedia
                    component="img"
                    sx={{
                      width: "auto",
                      height: "100%",
                      display: noImage ? "none" : "block",
                    }}
                    image={thumbnailValue}
                    onError={() => setNoImage(true)}
                    onLoad={() => setNoImage(false)}
                  />
                )}
                {(!thumbnailValue ||
                  noImage ||
                  (showPlayIcon && isVideoType)) &&
                  renderMediaIcon()}
              </>
            )}
          </Box>
        )}
        <Box
          sx={{
            py: 2,
            px: 1.5,
            flex: "1 0 auto",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "flex-start",
            rowGap: 0.25,
            flexShrink: 1,
            flexGrow: 1,
            overflow: "hidden",
          }}
        >
          <Box
            display="flex"
            alignItems="center"
            justifyContent="space-between"
            width="100%"
            overflow="hidden"
            whiteSpace="no-wrap"
            columnGap={3}
          >
            <Typography
              variant="body2"
              noWrap
              width="100%"
              sx={{ fontWeight: 600 }}
            >
              {headingValue}
            </Typography>
            {type === "shopify" && !!detail && (
              <Typography
                variant="body2"
                noWrap
                width="100px"
                sx={{
                  fontWeight: 400,
                  direction: "rtl",
                }}
              >
                {detailValue}
              </Typography>
            )}
          </Box>

          <Typography
            variant="body2"
            noWrap
            width="100%"
            sx={{ fontWeight: 400, color: "text.secondary" }}
          >
            {subHeadingValue}
          </Typography>
        </Box>
        {isSpecialType && (
          <Box
            width="32px"
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              position: "relative",
              flexShrink: 0,
            }}
          >
            {loading ? (
              <Skeleton
                animation="wave"
                variant="rounded"
                width="30px"
                height="30px"
              />
            ) : (
              <Avatar
                variant="rounded"
                src={`/images/${type}Icon.svg`}
                sx={{ width: "100%", height: "auto" }}
              >
                {type.substring(0, 1).toUpperCase()}
              </Avatar>
            )}
          </Box>
        )}
      </>
    );
  };

  return (
    <Card
      className="displayCard"
      elevation={0}
      sx={{
        p: 0,
        columnGap: 0,
        borderRadius: 0,
        display: "flex",
        flexDirection: "row",
        justifyContent: "space-between",
        alignItems: "stretch",
        width: "100%",
        position: "relative",
        boxSizing: "border-box",
        bgcolor: "transparent",
