export const sanitizeJsonData = (data: any, stringify: boolean = false) => {
  try {
    let newData = data;

    if ("_itemId" in data) {
      const { _itemId, ...restData } = data;
      newData = restData;
    }
    return !stringify ? newData : JSON.stringify(newData, null, 2);
  } catch (error) {
    return `Script Error: ${error?.message}`;
  }
};

