        <FieldTypeMedia
          hasError={hasErrors(error)}
          limit={1}
          images={imagesArray}
          openMediaBrowser={(opts: any) => {
            setImageModal({
              ...opts,
              locked: Boolean(
                field?.settings &&
                  field?.settings.group_id &&
                  field?.settings.group_id != "0"
