        <Box width="100%">{children}</Box>
      </Tooltip>
    ) : (
      <>{children}</>
    );

  return (
    <Box
      width="100%"
      display="flex"
      flexDirection="column"
      justifyContent="flex-start"
      alignItems="flex-start"
