          {label}
        </Typography>
        {!!tooltip && (
          <Tooltip
            title={tooltip}
            placement="top-start"
            slotProps={{
              popper: {
                style: {
                  width: "fit-content",
                  maxWidth: "600px",
                },
                modifiers: [
                  {
                    name: "offset",
                    options: {
                      offset: [-20, -10],
                    },
                  },
                ],
              },
            }}
          >
            <InfoIcon
              sx={{ width: "10px", height: "10px", color: "action.active" }}
