import { FC, useCallback, useEffect, useState } from "react";
import {
  Button,
  Dialog,
  DialogActions,
  DialogTitle,
  Typography,
  Box,
} from "@mui/material";
import { DialogContent } from "@mui/material";

import WarningAmberRoundedIcon from "@mui/icons-material/WarningAmberRounded";
import { Chip } from "@mui/material";
import { CreateRedirectErrors, ErrorPathProps } from "./constants";
import { useRedirectsDialog } from ".";
import { useDispatch } from "react-redux";
import { notify } from "../../../../../../shell/store/notifications";

type ErrorDialogProps = {
  open: boolean;
  onClose: () => void;
  data: CreateRedirectErrors;
};

export const ErrorDialog: FC<ErrorDialogProps> = ({ open, onClose, data }) => {
  const dispatch = useDispatch();

  const [errorPaths, setErrorPaths] = useState<ErrorPathProps[]>([]);

  const { createRedirects, updateRedirect, closeErrorDialog, isLoading } =
    useRedirectsDialog();

  const handleResubmit = useCallback(async () => {
    const isEdit = !!data?.ZUID;
    const paths = errorPaths?.map((error) => error?.path?.trim());

    let response = null;

    if (isEdit) {
      response = await updateRedirect({
        path: paths[0],
        targetType: data?.targetType,
        code: data?.code,
        target: data?.target,
        ZUID: data?.ZUID,
      });
    } else {
      response = await createRedirects({
        paths: paths,
        target: data?.target,
        targetType: data?.targetType,
        code: data?.code,
      });
    }
    const errorPathRes = response
      ?.filter((item: any) => item?.status === "error")
      .map((item: any) => item?.path?.trim());

    if (!errorPathRes?.length) {
      dispatch(
        notify({
          kind: "success",
          message: !isEdit
            ? `${paths?.length} Redirect${paths?.length > 1 ? "s" : ""} Created`
            : `Redirect Saved: ${paths[0]}`,
        })
      );
      closeErrorDialog();
      return;
    }

    const updatedErrorPaths = errorPaths?.filter((error) =>
      errorPathRes?.includes(error?.path?.trim())
    );

    setErrorPaths(updatedErrorPaths);
  }, [data, errorPaths]);

  useEffect(() => {
    const pathErrors = data?.errors?.map((error) => {
      return {
        error: error?.error,
        path: error?.path?.trim(),
      };
    });
    setErrorPaths(pathErrors);
  }, [data]);

  return (
    <>
      <Dialog
        data-cy="RedirectsErrorDialog"
        open={open}
        fullWidth
        maxWidth={false}
        onClose={onClose}
        slotProps={{
          paper: {
            sx: {
              width: "480px",
            },
          },
        }}
      >
        <DialogTitle>
          <Box
            sx={{
              backgroundColor: "red.100",
              borderRadius: "100%",
              width: "40px",
              height: "40px",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              mb: 1.5,
            }}
          >
            <WarningAmberRoundedIcon color="error" />
          </Box>

          <Typography
            variant="inherit"
            fontWeight={700}
            flexGrow={0}
            flexShrink={0}
            data-cy="RedirectsErrorDialogHeader"
          >
            {`${errorPaths?.length} Redirect${
              errorPaths?.length > 1 ? "s" : ""
            } couldn't be created`}
          </Typography>

          <Typography variant="body2" color="text.secondary" sx={{ mt: "8px" }}>
            The following paths couldn't be saved as redirects.
          </Typography>
        </DialogTitle>
        <DialogContent>
          <Box
            data-cy="RedirectsErrorDialogListContainer"
            sx={{
              display: "flex",
              flexDirection: "column",
              justifyContent: "flex-start",
              alignItems: "stretch",
              rowGap: "20px",
            }}
          >
            {errorPaths?.map((error) => (
              <Box
                className="RedirectsErrorListItem"
                key={error?.path}
                display="flex"
                flexDirection="row"
                justifyContent="space-between"
                alignItems="center"
                columnGap={1}
                width="100%"
              >
                <Typography variant="body2" color="info.dark" flexGrow={1}>
                  {error?.path}
                </Typography>
                <Chip
                  size="small"
                  label={error.error}
                  color={error?.error !== "error" ? "warning" : "error"}
                  sx={{ flexGrow: 0 }}
                />
              </Box>
            ))}
          </Box>
        </DialogContent>
        <DialogActions sx={{ p: "20px" }}>
          <Button
            data-cy="RedirectsErrorDialogTryAgainButton"
            variant="text"
            color="inherit"
            size="medium"
            loading={isLoading}
            onClick={handleResubmit}
          >
            Try Again
          </Button>
          <Button
            data-cy="RedirectsErrorDialogDoneButton"
            variant="contained"
            color="primary"
            size="medium"
            onClick={onClose}
          >
            Done
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default ErrorDialog;

import {
  createContext,
  useContext,
  ReactNode,
  useState,
  useCallback,
} from "react";
import {
  useCreateRedirectMutation,
  useUpdateRedirectMutation,
} from "../../../../../../shell/services/instance";
import {
  RedirectsCodes,
  RedirectsTargetType,
} from "../../../../../../shell/services/types";
import ChangeDialog, { ChangeRedirectProps } from "./ChangeDialog";
import { CreateRedirectErrors } from "./constants";
import CreateForm from "./CreateRedirects/CreateForm";
import { DeleteDialog, DeleteRedirectsProps } from "./DeleteDialog";
import ErrorDialog from "./ErrorDialog";

export type CreateFormDefaultValues = {
  ZUID?: string;
  code?: RedirectsCodes;
  target?: string;
  targetType?: RedirectsTargetType;
  path?: string;
};

export const parseRedirectError = (error: string): string => {
  if (error?.toLowerCase()?.includes("already exists")) return "Already exists";
  if (error?.toLowerCase()?.includes("validation error: redirect item"))
    return "Not Published";
  return "Error";
};

type RedirectsDialogContextType = {
  openCreateForm: (
    data?: CreateFormDefaultValues | null,
    isInternal?: boolean
  ) => void;
  closeCreateForm: () => void;
  openErrorDialog: (errors: CreateRedirectErrors) => void;
  closeErrorDialog: () => void;
  isLoading: boolean;
  createRedirects: (params: {
    paths: string[];
    targetType: RedirectsTargetType;
    code: RedirectsCodes;
    target: string;
  }) => Promise<any>;
  updateRedirect: (params: {
    path: string;
    targetType: RedirectsTargetType;
    code: RedirectsCodes;
    target: string;
    ZUID: string;
  }) => Promise<any>;
  openDeleteDialog: (data: DeleteRedirectsProps[]) => void;
  closeDeleteDialog: () => void;
  openChangeDialog: (
    redirect: ChangeRedirectProps | null,
    newPath: string
  ) => void;
  closeChangeDialog: () => void;
};

const RedirectsDialogContext = createContext<RedirectsDialogContextType | null>(
  null
);

const RedirectsDialogContextProvider = ({
  children,
}: {
  children: ReactNode;
}) => {
  const [createFormOpen, setCreateFormOpen] = useState<boolean>(false);
  const [errorDialogOpen, setErrorDialogOpen] = useState<boolean>(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState<boolean>(false);
  const [changeDialogOpen, setChangeDialogOpen] = useState<boolean>(false);
  const [isInternal, setIsInternal] = useState<boolean>(false);
  const [createRedirectErrors, setCreateRedirectErrors] =
    useState<CreateRedirectErrors>();
  const [deleteRedirects, setDeleteRedirects] = useState<
    DeleteRedirectsProps[]
  >([]);
  const [changeRedirect, setChangeRedirect] = useState<{
    redirect: ChangeRedirectProps | null;
    newPath?: string;
  } | null>(null);
  const [createFormDefaultValues, setCreateFormDefaultValues] =
    useState<CreateFormDefaultValues | null>(null);

  const openCreateForm = (
    data: CreateFormDefaultValues | null = null,
    isInternal: boolean = false
  ) => {
    setIsInternal(isInternal);
    setCreateFormDefaultValues(data);
    setCreateFormOpen(true);
  };
  const closeCreateForm = () => setCreateFormOpen(false);

  const openErrorDialog = (errors: CreateRedirectErrors) => {
    setCreateRedirectErrors(errors);
    setErrorDialogOpen(true);
  };
  const closeErrorDialog = () => setErrorDialogOpen(false);

  const openDeleteDialog = (data: DeleteRedirectsProps[]) => {
    setDeleteRedirects(data);
    setDeleteDialogOpen(true);
  };
  const closeDeleteDialog = () => setDeleteDialogOpen(false);

  const openChangeDialog = (
    redirect: ChangeRedirectProps | null,
    newPath: string
  ) => {
    setChangeRedirect({ redirect, newPath });
    setChangeDialogOpen(true);
  };
  const closeChangeDialog = () => setChangeDialogOpen(false);

  const [createRedirect, { isLoading: isCreatingRedirect }] =
    useCreateRedirectMutation();
  const [updateRedirect, { isLoading: isUpdatingRedirect }] =
    useUpdateRedirectMutation();

  const sendRedirectRequest = async ({
    paths,
    target,
    targetType,
    code,
    ZUID,
  }: {
    paths: string[];
    target: string;
    targetType: RedirectsTargetType;
    code: RedirectsCodes;
    ZUID?: string | null;
  }) => {
    const request = async ({
      path,
      targetType,
      code,
      target,
    }: {
      path: string;
      targetType: RedirectsTargetType;
      code: RedirectsCodes;
      target: string;
    }) => {
      const responseData = {
        status: "success",
        message: "",
        data: {},
      };
      try {
        const reqData = {
          path,
          targetType,
          code,
          target,
        };
        let response: any;
        if (ZUID) {
          response = await updateRedirect({ ZUID, body: reqData });
        } else {
          response = await createRedirect(reqData);
        }

        if (response?.error) {
          throw new Error(response?.error?.data?.error);
        }
      } catch (error) {
        responseData.status = "error";
        responseData.message = parseRedirectError(error?.message);
        responseData.data = {
          path,
          targetType,
          code,
          target,
        };
      }
      return responseData;
    };

    const redirectRequests = [...new Set(paths)]?.map((path) =>
      request({ path, targetType, code, target })
    );

    const redirectsResponses = await Promise.allSettled(redirectRequests);
    return redirectsResponses.map((item: any) => ({
      status: item?.value.status,
      message: item?.value?.message,
      path: item?.value?.data?.path,
    }));
  };

  const createRedirectRequest = useCallback(
    async ({
      paths,
      targetType,
      code,
      target,
    }: {
      paths: string[];
      targetType: RedirectsTargetType;
      code: RedirectsCodes;
      target: string;
    }) => {
      return sendRedirectRequest({ paths, targetType, code, target });
    },
    []
  );

  const updateRedirectRequest = useCallback(
    async ({
      path,
      targetType,
      code,
      target,
      ZUID,
    }: {
      path: string;
      targetType: RedirectsTargetType;
      code: RedirectsCodes;
      target: string;
      ZUID: string;
    }) => {
      return sendRedirectRequest({
        paths: [path],
        targetType,
        code,
        target,
        ZUID,
      });
    },
    []
  );

  return (
    <RedirectsDialogContext.Provider
      value={{
        openCreateForm,
        closeCreateForm,
        openErrorDialog,
        closeErrorDialog,
        isLoading: isUpdatingRedirect || isCreatingRedirect,
        createRedirects: createRedirectRequest,
        updateRedirect: updateRedirectRequest,
        openDeleteDialog,
        closeDeleteDialog,
        openChangeDialog,
        closeChangeDialog,
      }}
    >
      {children}

      {createFormOpen && (
        <CreateForm
          open={createFormOpen}
          onClose={closeCreateForm}
          defaultValues={createFormDefaultValues}
          isInternal={isInternal}
        />
      )}
      {errorDialogOpen && (
        <ErrorDialog
          open={errorDialogOpen}
          onClose={closeErrorDialog}
          data={createRedirectErrors}
        />
      )}
      {deleteDialogOpen && (
        <DeleteDialog
          open={deleteDialogOpen}
          onClose={closeDeleteDialog}
          redirects={deleteRedirects}
        />
      )}
      {changeDialogOpen && (
        <ChangeDialog
          redirect={changeRedirect?.redirect ?? null}
          open={changeDialogOpen}
          onClose={closeChangeDialog}
          newPath={changeRedirect?.newPath ?? ""}
        />
      )}
    </RedirectsDialogContext.Provider>
  );
};

export const useRedirectsDialog = () => {
  const context = useContext(RedirectsDialogContext);
  if (context === null) {
    throw new Error(
      "useRedirectsDialogContext must be used within a RedirectsDialogContextProvider"
    );
  }
  return context;
};

export default RedirectsDialogContextProvider;

