  errors: Errors;
  errorComponent?: React.ReactNode;
  item: ContentItem;
};
export const Meta = forwardRef(
  (
    { isSaving, onUpdateSEOErrors, errors, errorComponent, item }: MetaProps,
    ref
  ) => {
    const dispatch = useDispatch();
    const location = useLocation();
    const isCreateItemPage = location?.pathname?.split("/")?.pop() === "new";
    const { modelZUID, itemZUID } = useParams<{
      modelZUID: string;
      itemZUID: string;
    }>();
    const { data: model, isFetching } = useGetContentModelQuery(modelZUID, {
      skip: !modelZUID,
    });
    const { data: fields } = useGetContentModelFieldsQuery({ modelZUID });
    const { data: instanceSettings, isFetching: instanceSettingsFetching } =
      useGetInstanceSettingsQuery();
    const { meta, data, web }: { meta: MetaType; data: Data; web: Web } =
      useSelector(
        (state: AppState) =>
          state.content[isCreateItemPage ? `new:${modelZUID}` : itemZUID]
      ) || {
        meta: {} as MetaType,
        data: {} as Data,
        web: {} as Web,
      };
    const [flowType, setFlowType] =
      useState<(typeof FlowType)[keyof typeof FlowType]>(null);
    const metaDescriptionButtonRef = useRef(null);
    const metaTitleButtonRef = useRef(null);
    const showSEOPreview =
      instanceSettings?.find((setting) => setting.key === "disable_seo_preview")
        ?.value !== "1" && model?.type !== "dataset";

    // @ts-expect-error untyped
    const siteName = useMemo(() => dispatch(fetchGlobalItem())?.site_name, []);

    const metaFields = useMemo(() => {
      if (fields?.length) {
        return fields.reduce(
          (
            accu: Record<string, ContentModelField>,
            curr: ContentModelField
          ) => {
            if (
              !curr.deletedAt &&
              DYNAMIC_META_FIELD_NAMES.includes(curr.name.toLowerCase())
            ) {
              accu[curr.name] = curr;
            }

            return accu;
          },
          {}
        );
      }

      return {};
    }, [fields]);

    const REQUIRED_FIELDS = useMemo(() => {
      const fields = ["metaTitle", "parentZUID", "pathPart"];

      return fields;
    }, [model]);

    const handleOnChange = useCallback(
      (value, name) => {
        if (!name) {
          throw new Error("Input is missing name attribute");
        }

        const currentErrors = cloneDeep(errors);

        if (REQUIRED_FIELDS.includes(name)) {
          currentErrors[name] = {
            ...currentErrors?.[name],
            MISSING_REQUIRED: !value,
          };
        }

        if (MaxLengths[name]) {
          currentErrors[name] = {
            ...currentErrors?.[name],
            EXCEEDING_MAXLENGTH:
              value?.length > MaxLengths[name]
                ? value?.length - MaxLengths[name]
                : 0,
          };
        }

        if (DYNAMIC_META_FIELD_NAMES.includes(name) && name in metaFields) {
          const isRequired = metaFields[name].required;

          currentErrors[name] = {
            ...currentErrors[name],
            MISSING_REQUIRED: isRequired ? !value : false,
          };
        }

        if (name === "metaDescription") {
          const metaDescriptionError = validateMetaDescription(value);

          currentErrors.metaDescription = {
            ...currentErrors.metaDescription,
            CUSTOM_ERROR: !!metaDescriptionError ? metaDescriptionError : "",
          };
        }

        onUpdateSEOErrors(currentErrors);

        dispatch({
          // The og_image is stored as an ordinary field item and not a SEO field item
          type: [...DYNAMIC_META_FIELD_NAMES, "og_image"].includes(name)
            ? "SET_ITEM_DATA"
            : "SET_ITEM_WEB",
          itemZUID: meta?.ZUID,
          key: name,
          value: value,
        });
      },
      [meta?.ZUID, errors]
    );

    useImperativeHandle(
      ref,
      () => {
        return {
          validateMetaFields() {
            const currentErrors = cloneDeep(errors);

            REQUIRED_FIELDS.forEach((fieldName) => {
              // @ts-expect-error
              const value = web[fieldName];

              currentErrors[fieldName] = {
                ...currentErrors?.[fieldName],
                MISSING_REQUIRED: !value,
              };
            });

            Object.keys(MaxLengths).forEach((fieldName) => {
              const value = DYNAMIC_META_FIELD_NAMES.includes(fieldName)
                ? data[fieldName]
                : // @ts-expect-error
                  web[fieldName];

              currentErrors[fieldName] = {
                ...currentErrors?.[fieldName],
                EXCEEDING_MAXLENGTH:
                  value?.length > MaxLengths[fieldName]
                    ? value?.length - MaxLengths[fieldName]
                    : 0,
              };
            });

            Object.entries(metaFields).forEach(([name, settings]) => {
              const isRequired = settings.required;
              const value = data[name] as string;

              currentErrors[name] = {
                ...currentErrors?.[name],
                MISSING_REQUIRED: isRequired ? !value : false,
              };
            });

            // Validate meta description value
            const metaDescriptionError = validateMetaDescription(
              web.metaDescription || ""
            );

            currentErrors.metaDescription = {
              ...currentErrors.metaDescription,
              CUSTOM_ERROR: !!metaDescriptionError ? metaDescriptionError : "",
            };

            // No need to validate pathPart for datasets
            if (
              model?.type === "dataset" ||
              model?.type === "block" ||
              web?.pathPart === "zesty_home"
            ) {
              delete currentErrors.pathPart;
              delete currentErrors.parentZUID;
            }

            setTimeout(() => {
              // Makes sure that the user sees the error blurbs on each
              // field when in the create item page
              if (isCreateItemPage) {
                setFlowType(FlowType.Manual);
              }
              onUpdateSEOErrors(currentErrors);
            });

            return Object.values(currentErrors)
              ?.map((error) => {
                return Object.values(error) ?? [];
              })
              ?.flat()
              .some((error) => !!error);
          },
          triggerAIGeneratedFlow() {
            setFlowType(FlowType.AIGenerated);
          },
        };
      },
      [errors, web, model, metaFields, data]
    );

    useEffect(() => {
      if (isSaving) {
        onUpdateSEOErrors({});
        return;
      }
    }, [isSaving]);

    useEffect(() => {
      if (!isCreateItemPage) return;

      if (flowType === FlowType.AIGenerated) {
        // Immediately clear out the existing values for the meta title and description
        dispatch({
          type: "SET_ITEM_WEB",
          itemZUID: meta?.ZUID,
          key: "metaTitle",
          value: "",
        });
        dispatch({
          type: "SET_ITEM_WEB",
          itemZUID: meta?.ZUID,
          key: "metaDescription",
          value: "",
        });

        // Then trigger the AI assistant popup
        metaTitleButtonRef.current?.triggerAIButton?.();
      }
    }, [flowType, isCreateItemPage, meta?.ZUID]);

    const handleMetaTitle = useMemo(
      () => ({
        setValue: (val: string) => {
          const el = document.getElementById("metaTitle");
          if (el) {
            el.scrollIntoView({
              behavior: "smooth",
              block: "nearest",
              inline: "center",
            });
          }

          const inputEl = el.querySelector(
            'input, textarea, [contenteditable="true"]'
          ) as HTMLElement | null;
          if (inputEl && typeof inputEl.focus === "function") {
            inputEl.focus();
          }

          handleOnChange(val, "metaTitle");
        },
      }),
      []
    );

    const handleMetaDescription = useMemo(
      () => ({
        setValue: (val: string) => {
          const el = document.getElementById("metaDescription");
          if (el) {
            el.scrollIntoView({
              behavior: "smooth",
              block: "nearest",
              inline: "center",
            });
          }

          const inputEl = el.querySelector(
            'input, textarea, [contenteditable="true"]'
          ) as HTMLElement | null;
          if (inputEl && typeof inputEl.focus === "function") {
            inputEl.focus();
          }

          handleOnChange(val, "metaDescription");
        },
      }),
      []
    );

    useRegisterRef("meta-title", handleMetaTitle, item);
    useRegisterRef("meta-description", handleMetaDescription, item);

    if (isFetching) return null;

    if (isCreateItemPage && flowType === null && model?.type !== "block") {
      return (
        <>
          <Box
            sx={{
              mt: 2.5,
              mb: 5,
              borderRadius: 2,
              p: 0.25,
              background:
                "linear-gradient(0deg, rgba(255,93,10,1) 0%, rgba(18,183,106,1) 25%, rgba(11,165,236,1) 50%, rgba(238,70,188,1) 75%, rgba(105,56,239,1) 100%)",
              animation: `${rotateAnimation} 1.5s linear alternate infinite`,
              backgroundSize: "300% 300%",
            }}
          >
            <Stack gap={3} p={3} bgcolor="background.paper" borderRadius={1.5}>
              <Box>
                <Typography
                  variant="h5"
                  fontWeight={600}
                  mb={1}
                  color="text.primary"
                >
                  Have AI write your Meta Data?
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Our AI Assistant will scan your content and improve your meta
                  title and description to help{" "}
                  {model?.type === "dataset"
                    ? "with internal content search."
                    : "improve search engine visibility."}
                </Typography>
              </Box>
              {flowButtons.map((data) => (
                <ListItemButton
                  data-cy={
                    data.flowType === FlowType.AIGenerated
                      ? "AIAssistedMetaFlow"
                      : "ManualMetaFlow"
                  }
                  key={data.flowType}
                  onClick={() => setFlowType(data.flowType)}
                  sx={{
                    borderRadius: 2,
                    border: 1,
                    borderColor: "border",
                    backgroundColor: "common.white",
                    py: 2,
                  }}
                >
                  <ListItemIcon sx={{ minWidth: 48 }}>{data.icon}</ListItemIcon>
                  <ListItemText
                    primary={
                      <Typography
                        variant="h6"
                        fontWeight={600}
                        color="text.primary"
                      >
                        {data.primaryText}
                      </Typography>
                    }
                    disableTypography
                    sx={{ my: 0 }}
                    secondary={
                      <Typography
                        variant="body2"
                        sx={{ mt: 0.5 }}
                        color="text.primary"
                      >
                        {data.secondaryText}
                      </Typography>
                    }
                  />
                </ListItemButton>
              ))}
            </Stack>
          </Box>
          <Box sx={{ display: "none" }}>
            <ItemParent onChange={handleOnChange} />
          </Box>
        </>
      );
    }

    if (model?.type === "block" && isCreateItemPage) {
      return (
        <Stack
          gap={3}
          pb={2}
          mb={2}
          sx={{
            borderBottom: "2px solid",
            borderColor: "border",
          }}
        >
          {!!errorComponent && errorComponent}
          <MetaTitle
            label="Variant Title"
            aiButtonRef={metaTitleButtonRef}
            value={web.metaTitle}
            onChange={handleOnChange}
            error={errors?.metaTitle}
            onResetFlowType={() => {
              if (flowType === FlowType.AIGenerated) {
                console.log("reset on meta title");
                setFlowType(FlowType.Manual);
              }
            }}
            onAIMetaTitleInserted={() => {
              // Scroll to and open the meta description ai generator to continue
              // with the AI-assisted flow
              if (flowType === FlowType.AIGenerated) {
                metaDescriptionButtonRef.current?.triggerAIButton?.();
              }
            }}
          />
        </Stack>
      );
    }

    return (
      <Box
        display="grid"
        gridTemplateColumns={
          !isCreateItemPage ? "1fr minmax(auto, 40%)" : "1fr"
        }
        gap={4}
        pt={2.5}
        mb={isCreateItemPage ? 4 : 0}
        px={isCreateItemPage ? 0 : 4}
        color="text.primary"
        sx={{
          scrollbarWidth: "none",
