            Updated on{" "}
            {isValid(new Date(block.web?.updatedAt))
              ? format(new Date(block.web?.updatedAt), "MMM d, yyyy")
              : ""}{" "}
            by&nbsp;
            {updatedByUser?.firstName} {updatedByUser?.lastName}
          </Typography>
        </Box>
      </ListItemButton>
