                          searchedContentItemPublishings?.slice(0, 10)?.length -
                            1
                            ? false
                            : true
                        }
                        onClick={handleItemClick}
                      />
                    ))
                : uniqueItemPublishings
                    ?.slice(0, 20)
                    ?.map((publishing: any, index: number) => (
                      <PublishingItem
