const PublishingItem = ({ publishing, divider, onClick }: any) => {
  const { data: itemData, isFetching: isFetchingItemData } =
    useGetContentItemQuery(publishing.itemZUID);
  const { data: modelData, isFetching: isFetchingModelData } =
    useGetContentModelQuery(itemData?.meta?.contentModelZUID, {
      skip: !itemData?.meta?.contentModelZUID,
    });
  const { data: users, isFetching: isFetchingUsersData } = useGetUsersQuery();
  const languages = useSelector((state: any) => state.languages);
  const langCode = languages.find(
    (lang: any) => lang.ID === itemData?.meta?.langID
  )?.code;
  const langDisplay = langCode ? `(${langCode}) ` : "";

  const hasSiblings =
    itemData &&
    itemData?.siblings &&
    Object.keys(itemData?.siblings).length > 1;

  const itemTitle = `${hasSiblings ? langDisplay : ""} ${
    itemData?.web?.metaTitle || itemData?.web?.path || itemData?.meta.ZUID
  }`;

  const firstName = users?.find(
    (user: User) => user.ZUID === publishing.publishedByUserZUID
  )?.firstName;
  const lastName = users?.find(
    (user: User) => user.ZUID === publishing.publishedByUserZUID
  )?.lastName;

  const showSkeleton =
    isFetchingItemData || isFetchingModelData || isFetchingUsersData;

  const userInfo =
    firstName || lastName ? `${firstName} ${lastName}` : "Unknown User";

  if (!showSkeleton && !itemData?.web?.path) return null;

  const publishDate = publishing?.publishAt
    ? new Date(publishing.publishAt)
    : null;
  const relativeTime =
    publishDate && isValid(publishDate)
      ? formatDistanceToNow(publishDate, { addSuffix: true })
      : "";

  return (
    <ListItemButton
      key={publishing.ZUID}
      divider={divider}
      disableGutters
      disabled={showSkeleton}
      onClick={() => {
        if (!showSkeleton) onClick(publishing.itemZUID);
      }}
      sx={{
        px: 2,
        py: 1.5,
        borderColor: "border",
      }}
    >
      <ListItemIcon
        sx={{
          minWidth: "34px",
        }}
      >
        {showSkeleton ? (
          <Skeleton variant="circular" width={16} height={16} />
        ) : (
          <SvgIcon
            component={modelIconMap[modelData?.type]}
            color="action"
            sx={{ width: 16, height: 16 }}
          />
        )}
      </ListItemIcon>
      <ListItemText
        sx={{
          m: 0,
        }}
        primary={
          showSkeleton ? (
            <Skeleton
              variant="rectangular"
              height={20}
              width={555}
              sx={{ mb: 1 }}
            />
          ) : (
            itemTitle
          )
        }
        primaryTypographyProps={{
          variant: "body2",
        }}
        secondary={
          showSkeleton ? (
            <Skeleton variant="rectangular" height={10} width={425} />
          ) : (
            `${modelData?.label} • ${relativeTime} • by ${userInfo}`
          )
        }
        secondaryTypographyProps={{
          fontSize: "12px",
          lineHeight: "18px",
        }}
      />
    </ListItemButton>
  );
};

import { useEffect, useMemo } from "react";
import { DateFilterValue } from "../../../../../../../shell/components/Filters/DateFilter";
import { useParams as useQueryParams } from "../../../../../../../shell/hooks/useParams";
import {
  DateFilter,
  DateRangeFilterValue,
} from "../../../../../../../shell/components/Filters";
import { Skeleton } from "@mui/material";

type Props = {
  showSkeleton?: boolean;
};

export const AnalyticsDateFilter = ({ showSkeleton }: Props) => {
  const [params, setParams] = useQueryParams();
  const activeDateFilter: DateFilterValue = useMemo(() => {
    const isPreset = Boolean(params.get("datePreset"));
    const isDateRange =
      Boolean(params.get("to")) &&
      Boolean(params.get("from")) &&
      params.get("to") !== params.get("from");

    if (isPreset) {
      return {
        type: "preset",
        value: params.get("datePreset"),
      };
    }

    if (isDateRange) {
      return {
        type: "daterange",
        value: {
          from: params.get("from"),
          to: params.get("to"),
        },
      };
    }

    return {
      type: "",
      value: "",
    };
  }, [params]);

  const handleDateFilterChanged = (dateFilter: DateFilterValue) => {
    switch (dateFilter.type) {
      case "daterange": {
        const value = dateFilter.value as DateRangeFilterValue;

        setParams(value.to, "to");
        setParams(value.from, "from");
        setParams(null, "datePreset");
        return;
      }
      case "preset": {
        const value = dateFilter.value as string;

        setParams(value, "datePreset");
        setParams(null, "to");
        setParams(null, "from");
        return;
      }

      default: {
        setParams(null, "to");
        setParams(null, "from");
        setParams(null, "datePreset");
        return;
      }
    }
  };

  useEffect(() => {
    if (!params.get("datePreset") && !params.get("from") && !params.get("to")) {
      handleDateFilterChanged({ type: "preset", value: "last_14_days" });
    }
  }, []);

  if (showSkeleton) {
    return <Skeleton variant="rectangular" width="137px" height="28px" />;
  }

  return (
    <DateFilter
      clearable={false}
      value={activeDateFilter}
      onChange={handleDateFilterChanged}
      hideCustomDates
      withDateRange
      extraPresets={[
        {
          text: "This Week (Sun - Today)",
          value: "this_week",
        },
        {
          text: "This Year (Jan - Today)",
          value: "this_year",
        },
        {
          text: "Quarter to Date",
          value: "quarter_to_date",
        },
      ]}
    />
  );
};

