import { theme } from "@zesty-io/material";
import { useMemo, useRef, useState } from "react";
import { Line } from "react-chartjs-2";
import ChartDataLabels from "chartjs-plugin-datalabels";
import {
  Button,
  Box,
  Paper,
  Typography,
  ButtonGroup,
  Skeleton,
} from "@mui/material";
import { ChartEvent } from "chart.js";
import {
  addDays,
  differenceInCalendarDays,
  format as fmt,
  getYear,
} from "date-fns";

import "chartjs-adapter-date-fns";

import lineChartSkeleton2 from "../../../../../../../../../public/images/lineChartSkeleton2.svg";
import {
  calculatePercentageDifference,
  findValuesForDimensions,
  padArray,
} from "../../utils";

type Props = {
  startDate: Date;
  endDate: Date;
  dateRange0Label: string;
  dateRange1Label: string;
  data: any;
  loading?: boolean;
};

function getDatesArray(start: Date, end: Date) {
  const diff = differenceInCalendarDays(end, start);
  return Array.from({ length: diff + 1 }, (_, i) => addDays(start, i));
}

export const ByDayLineChart = ({
  startDate,
  endDate,
  dateRange0Label,
  dateRange1Label,
  data,
  loading = true,
}: Props) => {
  const chartRef = useRef<any>(null);
  const [tooltipModel, setTooltipModel] = useState<any>(null);
  const [isTooltipEntered, setIsTooltipEntered] = useState(false);

  const handleHover = (event: ChartEvent, chartElement: Array<any>) => {
    if (chartElement.length === 0 && !isTooltipEntered) {
      setTooltipModel(null);
      return;
    }

    const chart = chartRef.current;
    const activeElement = chart?.getElementsAtEventForMode(
      event.native!,
      "nearest",
      { intersect: true },
      false
    )?.[0];

    const datasetIndex = activeElement?.datasetIndex;
    const index = activeElement?.index;

    if (typeof datasetIndex === "number" && typeof index === "number") {
      const model = {
        datasetIndex,
        dataIndex: index,
        x: (event as any).x - 180,
        y: (event as any).y - 100,
      };
      if (
        !tooltipModel ||
        model.dataIndex !== tooltipModel.dataIndex ||
        model.datasetIndex !== tooltipModel.datasetIndex
      ) {
        setTooltipModel(model);
        setIsTooltipEntered(true);
      }
    }
  };

  const dateChartLabels = useMemo(
    () => getDatesArray(startDate, endDate),
    [startDate, endDate]
  );

  const daysSpan = differenceInCalendarDays(endDate, startDate) + 1;

  const lastData = useMemo(() => {
    const result = findValuesForDimensions(data?.rows, ["date_range_0"]);
    if (result.length === 1 || result.length === 2)
      return [result[result.length - 1]];
    return padArray(result, daysSpan * 2).slice(daysSpan);
  }, [data, daysSpan]);

  const priorData = useMemo(() => {
    const result = findValuesForDimensions(data?.rows, ["date_range_1"]);
    if (result.length === 1 || result.length === 2) return [result[0]];
    return padArray(result, daysSpan * 2).slice(0, daysSpan);
  }, [data, daysSpan]);

  const spansMoreThanOneYear = useMemo(() => {
    if (!dateChartLabels.length) return false;
    const first = dateChartLabels[0];
    const last = dateChartLabels[dateChartLabels.length - 1];
    return getYear(first) !== getYear(last);
  }, [dateChartLabels]);

  if (loading) {
    return (
      <Box height="106px" width="100%" minWidth="0">
        <img src={lineChartSkeleton2} height="100%" width="100%" />
      </Box>
    );
  }

  return (
    <Box position="relative" height="106px" width="100%" minWidth="0">
      <Line
        ref={chartRef}
        data={{
          labels: dateChartLabels, // Dates, not strings
          datasets: [
            {
              label: dateRange0Label,
              data: lastData,
              fill: false,
              backgroundColor: theme.palette.info.main,
              borderColor: theme.palette.info.main,
              pointRadius: lastData.length <= 2 ? 4 : 0,
              datalabels: { display: false },
              borderWidth: 2,
            },
            {
              label: dateRange1Label,
              data: priorData,
              fill: false,
              backgroundColor: theme.palette.grey[300],
              borderColor: theme.palette.grey[300],
              pointRadius: priorData.length <= 2 ? 4 : 0,
              datalabels: { display: false },
              borderWidth: 2,
            },
          ],
        }}
        plugins={[ChartDataLabels]}
        options={{
          layout: { padding: 0 },
          responsive: true,
          maintainAspectRatio: false,
          onHover: handleHover,
          plugins: {
            tooltip: { enabled: false },
            legend: {
              display: true,
              position: "top",
              align: "start",
              labels: {
                usePointStyle: true,
                pointStyle: "circle",
                boxWidth: 4.5,
                font: { family: "Mulish", size: 12 },
                color: theme.palette.text.primary,
              },
            },
          },
          scales: {
            y: { display: false, beginAtZero: true },
            x: {
              grid: {
                drawOnChartArea: false,
                drawTicks: false,
                drawBorder: false,
              },
              type: "time",
              time: {
                // no parser needed when labels are Date objects
                unit: "day",
                displayFormats: {
                  day: spansMoreThanOneYear ? "MMM d yyyy" : "MMM d",
                },
              },
              ticks: {
                padding: 0,
                color: theme.palette.text.disabled,
                font: { size: 12, family: "Mulish" },
                maxTicksLimit: 5,
                maxRotation: 0,
                minRotation: 0,
                autoSkip: true,
              },
            },
          },
        }}
      />

      <Paper
        sx={{
          display: tooltipModel ? "block" : "none",
          position: "absolute",
          top: tooltipModel?.y,
          left: tooltipModel?.x,
          width: 258,
          zIndex: theme.zIndex.tooltip,
        }}
        onMouseLeave={() => {
          setIsTooltipEntered(false);
          setTooltipModel(null);
        }}
      >
        <Box sx={{ p: 2 }}>
          <Typography variant="body1" fontWeight={600}>
            Sessions
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mt: 0.5 }}>
            {fmt(addDays(startDate, tooltipModel?.dataIndex ?? 0), "eee d MMM")}{" "}
            vs{" "}
            {fmt(
              addDays(
                addDays(startDate, -daysSpan),
                tooltipModel?.dataIndex ?? 0
              ),
              "eee d MMM"
            )}
          </Typography>
          <Typography variant="h2" fontWeight={600}>
            {lastData?.[tooltipModel?.dataIndex]?.toLocaleString()}
          </Typography>
          <Typography
            variant="body3"
            color="text.disabled"
            fontWeight={600}
            sx={{ mt: 1 }}
          >
            {priorData?.[tooltipModel?.dataIndex]?.toLocaleString()}{" "}
            <Typography
              variant="body3"
              color={
                calculatePercentageDifference(
                  +(priorData?.[tooltipModel?.dataIndex] ?? 0),
                  +(lastData?.[tooltipModel?.dataIndex] ?? 0)
                ).startsWith("-")
                  ? "error.main"
                  : "success.main"
              }
              fontWeight={600}
            >
              {calculatePercentageDifference(
                +(priorData?.[tooltipModel?.dataIndex] ?? 0),
                +(lastData?.[tooltipModel?.dataIndex] ?? 0)
              )}
            </Typography>
          </Typography>
        </Box>
      </Paper>
    </Box>
  );
};

import { theme } from "@zesty-io/material";
import { useMemo, useRef, useState } from "react";
import { Doughnut } from "react-chartjs-2";
import { ChartEvent } from "chart.js";
import { Box, Paper, Typography, Skeleton, Divider } from "@mui/material";
import { isEqual } from "lodash";
import {
  calculatePercentageDifference,
  findTopDimensions,
  findValuesForDimensions,
} from "../../utils";

const SOURCE_LEGEND_COLORS = [
  theme.palette.blue[500],
  theme.palette.green[500],
  theme.palette.pink[500],
  theme.palette.yellow[300],
  theme.palette.purple[500],
  theme.palette.grey[400],
] as const;

export const UsersDoughnutChart = ({
  usersData,
  sourceData,
  dateRange1Label,
  dateRange0Label,
  loading,
}: any) => {
  const chartRef = useRef(null);
  const [tooltipModel, setTooltipModel] = useState(null);

  const handleHover = (event: ChartEvent, chartElement: Array<any>) => {
    if (chartElement.length === 0) {
      setTooltipModel(null);
      return;
    }

    const chart = chartRef.current;
    const activeElement = chart.getElementsAtEventForMode(
      event.native,
      "nearest",
      { intersect: true },
      false
    )[0];
    const datasetIndex = activeElement?.datasetIndex;
    const index = activeElement?.index;

    if (typeof datasetIndex === "number" && typeof index === "number") {
      const model = {
        datasetIndex,
        dataIndex: index,
        x: event.x - 200,
        y: event.y + 10,
      };
      if (!isEqual(tooltipModel, model)) {
        setTooltipModel(model);
      }
    }
  };

  const dataset = useMemo(() => {
    const topSources = findTopDimensions(
      sourceData?.rows,
      ["date_range_0"],
      5
    )?.map((item) => item?.[0]?.value);
    if (!sourceData) return [];
    const result = [
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[0], "date_range_0"],
        0
      ) || 0,
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[1], "date_range_0"],
        0
      ) || 0,
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[2], "date_range_0"],
        0
      ) || 0,
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[3], "date_range_0"],
        0
      ) || 0,
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[4], "date_range_0"],
        0
      ) || 0,
    ];
    const sum = result.reduce((a, b) => a + b, 0);
    const totalSum = findValuesForDimensions(sourceData?.rows, ["date_range_0"])
      ?.map((item) => +(item || 0))
      .reduce((a, b) => a + b, 0);

    result.push(totalSum - sum);

    return result;
  }, [sourceData]);

  const priorDataset = useMemo(() => {
    const topSources = findTopDimensions(
      sourceData?.rows,
      ["date_range_1"],
      5
    )?.map((item) => item?.[0]?.value);
    if (!sourceData) return [];
    const result = [
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[0], "date_range_1"],
        0
      ) || 0,
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[1], "date_range_1"],
        0
      ) || 0,
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[2], "date_range_1"],
        0
      ) || 0,
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[3], "date_range_1"],
        0
      ) || 0,
      +findValuesForDimensions(
        sourceData?.rows,
        [topSources[4], "date_range_1"],
        0
      ) || 0,
    ];
    const sum = result.reduce((a, b) => a + b, 0);
    const totalSum = findValuesForDimensions(sourceData?.rows, ["date_range_1"])
      ?.map((item) => +(item || 0))
      .reduce((a, b) => a + b, 0);

    result.push(totalSum - sum);

    return result;
  }, [sourceData]);

  const topSources = findTopDimensions(
    sourceData?.rows,
    ["date_range_0"],
    5
  )?.map((item) => item?.[0]?.value);

  const topSourceIncreased = useMemo(() => {
    if (!sourceData) return null;
    const topSources = findTopDimensions(
      sourceData?.rows,
      ["date_range_0"],
      5
    )?.map((item) => item?.[0]?.value);

    const percentageIncreases = topSources
      .map((source) => {
        const current = +findValuesForDimensions(
          sourceData?.rows,
          [source, "date_range_0"],
          0
        );
        const prior = +findValuesForDimensions(
          sourceData?.rows,
          [source, "date_range_1"],
          0
        );
        return {
          source,
          percentage:
            current && prior
              ? Math.floor(
                  (Math.abs(current - prior) / ((current + prior) / 2)) * 100
                )
              : 0,
        };
      })
      .sort((a, b) => b.percentage - a.percentage);

    return percentageIncreases?.[0];
  }, [sourceData]);

  return (
    <>
      <Box
        position="relative"
        height="106px"
        width="110px"
        onMouseLeave={() => setTooltipModel(null)}
      >
        <Doughnut
          ref={chartRef}
          data={{
            labels: topSources,
            datasets: [
              {
                data: !loading ? dataset : [30, 20, 20, 8, 7],
                backgroundColor: [
                  !loading ? theme.palette.blue[500] : theme.palette.grey[50],
                  !loading ? theme.palette.green[500] : theme.palette.grey[100],
                  !loading ? theme.palette.pink[500] : theme.palette.grey[200],
                  !loading
                    ? theme.palette.yellow[300]
                    : theme.palette.grey[300],
                  !loading
                    ? theme.palette.purple[500]
                    : theme.palette.grey[400],
                  theme.palette.grey[400],
                ],
                borderWidth: 0,
              },
            ],
          }}
          options={{
            maintainAspectRatio: false,
            onHover: handleHover,
            layout: {
              padding: 0,
            },
            plugins: {
              tooltip: {
                enabled: false,
              },
              legend: {
                display: false,
              },
            },
            cutout: "80%",
          }}
        />
        <Box
          textAlign="center"
          position="absolute"
          top="18px"
          left="27px"
          width="56px"
        >
          {loading ? (
            <Box>
              <Skeleton
                variant="rectangular"
                height="16px"
                width="100%"
                sx={{ mt: 2, mb: 1 }}
              />
              <Skeleton variant="rectangular" height="16px" width="100%" />
            </Box>
          ) : (
            <>
              <Typography fontSize={14} fontWeight={700} lineHeight="18px">
                {(
                  +findValuesForDimensions(
                    usersData?.rows,
                    ["new", "date_range_0"],
                    0
                  ) || 0
                )?.toLocaleString()}
              </Typography>

              <Typography
                fontWeight={600}
                fontSize={10}
                lineHeight="12px"
                color="text.secondary"
              >
                {isNaN(
                  Math.floor(
                    ((+findValuesForDimensions(
                      usersData?.rows,
                      ["new", "date_range_0"],
                      0
                    ) || 0) /
                      ((+findValuesForDimensions(
                        usersData?.rows,
                        ["new", "date_range_0"],
                        0
                      ) || 0) +
                        (+findValuesForDimensions(
                          usersData?.rows,
                          ["returning", "date_range_0"],
                          0
                        ) || 0))) *
                      100
                  )
                )
                  ? 0
                  : Math.floor(
                      ((+findValuesForDimensions(
                        usersData?.rows,
                        ["new", "date_range_0"],
                        0
                      ) || 0) /
                        ((+findValuesForDimensions(
                          usersData?.rows,
                          ["new", "date_range_0"],
                          0
                        ) || 0) +
                          (+findValuesForDimensions(
                            usersData?.rows,
                            ["returning", "date_range_0"],
                            0
                          ) || 0))) *
                        100
                    )}
                % New
              </Typography>
              <Divider
                sx={{
                  my: "3px",
                }}
              />
              <Typography fontSize={14} fontWeight={700} lineHeight="18px">
                {(
                  +findValuesForDimensions(
                    usersData?.rows,
                    ["returning", "date_range_0"],
                    0
                  ) || 0
                )?.toLocaleString()}
              </Typography>
              <Typography
                fontWeight={600}
                fontSize={10}
                lineHeight="12px"
                color="text.secondary"
              >
                Returning
              </Typography>
            </>
          )}
        </Box>
        <Paper
          sx={{
            visibility: tooltipModel && !loading ? "visible" : "hidden",
            position: "absolute",
            top: tooltipModel?.y,
            left: tooltipModel?.x,
            zIndex: theme.zIndex.tooltip,
            width: 258,
          }}
          onMouseLeave={() => {
            setTooltipModel(null);
          }}
        >
          <Box sx={{ p: 2 }}>
            <Typography variant="h6" fontWeight="600" sx={{ mb: 0.5 }}>
              {topSources?.[tooltipModel?.dataIndex]}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {dateRange0Label} vs {dateRange1Label}
            </Typography>
            <Typography variant="h3" fontWeight="600" sx={{ mb: 1 }}>
              {dataset[tooltipModel?.dataIndex]?.toLocaleString()}
            </Typography>
            <Typography
              variant="body3"
              color="text.disabled"
              fontWeight={600}
              sx={{ mt: 1 }}
            >
              {priorDataset?.[tooltipModel?.dataIndex]?.toLocaleString() + " "}
              <Typography
                variant="body3"
                color={
                  calculatePercentageDifference(
                    priorDataset?.[tooltipModel?.dataIndex],
                    dataset?.[tooltipModel?.dataIndex]
                  ).startsWith("-")
                    ? "error.main"
                    : "success.main"
                }
                fontWeight={600}
              >
                {calculatePercentageDifference(
                  priorDataset?.[tooltipModel?.dataIndex],
                  dataset?.[tooltipModel?.dataIndex]
                )}
              </Typography>
            </Typography>
          </Box>
        </Paper>
      </Box>
      <Box width="100%">
        {loading ? (
          <Skeleton
            variant="rectangular"
            height="21px"
            sx={{ bgcolor: "grey.200" }}
            width="60%"
          />
        ) : (
          <Typography variant="h3" fontWeight={600}>
            {(
              (+findValuesForDimensions(
                usersData?.rows,
                ["new", "date_range_0"],
                0
              ) || 0) +
                +findValuesForDimensions(
                  usersData?.rows,
                  ["returning", "date_range_0"],
                  0
                ) || 0
            )?.toLocaleString()}
            <Typography display="inline" fontWeight={600}>
              {" "}
              users
            </Typography>
          </Typography>
        )}
        {loading ? (
          <Skeleton variant="rectangular" height="36px" sx={{ mb: 1 }} />
        ) : topSourceIncreased?.source && topSourceIncreased?.percentage ? (
          <Typography
            sx={{ mb: 1 }}
            fontSize={10}
            color="text.secondary"
            fontWeight={600}
            lineHeight="12px"
          >
            {topSourceIncreased?.source} users increased by{" "}
            {topSourceIncreased?.percentage}%{" "}
            {dateRange0Label?.startsWith("Last") ? "in the" : ""}{" "}
            {dateRange0Label?.toLowerCase()}
          </Typography>
        ) : null}
        {loading ? (
          <Skeleton variant="rectangular" height="16px" width="50%" />
        ) : (
          <Box display="flex" flexWrap="wrap">
            {topSources?.map((item, index) => (
              <Box
                key={index}
                display="flex"
                alignItems="center"
                gap={0.5}
                mr={1}
              >
                <Box
                  sx={{
                    width: 8,
                    height: 8,
                    borderRadius: "50%",
                    backgroundColor: SOURCE_LEGEND_COLORS[index],
                  }}
                />
                <Typography
                  variant="body3"
                  fontSize={10}
                  color="text.secondary"
                >
                  {item}
                </Typography>
              </Box>
            ))}
            {topSources?.length ? (
              <Box key={5} display="flex" alignItems="center" gap={0.5} mr={1}>
                <Box
                  sx={{
                    width: 8,
                    height: 8,
                    borderRadius: "50%",
                    backgroundColor: SOURCE_LEGEND_COLORS[5],
                  }}
                />
                <Typography
                  variant="body3"
                  color="text.secondary"
                  fontSize={10}
                >
                  Other
                </Typography>
              </Box>
            ) : null}
          </Box>
        )}
      </Box>
    </>
  );
};

import { Box, SvgIcon, Typography, Skeleton } from "@mui/material";
import { useHistory } from "react-router";
import {
  InboxRounded,
  LanguageRounded,
  SearchRounded,
  Instagram,
  Facebook,
  Twitter,
  YouTube,
  OpenInNewRounded,
  WarningRounded,
} from "@mui/icons-material";
import {
  useGetAllPublishingsQuery,
  useGetContentModelQuery,
  useSearchContentQuery,
} from "../../../../../../../../../shell/services/instance";
import { useGetUsersQuery } from "../../../../../../../../../shell/services/accounts";
import { startCase } from "lodash";
import { useSelector } from "react-redux";
import { format, parseISO, isValid as isValidDate } from "date-fns";

const SOURCE_DETAIL_MAP = {
  "(direct)": { color: "info.dark", bgcolor: "blue.100", icon: InboxRounded },
  google: { color: "error.dark", bgcolor: "red.100", icon: SearchRounded },
  bing: { color: "error.dark", bgcolor: "red.100", icon: SearchRounded },
  instagram: { color: "#6727BB", bgcolor: "#EBE9FE", icon: Instagram },
  facebook: { color: "#1574EA", bgcolor: "#E0F2FE", icon: Facebook },
  twitter: { color: "#1DA0F0", bgcolor: "#E0F2FE", icon: Twitter },
  youtube: { color: "#FE0000", bgcolor: "#FEE4E2", icon: YouTube },
} as const;

const fmtShort = (d?: string) => {
  if (!d) return "";
  const parsed = parseISO(d);
  const dateObj = isValidDate(parsed) ? parsed : new Date(d);
  return isValidDate(dateObj) ? format(dateObj, "MMM d") : "";
};

export const NameCell = ({
  path,
  screenPageViews,
  topSource,
  topSourceValue,
  externalLink,
}: {
  path?: string;
  screenPageViews?: number;
  topSource: keyof typeof SOURCE_DETAIL_MAP;
  topSourceValue: number;
  externalLink?: string;
}) => {
  const history = useHistory();
  const { data: item, isFetching: isItemFetching } = useSearchContentQuery({
    query: path,
    limit: 1,
  });
  const foundItem = item?.[0]?.web?.path === path ? item?.[0] : null;

  const { data: publishings, isFetching: isPublishingFetching } =
    useGetAllPublishingsQuery();
  const foundPublishing = publishings?.find(
    (p) => p.itemZUID === foundItem?.meta?.ZUID
  );

  const { data: users, isFetching: isUsersFetching } = useGetUsersQuery();
  const foundUser = users?.find(
    (u) => u.ZUID === foundPublishing?.publishedByUserZUID
  );

  const { data: model, isFetching: isModelsFetching } = useGetContentModelQuery(
    foundItem?.meta?.contentModelZUID,
    { skip: !foundItem?.meta?.contentModelZUID }
  );

  const languages = useSelector((state: any) => state.languages);
  const langCode = languages.find(
    (lang: any) => lang.ID === foundItem?.meta?.langID
  )?.code;
  const langDisplay = langCode ? `(${langCode}) ` : "";

  const hasSiblings =
    foundItem?.siblings && Object.keys(foundItem?.siblings).length > 1;

  const isFetching =
    isItemFetching ||
    isPublishingFetching ||
    isUsersFetching ||
    isModelsFetching;

  const getImage = () => {
    const ogImage = Object.keys(foundItem?.data || {}).find(
      (v) =>
        v === "ogimage" ||
        v === "ogImage" ||
        v === "og_image" ||
        v === "og:image"
    );
    if (ogImage) return foundItem?.data?.[ogImage];
    return Object.values(foundItem?.data || {}).find(
      (v) => typeof v === "string" && v.startsWith("3-")
    );
  };

  if (isFetching || !path) {
    return (
      <Box
        display="flex"
        height="40px"
        width="100%"
        alignItems="center"
        gap={1}
      >
        <Skeleton
          variant="rectangular"
          width="40px"
          height="40px"
          sx={{ minWidth: "40px" }}
        />
        <Box width="100%">
          <Skeleton
            variant="rectangular"
            width="100%"
            height="12px"
            sx={{ bgcolor: "grey.200", mb: 1 }}
          />
          <Skeleton variant="rectangular" width="80%" height="12px" />
        </Box>
      </Box>
    );
  }

  return (
    <Box
      display="flex"
      height="40px"
      width="100%"
      alignItems="center"
      gap={1}
      onClick={() => {
        if (foundItem) {
          history.push(
            `/content/${foundItem?.meta?.contentModelZUID}/${foundItem?.meta?.ZUID}`
          );
        } else if (externalLink) {
          window.open(externalLink);
        }
      }}
    >
      <Box height="40px" width="40px" bgcolor="info.main" borderRadius="4px">
        {Object.values(foundItem?.data || {}).some(
          (v) => typeof v === "string" && v.startsWith("3-")
        ) && (
          <img
            width="100%"
            height="100%"
            style={{
              objectFit: "cover",
              minWidth: "40px",
              borderRadius: "4px",
            }}
            src={`${
              // @ts-ignore
              CONFIG.SERVICE_MEDIA_RESOLVER
            }/resolve/${getImage()}/getimage/?w=200&h=200&type=fit`}
            onError={(e) => {
              e.currentTarget.style.display = "none";
            }}
          />
        )}
      </Box>

      <Box>
        <Box display="flex" gap={0.5} alignItems="center">
          <Typography
            variant="body2"
            fontWeight={600}
            mb={0.25}
            noWrap
            maxWidth="420px"
          >
            {hasSiblings ? langDisplay : ""}
            {foundItem?.web?.metaTitle || foundItem?.web?.metaLinkText || path}
          </Typography>
          <OpenInNewRounded
            onClick={(e) => {
              e.stopPropagation();
              if (externalLink) window.open(externalLink);
            }}
            color="action"
            sx={{ width: 16, height: 16 }}
          />
        </Box>

        {foundItem ? (
          <Box display="flex" gap={1.5}>
            <Typography variant="body3" fontWeight={600} color="text.secondary">
              {fmtShort(foundPublishing?.publishAt)}
            </Typography>
            <Typography variant="body3" fontWeight={600} color="text.secondary">
              {foundUser
                ? `${foundUser.firstName} ${foundUser.lastName}`
                : "Unknown User"}
            </Typography>
            <Typography variant="body3" fontWeight={600} color="text.secondary">
              {model?.label}
            </Typography>

            {topSource && (
              <Box display="flex" alignItems="center">
                <Box
                  display="flex"
                  alignItems="center"
                  gap={0.25}
                  px={0.5}
                  py={0.25}
                  bgcolor={SOURCE_DETAIL_MAP[topSource]?.bgcolor || "yellow.50"}
                  sx={{ borderRadius: "2px 0 0 2px" }}
                >
                  <SvgIcon
                    component={
                      SOURCE_DETAIL_MAP[topSource]?.icon || LanguageRounded
                    }
                    sx={{
                      width: 8,
                      height: 8,
                      color:
                        SOURCE_DETAIL_MAP[topSource]?.color || "warning.main",
                    }}
                  />
                  <Typography
                    fontSize="10px"
                    fontWeight={600}
                    lineHeight="12px"
                    color={
                      SOURCE_DETAIL_MAP[topSource]?.color || "warning.main"
                    }
                  >
                    {startCase(topSource)}
                  </Typography>
                </Box>
                <Box
                  px={0.5}
                  py={0.25}
                  bgcolor={
                    SOURCE_DETAIL_MAP[topSource]?.color || "warning.main"
                  }
                  sx={{ borderRadius: "0 2px 2px 0" }}
                >
                  <Typography
                    fontSize="8px"
                    fontWeight={600}
                    lineHeight="12px"
                    color="common.white"
                  >
                    {isNaN(
                      Math.floor(
                        (topSourceValue / (screenPageViews || 0)) * 100
                      )
                    )
                      ? 0
                      : Math.floor(
                          (topSourceValue / (screenPageViews || 1)) * 100
                        )}
                    %
                  </Typography>
                </Box>
              </Box>
            )}
          </Box>
        ) : (
          <Box display="flex" gap={0.5} alignItems="center">
            <WarningRounded sx={{ width: 12, height: 12 }} color="warning" />
            <Typography variant="body3" fontWeight={600} color="text.secondary">
              This item does not exist in your instance
            </Typography>
          </Box>
        )}
      </Box>
    </Box>
  );
};

import { Box, Skeleton, Typography } from "@mui/material";
import { useSearchContentQuery } from "../../../../../../../../../shell/services/instance";
import { numberFormatter } from "../../../../../../../../../utility/numberFormatter";
import { useHistory } from "react-router";

const formatMMSS = (totalSeconds: number) => {
  const m = Math.floor((totalSeconds || 0) / 60);
  const s = Math.floor((totalSeconds || 0) % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
};

export const StatsCell = ({
  path,
  users,
  avgSessionDuration,
}: {
  path?: string;
  users: number;
  avgSessionDuration: number;
}) => {
  const history = useHistory();
  const { data: item, isFetching } = useSearchContentQuery({
    query: path,
    limit: 1,
  });
  const foundItem = item?.[0]?.web?.path === path ? item?.[0] : null;

  if (isFetching || !path) {
