        {formatMMSS(avgSessionDuration)} avg. time
      </Typography>
    </Box>
  );
};

import { Box, Skeleton, Typography } from "@mui/material";

import { useSearchContentQuery } from "../../../../../../../../../shell/services/instance";
import { calculatePercentageDifference } from "../../../utils";
