const AnalyticsDashboard = ({ loading }: Props) => {
  const [params] = useQueryParams();
  const instance = useSelector((state: AppState) => state.instance);
  const { data: instanceSettings, isFetching: instanceSettingsFetching } =
    useGetInstanceSettingsQuery();
  const propertyId = instanceSettings?.find(
    (setting) => setting.key === "google_property_id"
  )?.value;

  const [startDate, endDate, dateRange0Label, dateRange1Label] =
    getDateRangeAndLabelsFromParams(params);

  const {
    data: ga4Data,
    isFetching,
    isError,
    refetch,
  } = useGetAnalyticsPropertyDataByQueryQuery(
    {
      property: propertyId,
      requests: [
        {
          // overall sessions, duration, bounce and conversions
          metrics: [
            { name: "sessions" },
            { name: "averageSessionDuration" },
            { name: "bounceRate" },
            { name: "eventCount" },
            { name: "conversions" },
          ],
          dateRanges: generateDateRangesForReport(startDate, endDate),
        },
        {
          // daily and total sessions
          dimensions: [{ name: "date" }],
          metrics: [{ name: "sessions" }],
          dateRanges: generateDateRangesForReport(startDate, endDate),
          orderBys: [{ dimension: { dimensionName: "date" } }],
        },
        {
          // user traffic default channel
          dimensions: [{ name: "firstUserDefaultChannelGroup" }],
          metrics: [{ name: "sessions" }],
          dateRanges: generateDateRangesForReport(startDate, endDate),
          metricAggregations: ["TOTAL"],
        },
        {
          // new vs returning
          dimensions: [{ name: "newVsReturning" }],
          metrics: [{ name: "totalUsers" }],
          dateRanges: generateDateRangesForReport(startDate, endDate),
        },
      ],
    },
    { skip: !propertyId }
  );

  const [
    metricsReport,
    dailySessionsReport,
    userSourcesReport,
    newVsReturningReport,
  ] = ga4Data?.reports || [];

  const isLoading = isFetching || instanceSettingsFetching || loading;

  if (isError) {
    return (
      <NotFound
        title="Unable to Load Analytics Data"
        message="This may be due to a bad internet connection so please try again. If you are still unable to resolve this issue, please contact support."
        button={
          <>
            <Button
              startIcon={<SupportAgentRoundedIcon color="action" />}
              variant="contained"
              color="inherit"
              sx={{ mr: 2 }}
              onClick={() =>
                window.open(
                  `https://www.zesty.io/instances/${instanceZUID}/support/`
                )
              }
            >
              Contact Support
            </Button>
            <Button
              startIcon={<RefreshRoundedIcon />}
              variant="contained"
              onClick={() => refetch()}
            >
              Try Again
            </Button>
          </>
        }
      />
    );
  }

  return (
    <Box
      color={theme.palette.text.primary}
      bgcolor={theme.palette.grey[50]}
      boxSizing="border-box"
      display="flex"
      flexDirection="column"
      height="100%"
    >
      <AnalyticsDashboardHeader />
      <Box pb={8} px={4} overflow="auto" height="100%">
        <Box display="flex" py={2} justifyContent="space-between">
          <AnalyticsDateFilter />
          <Typography variant="h6" fontWeight="600" maxWidth={304} noWrap>
            {instance.name}
          </Typography>
          <AnalyticsPropertySelector />
        </Box>

        <Box display="flex" gap={2}>
          <Box
            borderRadius={"8px"}
            gap={2}
            p={2}
            border={(theme) => `1px solid ${theme.palette.border}`}
            bgcolor="background.paper"
            display="flex"
            width="55%"
          >
            <Box minWidth="120px">
              {isLoading ? (
                <Skeleton
                  variant="rectangular"
                  width="100%"
                  height="32px"
                  sx={{ bgcolor: "grey.200" }}
                />
              ) : (
                <>
                  <Typography variant="body2" fontWeight="600">
                    Total Sessions
                  </Typography>
                  <Typography
                    variant="body3"
                    fontWeight="600"
                    color="text.secondary"
                  >
                    {dateRange0Label}
                  </Typography>
                </>
              )}
