      <Box
        gap={3}
        pb={2}
        pr={4}
        sx={{
          display: "grid",
          gridTemplateColumns: "repeat(3, minmax(auto, 510px))",
          gridTemplateRows: "repeat(2, 378px)",
          gridColumnGap: "24px",
