export const ApiDetails = () => {
  const history = useHistory();
  const location = useLocation();
  const { contentModelZUID } = useParams<{ contentModelZUID: string }>();
  const { data: modelData } = useGetContentModelQuery(contentModelZUID, {
    skip: !contentModelZUID,
  });
  const installedApps = useSelector((state: AppState) => state.apps.installed);
  const selectedType = location.pathname.split("/").pop() as ApiType;
  const { data: instanceSettings, isFetching } = useGetInstanceSettingsQuery(
    null,
    { skip: selectedType !== "site-generators" }
  );
  const headlessEnabled =
    instanceSettings?.find((setting) => setting.key === "mode")?.value !==
    "traditional";

  const filteredApiTypes = useMemo(() => {
    if (modelData?.type === "dataset") {
      return apiTypes.filter((apiType) => apiType !== "site-generators");
    }

    return apiTypes;
  }, [modelData]);

  const handleVisualLayoutClick = () => {
    const layoutApp = installedApps?.find(
      (app: any) => app?.name === "layouts"
    );
    if (layoutApp) {
      history.push(`/app/${layoutApp.ZUID}`);
    } else {
      window.open("https://www.zesty.io/marketplace/apps/page-layout-designer");
    }
  };

  useEffect(() => {
    if (selectedType === "site-generators" && modelData?.type === "dataset") {
      history.replace(`${location.pathname.split("/").slice(0, -1).join("/")}`);
    }
  }, [selectedType, modelData]);

  return (
    <Box display="flex" height="100%" sx={{ overflowY: "auto" }}>
      <Box
        width="220px"
        pt={2}
        pl={4}
        sx={{
          borderRight: (theme) => `1px solid ${theme.palette.border}`,
        }}
      >
        <Box pb={1}>
          <Button
            size="small"
            color="inherit"
            startIcon={<ArrowBackRoundedIcon color="action" />}
            onClick={() =>
              history.push(
                `${location.pathname.split("/").slice(0, -1).join("/")}`
              )
            }
          >
            Back
          </Button>
        </Box>
        <Box pr={1}>
          {filteredApiTypes?.map((type) => (
            <ListItemButton
              key={type}
              sx={{ py: "6px", px: "12px", borderRadius: "4px" }}
              selected={selectedType === type}
              onClick={() =>
                history.push(
                  `${location.pathname
                    .split("/")
                    .slice(0, -1)
                    .join("/")}/${type}`
                )
              }
            >
              <ListItemIcon
                sx={{
                  minWidth: "unset",
                  mr: 1,
                  color: selectedType === type && "primary.main",
                }}
              >
                <SvgIcon fontSize="small" component={apiTypeIconMap[type]} />
              </ListItemIcon>
              <ListItemText
                sx={{ m: 0 }}
                primary={apiTypeLabelMap[type]}
                primaryTypographyProps={{
                  fontWeight: 500,
                  variant: "caption",
                  color:
                    selectedType === type ? "primary.dark" : "text.secondary",
                  sx: { wordBreak: "break-word" },
                }}
              />
            </ListItemButton>
          ))}
        </Box>
      </Box>
      {isFetching ? (
        <Box
          flex={1}
          display="flex"
          alignItems="center"
          justifyContent="center"
          height="100%"
        >
          <CircularProgress />
        </Box>
      ) : (
        <Box
          flex={1}
          pl={3}
          pr={4}
          py={2}
          sx={{
            overflow: "auto",
          }}
        >
          {selectedType === "site-generators" && !headlessEnabled ? (
            <HeadlessSwitcher
              instanceSetting={instanceSettings?.find(
                (setting) => setting.key === "mode"
              )}
            />
          ) : (
            <Box maxWidth="640px">
              <ApiInfo type={selectedType} large />

              {[...apiTypesWithEndpoints].includes(selectedType) && (
                <Button
                  variant="outlined"
                  startIcon={<MenuBookRoundedIcon />}
                  sx={{
                    my: 3,
                  }}
                  onClick={() => window.open(apiTypeDocsMap[selectedType])}
                >
                  Read Docs
                </Button>
              )}
              {selectedType === "custom-endpoints" && (
                <Stack
                  direction="row"
                  gap={1.5}
                  sx={{
                    my: 3,
                  }}
                >
                  <Button
                    variant="outlined"
                    startIcon={<CodeRoundedIcon />}
                    onClick={() => history.push("/code")}
                  >
                    Open Code App
                  </Button>
                  <Button
                    variant="outlined"
                    startIcon={<MenuBookRoundedIcon color="action" />}
                    onClick={() => window.open(apiTypeDocsMap[selectedType])}
                    color="inherit"
                  >
                    Read Docs
                  </Button>
                </Stack>
              )}
              {selectedType === "visual-layout" && (
                <Stack
                  direction="row"
                  gap={1.5}
                  sx={{
                    my: 3,
                  }}
                >
                  <Button
                    variant="outlined"
                    startIcon={<NewspaperRoundedIcon />}
                    onClick={handleVisualLayoutClick}
                  >
                    Open Visual Layout
                  </Button>
                  <Button
                    variant="outlined"
                    startIcon={<MenuBookRoundedIcon color="action" />}
                    onClick={() => window.open(apiTypeDocsMap[selectedType])}
                    color="inherit"
                  >
                    Read Docs
                  </Button>
                </Stack>
              )}
              {apiTypesWithEndpoints.includes(selectedType) && (
                <ApiDomainEndpoints type={selectedType} />
              )}
            </Box>
          )}
        </Box>
      )}
    </Box>
  );
};

import { format as dfFormat, isSameDay, subDays, getYear } from "date-fns";
import { utcToZonedTime } from "date-fns-tz";

export const formatDate = (
  dateString: string,
  showPastYear?: boolean
): string => {
  try {
    const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
    const input = new Date(dateString);
    if (isNaN(input.getTime())) return "Invalid Date";

    // Convert to the user's TZ for comparisons/formatting
    const zoned = utcToZonedTime(input, timeZone);
    const nowZoned = utcToZonedTime(new Date(), timeZone);

    let dateLabel: string;
    if (isSameDay(zoned, nowZoned)) {
      dateLabel = "Today";
    } else if (isSameDay(zoned, subDays(nowZoned, 1))) {
      dateLabel = "Yesterday";
    } else if (showPastYear) {
      dateLabel =
        getYear(zoned) === getYear(nowZoned)
          ? dfFormat(zoned, "MMM d")
          : dfFormat(zoned, "MMM d, yyyy");
    } else {
      dateLabel = dfFormat(zoned, "MMM d");
    }

    // Get TZ abbreviation via Intl parts (e.g., "PDT")
    const tzName =
      new Intl.DateTimeFormat("en-US", {
        timeZone,
        timeZoneName: "short",
      })
        .formatToParts(zoned)
        .find((p) => p.type === "timeZoneName")?.value || "";

    const timeLabel = dfFormat(zoned, "h:mm a");
    return `${dateLabel}, ${timeLabel} ${tzName}`;
  } catch (e) {
    // Fallback: best-effort local formatting
    const d = new Date(dateString);
    if (isNaN(d.getTime())) return "Invalid Date";
    return dfFormat(d, "MMM d, h:mm a");
  }
};

