export const LanguageSelector = () => {
  const dispatch = useDispatch();
  const history = useHistory();
  const location = useLocation();
  const { modelZUID, itemZUID } = useParams<{
    modelZUID: string;
    itemZUID: string;
  }>();
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const { data: versions } = useGetContentItemVersionsQuery({
    modelZUID,
    itemZUID,
  });
  const { data: itemPublishings } = useGetItemPublishingsQuery({
    modelZUID,
    itemZUID,
  });
  const { data: languages, isLoading: isLoadingLanguages } = useGetLangsQuery(
    {}
  );

  const item = useSelector(
    (state: AppState) => state.content[itemZUID] as ContentItem
  );

  const onSelect = (langId: string) => {
    dispatch(selectLang(langId));

    // If we are at a content item level then reload newly selected language item
    const parts = location.pathname.split("/");
    // @ts-ignore
    const siblingZUID = item.siblings[langId];

    if (parts[3] && siblingZUID) {
      const subpath = parts.slice(0, 3);
      subpath.push(siblingZUID);
      history.push(`${subpath.join("/")}`);
    }
  };

  const activeLanguage = languages?.find(
    (lang) => lang.ID === item?.meta?.langID
  ) || {
    code: "en-US",
  };

  if (isLoadingLanguages) {
    return (
      <Stack direction="row" gap={0.5}>
        <Skeleton variant="rounded" width={69} height={20} />
        <KeyboardArrowDownRounded fontSize="small" color="action" />
      </Stack>
    );
  }

  return (
    <>
      <Tooltip
        title="View Languages"
        enterDelay={1000}
        enterNextDelay={1000}
        placement="top-start"
      >
        <Button
          sx={{
            color: "text.disabled",
            height: "24px",
            minWidth: "unset",
            padding: "2px",
            " .MuiButton-endIcon": {
              marginLeft: "4px",
            },
          }}
          color="inherit"
          endIcon={<KeyboardArrowDownRounded color="action" />}
          onClick={(e) => setAnchorEl(e.currentTarget)}
          data-cy="language-selector"
        >
          <Box component="span" color="text.primary">
            <Flag countryCode={getCountryCode(activeLanguage?.code)} />
          </Box>{" "}
          {activeLanguage?.code?.split("-")[0]?.toUpperCase()} (
          {getCountryCode(activeLanguage?.code)})
        </Button>
      </Tooltip>
      <Menu
        onClose={() => setAnchorEl(null)}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "right",
        }}
        transformOrigin={{
          vertical: -10,
          horizontal: "right",
        }}
        anchorEl={anchorEl}
        open={!!anchorEl}
        PaperProps={{
          sx: {
            boxShadow: (theme) => theme.shadows[8],
            width: "280px",
          },
        }}
      >
        {languages?.map((language) => (
          <MenuItem
            key={language.code}
            onClick={() => {
              setAnchorEl(null);
              onSelect(language.code);
            }}
          >
            <Flag countryCode={getCountryCode(language.code)} />{" "}
            {language.code.split("-")[0]?.toUpperCase()} (
            {getCountryCode(language.code)})
          </MenuItem>
        ))}
      </Menu>
    </>
  );
};

import {
  Button,
  Dialog,
  DialogActions,
  DialogTitle,
  Typography,
  Box,
} from "@mui/material";
import { ContentCopyRounded } from "@mui/icons-material";
import { useHistory, useParams } from "react-router";
import { useSelector, useDispatch } from "react-redux";

import { AppState } from "../../../../../../../../shell/store/types";
import {
  ContentItem,
  Language,
} from "../../../../../../../../shell/services/types";
import {
  useCreateContentItemMutation,
  useGetContentModelFieldsQuery,
  useGetContentModelsQuery,
} from "../../../../../../../../shell/services/instance";
import { notify } from "../../../../../../../../shell/store/notifications";
import { fetchItems } from "../../../../../../../../shell/store/content";

type DuplicateItemProps = {
  onClose: () => void;
};

export const DuplicateItemDialog = ({ onClose }: DuplicateItemProps) => {
  const dispatch = useDispatch();
  const { modelZUID, itemZUID } = useParams<{
    modelZUID: string;
    itemZUID: string;
  }>();
  const { data: modelFields } = useGetContentModelFieldsQuery({
    modelZUID,
    showDeleted: false,
  });
  const history = useHistory();
  const item = useSelector(
    (state: AppState) => state.content[itemZUID] as ContentItem
  );
  const langCode = useSelector((state: AppState) => state?.user?.selected_lang);

  const { data: models, refetch: refetchContentModels } =
    useGetContentModelsQuery();

  const [createContentItem, { isLoading }] = useCreateContentItemMutation();

  const duplicateItem = () => {
    let fieldToChange;
    if (modelFields?.[0]?.datatype === "text") {
      fieldToChange = modelFields[0].name;
    }

    const uuidFieldKeys = modelFields
      ?.filter((field) => field.datatype === "uuid")
      ?.map((field) => field.name);

    const newData = { ...item.data };

    uuidFieldKeys?.forEach((key) => {
      newData[key] = null; // Set each uuid key to null
    });

    createContentItem({
      modelZUID,
      body: {
        data: {
          ...newData,
          ...(fieldToChange && {
            [fieldToChange]: item.data[fieldToChange] + " (copy)",
          }),
        },
        web: {
          canonicalTagMode: item.web.canonicalTagMode,
          parentZUID: item.web.parentZUID,
          metaLinkText: !item.web.metaLinkText
            ? null
            : item.web.metaLinkText?.slice(0, 143) + " (copy)",
          metaTitle: item.web.metaTitle?.slice(0, 143) + " (copy)",
          metaDescription: !item.web.metaDescription
            ? null
            : item.web.metaDescription?.slice(0, 153) + " (copy)",
          pathPart: item.web.pathPart
            ? item.web.pathPart + `-${new Date().toISOString()}`
            : undefined,
        },
        meta: {
          langID: item.meta.langID,
          contentModelZUID: item.meta.contentModelZUID,
        },
      },
    })
      .unwrap()
      .then((res) => {
        refetchContentModels();
        dispatch(fetchItems(modelZUID))
          //@ts-ignore
          .then((fetchItemsResponse: any) => {
            const createdItem = fetchItemsResponse?.data?.find(
              (item: ContentItem) => item?.meta?.ZUID === res.data.ZUID
            );
            const itemLangZUID =
              createdItem?.siblings?.[langCode] || res?.data?.ZUID;
            history.push(
              `/${
                models?.find((model) => model?.ZUID === modelZUID)?.type ===
                "block"
                  ? "blocks"
                  : "content"
              }/${modelZUID}/${itemLangZUID}`
            );
          });
        onClose();
      })
      .catch((error) => {
        console.error("Failed to duplicate item", error);
        dispatch(
          notify({
            message: "Failed to duplicate item.",
            kind: "error",
          })
        );
      });
  };

  return (
    <Dialog open fullWidth maxWidth={"xs"} onClose={onClose}>
      <DialogTitle component="div">
        <Box
          sx={{
            backgroundColor: "deepOrange.100",
            borderRadius: "100%",
            width: "40px",
            height: "40px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <ContentCopyRounded color="primary" />
        </Box>
        <Typography variant="h5" sx={{ mt: 1.5 }}>
          <Typography variant="inherit" display="inline" fontWeight={600}>
            Duplicate Content Item:
          </Typography>{" "}
          {item?.web?.metaTitle || item?.web?.metaLinkText}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          This will create and save a copy of this item immediately.
        </Typography>
      </DialogTitle>
      <DialogActions>
        <Button color="inherit" onClick={onClose}>
          Cancel
        </Button>
        <Button
          variant="contained"
          color="primary"
          onClick={() => duplicateItem()}
          loading={isLoading}
        >
          Duplicate Item
        </Button>
      </DialogActions>
    </Dialog>
  );
};

import {
  Button,
  Dialog,
  DialogActions,
  DialogTitle,
  Typography,
  Stack,
  Box,
} from "@mui/material";
import { DeleteRounded } from "@mui/icons-material";
import { useHistory, useParams } from "react-router";
import { useDispatch, useSelector } from "react-redux";
import { AppState } from "../../../../../../../../shell/store/types";
import { ContentItem } from "../../../../../../../../shell/services/types";
import {
  useDeleteContentItemMutation,
  useGetContentModelItemsQuery,
} from "../../../../../../../../shell/services/instance";

type DuplicateItemProps = {
  onClose: () => void;
};

export const DeleteItemDialog = ({ onClose }: DuplicateItemProps) => {
  const dispatch = useDispatch();
  const { modelZUID, itemZUID } = useParams<{
    modelZUID: string;
    itemZUID: string;
  }>();
  const history = useHistory();
  const item = useSelector(
    (state: AppState) => state.content[itemZUID] as ContentItem
  );
  const { data: modelItems } = useGetContentModelItemsQuery(
    { modelZUID },
    { skip: !modelZUID }
  );

  const [deleteContentItem, { isLoading }] = useDeleteContentItemMutation();

  const handleRedirectBlockItem = () => {
    if (modelItems?.length - 1 <= 0) {
      history.push("/blocks");
    } else {
      history.push(`/blocks/${modelZUID}`);
    }
  };

  return (
    <Dialog open fullWidth maxWidth={"xs"} onClose={onClose}>
      <DialogTitle>
        <Box
          sx={{
            backgroundColor: "red.100",
            borderRadius: "100%",
            width: "40px",
            height: "40px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            mb: 1.5,
          }}
        >
          <DeleteRounded color="error" />
        </Box>
        <Stack>
          Delete Content Item:
          <Typography variant="inherit" fontWeight={600}>
            {item?.web?.metaTitle || item?.web?.metaLinkText}
          </Typography>
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          Deleting this item will remove it from all locations throughout your
          site and make it unavailable to API requests. This cannot be undone.
        </Typography>
      </DialogTitle>
      <DialogActions>
        <Button color="inherit" onClick={onClose}>
          Cancel
        </Button>
        <Button
          data-cy="DeleteContentItemConfirmButton"
          variant="contained"
          color="error"
          onClick={() => {
            deleteContentItem({
              modelZUID: modelZUID,
              itemZUID: itemZUID,
            }).then(() => {
              /**
               * Remove the item from the store before redirecting
               */
              dispatch({
                type: "REMOVE_ITEM",
                itemZUID,
              });

              if (history.location.pathname.includes("blocks")) {
                handleRedirectBlockItem();
              } else {
                history.push(`/content/${modelZUID}`);
              }
            });
          }}
          loading={isLoading}
        >
          Delete Item
        </Button>
      </DialogActions>
    </Dialog>
  );
};

