          variant="contained"
          onClick={() => {
            updateContentItem({
              modelZUID: modelZUID,
              itemZUID: itemZUID,
              body: {
                ...item,
                web: {
                  ...item.web,
                  metaTitle: newTitle,
                },
              },
            }).then(() => {
              dispatch(fetchItem(modelZUID, itemZUID));
              refetchContentModels();
              onClose();
            });
          }}
          loading={isLoading}
        >
          Save
        </Button>
      </DialogActions>
    </Dialog>
  );
};

