        <MenuItem
          onClick={() => {
            setAnchorEl(null);
            setShowDuplicateItemDialog(true);
          }}
        >
          <ListItemIcon>
            <ContentCopyRounded />
          </ListItemIcon>
          Duplicate {type === "block" ? "Variant" : "Item"}
