export const DuoModeSwitch = () => {
  const {
    value: showDuoMode,
    setValue: setShowDuoMode,
    isDisabled,
  } = useContext(DuoModeContext);

  if (isDisabled) {
    return null;
  }

  return (
    <Tooltip
      title={`Switch ${showDuoMode ? "off" : "on"} DUO Mode`}
      enterDelay={1000}
      enterNextDelay={1000}
      placement="top-start"
    >
      <Box>
        <IOSSwitch
          data-cy="DuoModeToggle"
          checked={showDuoMode}
          onChange={(event) => {
            if (event.target.checked) {
              setShowDuoMode(true);
            } else {
              setShowDuoMode(false);
            }
          }}
        />
      </Box>
    </Tooltip>
  );
};

