        <Stack direction="row" gap={1} flexShrink={0} alignItems="flex-start">
          {!isRenderedAsDialog && (
            <ButtonGroup
              variant="outlined"
              color="primary"
              size="small"
              disabled={!isDirty || isLoading}
            >
              <Button
                startIcon={<AddRoundedIcon />}
                onClick={() => {
                  onSave("addNew");
                }}
                loading={isLoading}
                variant="outlined"
              >
                Create & Add New
              </Button>
              <Button
                size="xsmall"
                onClick={(evt) => {
                  setAnchorEl(evt.currentTarget);
                  setDropdownMenuType("addNew");
                }}
                sx={{
                  px: 1,
                  "&.MuiButtonGroup-grouped": {
                    minWidth: 34,
                  },
                }}
              >
                <ArrowDropDownRoundedIcon sx={{ fontSize: 18 }} />
              </Button>
            </ButtonGroup>
          )}
          <ButtonGroup
            variant="contained"
            color="primary"
            size="small"
            disabled={!isDirty || isLoading}
            sx={{
              "& .MuiButtonGroup-grouped": {
                backgroundColor: "primary.main",
                color: "common.white",

                "&:hover": {
                  backgroundColor: "primary.dark",
                },
              },
            }}
          >
            <Button
              startIcon={<SaveRoundedIcon />}
              onClick={() => {
                onSave("");
              }}
              loading={isLoading}
              variant="contained"
              data-cy="CreateItemSaveButton"
            >
              Create
            </Button>
            <Button
              size="xsmall"
              onClick={(evt) => {
                setAnchorEl(evt.currentTarget);
                setDropdownMenuType("default");
              }}
              sx={{
                px: 1,
                "&.MuiButtonGroup-grouped": {
                  minWidth: 34,
                },
              }}
            >
              <ArrowDropDownRoundedIcon sx={{ fontSize: 18 }} />
            </Button>
          </ButtonGroup>
          {isRenderedAsDialog && (
            <IconButton
              size="small"
              onClick={() => {
                setInitiatorZUID(null);
