import { format as fmt, isValid as isValidDate } from "date-fns";

// This assumes the date passed in the param has a format of YYYY-MM-DD
export const toUTC = (originalDate: string) => {
  if (!originalDate) return;

  const [yearStr, monthStr, dayStr] = originalDate.split("-");
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  if (
    !Number.isFinite(year) ||
    !Number.isFinite(month) ||
    !Number.isFinite(day)
  )
    return;

  // Create a UTC date at 00:00:00 UTC for the provided Y-M-D
  const utcDate = new Date(Date.UTC(year, month - 1, day));
  if (!isValidDate(utcDate)) return;

  return fmt(utcDate, "P");
};

import { useMemo } from "react";

import {
  useGetAuditsQuery,
  useGetContentModelsQuery,
} from "../services/instance";

type GetAuditsWithBlocksParams = {
  skip?: boolean;
  params?: Record<string, any>;
};
export const useGetAuditsWithBlocks = ({
  skip = false,
  params = {},
}: GetAuditsWithBlocksParams) => {
  const { data: models } = useGetContentModelsQuery();
  const {
    data: actions,
    isLoading,
    isFetching,
    isUninitialized,
    status,
    refetch,
  } = useGetAuditsQuery(params, { skip });

  const auditsWithBlocks = useMemo(() => {
    return actions?.map((audit) => {
      if (audit.affectedZUID.startsWith("7")) {
        // Get the modelZUID from the URI
        const modelZUID = audit.meta.uri?.split("/")?.[4];
        const model = models?.find((model) => model.ZUID === modelZUID);

        if (model?.type === "block") {
          return {
            ...audit,
            resourceType: "block",
          };
        }
      }

      return audit;
    });
  }, [actions, models]);

  return {
    data: auditsWithBlocks,
    isLoading,
    isFetching,
    isUninitialized,
    status,
    refetch,
  };
};

