import { memo, useEffect, useState } from "react";
import { usePermission } from "../../../../../../shell/hooks/use-permissions";
import SaveRoundedIcon from "@mui/icons-material/SaveRounded";
import { Box } from "@mui/material";
import { useMetaKey } from "../../../../../../shell/hooks/useMetaKey";
import { fetchFiles, publishFile, saveFile } from "../../../store/files";
import CloudUploadRoundedIcon from "@mui/icons-material/CloudUploadRounded";
import { useDispatch } from "react-redux";
import { ActionButton } from "./ActionButton";
import { formatDate } from "../../../../../../utility/formatDate";
import { fetchAuditTrail } from "../../../store/auditTrail";

interface EditorActionsProps {
  fileZUID: string;
  fileType: string;
  version?: number;
  synced: boolean;
  status: string;
  isLive: boolean;
  code?: string;
  contentModelZUID?: string;
  publishedVersion?: number;
  isDirty: boolean;
  updatedAt?: string;
  updatedBy?: string;
  publishedAt?: string;
  publishedBy?: string;
}

export const EditorActions = memo(function EditorActions(
  props: EditorActionsProps
) {
  const dispatch = useDispatch();
  const canPublish = usePermission("PUBLISH");
  const canUpdate = usePermission("UPDATE", props?.fileZUID);
  const [isSaving, setIsSaving] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [fileZUID, setFileZUID] = useState(null);
  const [initialCode, setInitialCode] = useState(props.code);

  const isNotSaved = initialCode !== props.code || !!props?.isDirty;
  const isUnpublished = !props?.isLive || isNotSaved;
  const saveShortcut = useMetaKey("s", () => onSave());
  const publishShortcut = useMetaKey("p", () => onPublish());

  const fileLastUpdate =
    formatDate(props?.updatedAt).includes("Today") ||
    formatDate(props?.updatedAt).includes("Yesterday");

  const getUpdatedFiles = () => {
    dispatch(fetchFiles(props?.fileType));
    dispatch(fetchAuditTrail(props.fileZUID));
  };

  const onSave = async () => {
    setIsSaving(true);

    try {
      await Promise.resolve(
        dispatch(saveFile(props.fileZUID, props.status, props.code))
      );
    } finally {
      getUpdatedFiles();
      setInitialCode(props.code);
      setIsSaving(false);
    }
  };
  const onPublish = async () => {
    setIsPublishing(true);

    try {
      if (isNotSaved) {
        await Promise.resolve(
          dispatch(saveFile(props.fileZUID, props.status, props.code))
        );
      }
      await Promise.resolve(
        dispatch(publishFile(props.fileZUID, props.status))
      );
    } finally {
      getUpdatedFiles();
      setInitialCode(props.code);
      setIsPublishing(false);
    }
  };
  useEffect(() => {
    if (props.fileZUID !== fileZUID) {
      setInitialCode(props?.code);
      setFileZUID(props.fileZUID);
    }
  }, [props.fileZUID, props?.code, fileZUID]);

  return (
    <Box
      display="flex"
      gap={1}
      alignItems="center"
      sx={{ color: "grey.300" }}
      color="grey.300"
      pl={isNotSaved ? 1 : 0}
    >
      <ActionButton
        label={isNotSaved ? "Save" : "Saved"}
        color="primary"
        variant="contained"
        size="small"
        startIcon={<SaveRoundedIcon fontSize="small" />}
        tooltip={
          isNotSaved
            ? `Save File ${saveShortcut}`
            : `v${props?.version} saved ${!fileLastUpdate ? "" : "on"}
              ${formatDate(props?.updatedAt)}
              by ${props?.updatedBy || "Unknown"}
           `
        }
        isActive={isNotSaved}
        isLoading={isNotSaved && (isSaving || isPublishing)}
        onClick={onSave}
        isDisabled={!canUpdate}
      />

      <ActionButton
        label={
          isUnpublished ? `${isNotSaved ? "Save & " : ""}Publish` : "Published"
        }
        color="success"
        inActiveColor="success.main"
        variant="contained"
        size="small"
        startIcon={<CloudUploadRoundedIcon fontSize="small" />}
        tooltip={
          isUnpublished
            ? `Publish File ${publishShortcut}`
            : `v${props?.version} published ${!props?.publishedAt ? "" : "on"}
              ${formatDate(props?.publishedAt)}
              by ${props?.publishedBy || "Unknown"}
           `
        }
        isActive={isUnpublished}
        isLoading={isUnpublished && isPublishing}
        onClick={onPublish}
        isDisabled={!canPublish}
      />
    </Box>
  );
});

import { memo, useState, useCallback } from "react";
import { useHistory } from "react-router";
import {
  Button,
  Dialog,
  DialogActions,
  DialogTitle,
  Typography,
  Stack,
  Box,
} from "@mui/material";
import { DeleteRounded } from "@mui/icons-material";
import { useDispatch } from "react-redux";
import { deleteFile } from "../../../store/files";

interface DeleteDialogProps {
  open: boolean;
  onClose: () => void;
  fileZUID: string;
  fileName: string;
  status: string;
}

export const DeleteDialog = memo(function DeleteDialog(
  props: DeleteDialogProps
) {
  const { open, onClose, fileZUID, fileName, status } = props;

  const [deleting, setDeleting] = useState(false);
  const history = useHistory();
  const dispatch = useDispatch();

  const handleDeleteFile = useCallback(async () => {
    if (!fileZUID || !status) return;
    setDeleting(true);

    try {
      const res: any = await dispatch(deleteFile(fileZUID, status));
      setDeleting(false);
      if (res.status === 200) {
        onClose();
        history.push("/code");
      }
    } catch (err) {
      setDeleting(false);
      console.error("Failed to delete file:", err);
    }
  }, [dispatch, fileZUID, status, history, onClose]);
  return (
    <Dialog open={open} fullWidth maxWidth="xs" onClose={onClose}>
      <DialogTitle>
        <Box
          sx={{
            backgroundColor: "red.100",
            borderRadius: "100%",
            width: "40px",
            height: "40px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            mb: 1.5,
          }}
        >
          <DeleteRounded color="error" />
        </Box>
        <Stack
          display="flex"
          flexDirection="row"
          justifyContent="flex-start"
          alignItems="center"
          columnGap={1}
          overflow="hidden"
          textOverflow="ellipsis"
        >
          <Typography
            variant="inherit"
            fontWeight={700}
            flexGrow={0}
            flexShrink={0}
          >
            Delete File:
          </Typography>
          <Typography variant="inherit" fontWeight={600} noWrap flexGrow={0}>
            {`${fileName}`}
          </Typography>
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          Deleting a file will remove it and trigger a CDN purge causing A
          production to update immediately.
        </Typography>
      </DialogTitle>
      <DialogActions>
        <Button variant="text" color="inherit" onClick={onClose}>
          Cancel
        </Button>
        <Button
          data-cy="DeleteContentItemConfirmButton"
          variant="contained"
          color="error"
          onClick={handleDeleteFile}
          loading={deleting}
        >
          Delete
        </Button>
      </DialogActions>
    </Dialog>
  );
});

import { memo, useState } from "react";
import * as React from "react";
import MenuList from "@mui/material/MenuList";
import MenuItem from "@mui/material/MenuItem";
import ListItemText from "@mui/material/ListItemText";
import ListItemIcon from "@mui/material/ListItemIcon";
import Menu from "@mui/material/Menu";
import DeleteIcon from "@mui/icons-material/Delete";
import MoreHorizIcon from "@mui/icons-material/MoreHoriz";
import { IconButton, Tooltip } from "@mui/material";
import { useHistory, useLocation } from "react-router-dom";
