interface MoreOptionsProps {
  contentModelZUID?: string;
  fileType: string;
  fileZUID: string;
  publishedVersion?: string;
  version: string;
  openDeleteDialog: () => void;
}

const MoreOptions = (props: MoreOptionsProps) => {
  const history = useHistory();
  const location = useLocation();

  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);
  const open = Boolean(anchorEl);

  const [isCopied, setIsCopied] = useState(false);

  const handleCopyClick = (data: string) => {
    return () => {
      navigator?.clipboard
        ?.writeText(data)
        .then(() => {
          setIsCopied(true);
          setTimeout(() => {
            setIsCopied(false);
          }, 700);
        })
        .catch((err) => {
          console.error(err);
        });
    };
  };

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };
  const handleClose = () => {
    setAnchorEl(null);
  };
  return (
    <>
      <IconButton
        size="small"
        sx={{ color: "grey.400" }}
        id="more-options"
        onClick={handleClick}
      >
        <MoreHorizIcon fontSize="small" />
      </IconButton>
      <Menu
        id="basic-menu"
        anchorEl={anchorEl}
        open={open}
        onClose={handleClose}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "right",
        }}
        transformOrigin={{
          vertical: -8,
          horizontal: "right",
        }}
        slotProps={{
          paper: {
            sx: {
              width: 200,
              borderRadius: 1,
            },
          },
        }}
      >
        <MenuList>
          <MenuItem
            onClick={() => {
              handleClose();
              props.openDeleteDialog();
            }}
          >
            <ListItemIcon color="inherit">
              <DeleteIcon />
            </ListItemIcon>
            <ListItemText color="text.primary">Delete File</ListItemText>
          </MenuItem>
          <MenuItem onClick={handleCopyClick(props.fileZUID)}>
            <ListItemIcon color="inherit">
              {isCopied ? (
                <CheckIcon color="success" />
              ) : (
                <WidgetsRoundedIcon />
              )}
            </ListItemIcon>
            <ListItemText>Copy ZUID</ListItemText>
          </MenuItem>
          {props.contentModelZUID && (
            <MenuItem
              onClick={() =>
                window.open(
                  //@ts-expect-error
                  `${CONFIG.URL_PREVIEW_FULL}/-/instant/${props?.contentModelZUID}.json`,
                  "_blank"
                )
              }
            >
              <ListItemIcon color="inherit">
                <ElectricBoltOutlinedIcon />
              </ListItemIcon>
              <ListItemText>Preview JSON</ListItemText>
            </MenuItem>
          )}
        </MenuList>
      </Menu>
    </>
  );
};
export { TopBar };

import { FC, useState, useEffect } from "react";
import { Prompt } from "react-router-dom";

import { useDispatch } from "react-redux";

import {
  saveFile,
  fetchFile,
} from "../../../../../../apps/code-editor/src/store/files";

import { DirtyCodeModal } from "../../../../../../shell/components//DirtyCodeModal";

export type LocalDirtyCodeModal = {
  title: string;
  content: string;
  show: boolean;
  dirtyCodeZuid: string;
  dirtyCodeStatus: string;
  dirtyCodeFileType: string;
  dirtyCodeCode: string;
};

export const LocalDirtyCodeModal: FC<LocalDirtyCodeModal> = ({
  show,
  title,
  content,
  dirtyCodeZuid,
  dirtyCodeStatus,
  dirtyCodeFileType,
  dirtyCodeCode,
}) => {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [answer, setAnswer] = useState(() => (answer: boolean) => {});

  const dispatch = useDispatch();
  // Expose globals so external components can invoke
  // NOTE: Should this be a portal?
  useEffect(() => {
    window.openCodeNavigationModal = (callback) => {
      setOpen(true);
      setAnswer(() => callback);
    };
    return () => {
      window.openCodeNavigationModal = null;
    };
  }, []);

  return (
    <>
      <Prompt when={Boolean(show)} message={"code_confirm"} />
      <DirtyCodeModal
        title={title}
        content={content}
        open={open}
        loading={loading}
        onCancel={() => {
          setLoading(false);
          setOpen(false);
          answer(false);
        }}
        onSave={async () => {
          setLoading(true);
          await dispatch(
            saveFile(dirtyCodeZuid, dirtyCodeStatus, dirtyCodeCode)
          );
          setLoading(false);
          setOpen(false);
          answer(true);
        }}
        onDiscard={async () => {
          setLoading(true);
          await dispatch(
            fetchFile(dirtyCodeZuid, dirtyCodeFileType, {
              forceSync: true,
            })
          );
          await dispatch({
            type: "UNMARK_FILE_DIRTY",
            payload: { ZUID: dirtyCodeZuid },
          });
          setLoading(false);
          setOpen(false);
          answer(true);
        }}
      />
    </>
  );
};

