          )}
        </Typography>
        <OutlinedInput
          {...other}
          fullWidth
          placeholder={placeholder}
          required={required}
          error={!!error}
          inputProps={{
            name: name,
            value: value,
            onInput: handleChage,
            // "data-cy": `form-input-${name}`,
          }}
        />
