} from "@mui/material";
import { useEffect, useState } from "react";
import DeleteRoundedIcon from "@mui/icons-material/DeleteRounded";
import { useDeleteContentModelMutation } from "../../../../../shell/services/instance";
import { ContentModel, WebView } from "../../../../../shell/services/types";
import { notify } from "../../../../../shell/store/notifications";
import { useDispatch, useSelector } from "react-redux";
import { useHistory } from "react-router";

interface Props {
  onClose: () => void;
  model: ContentModel;
}

export const DeleteModelDialogue = ({ onClose, model }: Props) => {
  const dispatch = useDispatch();
  const history = useHistory();
  const [deleteConfirmation, setDeleteConfirmation] = useState("");
  const files = useSelector((state: any) => state.files) as Record<
    string,
    WebView
  >;

  const [deleteModel, { isLoading, isSuccess, error }] =
    useDeleteContentModelMutation();

  useEffect(() => {
    if (isSuccess) {
      onClose();
      const targetPath = `/${history?.location?.pathname.split("/")[1]}`;
      history.push(targetPath);
    }
  }, [isSuccess, history]);

  useEffect(() => {
    // @ts-ignore
    let message = error?.data?.error || "Failed to delete model";
    // @ts-ignore
    if (error?.data?.error.includes("Failed to Delete Model")) {
      message = `Cannot Delete Model: ${model.label}`;
    }

    if (error) {
      dispatch(
        notify({
          message,
          kind: "error",
        })
      );
    }
  }, [error]);

  const handleModelDelete = () => {
    const fileToDelete = Object.values(files).find(
      (file: WebView) => file.contentModelZUID === model.ZUID
    );
    if (fileToDelete) {
      dispatch({
        type: "DELETE_FILE_SUCCESS",
        payload: {
          fileZUID: fileToDelete.ZUID,
        },
      });
    }
    deleteModel(model.ZUID);
  };

  return (
    <Dialog open onClose={onClose} fullWidth maxWidth="xs">
      <DialogTitle>
        <Box
          sx={{
            backgroundColor: "red.100",
            borderRadius: "100%",
            width: "40px",
            height: "40px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            mb: 1.5,
          }}
        >
          <DeleteRoundedIcon color="error" />
        </Box>
        Delete Model?
        <Typography variant="body2" sx={{ mt: 1 }} color="text.secondary">
          Deleting the “{model.label}” model will also delete all of it&apos;s
          content items. This cannot be undone.
        </Typography>
      </DialogTitle>
      <DialogContent>
        <InputLabel sx={{ mb: 2.5 }}>
          Confirm by typing{" "}
          <Typography component="span" variant="inherit" color="error.main">
            "{model.label}"
          </Typography>{" "}
          below.
        </InputLabel>
        <TextField
          autoFocus
          data-cy="delete-model-confirmation-input"
          value={deleteConfirmation}
          onChange={(event) => setDeleteConfirmation(event.target.value)}
          fullWidth
        />
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} color="inherit">
          Cancel
        </Button>
        <Button
          disabled={deleteConfirmation !== model.label}
          onClick={handleModelDelete}
          loading={isLoading}
          variant="contained"
          color="error"
          data-cy="delete-model-confirmation-button"
        >
          Delete Forever
        </Button>
      </DialogActions>
    </Dialog>
  );
};

