export const FieldsListRight = ({ model }: Props) => {
  const history = useHistory();
  const [description, setDescription] = useState("");
  const [isCopied, setIsCopied] = useState(null);
  const [newParentZUID, setNewParentZUID] = useState(null);
  const [showSaveParentModelButton, setshowSaveParentModelButton] =
    useState(false);
  const { data: views } = useGetWebViewsQuery();
  const view = views?.find((view) => view?.contentModelZUID === model?.ZUID);

  useEffect(() => {
    if (model?.parentZUID) {
      setNewParentZUID(model.parentZUID === "0" ? null : model.parentZUID);
    }
  }, [model]);

  const [updateContentModel, { isLoading, isSuccess }] =
    useUpdateContentModelMutation();

  useEffect(() => {
    if (model?.description) {
      setDescription(model?.description || "");
    }
  }, [model]);

  useEffect(() => {
    if (isSuccess) {
      setshowSaveParentModelButton(false);
    }
  }, [isSuccess]);

  const handleCopyClick = (data: string) => {
    navigator?.clipboard
      ?.writeText(data)
      .then(() => {
        setIsCopied(data);
        setTimeout(() => {
          setIsCopied(null);
        }, 3000);
      })
      .catch((err) => {
        console.error(err);
      });
  };

  const handleSave = (type: "description" | "parentZUID" | "blockGroup") => {
    let body = { ...model };

    switch (type) {
      case "description":
        body = {
          ...body,
          description,
        };
        break;

      case "parentZUID":
        body = {
          ...body,
          parentZUID: newParentZUID ?? "0",
        };
        break;

      case "blockGroup":
        // TODO: Update data here
        break;

      default:
        break;
    }

    updateContentModel({
      ZUID: model.ZUID,
      body,
    });
