            Edit Template File
          </Button>
        </Alert>
      )}
      <InputLabel>
        Reference ID
        <Tooltip
          placement="top"
          title="Use this ID to retrieve anything related to this model via the API"
        >
          <InfoRoundedIcon
            sx={{ ml: 1, width: "12px", height: "12px" }}
            color="action"
          />
        </Tooltip>
      </InputLabel>
      <TextField
        disabled
        value={model?.name}
        fullWidth
        inputProps={{
          sx: {
