              textFillColor: "#101828",
            },
          },
        }}
        InputProps={{
          endAdornment: (
            <InputAdornment position="end">
              <IconButton
                size="small"
                onClick={() => handleCopyClick(model?.name)}
              >
                {isCopied === model?.name ? (
                  <CheckIcon color="action" />
