            <Typography variant="body2" color="text.secondary">
              This can be re-configured later
            </Typography>
          </Box>
          <IconButton size="small" onClick={closeForm}>
            <CloseRoundedIcon />
          </IconButton>
        </Stack>
      </DialogTitle>
      <DialogContent
        data-cy="integrationSelectDisplayOptionsDialog"
        sx={{
          py: "0px !important",
          backgroundColor: "grey.50",
          minHeight: "400px",
