  closeForm,
}: {
  activeStep: number;
  endpoint: string;
  setEndpoint: (endpoint: string) => void;
  headers: IntegrationRequestHeaders;
  setHeaders: (headers: IntegrationRequestHeaders | null) => void;
  setApiData: (data: any) => void;
  setActiveStep: (step: number) => void;
  closeForm?: () => void;
}) => {
  const focusRef = useRef<string>("url");
  const { data, status, fetchApiData } = useIntegrationField();

  const [isValidUrl, setIsValidUrl] = useState(true);
  const [reqAborted, setReqAborted] = useState<boolean>(false);

  const [endpointLocal, setEndpointLocal] = useState<string>(endpoint || "");

  const [headersLocal, setHeadersLocal] = useState<
    Record<string, { key: string; value: string }>
  >(() => {
    if (!headers || Object.keys(headers).length === 0) {
      const id = Date.now().toString();
      return { [id]: { key: "", value: "" } };
    }

    return Object.entries(headers).reduce((acc, [key, value]) => {
      const id = Date.now() + Math.random().toString(36).substr(2, 9);
      acc[id] = { key, value: String(value) };
      return acc;
    }, {} as Record<string, { key: string; value: string }>);
  });

  const handleNext = () => {
    const headersLocalValues = Object.values(headersLocal);
    const headersWithKeys = headersLocalValues.filter((i) => !!i?.key);
    const reqHeaders = !headersWithKeys?.length
      ? null
      : headersWithKeys?.reduce((acc: any, obj: any) => {
          acc[obj.key] = obj.value;
          return acc;
        }, {});

    setApiData(data);
    setHeaders(reqHeaders);
    setEndpoint(endpointLocal);
    setReqAborted(false);
    setActiveStep(activeStep + 1);
  };
  const handleAbort = () => {
    setReqAborted(true);
    setActiveStep(0);
  };

  const handleApiConnect = useCallback(() => {
    setReqAborted(false);
    setApiData(null);
    const headersLocalValues = Object.values(headersLocal);
    const headersWithKeys = headersLocalValues.filter((i) => !!i?.key);
    const options = !headersWithKeys?.length
      ? {}
      : {
          headers: headersWithKeys?.reduce((acc: any, obj: any) => {
            acc[obj.key] = obj.value;
            return acc;
          }, {}),
        };
    fetchApiData(endpointLocal, options);
  }, [endpointLocal, headersLocal]);

  return (
    <FormWrapper width="480px" height="fit-content">
      <DialogTitle component="div">
        <DataObjectRoundedIcon
          color="primary"
          sx={{
            padding: 1,
            borderRadius: "20px",
            backgroundColor: "deepOrange.50",
            display: "block",
            width: "40px",
            height: "40px",
            mb: 1.5,
          }}
        />
        <Typography variant="h5" color="text.primary" sx={{ fontWeight: 700 }}>
          Connect to API
        </Typography>
        <Typography sx={{ my: 0.5 }} variant="body2" color="text.secondary">
          Establish a connection to an endpoint for users to select items from
        </Typography>
        <Box
          display="flex"
          flexDirection="row"
          columnGap={1}
          justifyContent="flex-start"
          alignItems="center"
          component={Link}
          href="#"
        >
          <MenuBookRoundedIcon color="info" />
          <Typography variant="body2" color="info.dark">
            Learn about endpoint structures we accept
          </Typography>
        </Box>
      </DialogTitle>
      <DialogContent>
        <FieldWrapper
          label="API URL"
          isRequired={true}
          toolTip="URL defining the external data source. Must return a JSON array of flat objects with a consistent shape."
          name="integrationUrl"
        >
          <TextField
            data-cy="integrationEndpointInput"
            fullWidth
            size="small"
            autoFocus={focusRef?.current === "url"}
            placeholder="https://api.example.com/endpoint"
            value={endpointLocal}
            onInput={(e: any) => {
              const validUrl = !!e.target.value && validateUrl(e.target.value);
              setIsValidUrl(validUrl);
              setEndpointLocal(e.target.value);
            }}
            slotProps={{
              input: {
                startAdornment: (
                  <LinkRoundedIcon
                    fontSize="small"
                    color="action"
                    sx={{ mr: 0.5 }}
                  />
                ),
              },
              formHelperText: {
                "data-cy": "integrationEndpointHelperText",
              } as FormHelperTextProps,
            }}
            error={!isValidUrl}
            helperText={
              !isValidUrl
                ? "Please enter a valid URL. e.g. https://api.example.org/items.json"
                : ""
            }
          />
        </FieldWrapper>
        <Divider orientation="horizontal" sx={{ my: 1, border: "none" }} />
        <FieldWrapper
          label="HTTP Headers (optional)"
          toolTip="Authentication Headers"
        >
          <Grid
            container
            spacing={1}
            columns={16}
            width="100%"
            data-cy="integrationHeadersContainer"
          >
            {Object.entries(headersLocal)?.map((entry, i) => {
              const entryId: string = entry[0];
              const headerKey = entry[1]?.key || "";
              const headerValue = entry[1]?.value || "";
              return (
                <Grid
                  data-cy={`integrationHeadersContainerRow-${i}`}
                  key={`header-${entryId}`}
                  container
                  size={16}
                  spacing={1}
                  columns={16}
                  width="100%"
                >
                  <Grid size={8}>
                    <TextField
                      autoFocus={entryId === focusRef?.current}
                      className="keyInput"
                      fullWidth
                      size="small"
                      placeholder="Key"
                      value={headerKey}
                      onChange={(e: any) => {
                        setHeadersLocal({
                          ...headersLocal,
                          [entryId]: {
                            ...headersLocal?.[entryId],
                            key: e.target.value,
                          },
                        });
                      }}
                    />
                  </Grid>
                  <Grid
                    size={i > 0 ? 7 : 8}
                    display="flex"
                    flexDirection="row"
                    justifyContent="space-between"
                    alignItems="center"
                  >
                    <TextField
                      className="valueInput"
                      size="small"
                      placeholder="Value"
                      value={headerValue}
                      onChange={(e: any) => {
                        setHeadersLocal({
                          ...headersLocal,
                          [entryId]: {
                            ...headersLocal?.[entryId],
                            value: e.target.value,
                          },
                        });
                      }}
                      sx={{ flexGrow: 1 }}
                    />
                  </Grid>
                  {i > 0 && (
                    <Grid
                      size={1}
                      display="flex"
                      flexDirection="row"
                      justifyContent="center"
                      alignItems="center"
                    >
                      <IconButton
                        data-cy="removeHeaderButton"
                        sx={{ flexGrow: 0 }}
                        onClick={() => {
                          setHeadersLocal((prev) => {
                            if (!prev[entryId]) return prev;
                            const updated = { ...prev };
                            delete updated[entryId];
                            return updated;
                          });
                        }}
                      >
                        <CloseOutlinedIcon />
                      </IconButton>
                    </Grid>
                  )}
                </Grid>
              );
            })}
          </Grid>
          <Button
            data-cy="addHeaderButton"
            fullWidth
            variant="outlined"
            startIcon={<AddCircleIcon />}
            onClick={() => {
              const keyId: string = Date.now().toString();
              focusRef.current = keyId;
              setHeadersLocal({
                ...headersLocal,
                [keyId]: {
                  key: "",
                  value: "",
                },
              });
            }}
          >
            Add HTTP Header
          </Button>
        </FieldWrapper>
      </DialogContent>
      <DialogActions>
        <Button color="inherit" onClick={closeForm}>
          Cancel
        </Button>
        <Button
          data-cy="integrationConnectButton"
          variant="contained"
          onClick={handleApiConnect}
          startIcon={<LinkRoundedIcon />}
          disabled={!endpointLocal || !isValidUrl}
        >
          Connect
        </Button>
      </DialogActions>
      {!!status && !reqAborted && (
        <Paper
          data-cy="integrationConnectionStatusContainer"
          elevation={0}
          sx={{
            borderRadius: 2,
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            rowGap: 0.5,
            p: 4,
          }}
        >
          {CONNECTION_STATUSES?.[status]?.icon || null}
          <Box
            width="100%"
            sx={{
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              rowGap: 0.5,
              pt: 3,
              pb: 2,
            }}
          >
            <Typography
              data-cy="integrationConnectionStatusLabel"
              variant="h5"
              color="text.primary"
              fontWeight={600}
              noWrap
            >
              {CONNECTION_STATUSES[status].title}
            </Typography>
            <Typography
              variant="body2"
              color="text.primary"
              fontWeight={400}
              textAlign="center"
            >
              {CONNECTION_STATUSES[status].subTitle}
            </Typography>
          </Box>
          <Button
            data-cy="integrationConnectionStatusButton"
            startIcon={CONNECTION_STATUSES[status].buttonIcon}
            onClick={status === "success" ? handleNext : handleAbort}
            variant={CONNECTION_STATUSES[status].variant}
            color={CONNECTION_STATUSES[status].color}
            size="small"
          >
            {CONNECTION_STATUSES[status].buttonLabel}
          </Button>
        </Paper>
      )}
    </FormWrapper>
  );
};
export default ConnectToApi;

import { RefObject } from "react";
import { Box, Typography, Autocomplete, Paper, TextField } from "@mui/material";

import { COLOR_MAP } from "../configs";
import { getKeyValue } from "../utils";
import { IntegrationTypes } from "../../../services/types";
import { validateUrl } from "../../../../utility/validateUrl";

const KeyPathSelector = ({
  value,
  onChange,
  options,
  placeholder = "",
  optionsDescription = "",
  data,
  inputRef,
  restrictedTypes = [],
  name,
}: {
  value: string;
  onChange: (value: string) => void;
  options: string[];
  placeholder?: string;
  optionsDescription?: string;
  data?: any;
  inputRef?: RefObject<HTMLInputElement>;
  type?: IntegrationTypes;
  restrictedTypes?: string[];
  name?: string;
}) => {
  const filteredOptions = restrictedTypes.length
    ? options.filter((option) => {
        const optionValue = getKeyValue(data, option);
        const valueType = typeof optionValue;
        return !restrictedTypes.includes(valueType);
      })
    : options;

  const getValueType = (value: any): string => {
    if (Array.isArray(value)) return "array";
    if (value === null) return "null";
    return typeof value;
  };

  return (
    <Autocomplete
      data-cy={`integrationKeyPathSelector-${name}`}
      fullWidth
      options={filteredOptions}
      value={value}
      size="small"
      disableClearable
      autoHighlight
      onChange={(_, value) => onChange(value || "")}
      slots={{
        paper: (props) => (
          <Paper {...props} sx={{ px: 0, py: 1, position: "relative" }}>
            {optionsDescription && (
              <Typography
                variant="body2"
                color="text.secondary"
                sx={{ px: 2, pt: 1, pb: 0.5, fontStyle: "italic" }}
              >
                {optionsDescription}
              </Typography>
            )}
            <Box sx={{ width: "100%" }}>{props?.children}</Box>
          </Paper>
        ),
      }}
      renderInput={(params) => (
        <TextField {...params} placeholder={placeholder} inputRef={inputRef} />
      )}
      renderOption={(props, option) => {
        const optionValue = data ? getKeyValue(data, option) : null;
        const valueType = getValueType(optionValue);
        const isUrl =
          valueType === "string" && validateUrl(optionValue as string);
        const typeColor =
          COLOR_MAP[valueType as keyof typeof COLOR_MAP] || COLOR_MAP.default;

        const { key, ...otherProps } = props;

        return (
          <li key={key} {...otherProps}>
            <Box
              display="flex"
              alignItems="center"
              gap={1}
              width="100%"
              sx={{
                "& .MuiTypography-root": { fontFamily: "monospace" },
              }}
            >
              <Typography noWrap flex={1} variant="body2">
                {`${option}: `}
                <Typography
                  component="span"
                  variant="body2"
                  color={`${isUrl ? COLOR_MAP.url : typeColor}.600`}
                >
                  {valueType === "string"
                    ? `"${optionValue}"`
                    : JSON.stringify(optionValue, null, 3)}
                </Typography>
              </Typography>

              <Box
                component="span"
                sx={{
                  flexShrink: 0,
                  borderRadius: 1,
                  fontSize: "12px",
                  bgcolor: `${typeColor}.50`,
                  color: `${typeColor}.600`,
                  py: 0,
                  px: 1,
                }}
              >
                {valueType}
              </Box>
            </Box>
          </li>
        );
      }}
    />
  );
};

export default KeyPathSelector;

import { useEffect, useState, useRef } from "react";
import {
  Button,
  DialogActions,
  DialogContent,
  DialogTitle,
  Box,
  Divider,
  List,
  ListItem,
  Paper,
  Stack,
  Typography,
  IconButton,
} from "@mui/material";
import {
  CheckRounded,
  Settings,
  DragIndicatorRounded,
  MoreHoriz,
  DeleteRounded,
  AddRounded,
} from "@mui/icons-material";

import { FormWrapper, FieldWrapper } from "../components/Wrappers";
import { DISPLAY_OPTIONS_CONFIG, ConfigProps } from "../configs";
import { getKeyValue } from "../utils";
import { IntegrationKeyPaths, IntegrationTypes } from "../../../services/types";
import KeyPathSelector from "./KeyPathSelector";
import DisplayCard from "../components/DisplayCard";

const getObjectKeyPaths = <T extends object>(obj: T, prefix = ""): string[] => {
  const result: string[] = [];

  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const currentKey = prefix ? `${prefix}.${key}` : key;
      const value = (obj as Record<string, unknown>)[key];

      if (typeof value === "object" && value !== null) {
        if (Array.isArray(value)) {
          value.forEach((arrayElement, index) => {
            const arrayKey = `${currentKey}[${index}]`;
            if (typeof arrayElement === "object" && arrayElement !== null) {
              result.push(...getObjectKeyPaths(arrayElement, arrayKey));
            } else {
              result.push(arrayKey);
            }
          });
        } else {
          result.push(...getObjectKeyPaths(value, currentKey));
        }
      } else {
        result.push(currentKey);
      }
    }
  }

  return result;
};

const getAllArrayKeyPaths = <T extends object>(
  obj: T,
  prefix = ""
): string[] => {
  const result: string[] = [];

  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const currentKey = prefix ? `${prefix}.${key}` : key;
      const value = (obj as Record<string, unknown>)[key];

      if (Array.isArray(value)) {
        if (value.length > 0 && typeof value[0] === "object") {
          result.push(currentKey);
        }

        value.forEach((item, index) => {
          if (typeof item === "object" && item !== null) {
            result.push(
              ...getAllArrayKeyPaths(item, `${currentKey}[${index}]`)
            );
          }
        });
      } else if (typeof value === "object" && value !== null) {
        result.push(...getAllArrayKeyPaths(value, currentKey));
      }
    }
  }

  return result;
};

const ConfigureDisplayOptions = ({
  type,
  keyPaths,
  setKeyPaths,
  apiData,
  closeForm,
  setActiveStep,
  onSave,
}: {
  type: IntegrationTypes | null;
  keyPaths: IntegrationKeyPaths | null;
  setKeyPaths: (keyPaths: IntegrationKeyPaths) => void;
  apiData: any;
  closeForm?: () => void;
  setActiveStep?: (step: number) => void;
  onSave: () => void;
}) => {
  const lastDetailRef = useRef(null);
  const [apiPathOptions, setApiPathOptions] = useState<string[]>([]);
  const [rootPathOptions, setRootPathOptions] = useState<string[]>([]);
  const [rootPath, setRootPath] = useState(keyPaths?.rootPath || "");
  const [rootData, setRootData] = useState(null);

  const [rootPathData, setRootPathData] = useState({
    heading: keyPaths?.heading || null,
    subHeading: keyPaths?.subHeading || null,
    thumbnail: keyPaths?.thumbnail || null,
    detail: keyPaths?.detail || null,
  });
  const [detailsPathData, setDetailsPathData] = useState<string[]>(
    type !== "details" ? null : keyPaths?.details || [""]
  );
  const [isCompleted, setIsCompleted] = useState<boolean>(false);

  const handleSave = () => {
    onSave();
    closeForm?.();
  };

  const handleRemoveDetail = (index: number) => {
    if (detailsPathData.length === 1) {
      setDetailsPathData([""]);
      lastDetailRef.current?.focus();
      return;
    }
    setDetailsPathData((prev) => prev.filter((_, i) => i !== index));
  };

  useEffect(() => {
    if (!apiData || rootData) return;

    if (rootPath) {
      const dataRoot = getKeyValue(apiData, rootPath)[0];
      const optionsRaw = getObjectKeyPaths(dataRoot);
      setRootData(dataRoot);
      setRootPathOptions(optionsRaw);
      return;
    }

    const rootIsArray = Array.isArray(apiData);
    if (rootIsArray) {
      const dataRoot = apiData?.[0];
      const rootOptions = getObjectKeyPaths(dataRoot);
      setRootData(dataRoot);
      setRootPathOptions(rootOptions);
      return;
    }

    const apiOptions = getAllArrayKeyPaths(apiData);
    setRootData(null);
    setApiPathOptions(apiOptions);
  }, [apiData, rootPath, rootData]);

  const displayConfig = DISPLAY_OPTIONS_CONFIG?.[type] || [];

  useEffect(() => {
    const inputs = displayConfig?.map((item) => item?.name);

    const inputStatus = inputs?.map((inputName) => {
      if (inputName === "details") {
        return !detailsPathData?.filter((item) => !item)?.length;
      }
      return !!rootPathData?.[inputName as keyof typeof rootPathData];
    });

    const completed = inputStatus?.every((status) => !!status);

    if (completed) {
      setKeyPaths({
        rootPath,
        ...rootPathData,
        details: detailsPathData,
      });
    }
    setIsCompleted(completed);
  }, [displayConfig, rootPathData, detailsPathData, rootPath]);

  return (
    <FormWrapper height="calc(100vh - 40px)" width="1200px">
      <DialogTitle component="div" flexGrow={0}>
        <Settings
          color="primary"
          sx={{
            p: 1,
            borderRadius: "20px",
            bgcolor: "deepOrange.50",
            width: 40,
            height: 40,
            mb: 1.5,
            display: "block",
          }}
        />
        <Stack
          direction="row"
          justifyContent="space-between"
          alignItems="flex-start"
        >
          <Box width={520}>
            <Typography variant="h5" fontWeight={700} mb={1}>
              Configure Display Options
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Select which fields to display to content editors when they are
              editing items
            </Typography>
          </Box>
        </Stack>
      </DialogTitle>

      <DialogContent
        sx={{
          p: 0,
          bgcolor: "grey.50",
          minHeight: 400,
          display: "flex",
          flexDirection: "column",
          overflow: "hidden",
        }}
        dividers
      >
        <Box display="flex" height="100%" width="100%">
          <Box
            width="50%"
            p={2.5}
            display="flex"
            flexDirection="column"
            gap={2}
            bgcolor="grey.50"
          >
            <Box>
              <Typography variant="body1" fontWeight={700}>
                Select Keys to Display in Item
              </Typography>
              <Typography variant="body2">
                These can be re-configured later
              </Typography>
            </Box>

            {apiPathOptions.length > 0 && (
              <>
                <FieldWrapper label="Data Path" isRequired>
                  <KeyPathSelector
                    name="rootPath"
                    value={rootPath}
                    options={apiPathOptions}
                    placeholder="Select Data Path"
                    onChange={(value) => {
                      const rootDataRaw = getKeyValue(apiData, value)[0];
                      const rootPathOptionsRaw = getObjectKeyPaths(rootDataRaw);
                      setRootData(rootDataRaw);
                      setRootPathOptions(rootPathOptionsRaw);
                      setRootPath(value);
                    }}
                    data={apiData}
                  />
                </FieldWrapper>
                <Divider sx={{ my: 2 }} />
              </>
            )}

            <Box
              width="100%"
              display="flex"
              flexDirection="column"
              gap={1.5}
              data-cy="integrationConfigureOptionKeyPathContainer"
            >
              {rootPathOptions.length > 0 &&
                displayConfig.map((config: ConfigProps) => (
                  <FieldWrapper
                    key={config.name}
                    label={config.label}
                    isRequired={true}
                  >
                    {config.type === "option" ? (
                      <Box
                        width="100%"
                        display="flex"
                        flexDirection="column"
                        gap={0.5}
                      >
                        <List disablePadding sx={{ width: "100%" }}>
                          {detailsPathData.map((item, index) => (
                            <ListItem
                              data-cy={`integrationDetailsSelectorRow-${index}`}
                              key={index}
                              sx={{
                                gap: 1,
                                alignItems: "center",
                                justifyContent: "space-between",
                                px: 0,
                                py: 0.5,
                              }}
                            >
                              <KeyPathSelector
                                name={config.name}
                                value={item}
                                data={rootData}
                                options={rootPathOptions}
                                placeholder={config.placeholder}
                                optionsDescription="Values previewed for the keys below are from the first item in the API response."
                                onChange={(value) => {
                                  setDetailsPathData((prev) => [
                                    ...prev.slice(0, index),
                                    value,
                                    ...prev.slice(index + 1),
                                  ]);
                                }}
                                inputRef={
                                  index === detailsPathData.length - 1
                                    ? lastDetailRef
                                    : null
                                }
                              />
                              <IconButton
                                size="small"
                                onClick={() => handleRemoveDetail(index)}
                              >
                                <DeleteRounded color="action" />
                              </IconButton>
                            </ListItem>
                          ))}
                        </List>
                        <Button
                          data-cy="integrationConfigureDisplayOptionsAddDetailButton"
                          variant="outlined"
                          color="primary"
                          size="small"
                          startIcon={<AddRounded />}
                          onClick={() =>
                            setDetailsPathData((prev) => [...prev, ""])
                          }
                          sx={{ width: "fit-content" }}
                        >
                          Add Detail
                        </Button>
                      </Box>
                    ) : (
                      <KeyPathSelector
                        name={config.name}
                        value={
                          rootPathData[
                            config.name as keyof typeof rootPathData
                          ] as string
                        }
                        options={rootPathOptions}
                        placeholder={config.placeholder}
                        optionsDescription="Values previewed for the keys below are from the first item in the API response."
                        onChange={(value) =>
                          setRootPathData((prev) => ({
                            ...prev,
                            [config.name]: value,
                          }))
                        }
                        data={rootData}
                      />
                    )}
                  </FieldWrapper>
                ))}
            </Box>
          </Box>
          <Box
            width="50%"
            p={2.5}
            display="flex"
            flexDirection="column"
            gap={2}
            bgcolor="grey.100"
          >
            <Box>
              <Typography variant="body1" fontWeight={700}>
                Item Preview
              </Typography>
              <Typography variant="body2">
                How the items will appear to content editors
              </Typography>
            </Box>
            <Paper
              elevation={0}
              variant="outlined"
              sx={{
                width: "100%",
                display: "flex",
                flexDirection: "row",
                justifyContent: "space-between",
                alignItems: "center",
                borderColor: "border",
                borderRadius: 2,
              }}
            >
              <DragIndicatorRounded
                color="action"
                fontSize="small"
                sx={{ m: 0.5 }}
              />
              <DisplayCard
                type={type}
                heading={getKeyValue(rootData, rootPathData.heading)}
                subHeading={getKeyValue(rootData, rootPathData.subHeading)}
                thumbnail={getKeyValue(rootData, rootPathData.thumbnail)}
                detail={getKeyValue(rootData, rootPathData.detail)}
                details={detailsPathData?.map((keyPath) => ({
                  key: keyPath || "",
                  value: !keyPath ? "" : getKeyValue(rootData, keyPath),
                }))}
                showPlayIcon={false}
              />
              <MoreHoriz color="action" sx={{ m: 1.75 }} />
            </Paper>
          </Box>
        </Box>
      </DialogContent>

      <DialogActions sx={{ p: 2, height: 76, minHeight: 76 }}>
        <Button
          variant="outlined"
          color="inherit"
          onClick={() => setActiveStep?.(1)}
        >
          Back
        </Button>
        <Button
          data-cy="integrationConfigureDisplayOptionsDoneButton"
          variant="contained"
          startIcon={<CheckRounded />}
          disabled={!isCompleted}
          onClick={handleSave}
        >
          Done
        </Button>
      </DialogActions>
    </FormWrapper>
  );
};

