        sx={{
          pt: 2.5,
          pl: activeTab === "details" ? 0 : 2.5,
          backgroundColor: "grey.50",
          borderTop: 0,
        }}
      >
        {activeTab === "details" && (
          <Grid
            data-cy="DetailsTab"
            container
            rowSpacing={2.5}
            columnSpacing={2.5}
            width="inherit"
            // minHeight={448}
            ml={0}
          >
            {FORM_CONFIG[type]?.details?.map((fieldConfig, index) => {
              // Only show tooltip field when updating a field that already has a tooltip value
              const hideTooltipField =
                fieldConfig.name === "tooltip" &&
                (!isUpdateField || !fieldData.settings?.tooltip?.length);

              if (hideTooltipField) return;

              let dropdownOptions: DropdownOptions[];
              let disabled = false;
              let renderOption: any;
              let filterOptions: any;
              let autocompleteConfig: AutocompleteConfig = {};
              let integrationFieldConfig: IntegrationFieldConfig = null;

              if (fieldConfig.name === "relatedModelZUID") {
                dropdownOptions = modelsOptions;
                disabled = isLoadingModels;
              }

              if (fieldConfig.name === "integrationFieldConfig") {
                integrationFieldConfig = isUpdateField
                  ? fieldData?.settings?.integrationFieldConfig
                  : (formData[
                      "integrationFieldConfig"
                    ] as IntegrationFieldConfig);
              }

              if (fieldConfig.name === "relatedFieldZUID") {
                dropdownOptions = fieldsOptions;
                disabled = isFetchingSelectedModelFields;
              }

              if (fieldConfig.name === "currency") {
                const selectedValue = currencies.find(
                  (currency) => currency.value === formData.currency
                );
                dropdownOptions = currencies;
                renderOption = (props: any, value: Currency) => (
                  <ListItem
                    {...props}
                    key={value.value}
                    sx={{ color: "text.primary" }}
                  >
                    <Box
                      component="img"
                      height={16}
                      src={`/images/flags/${value.countryCode?.toLowerCase()}.svg`}
                      loading="lazy"
                      alt={`${value.countryCode} flag`}
                    />
                    <Typography variant="body1" fontWeight={700} pl={1}>
                      {value.value} {value.symbol_native} &nbsp;
                    </Typography>
                    <Typography variant="body1">{value.label}</Typography>
                  </ListItem>
                );
                filterOptions = (options: Currency[], state: any) => {
                  if (state.inputValue) {
                    return options.filter(
                      (option) =>
                        option.label
                          ?.toLowerCase()
                          .includes(state.inputValue.toLowerCase()) ||
                        option.value
                          ?.toLowerCase()
                          .includes(state.inputValue.toLowerCase())
                    );
                  } else {
                    return options;
                  }
                };
                autocompleteConfig.inputProps = {
                  startAdornment: !!selectedValue && (
                    <InputAdornment
                      position="start"
                      sx={{
                        pl: 0.25,

                        "&.MuiInputAdornment-root.MuiInputAdornment-positionStart":
                          {
                            color: "text.primary",
                          },
                      }}
                    >
                      <Box
                        component="img"
                        height={16}
                        src={`/images/flags/${selectedValue.countryCode?.toLowerCase()}.svg`}
                        loading="lazy"
                        alt={`${selectedValue.countryCode} flag`}
                      />
                      <Typography variant="body1" fontWeight={700} pl={1}>
                        {selectedValue.value} {selectedValue.symbol_native}
                      </Typography>
                    </InputAdornment>
                  ),
                };
                autocompleteConfig.maxHeight = 256;
              }

              return (
                <FieldFormInput
                  key={index}
                  fieldConfig={fieldConfig}
                  onDataChange={handleFieldDataChange}
                  errorMsg={isSubmitClicked && errors[fieldConfig.name]}
                  prefillData={formData[fieldConfig.name]}
                  dropdownOptions={dropdownOptions || []}
                  disabled={disabled}
                  renderOption={renderOption}
                  filterOptions={filterOptions}
                  autocompleteConfig={autocompleteConfig}
                  integrationFieldConfig={integrationFieldConfig}
                  isUpdateField={isUpdateField}
                />
              );
            })}
            {isUpdateField && (
              <Grid size={12}>
                <Button
                  data-cy="DeactivateReactivateFieldUpdateModal"
                  variant="outlined"
                  color="inherit"
                  startIcon={
                    fieldStateOnSaveAction === "deactivate" ? (
                      <PlayCircleFilledRoundedIcon color="action" />
                    ) : (
                      <PauseCircleOutlineRoundedIcon color="action" />
                    )
                  }
                  onClick={() => {
                    setFieldStateOnSaveAction(
                      fieldStateOnSaveAction === "deactivate"
                        ? "reactivate"
                        : "deactivate"
                    );
                  }}
                  loading={isDeletingField || isUndeletingField}
                >
                  {fieldStateOnSaveAction === "deactivate"
                    ? "Reactivate Field"
                    : "Deactivate Field"}
                </Button>
              </Grid>
            )}
          </Grid>
        )}

        {activeTab === "rules" && (
          <Rules
            type={type}
            onFieldDataChanged={handleFieldDataChange}
            mediaFoldersOptions={mediaFoldersOptions}
            formData={formData}
            isSubmitClicked={isSubmitClicked}
            errors={errors}
            isDefaultValueEnabled={isDefaultValueEnabled}
            setIsDefaultValueEnabled={setIsDefaultValueEnabled}
          />
        )}

        {activeTab === "learn" && <Learn type={type} />}
      </DialogContent>
      {isUpdateField ? (
        <DialogActions
          sx={{
            pt: 2.5,
          }}
        >
          <Button
            variant="outlined"
            color="inherit"
            onClick={onModalClose}
            sx={{
              mr: 1,
            }}
          >
            Cancel
          </Button>
          <Button
            data-cy="FieldFormAddFieldBtn"
            loading={isUpdatingField}
            onClick={handleSubmitForm}
            variant="contained"
            startIcon={<SaveRoundedIcon />}
          >
            Save
          </Button>
        </DialogActions>
      ) : (
        <DialogActions
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            pt: 2.5,
          }}
        >
          <Button variant="outlined" color="inherit" onClick={onBackClick}>
            Cancel
          </Button>
          <Box>
            <Button
              data-cy="FieldFormAddAnotherFieldBtn"
              variant="outlined"
              startIcon={<AddRoundedIcon />}
              sx={{
                mr: 2,
              }}
              loading={isCreatingField || isBulkUpdating}
              onClick={handleAddAnotherField}
            >
              Add Another Field
            </Button>
            <Button
              data-cy="FieldFormAddFieldBtn"
              loading={isCreatingField || isBulkUpdating}
              onClick={handleSubmitForm}
              variant="contained"
            >
              Add Field
            </Button>
          </Box>
        </DialogActions>
      )}
    </>
  );
};

import { useState, useMemo, useEffect } from "react";
import { useParams } from "react-router";
import { Dialog } from "@mui/material";

import { FieldSelection } from "./views/FieldSelection";
import { FieldForm } from "./views/FieldForm";
import { useGetContentModelFieldsQuery } from "../../../../../../shell/services/instance";
import { FieldType } from "../configs";
import { ContentModelFieldDataType } from "../../../../../../shell/services/types";

type Params = {
  id: string;
  fieldId: string;
};
export type ViewMode = "fields_list" | "new_field" | "update_field";
interface Props {
  onModalClose: () => void;
  mode: ViewMode;
  sortIndex?: number | null;
}
export const AddFieldModal = ({ onModalClose, mode, sortIndex }: Props) => {
  const [viewMode, setViewMode] = useState<ViewMode>(mode);
  const [selectedField, setSelectedField] = useState({
    fieldType: "",
    fieldName: "",
  });
  const params = useParams<Params>();
  const { id, fieldId } = params;
  const [localSortIndex, setLocalSortIndex] = useState<number | null>(null);
  const { data: fields } = useGetContentModelFieldsQuery({ modelZUID: id });
  useEffect(() => {
    // Local copy is incremented when user clicks "add another field"
    setLocalSortIndex(sortIndex);
  }, [sortIndex]);

  const fieldData = useMemo(() => {
    return fields?.find((field) => field.ZUID === fieldId);
  }, [fieldId, fields]);

  const handleFieldClick = (fieldType: FieldType, fieldName: string) => {
    setViewMode("new_field");
    setSelectedField({ fieldType, fieldName });
  };

  const handleCreateAnotherField = () => {
    setViewMode("fields_list");

    if (localSortIndex !== null) {
      setLocalSortIndex((prevData) => prevData + 1);
    }
  };

  return (
    <Dialog
      data-cy="AddFieldModal"
      open
      onClose={onModalClose}
      fullScreen={viewMode === "fields_list"}
      sx={{
        my: "20px",
      }}
      slotProps={{
        paper: {
          sx: {
            width: viewMode === "fields_list" ? "900px" : "640px",
            maxWidth: "100%",
            maxHeight: "min(100%, 1000px)",
            minHeight: "680px",
            m: 0,
            "&:has(.IntegrationConfigForm)": {
              visibility: "hidden",
            },
          },
        },
      }}
    >
      {viewMode === "fields_list" && (
        <FieldSelection
          onModalClose={onModalClose}
          onFieldClick={handleFieldClick}
        />
      )}
      {viewMode === "new_field" && (
        <FieldForm
          fields={fields}
          type={selectedField?.fieldType as ContentModelFieldDataType}
          name={selectedField?.fieldName}
          onModalClose={onModalClose}
          onBackClick={() => setViewMode("fields_list")}
          sortIndex={localSortIndex}
          onCreateAnotherField={handleCreateAnotherField}
        />
      )}
      {viewMode === "update_field" && (
        <FieldForm
          fields={fields}
          type={fieldData?.datatype as ContentModelFieldDataType}
          name={fieldData?.label}
          onModalClose={onModalClose}
          fieldData={fieldData}
          sortIndex={null}
        />
      )}
    </Dialog>
  );
};

import { Box, Typography, Button, Avatar } from "@mui/material";
import { useGetContentModelsQuery } from "../../../../../../shell/services/instance";
import { useHistory, useParams } from "react-router";
import { format, isValid } from "date-fns";
import { useGetUsersQuery } from "../../../../../../shell/services/accounts";
import { useState } from "react";
import { MD5 } from "../../../../../../utility/md5";

type Params = {
  id: string;
};

export const ActivityDetails = () => {
  const params = useParams<Params>();
  const { id } = params;
  const history = useHistory();
  const { data: models } = useGetContentModelsQuery();
  const model = models?.find((model) => model.ZUID === id);
  const { data: users } = useGetUsersQuery();
  const createdByUser = users?.find(
    (user) => user.ZUID === model?.createdByUserZUID
  );
  const updatedByUser = users?.find(
    (user) => user.ZUID === model?.updatedByUserZUID
  );

  const [isCopied, setIsCopied] = useState("");

  const createdDate = model?.createdAt ? new Date(model.createdAt) : null;
  const updatedDate = model?.updatedAt ? new Date(model.updatedAt) : null;

  const createdOn =
    createdDate && isValid(createdDate)
      ? format(createdDate, "do MMMM, yyyy 'at' h:mm a")
      : "";

  const updatedOn =
    updatedDate && isValid(updatedDate)
      ? format(updatedDate, "do MMMM, yyyy 'at' h:mm a")
      : "";

  const handleCopy = (data: string) => {
    navigator?.clipboard
      ?.writeText(data)
      .then(() => {
        setIsCopied(data);
        setTimeout(() => {
          setIsCopied("");
        }, 1500);
      })
      .catch((err) => {
        console.error(err);
      });
  };

  return (
    <Box>
      <Typography variant="h5" fontWeight={600}>
        Activity Details
      </Typography>
      <Typography color="text.secondary" sx={{ mt: 0.5, mb: 2 }}>
        Learn when the model was created, updated, and by whom
      </Typography>
      <Box
        borderRadius="8px"
        border="1px solid"
        borderColor="border"
        sx={{ backgroundColor: "background.paper" }}
      >
        <Box
          display="flex"
          alignItems="center"
          p={2}
          sx={{
            borderBottom: (theme) => `1px solid ${theme.palette.border}`,
          }}
        >
          <Box minWidth={280}>
            <Typography color="text.primary">Created On</Typography>
          </Box>
          <Box flex={1}>
            <Typography>{createdOn}</Typography>
          </Box>
        </Box>
        <Box
          display="flex"
          alignItems="center"
          px={2}
          py={1.5}
          sx={{
            borderBottom: (theme) => `1px solid ${theme.palette.border}`,
          }}
        >
          <Box minWidth={280}>
            <Typography color="text.primary">Created By</Typography>
          </Box>
          <Box flex={1} display="flex" gap={1.5} alignItems="center">
            <Avatar
              sx={{ width: 32, height: 32 }}
              src={`https://www.gravatar.com/avatar/${MD5(
                createdByUser?.email || ""
              )}?d=mm&s=32`}
            />
            <Typography>
              {createdByUser?.firstName} {createdByUser?.lastName}
            </Typography>
          </Box>
          <Box>
            <Button
              onClick={() => handleCopy(createdByUser?.email)}
              size="small"
            >
              {isCopied ? "Copied!" : "Copy Email"}
            </Button>
          </Box>
        </Box>
        <Box
          display="flex"
          alignItems="center"
          p={2}
          sx={{
            borderBottom: (theme) => `1px solid ${theme.palette.border}`,
          }}
        >
          <Box minWidth={280}>
            <Typography color="text.primary">Last Updated On</Typography>
          </Box>
          <Box flex={1}>
            <Typography>{updatedOn}</Typography>
          </Box>
        </Box>
        <Box display="flex" alignItems="center" px={2} py={1.5}>
          <Box minWidth={280}>
            <Typography color="text.primary">Last Updated By</Typography>
          </Box>
          <Box flex={1} display="flex" gap={1.5} alignItems="center">
            <Avatar
              sx={{ width: 32, height: 32 }}
              src={`https://www.gravatar.com/avatar/${MD5(
                updatedByUser?.email || ""
              )}?d=mm&s=32`}
            />
            <Typography>
              {updatedByUser?.firstName} {updatedByUser?.lastName}
            </Typography>
          </Box>
          <Box>
            <Button
              onClick={() => handleCopy(updatedByUser?.email)}
              size="small"
            >
              {isCopied ? "Copied!" : "Copy Email"}
            </Button>
          </Box>
        </Box>
      </Box>
      <Button
        sx={{ mt: 2 }}
        size="large"
        variant="outlined"
        onClick={() => history.push(`/reports/activity-log/resources/${id}`)}
      >
        View All Activity
      </Button>
    </Box>
  );
};

