import { useState, useEffect, useMemo } from "react";
import { useParams } from "react-router-dom";
import { Box, Stack } from "@mui/material";
import { isValid } from "date-fns";
import { isEmpty } from "lodash";

import { ActionsTimeline } from "../../../../reports/src/app/views/ActivityLog/components/ActionsTimeline";
import { Filters } from "../../../../reports/src/app/views/ActivityLog/components/Filters";
import { ActionsByUsers } from "../../../../reports/src/app/views/ActivityLog/components/ActionsByUsers";
import { EmptyState } from "../../../../reports/src/app/views/ActivityLog/components/EmptyState";
import {
  useGetContentModelQuery,
  useGetAuditsQuery,
} from "../../../../../shell/services/instance";
import { useParams as useSearchParams } from "../../../../../shell/hooks/useParams";
import { filterByParams } from "../../../../../utility/filterByParams";
import { toUTC } from "../../../../reports/src/app/views/ActivityLog/utils";
import { formatInTimeZone } from "date-fns-tz";

type Params = {
  id: string;
};
export const ModelActivityLog = () => {
  const { id } = useParams<Params>();
  const [searchParams, setSearchParams] = useSearchParams();
  const [initialized, setInitialized] = useState(false);

  const {
    data: modelData,
    isLoading: isLoadingModelData,
    isFetching: isFetchingModelData,
  } = useGetContentModelQuery(id);
  const {
    data: audits,
    isLoading: isLoadingAudits,
    isFetching: isFetchingAudits,
  } = useGetAuditsQuery(
    {
      ...(searchParams.get("from") && {
        start_date: toUTC(searchParams.get("from")),
      }),
      ...(searchParams.get("to") && {
        end_date: toUTC(searchParams.get("to")),
      }),
    },
    { skip: !initialized }
  );

  useEffect(() => {
    if (
      !searchParams.get("from") &&
      !searchParams.get("to") &&
      !isEmpty(modelData)
    ) {
      useDefaultDateParams();
    }

    setInitialized(true);
  }, [modelData, location.pathname]);

  const relatedAudits = useMemo(
    () => audits?.filter((audit) => audit.affectedZUID === id) || [],
    [id, audits]
  );

  const filteredAudits = useMemo(
    () =>
      relatedAudits?.length ? filterByParams(relatedAudits, searchParams) : [],
    [relatedAudits, searchParams]
  );
  const useDefaultDateParams = () => {
    const created = modelData?.createdAt ? new Date(modelData.createdAt) : null;

    const ymdUTC = (d: Date) => formatInTimeZone(d, "UTC", "yyyy-MM-dd");

    const from =
      created && isValid(created) ? ymdUTC(created) : ymdUTC(new Date());
    const to = ymdUTC(new Date());

    setSearchParams(from, "from");
    setSearchParams(to, "to");
  };

  return (
    <Stack
      height="100%"
      px={4}
      pt={0.5}
      sx={{
        "*::-webkit-scrollbar": {
          display: "none",
        },
      }}
    >
      <Filters
        filters={["action", "actionByUserZUID"]}
        actions={relatedAudits}
        showSkeletons={isLoadingAudits || isLoadingModelData}
      />

      {(!isFetchingAudits || !isFetchingAudits) && !filteredAudits?.length ? (
        <Stack
          height="calc(100svh - 230px)"
          justifyContent="center"
          alignItems="center"
        >
          <EmptyState
            title="No Logs Found"
            onReset={() => {
              setSearchParams("", "action");
              setSearchParams("", "actionByUserZUID");
              useDefaultDateParams();
            }}
          />
        </Stack>
      ) : (
        <Stack
          direction="row"
          justifyContent="space-between"
          gap={6}
          height="100%"
        >
          <ActionsTimeline
            actions={filteredAudits}
            showSkeletons={isFetchingAudits || isLoadingModelData}
          />

          <Box sx={{ minWidth: 260 }}>
            <ActionsByUsers
              actions={filteredAudits}
              showSkeletons={isFetchingAudits || isFetchingModelData}
            />
          </Box>
        </Stack>
      )}
    </Stack>
  );
};

import { useState } from "react";
import { Box, Button } from "@mui/material";
import { Redirect, Route, Switch, useParams, useHistory } from "react-router";
import { FieldList } from "../components/FieldList";
import { ModelHeader } from "../components/ModelHeader";
import { AddFieldModal } from "../components/AddFieldModal";
import { ModelInfo } from "../components/ModelInfo";
import { useGetContentModelsQuery } from "../../../../../shell/services/instance";
import { NotFound } from "../../../../../shell/components/NotFound";
import SchemaRoundedIcon from "@mui/icons-material/SchemaRounded";
import { ModelActivityLog } from "../components/ModelActivityLog";
import { ModelApi } from "../components/ModelApi";

type Params = {
  id: string;
};
export const Model = () => {
  const [isAddFieldModalOpen, setAddFieldModalOpen] = useState(false);
  const [sortIndex, setSortIndex] = useState<number | null>(null);
  const history = useHistory();
  const params = useParams<Params>();
  const { id } = params;
  const { data: models, isFetching } = useGetContentModelsQuery();

  const handleNewFieldModalClick = (sortIndex: number | null) => {
    setAddFieldModalOpen(true);
    setSortIndex(sortIndex);
  };

  const handleModalClosed = () => {
    setAddFieldModalOpen(false);
    setSortIndex(null);
  };

  if (!isFetching && !models?.find((model) => model.ZUID === id)) {
    return (
      <NotFound
        title="Model Not Found"
        message="We're sorry the model you requested could not be found. Please go back to the All Models page."
        button={
          <Button
            startIcon={<SchemaRoundedIcon />}
            variant="contained"
            onClick={() => history.push("/schema")}
          >
            Go to All Models
          </Button>
        }
      />
    );
  }

  return (
    <Box
      flex="1"
      display="flex"
      height="100%"
      flexDirection="column"
      sx={{ backgroundColor: "grey.50" }}
    >
      <ModelHeader onNewFieldModalClick={handleNewFieldModalClick} />
      <Route
        path="/schema/:id/fields/:fieldId"
        render={() => {
          return (
            <AddFieldModal
              mode="update_field"
              onModalClose={() => history.push(`/schema/${id}/fields`)}
            />
          );
        }}
      />
      <Switch>
        <Route
          path="/schema/:id/fields"
          render={() => (
            <FieldList onNewFieldModalClick={handleNewFieldModalClick} />
          )}
        />
        <Route path="/schema/:id/api" component={ModelApi} />
        <Route exact path="/schema/:id/info" component={ModelInfo} />
        <Route
          exact
          path="/schema/:id/activity-log"
          component={ModelActivityLog}
        />
        <Redirect to="/schema/:id/fields" />
      </Switch>
      {isAddFieldModalOpen && (
        <AddFieldModal
          mode="fields_list"
          onModalClose={handleModalClosed}
          sortIndex={sortIndex}
        />
      )}
    </Box>
  );
};

