  const [menuAnchorEl, setMenuAnchorEl] = useState<HTMLButtonElement | null>(
    null
  );
  const isFilterMenuOpen = Boolean(menuAnchorEl);
  const activeModelTypeFilter: ModelSet | "" = value;

  const handleOpenMenuClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    setMenuAnchorEl(e.currentTarget);
  };

  const handleFilterSelect = (filter: ModelSet) => {
    setMenuAnchorEl(null);
    onChange(filter);
  };

  return (
    <>
      <FilterButton
        isFilterActive={Boolean(activeModelTypeFilter)}
        buttonText={
          modelNameMap[activeModelTypeFilter as ModelSet] || "Model Type"
        }
        onOpenMenu={handleOpenMenuClick}
        onRemoveFilter={() => onChange("")}
      >
        <Menu
          open={isFilterMenuOpen}
          anchorEl={menuAnchorEl}
          onClose={() => setMenuAnchorEl(null)}
          PaperProps={{
            sx: {
              mt: 1,
            },
          }}
        >
          {MODEL_TYPE_FILTERS.map((filter, index) => (
            <MenuItem
              selected={
                activeModelTypeFilter
                  ? filter === activeModelTypeFilter
                  : index === 0
              }
              key={index}
              onClick={() => handleFilterSelect(filter)}
            >
              <ListItemIcon>
                <SvgIcon component={modelIconMap[filter]} />
              </ListItemIcon>
              <ListItemText>{modelNameMap[filter]}</ListItemText>
            </MenuItem>
          ))}
        </Menu>
      </FilterButton>
    </>
  );
};

import { Dispatch, FC, useMemo } from "react";
import { Box } from "@mui/material";

import {
  DateFilter,
  DateFilterValue,
} from "../../../../../../shell/components/Filters/DateFilter";
import { ModelType } from "./ModelType";
import { ModelFilter } from "../ModelsTable";
import { UserFilter } from "../../../../../../shell/components/Filters";
import { ModelType as ModelSetType } from "../../../../../../shell/services/types";
import { useGetUsersQuery } from "../../../../../../shell/services/accounts";

type FilterParam = string | ModelSetType | DateFilterValue;
export interface FiltersProps {
  onChange: Dispatch<Partial<ModelFilter>>;
  activeFilters: ModelFilter;
}
export const Filters: FC<FiltersProps> = ({ activeFilters, onChange }) => {
  const { data: users } = useGetUsersQuery();
  const userOptions = useMemo(() => {
    return users?.map((user) => ({
      firstName: user.firstName,
      lastName: user.lastName,
      ZUID: user.ZUID,
      email: user.email,
    }));
  }, [users]);

  const handleFilterChange = (
    type: "modelType" | "user" | "date",
    filter: FilterParam
  ) => {
    if (type === "date") {
      onChange({
        lastUpdated: filter as DateFilterValue,
      });
    } else {
      onChange({
        [type]: filter,
      });
    }
  };

  return (
    <Box display="flex" gap={1.5} mb={2}>
      <ModelType
        value={activeFilters.modelType}
        onChange={(filter) => handleFilterChange("modelType", filter)}
      />
      <UserFilter
        value={activeFilters.user}
        onChange={(filter) => handleFilterChange("user", filter)}
        options={userOptions}
      />
      <DateFilter
        value={activeFilters.lastUpdated}
        onChange={(filter) => handleFilterChange("date", filter)}
      />
    </Box>
  );
};

