import DeleteIcon from "@mui/icons-material/Delete";
import ClearIcon from "@mui/icons-material/Clear";
import DoneAllIcon from "@mui/icons-material/DoneAll";
import { useRedirectsDialog } from "../../../app/components/RedirectsDialogProvider";
import { useRedirectsTable } from "../RedirectsTable/RedirectsTableContextProvider";
import { GridRowId } from "@mui/x-data-grid-pro";

type RedirectsDeleteProps = {
  selectedRedirects: GridRowId[];
};

const RedirectsDelete: FC<RedirectsDeleteProps> = ({ selectedRedirects }) => {
  const { openDeleteDialog } = useRedirectsDialog();
  const { apiRef, redirects } = useRedirectsTable();

  const handleDelete = () => {
    const deleteData = selectedRedirects.map((ZUID: any) => ({
      ZUID,
      path: redirects.find((row: any) => row.ZUID === ZUID)?.path,
    }));
    openDeleteDialog(deleteData);
  };

  return (
    <Box
      width="100%"
      sx={{
        backgroundColor: "background.paper",
        alignItems: "center",
        justifyContent: "space-between",
        display: "flex",
        top: "0",
        zIndex: 2,
      }}
    >
      <Typography variant="h3" fontWeight="700">
        {selectedRedirects.length} Selected
      </Typography>
      <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        columnGap={1}
      >
        <Button
          data-cy="RedirectActionDeselectAll"
          variant="outlined"
          color="inherit"
          size="small"
          disabled={!selectedRedirects?.length}
          onClick={() => apiRef.current?.setRowSelectionModel([])}
          startIcon={<ClearIcon />}
        >
          Deselect All
        </Button>
        <Button
          data-cy="RedirectActionSelectAll"
          variant="outlined"
          color="inherit"
          size="small"
          disabled={selectedRedirects?.length === redirects?.length}
          onClick={() =>
            apiRef.current?.setRowSelectionModel(
              redirects.map((row: any) => row.ZUID)
            )
          }
          startIcon={<DoneAllIcon />}
        >
          Select All
        </Button>
        <Button
          data-cy="RedirectActionDeleteButton"
          variant="contained"
          color="error"
          size="small"
          onClick={() => handleDelete()}
          startIcon={<DeleteIcon />}
        >
          Delete
        </Button>
      </Box>
    </Box>
  );
};

export default RedirectsDelete;

import { FC, useCallback, useEffect, useRef, useState } from "react";
import FileUploadRoundedIcon from "@mui/icons-material/FileUploadRounded";
import Button from "@mui/material/Button";
import { importCSVFile, IMPORT_REDIRECTS } from "../../../store/imports";
import { useRedirectsTable } from "../RedirectsTable/RedirectsTableContextProvider";
import { useDispatch } from "react-redux";
import {
  Dialog,
  DialogTitle,
  Box,
  Stack,
  Typography,
  DialogActions,
  Link,
} from "@mui/material";
import WarningAmberIcon from "@mui/icons-material/WarningAmber";

const RedirectsImport: FC = () => {
  const dispatch = useDispatch();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [files, setFiles] = useState<FileList | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const { redirects } = useRedirectsTable();

  const clearFiles = () => {
    setFiles(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleFileImport = useCallback(async () => {
    if (!files?.length) return;

    try {
      const file = files[0];
      const importRes = await importCSVFile(file, redirects, dispatch);

      if (importRes.status === "error") {
        dispatch({ type: IMPORT_REDIRECTS, redirects: [] });
        setIsDialogOpen(true);
        return;
      }
      dispatch({ type: IMPORT_REDIRECTS, redirects: importRes.targets });
      clearFiles();
      setIsDialogOpen(false);
    } catch (error) {
      dispatch({ type: IMPORT_REDIRECTS, redirects: [] });
      setIsDialogOpen(true);
    }
  }, [files, redirects, dispatch]);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setFiles(event.target.files);
  };

  const handleRetry = () => {
    clearFiles();
    fileInputRef.current?.click();
  };

  useEffect(() => {
    handleFileImport();
  }, [handleFileImport]);

  return (
    <>
      <Button
        component="label"
        role={undefined}
        variant="outlined"
        color="inherit"
        tabIndex={-1}
        size="small"
        startIcon={<FileUploadRoundedIcon color="action" />}
      >
        Import CSV/XML
        <input
          ref={fileInputRef}
          hidden
          type="file"
          accept=".csv,.xml,text/csv,text/xml"
          onChange={handleFileChange}
        />
      </Button>

      <ImportErrorDialog
        open={isDialogOpen}
        onClose={() => setIsDialogOpen(false)}
        onRetry={handleRetry}
        clearFiles={clearFiles}
      />
    </>
  );
};

const ImportErrorDialog: FC<ImportErrorDialogProps> = ({
  open,
  onClose,
  onRetry,
  clearFiles,
}) => {
  const handleCancel = () => {
    clearFiles();
    onClose();
  };

  return (
    <Dialog open={open} fullWidth maxWidth="xs" onClose={handleCancel}>
      <DialogTitle>
        <Box
          sx={{
            backgroundColor: "red.100",
            borderRadius: "100%",
            width: "40px",
            height: "40px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            mb: 1.5,
          }}
        >
          <WarningAmberIcon color="error" />
        </Box>
        <Stack
          display="flex"
          flexDirection="row"
          justifyContent="flex-start"
          alignItems="center"
          columnGap={1}
          overflow="hidden"
          textOverflow="ellipsis"
        >
          <Typography
            data-cy="RedirectsImportErrorDialogHeader"
            variant="inherit"
            fontWeight={700}
          >
            File Import Failed
          </Typography>
        </Stack>
        <Typography variant="body2" color="text.secondary" mt="8px">
          The file format or structure doesn't match what we expected. Please
          check your CSV or XML file and refer to our&nbsp;
          <Link
            href="https://docs.zesty.io/docs/redirects#mass-redirect"
            target="_blank"
            rel="noopener noreferrer"
            sx={{
              color: "info.main",
              textDecoration: "underline",
              textDecorationColor: "info.main",
            }}
          >
            import guide
          </Link>
          &nbsp;in our docs for the correct format.
        </Typography>
      </DialogTitle>
      <DialogActions sx={{ p: "20px" }}>
        <Button variant="text" color="inherit" onClick={handleCancel}>
          Cancel
        </Button>
        <Button
          data-cy="RedirectsImportRetryButton"
          variant="contained"
          color="primary"
          onClick={onRetry}
        >
          Try Again
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export type ImportErrorDialogProps = {
  open: boolean;
  onClose: () => void;
  onRetry: () => void;
  clearFiles: () => void;
};

export default RedirectsImport;

import { Box, Typography, Button } from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import { useRedirectsDialog } from "../../../app/components/RedirectsDialogProvider";
import { useRedirectsTable } from "../RedirectsTable/RedirectsTableContextProvider";
import RedirectsDelete from "./RedirectsDelete";
import InputAdornment from "@mui/material/InputAdornment";
import SearchIcon from "@mui/icons-material/Search";
import RedirectsImport from "./RedirectsImport";
import SearchBox from "../../../../../../shell/components/SearchBox";
import { useEffect, useState } from "react";
import { GridRowId } from "@mui/x-data-grid-pro";

export default function RedirectActions() {
  const { openCreateForm } = useRedirectsDialog();
  const { redirects, searchFilter, setSearchFilter, apiRef, isTableLoaded } =
    useRedirectsTable();
  const [selectedRedirects, setSelectedRedirects] = useState<GridRowId[]>([]);

  useEffect(() => {
    if (
      !isTableLoaded ||
      !apiRef.current ||
      !Object.keys(apiRef.current).length
    ) {
      return;
    }

    const handleSelectionChange = () => {
      setSelectedRedirects(
        Array.from(apiRef.current.getSelectedRows().keys() || [])
      );
    };

    return apiRef.current.subscribeEvent(
      "rowSelectionChange",
      handleSelectionChange
    );
  }, [apiRef.current, isTableLoaded]);

  return (
    <>
      {selectedRedirects?.length ? (
        <RedirectsDelete selectedRedirects={selectedRedirects} />
      ) : (
        <Box
          component="header"
          width="100%"
          sx={{
            backgroundColor: "background.paper",
            alignItems: "center",
            justifyContent: "space-between",
            display: "flex",
            top: "0",
            zIndex: 2,
          }}
        >
          <Typography variant="h3" fontWeight="700">
            {redirects?.length} Total Redirects
          </Typography>
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            columnGap={1}
          >
            <SearchBox
              placeholder="Filter Redirects"
              variant="outlined"
              size="small"
              value={searchFilter}
              InputProps={{
                sx: {
                  backgroundColor: "grey.50",
                },
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon fontSize="small" />
                  </InputAdornment>
                ),
              }}
              onChange={(evt: React.ChangeEvent<HTMLInputElement>) => {
                const term = evt.target.value.trim();
                setSearchFilter(term);
              }}
              sx={{
                width: "240px",
                "& .MuiOutlinedInput-notchedOutline": {
                  border: 0,
                },
              }}
            />
            <RedirectsImport />
            <Button
              data-cy="RedirectActionCreateButton"
              variant="contained"
              color="primary"
              size="small"
              onClick={() => openCreateForm()}
              startIcon={<AddIcon />}
            >
              Create
            </Button>
          </Box>
        </Box>
      )}
    </>
  );
}

import { useState } from "react";
import { Box, Menu, MenuItem } from "@mui/material";
import { FilterButton } from "../../../../../../shell/components/Filters";
import { useRedirectsTable } from "./RedirectsTableContextProvider";

const SORT_OPTIONS = {
  createdAt: "Date Created",
  path: "Incoming Path",
  code: "HTTP Code",
  targetType: "Type",
  target: "Target",
} as const;

const HTTP_CODE_FILTERS = {
  "301": "301 - Permanent",
  "302": "302 - Temporary",
} as const;

const TYPE_FILTERS = {
  external: "External - link to an external webpage",
  path: "Wildcard - rule based redirects",
  internal: "Internal - linked to an item in this instance",
} as const;

export const TableSortFilters = () => {
  const [anchorEl, setAnchorEl] = useState({
    currentTarget: null,
    id: "",
  });

  const {
    sortBy,
    httpCodeFilter,
    typeFilter,
    setSortBy,
    setHttpCodeFilter,
    setTypeFilter,
  } = useRedirectsTable();

  const handleOpenMenu = (
    event: React.MouseEvent<HTMLButtonElement>,
    id: string
  ) => {
    setAnchorEl({
      currentTarget: event.currentTarget,
      id,
    });
  };

  const handleCloseMenu = () => {
    setAnchorEl({
      currentTarget: null,
      id: "",
    });
  };

  const getButtonText = (id: string) => {
    switch (id) {
      case "sort":
        return `Sort: ${SORT_OPTIONS[sortBy as keyof typeof SORT_OPTIONS]}`;
      case "code":
        return httpCodeFilter === null
          ? "HTTP Code"
          : HTTP_CODE_FILTERS[httpCodeFilter as keyof typeof HTTP_CODE_FILTERS];
      case "type":
        return typeFilter === null
          ? "Type"
          : TYPE_FILTERS[typeFilter as keyof typeof TYPE_FILTERS];
      default:
        return "";
    }
  };

  return (
    <Box display="flex" gap={1.5} py="16px">
      <FilterButton
        filterId="sortByFilter"
        isFilterActive={false}
        buttonText={getButtonText("sort")}
        onOpenMenu={(e) => handleOpenMenu(e, "sort")}
        onRemoveFilter={() => {
          setSortBy("createdAt");
        }}
      />
      <Menu
        open={!!anchorEl?.currentTarget && anchorEl.id === "sort"}
        onClose={handleCloseMenu}
        anchorEl={anchorEl?.currentTarget}
        transformOrigin={{
          vertical: -8,
          horizontal: "left",
        }}
        PaperProps={{
          sx: {
            width: "280px",
          },
        }}
      >
        {Object.entries(SORT_OPTIONS).map(([key, value]) => (
          <MenuItem
            key={key}
            onClick={() => {
              setSortBy(key);
              handleCloseMenu();
            }}
            selected={sortBy === key}
          >
            {value}
          </MenuItem>
        ))}
      </Menu>

      <FilterButton
        filterId="httpCode"
        isFilterActive={httpCodeFilter !== null}
        buttonText={getButtonText("code")}
        onOpenMenu={(e) => handleOpenMenu(e, "code")}
        onRemoveFilter={() => {
          setHttpCodeFilter(null);
        }}
      />
      <Menu
        open={!!anchorEl?.currentTarget && anchorEl.id === "code"}
        onClose={handleCloseMenu}
        anchorEl={anchorEl?.currentTarget}
        transformOrigin={{
          vertical: -8,
          horizontal: "left",
        }}
        PaperProps={{
          sx: {
            width: "160px",
          },
        }}
      >
        {Object.entries(HTTP_CODE_FILTERS).map(([key, value]) => (
          <MenuItem
            key={key}
            onClick={() => {
              setHttpCodeFilter(key);
              handleCloseMenu();
            }}
            selected={httpCodeFilter === key}
          >
            {value}
          </MenuItem>
        ))}
      </Menu>

      <FilterButton
        filterId="targetType"
        isFilterActive={typeFilter !== null}
        buttonText={getButtonText("type")}
        onOpenMenu={(e) => handleOpenMenu(e, "type")}
        onRemoveFilter={() => {
          setTypeFilter(null);
        }}
      />
      <Menu
        open={!!anchorEl?.currentTarget && anchorEl.id === "type"}
        onClose={handleCloseMenu}
        anchorEl={anchorEl?.currentTarget}
        transformOrigin={{
          vertical: -8,
          horizontal: "left",
        }}
        PaperProps={{
          sx: {
            width: "360px",
          },
        }}
      >
        {Object.entries(TYPE_FILTERS).map(([key, value]) => (
          <MenuItem
            key={key}
            onClick={() => {
              setTypeFilter(key);
              handleCloseMenu();
            }}
            selected={typeFilter === key}
          >
            {value}
          </MenuItem>
        ))}
      </Menu>
    </Box>
  );
};

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useState,
} from "react";
import {
  DataGridPro,
  GRID_CHECKBOX_SELECTION_COL_DEF,
  GridActionsCellItem,
  GridColDef,
  GridRenderCellParams,
  GridPinnedColumnFields,
  GridValidRowModel,
} from "@mui/x-data-grid-pro";
import { Box, Typography } from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import ArrowForwardRoundedIcon from "@mui/icons-material/ArrowForwardRounded";
import OpenInNewRoundedIcon from "@mui/icons-material/OpenInNewRounded";
import DescriptionRoundedIcon from "@mui/icons-material/DescriptionRounded";
import { RedirectTargetCell } from "./RedirectTargetCell";
import HiveIcon from "@mui/icons-material/Hive";
import AutoSizer from "react-virtualized-auto-sizer";
import ModeEditIcon from "@mui/icons-material/ModeEdit";
import MoreHorizIcon from "@mui/icons-material/MoreHoriz";
import { useRedirectsDialog } from "../../../app/components/RedirectsDialogProvider";
import { TableSortFilters } from "./TableSortFilters";
import { useRedirectsTable } from "./RedirectsTableContextProvider";
import { Redirects } from "../../../../../../shell/services/types";

const TARGET_TYPES_MAP = {
  page: "internal",
  path: "wildcard",
  external: "external",
} as const;

const RedirectsTable = () => {
  const { openDeleteDialog, openCreateForm } = useRedirectsDialog();
  const {
    redirects,
    isLoading,
    sortBy,
    httpCodeFilter,
    typeFilter,
    searchFilter,
    apiRef,
    setIsTableLoaded,
  } = useRedirectsTable();

  const [initialState, setInitialState] = useState<any>();
  const [pinnedColumns, setPinnedColumns] = useState<GridPinnedColumnFields>({
    left: [GRID_CHECKBOX_SELECTION_COL_DEF.field],
  });

  const columns: GridColDef[] = useMemo(
    () => [
      {
        field: "path",
        minWidth: 206,
        flex: 1,
        headerName: "Incoming Path",
        renderCell: ({ value }: GridRenderCellParams<GridValidRowModel>) => (
          <Typography variant="body2" color="text.primary">
            {value}
          </Typography>
        ),
      },
      {
        field: "code",
        width: 120,
        minWidth: 120,
        headerName: "HTTP Code",
        renderCell: ({ value }: GridRenderCellParams<GridValidRowModel>) => {
          return (
            <Typography
              variant="body2"
              color="text.primary"
              sx={{
                display: "flex",
                flexDirection: "row",
                justifyContent: "flex-start",
                alignItems: "center",
                columnGap: "12px",
                lineHeight: "100%",
              }}
            >
              {value}
              <ArrowForwardRoundedIcon fontSize="small" color="action" />
            </Typography>
          );
        },
      },
      {
        field: "targetType",
        width: 120,
        minWidth: 120,
        headerName: "Type",
        renderCell: ({ value }: GridRenderCellParams<GridValidRowModel>) => {
          return (
            <Typography
              variant="body2"
              color="text.primary"
              sx={{
                display: "flex",
                flexDirection: "row",
                justifyContent: "flex-start",
                alignItems: "center",
                columnGap: "12px",
                lineHeight: "100%",
              }}
            >
              {value === "external" ? (
                <>
                  <OpenInNewRoundedIcon fontSize="small" color="action" />
                  External&nbsp;
                </>
              ) : value === "path" ? (
                <>
                  <HiveIcon fontSize="small" color="action" />
                  Wildcard&nbsp;
                </>
              ) : (
                <>
                  <DescriptionRoundedIcon fontSize="small" color="action" />
                  Internal&nbsp;
                </>
              )}
            </Typography>
          );
        },
      },
      {
        field: "target",
        minWidth: 190,
        flex: 1,
        headerName: "Target",
        renderCell: ({
          value,
          row,
        }: GridRenderCellParams<GridValidRowModel>) => (
          <RedirectTargetCell target={value} targetType={row.targetType} />
        ),
      },
      {
        field: "actions",
        type: "actions",
        width: 54,
        minWidth: 54,
        maxWidth: 54,
        resizable: false,

        getActions: ({ row }: { row: Redirects }) => [
          <GridActionsCellItem
            showInMenu
            icon={<ModeEditIcon fontSize="small" />}
            color="action.secondary"
            label="Edit Redirect"
            onClick={() => {
              openCreateForm({
                ZUID: row?.ZUID,
                targetType: row?.targetType,
                code: row?.code,
                target: row?.target,
                path: row?.path,
              });
            }}
          />,
          <GridActionsCellItem
            showInMenu
            icon={<DeleteIcon fontSize="small" />}
            color="action.secondary"
            label="Delete Redirect"
            onClick={() =>
              openDeleteDialog([{ ZUID: row.ZUID, path: row.path }])
            }
          />,
        ],
      },
    ],
    []
  );

  const rows = useMemo(() => {
    if (isLoading) return [];
    return Object.values(redirects)
      .filter((redirect) => {
        const normalizedFilter = searchFilter?.toLowerCase() || "";
        const matchesSearch =
          redirect.path.toLowerCase().includes(normalizedFilter) ||
          String(redirect.code).toLowerCase().includes(normalizedFilter) ||
          redirect.targetType.toLowerCase().includes(normalizedFilter) ||
          TARGET_TYPES_MAP[redirect.targetType]
            .toLowerCase()
            .includes(normalizedFilter) ||
          redirect.ZUID.toLowerCase().includes(normalizedFilter) ||
          redirect.target.toLowerCase().includes(normalizedFilter);

        const matchesHttpCode =
          httpCodeFilter === null || String(redirect.code) === httpCodeFilter;
        const matchesType =
          typeFilter === null || redirect.targetType === typeFilter;

        return matchesSearch && matchesHttpCode && matchesType;
      })
      .sort((a, b) => {
        switch (sortBy) {
          case "createdAt":
            return (
              new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
            );
          case "path":
            return a.path.localeCompare(b.path);
          case "code":
            return a.code - b.code;
          case "targetType":
            return a.targetType.localeCompare(b.targetType);
          case "target":
            return a.target.localeCompare(b.target);
          default:
            return 0;
        }
      })
      .map((redirect) => ({
        ...redirect,
        id: redirect.ZUID,
      }));
  }, [redirects, searchFilter, isLoading, sortBy, httpCodeFilter, typeFilter]);

  const saveSnapshot = useCallback(() => {
    if (apiRef?.current?.exportState && localStorage) {
      const currentState = apiRef.current.exportState();
      const fullState = {
        ...currentState,
        pinnedColumns: apiRef.current.getPinnedColumns(),
      };
      localStorage.setItem(
        `zesty:redirects:dataGridState`,
        JSON.stringify(fullState)
      );
    }
  }, [apiRef]);

  useLayoutEffect(() => {
    if (!columns) return;
    const stateFromLocalStorage = localStorage?.getItem(
      `zesty:redirects:dataGridState`
    );

    if (stateFromLocalStorage) {
      const parsedState = JSON.parse(stateFromLocalStorage);
      setInitialState(parsedState);
      if (parsedState.pinnedColumns) {
        setPinnedColumns(parsedState.pinnedColumns);
      }
    } else {
      setInitialState({});
      setPinnedColumns({
        left: [GRID_CHECKBOX_SELECTION_COL_DEF.field],
      });
    }

    window.addEventListener("beforeunload", saveSnapshot);

    return () => {
      window.removeEventListener("beforeunload", saveSnapshot);
      saveSnapshot();
    };
  }, [saveSnapshot, columns, GRID_CHECKBOX_SELECTION_COL_DEF]);

  useEffect(() => {
    setIsTableLoaded(true);
  }, []);

  return (
    <>
      <Box display="flex" flexDirection="row" alignItems="center">
        <TableSortFilters />
      </Box>

      <Box
        sx={{
          display: "flex",
          flexDirection: "column",
          height: "100%",
          justifyContent: "flex-start",
          alignItems: "stretch",
          width: "100%",
          position: "relative",
          rowGap: "16px",
        }}
      >
        <Box width="100%" height="100%">
          <AutoSizer>
            {({ width, height }: { width: number; height: number }) => (
              <DataGridPro
                apiRef={apiRef}
                columns={columns}
                rows={rows}
                rowHeight={60}
                pinnedColumns={pinnedColumns}
                onPinnedColumnsChange={(newPinnedColumns) =>
                  setPinnedColumns(newPinnedColumns)
                }
                onColumnWidthChange={saveSnapshot}
                initialState={initialState}
                style={{
                  width: width,
                  height: height,
                }}
                checkboxSelection
                disableRowSelectionOnClick
                slots={{
                  moreActionsIcon: MoreHorizIcon,
                }}
                sx={{
                  bgcolor: "background.paper",
                  color: "text.primary",
                  fontSize: "typography.body2.fontSize",
                  "& .MuiDataGrid-cell, & .MuiDataGrid-columnHeader": {
                    outline: "none!important",
                  },
                  "& .MuiDataGrid-pinnedColumnHeaders": {
                    bgcolor: "transparent",
                  },

                  "& .MuiDataGrid-columnHeader:hover": {
                    "& .MuiDataGrid-columnSeparator": {
                      visibility: "visible",
                    },
                  },
                  "& .MuiDataGrid-cell": {
                    display: "flex",
                    flexDirection: "row",
                    justifyContent: "flex-start",
                    alignItems: "center",
                    outline: "none!important",
                  },
                  "& .MuiDataGrid-container--top [role=row]": {
                    backgroundColor: "grey.100",
                  },
                  "& .MuiDataGrid-columnHeaderCheckbox, & .MuiDataGrid-cellCheckbox":
                    {
                      padding: "0 0 0 6px",
                    },
                  "& .MuiDataGrid-cell:has([data-cy='sortCell'])": {
                    padding: 0,
                  },
                  "& .MuiCheckbox-root": {
                    color: "action.active",
                  },
                }}
                hideFooter
              />
            )}
          </AutoSizer>
        </Box>
      </Box>
    </>
  );
};

export default RedirectsTable;

import React, { useState } from "react";
import {
  Button,
  ToggleButton,
  ToggleButtonGroup,
  Select,
  MenuItem,
  TextField,
  SelectChangeEvent,
  Grid,
  Typography,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";

import { createRedirect } from "../../../store/redirects";
import { importTarget } from "../../../store/imports";
import { importQuery } from "../../../store/imports";
import { importCode } from "../../../store/imports";
import { importTargetType } from "../../../store/imports";

interface RedirectImportTableRowProps {
  index: number;
  path: string;
  code: number;
  targetType?: string;
  target?: string;
  target_zuid?: string;
  query_string?: string;
  isLoading?: boolean;
  dispatch: (action: any) => void;
}

const RedirectImportTableRow = ({
  index,
  path,
  code,
  target,
  targetType,
  target_zuid,
  query_string,
  isLoading,
  dispatch,
}: RedirectImportTableRowProps) => {
  const [loading, setLoading] = useState(false);

  const handleCode = (val: string) => {
    dispatch(importCode(path, val));
  };

  const handlePathTarget = (
    evt: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    dispatch(importTarget(path, evt.target.value, ""));
  };

  const handleTargetType = (evt: SelectChangeEvent<string>) => {
    dispatch(importTargetType(path, evt.target.value));
  };

  const handleQuery = (
    evt: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    dispatch(importQuery(path, evt.target.value));
  };

  const handleAddRedirect = async (
    evt: React.MouseEvent<HTMLButtonElement>
  ) => {
    setLoading(true);
    await dispatch(
      createRedirect({
        path: path,
        query_string: query_string,
        targetType: targetType,
        target: target_zuid || target,
        code: Number(code),
      })
    );
    setLoading(false);
  };

  const handleToggle = (val: string | null) => {
    if (val === null) return;
    handleCode(val);
  };

  return (
    <Grid
      container
      spacing={3}
      width="100%"
      py={2.5}
      pl={2}
      pr={1}
      direction="row"
      sx={{
        justifyContent: "space-between",
        alignItems: "center",
        flexWrap: "nowrap",
        color: "text.secondary",
        backgroundColor: index % 2 === 0 ? "transparent" : "grey.50",
      }}
    >
      <Grid size="grow" minWidth="200px">
        <Typography variant="body2" fontWeight={400}>
          {path}
        </Typography>
      </Grid>

      <Grid minWidth="115px">
        <ToggleButtonGroup
          color="primary"
          value={code}
          size="small"
          exclusive
          onChange={(evt, val) => handleToggle(val)}
        >
          <ToggleButton value={"302"}>302</ToggleButton>
          <ToggleButton value={"301"}>301</ToggleButton>
        </ToggleButtonGroup>
      </Grid>
      <Grid minWidth="130px">
        <Select
          onChange={handleTargetType}
          size="small"
          fullWidth
          value={targetType}
        >
          <MenuItem value={"path"}>Wildcard</MenuItem>
          <MenuItem value={"page"}>Internal</MenuItem>
          <MenuItem value={"external"}>External</MenuItem>
        </Select>
      </Grid>

      <Grid size="grow" minWidth="200px">
        <TextField
          onChange={handlePathTarget}
          defaultValue={target}
          size="small"
          variant="outlined"
          color="primary"
          fullWidth
        />
        {targetType === "path" && (
          <TextField
            onChange={handleQuery}
            placeholder="Redirect query string"
            defaultValue={query_string}
            size="small"
            variant="outlined"
            color="primary"
            fullWidth
          />
        )}
      </Grid>

      <Grid width="115px" sx={{ textAlign: "center" }}>
        <Button
          variant="contained"
          onClick={handleAddRedirect}
          startIcon={<AddIcon />}
          size="small"
          loading={isLoading || loading}
        >
          Redirect
        </Button>
      </Grid>
    </Grid>
  );
};

export default RedirectImportTableRow;

