        {titleHidden ? null : (
          <Typography
            variant="h3"
            fontWeight={700}
            color="text.primary"
            noWrap
            minWidth="fit-content"
          >
            {title}
          </Typography>
        )}
        {!!children ? children : null}
        {!onSave || saveHidden ? null : (
          <Box
            display="flex"
            flexDirection="row"
            justifyContent="space-between"
            alignItems="center"
            columnGap={1}
          >
            <ActionButton
              id="SaveSettings"
              label={isNotSaved ? "Save" : "Saved"}
              startIcon={<SaveRoundedIcon fontSize="small" />}
              tooltip={isNotSaved ? `Save Settings ${saveShortcut}` : ""}
              onClick={() => setOpen(true)}
              isActive={isNotSaved}
            />
          </Box>
        )}
      </Box>
      {!onSave ? null : (
        <ConfirmSaveDialog
          open={open}
          onClose={() => setOpen(false)}
          onConfirm={handleSave}
          title={title}
          isSaving={isLoading}
        />
      )}
    </>
  );
};

