import FontFamilyCard from "./FontFamilyCard";
import { useInstalledFonts } from "../Installed";
import { useSelector } from "react-redux";
import { AppState } from "../../../../../../../shell/store/types";

type InstalledFont = {
  ZUID: string;
  family: string;
  variants: string[];
  href: string;
};

export type FontAndVariants = {
  family: string;
  variants: string[];
};

export const getFontDataFromHref = (url: string): FontAndVariants => {
  if (!url)
    return {
      family: "",
      variants: [],
    };
  const fontUrlData = new URL(url);
  const fontFamilyAndVariants = fontUrlData?.searchParams?.get("family");

  const [family, variantsString = ""] = fontFamilyAndVariants?.split(":") || [];
  const variants = variantsString?.split(",") || [];

  return {
    family,
    variants,
  };
};

const Browse = () => {
  const [loadComplete, setLoadComplete] = useState<boolean>(false);
  const [search, setSearch] = useState<string>("");
  const searchInputRef = useRef<HTMLInputElement>(null);

  const [prevActivePage, setPrevActivePage] = useState<number>(0);
  const [activePage, setActivePage] = useState<number>(0);
  const [activePagination, setActivePagination] = useState([]);
  const [previewText, setPreviewText] = useState<string>("");

  const webFonts = useSelector(({ settings }: AppState) => settings?.fonts);
  const { fonts: installedFonts } = useInstalledFonts();

  const fontData = useMemo(() => {
    if (!webFonts?.length) {
      return [];
    } else {
      const paginationWithZUID = [...webFonts]
        ?.sort((a, b) => a?.family?.localeCompare(b?.family))
        ?.map((gFont, index) => {
          const currentInstalledFonts = installedFonts?.find(
            (item: InstalledFont) => {
              const { family } = getFontDataFromHref(item?.href);
              return family === gFont?.family;
            }
          );

          const { variants } = getFontDataFromHref(currentInstalledFonts?.href);

          return {
            index: index,
            family: gFont?.family,
            ZUID: currentInstalledFonts?.ZUID || null,
            variants: gFont?.variants,
            installedVariants: variants,
          };
        });

      setLoadComplete(true);
      return paginationWithZUID;
    }
  }, [installedFonts, webFonts]);

  const paginationData = useMemo(() => {
    if (!fontData) return [];
    if (!search) return fontData;

    const searchFilteredFontData = fontData?.filter((font) =>
      font?.family?.toLowerCase().includes(search.toLowerCase())
    );

    return searchFilteredFontData;
  }, [search, fontData]);

  useEffect(() => {
    if (!loadComplete || !paginationData) return;
    const start = activePage * 10;
    const end = start + 10;

    const currentPageData = paginationData.slice(start, end);

    setActivePagination([...currentPageData]);
  }, [paginationData, loadComplete, activePage]);

  return (
    <>
      {!!activePagination?.length && (
        <Portal container={document.head}>
          {activePagination?.map((itemFont) => (
            <link
              key={itemFont?.family}
              rel="stylesheet"
              href={`https://fonts.googleapis.com/css?family=${itemFont?.family?.replace(
                /\s/g,
                "+"
              )}`}
            />
          ))}
        </Portal>
      )}
      <TopBar
        title="Browse Fonts"
        isNotSaved={false}
        isLoading={false}
        saveHidden
      >
        <Box
          display="flex"
          flexDirection="row"
          alignItems="center"
          justifyContent="space-between"
          columnGap={2}
        >
          <SearchBox
            data-cy="BrowseFontSearchInput"
            placeholder="Search Fonts"
            type="text"
            variant="outlined"
            size="small"
            value={search}
            onChange={(evt) => {
              if (activePage !== 0 && !!evt.target.value) {
                setActivePage(0);
                setPrevActivePage(activePage);
              }

              if (
                activePage === 0 &&
                !evt.target.value &&
                activePage !== prevActivePage
              ) {
                setActivePage(prevActivePage);
                setPrevActivePage(prevActivePage);
              }
              setSearch(evt.target.value);
            }}
            inputRef={searchInputRef}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon fontSize="small" />
                </InputAdornment>
              ),
              sx: {
                bgcolor: "grey.50",
              },
            }}
            sx={{
              width: "280px",
            }}
          />
        </Box>
      </TopBar>

      <Box
        className="main-wrapper"
        px={4}
        sx={{
          width: "100%",
          height: "calc(100% - 84px)",
          overflowY: "auto",
          overflowX: "hidden",
          margin: 0,
          display: "block",
          maxHeight: "calc(100% - 84px)",
          position: "relative",
          boxSizing: "border-box",
        }}
      >
        <Box
          py={2}
          height="100%"
          display="flex"
          flexDirection="column"
          justifyContent="flex-start"
          sx={{
            minHeight: "100%",
            boxSizing: "border-box",
          }}
        >
          <Box
            sx={{
              width: "100%",

              display: "flex",
              flexDirection: "column",
              justifyContent: "space-between",
              alignItems: "flex-start",
              borderBottom: "1px solid",
              borderColor: "border",
              pb: 3,
            }}
          >
            <TextField
              id="previewText"
              placeholder="Type something to preview"
              type="text"
              variant="outlined"
              size="small"
              name="previewText"
              value={previewText}
              onChange={(evt) => setPreviewText(evt.target.value)}
              sx={{
                width: "60%",
                minWidth: "300px",
              }}
            />
          </Box>
          {!!search && paginationData?.length < 1 ? (
            <Box
              width="100%"
              height="100%"
              display="grid"
              alignContent="center"
              data-cy="BrowseFontNoResultsContainer"
            >
              <NoResults
                type="search"
                searchTerm={search}
                onButtonClick={() => {
                  setSearch("");
                  setActivePage(prevActivePage);
                  searchInputRef?.current?.focus();
                }}
              />
            </Box>
          ) : (
            <>
              <Box width="100%" data-cy="FontListContainer">
                {activePagination?.map((itemFont, index) => (
                  <FontFamilyCard
                    previewText={previewText}
                    key={itemFont?.family + index}
                    family={itemFont?.family}
                    variants={[...itemFont?.variants]}
                    installedVariants={itemFont?.installedVariants}
                    ZUID={itemFont?.ZUID}
                    activePage={activePage + 1}
                  />
                ))}
              </Box>
              <Box
                width="100%"
                display="flex"
                flexDirection="row"
                justifyContent="center"
                alignItems="center"
                py={5}
                boxSizing="border-box"
              >
                <Button
                  variant="contained"
                  color="primary"
                  size="large"
                  onClick={() => {
                    setActivePage((prev) => prev - 1);
                  }}
                  disabled={activePage === 0}
                  sx={{
                    py: 2,
                    width: 64,
                  }}
                >
                  Prev
                </Button>
                <Typography
                  variant="h5"
                  sx={{
                    width: "85px",
                    textAlign: "center",
                    color: "text.secondary",
                  }}
                  noWrap
                >
                  {`${activePage + 1} / ${
                    Math.ceil(paginationData?.length / 10) || 1
                  }`}
                </Typography>
                <Button
                  variant="contained"
                  color="primary"
                  onClick={() => {
                    setActivePage((prev) => prev + 1);
                  }}
                  disabled={
                    activePage >= Math.ceil(paginationData?.length / 10) - 1
                  }
                  sx={{
                    py: 2,
                    width: 64,
                  }}
                >
                  Next
                </Button>
              </Box>
            </>
          )}
        </Box>
      </Box>
    </>
  );
};
export default Browse;

import { FC, useCallback } from "react";
import {
  Dialog,
  DialogTitle,
  Typography,
  DialogContent,
  DialogActions,
  Button,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import LoadingButton from "@mui/lab/LoadingButton";
import { Stack } from "@mui/material";
import { useDispatch } from "react-redux";
import { fetchFontsInstalled } from "../../../../../../../shell/store/settings";
import {
  useDeleteHeadTagMutation,
  useUpdateHeadTagsMutation,
} from "../../../../../../../shell/services/instance";
import { useInstalledFonts } from ".";
import { notify } from "../../../../../../../shell/store/notifications";
import { getFontDataFromHref } from "../Browse";

export type DeleteFontDialogProps = {
  open: boolean;
  onClose: () => void;
  family: string;
  variant: string;
  ZUID: string;
};

const DeleteFontDialog = ({
  open,
  onClose,
  family,
  variant,
  ZUID,
}: DeleteFontDialogProps) => {
  const dispatch = useDispatch();
  const fontLabel = `${family} (${variant})`;

  const [deleteFont, { isLoading: isDeleting }] = useDeleteHeadTagMutation();
  const [updateFont, { isLoading: isUpdating }] = useUpdateHeadTagsMutation();

  const { fonts: installedFonts } = useInstalledFonts();

  const handleFontDelete = useCallback(async () => {
    const thisFont = installedFonts?.find((font) => font?.ZUID === ZUID);
    const { family, variants } = getFontDataFromHref(thisFont?.href);
    const fontLabel = `${family} (${variant})`;
    const remainingVariants = variants?.filter(
      (itemVariant) => itemVariant !== variant
    );

    try {
      let response: any = null;
      if (!remainingVariants?.length) {
        response = await deleteFont(ZUID);
      } else {
        const updatedHref = `https://fonts.googleapis.com/css?family=${family.replace(
          /\s/g,
          "+"
        )}:${remainingVariants.join(",")}`;

        response = await updateFont({
          ZUID,
          href: updatedHref,
        });
      }

      if (!response?.error) {
        dispatch(
          notify({
            kind: "success",
            message: `Font "${fontLabel}" has been uninstalled`,
          })
        );
      } else {
        throw new Error(`${response?.error?.data?.error}`);
      }
    } catch (error) {
      dispatch(
        notify({
          kind: "error",
          message: `Failed to uninstall ${fontLabel}: ${error}`,
        })
      );
    } finally {
      dispatch(fetchFontsInstalled());
      onClose();
    }
  }, [ZUID, variant]);

  return (
    <>
      <Dialog
        data-cy="DeleteFontDialog"
        open={open}
        onClose={onClose}
        fullWidth
        maxWidth={"xs"}
      >
        <DialogTitle>
          <DeleteIcon
            color="error"
            sx={{
              padding: 1,
              borderRadius: "50%",
              backgroundColor: "red.100",
              display: "block",
              mb: 1.5,
              width: "40px",
              height: "40px",
            }}
          />
          <Stack
            display="flex"
            flexDirection="row"
            justifyContent="flex-start"
            alignItems="center"
            columnGap={1}
            overflow="hidden"
            textOverflow="ellipsis"
          >
            <Typography
              variant="h5"
              color="text.primary"
              fontWeight={700}
              mb={1}
            >
              Remove Font:
            </Typography>

            <Typography
              data-cy="DeleteFontDialogLabel"
              variant="h5"
              color="text.primary"
              fontWeight={500}
              mb={1}
              textTransform="capitalize"
            >
              {fontLabel}
            </Typography>
          </Stack>
          <Typography variant="body2" color="text.secondary">
            Do you really want to uninstall this font?
          </Typography>
        </DialogTitle>
        <DialogContent></DialogContent>
        <DialogActions>
          <Button onClick={onClose} color="inherit">
            Cancel
          </Button>
          <LoadingButton
            data-cy="DeleteFontDialogConfirmButton"
            variant="contained"
            color="error"
            onClick={handleFontDelete}
            loading={isDeleting || isUpdating}
          >
            Remove
          </LoadingButton>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DeleteFontDialog;

import { useState } from "react";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import { Typography, Button } from "@mui/material";
import DeleteFontDialog from "./DeleteFontDialog";
import { capitalize } from "lodash";
import { getFontDataFromHref } from "../Browse";

const FONT_PREVIEW_TEXT = "All their equipment and instruments are alive.";

export type WebFontCardProps = {
  ZUID: string;
  href: string;
};

const getWeightAndStyle = (fontText: string) => {
  const sanitizedVariant = fontText?.trim()?.toLowerCase();
  const fontWeight = ["regular", "italic"]?.includes(sanitizedVariant)
    ? "400"
    : fontText?.replace(/(italic|i)/g, "");

  const fontStyle =
    sanitizedVariant?.includes("italic") || sanitizedVariant?.includes("i")
      ? "italic"
      : "normal";

  return {
    weight: +fontWeight,
    style: fontStyle,
  };
};

const WebFontCard = ({ ZUID, href }: WebFontCardProps) => {
  const { family, variants } = getFontDataFromHref(href);
  const [deleteDialogIsOpen, setDeleteDialogIsOpen] = useState(false);
  const [fontForDelete, setFontForDelete] = useState(null);
  const handleDeleteFontVariant = (variant: string) => {
    const updatedVariants = variants?.filter((item) => item !== variant);
    setFontForDelete({ ZUID, family, variant, updatedVariants });
    setDeleteDialogIsOpen(true);
  };

  return (
    <>
      <Box
        data-cy="WebFontCard"
        display="flex"
        flexDirection="column"
        justifyContent="space-between"
        alignItems="flex-start"
        sx={{
          width: "100%",
          pt: 4,
          borderBottom: "1px solid",
          borderColor: "grey.200",
          position: "relative",
          overflow: "hidden",
        }}
      >
        <Typography
          data-cy="WebFontCardLabel"
          variant="h6"
          color="text.primary"
          fontWeight={700}
          noWrap
        >
          {family}
        </Typography>

        <Box
          display="flex"
          flexDirection="column"
          justifyContent="space-between"
          alignItems="flex-start"
          width="100%"
          sx={{ pt: 3, pb: 1 }}
        >
          {variants
            ?.sort((a: string, b: string) => {
              const { weight: aWeight } = getWeightAndStyle(a);
              const { weight: bWeight } = getWeightAndStyle(b);
              return aWeight - bWeight;
            })
            ?.map((variant, index) => {
              const sanitizedVariant = variant?.trim()?.toLowerCase();

              const fontWeight = ["regular", "italic"]?.includes(
                sanitizedVariant
              )
                ? "400"
                : variant?.replace(/(italic|i)/g, "");

              const fontStyle =
                sanitizedVariant?.includes("italic") ||
                sanitizedVariant?.includes("i")
                  ? "italic"
                  : "normal";

              return (
                <Box
                  key={`${family}-${fontWeight}-${fontStyle}-${index}`}
                  display="flex"
                  flexDirection="row"
                  justifyContent="space-between"
                  alignItems="center"
                  width="100%"
                  sx={{
                    py: 2,
                    position: "relative",
                    overflow: "hidden",
                    columnGap: 4,
                  }}
                >
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    fontWeight={+fontWeight}
                    fontStyle={fontStyle}
                    fontFamily={family}
                    noWrap
                  >
                    {FONT_PREVIEW_TEXT}
                  </Typography>
                  <Button
                    data-cy="UninstallFontButton"
                    variant="outlined"
                    color="error"
                    onClick={() => handleDeleteFontVariant(variant)}
                    startIcon={<DeleteIcon fontSize="small" />}
                    sx={{
                      flexGrow: 0,
                      whiteSpace: "nowrap",
                      minWidth: "fit-content",
                    }}
                  >
                    {`Remove ${capitalize(variant)}`}
                  </Button>
                </Box>
              );
            })}
        </Box>
      </Box>
      {!!deleteDialogIsOpen && (
        <DeleteFontDialog
          open={deleteDialogIsOpen}
          onClose={() => setDeleteDialogIsOpen(false)}
          family={fontForDelete?.family}
          variant={fontForDelete?.variant}
          ZUID={fontForDelete?.ZUID}
        />
      )}
    </>
  );
};

