          currently have it. You can always reactivate this status in the
          future.
        </Typography>
      </DialogContent>

      <DialogActions>
        <Button
          data-amp-track-id="workflows-status-label-deactivation-cancel-button"
          onClick={onClose}
          variant="text"
          color="inherit"
        >
          Cancel
        </Button>

        <Button
          data-amp-track-id="workflows-status-label-deactivation-confirm-button"
          onClick={handleConfirm}
          variant="contained"
          color="error"
          loading={isLoading}
          loadingPosition="center"
          data-cy="deactivation-dialog-confirm-button"
        >
          Deactivate Status
        </Button>
      </DialogActions>
    </Dialog>
  );
};

