const ColorSelectInput = ({
  id,
  name,
  defaultValue = "",
  usedColors = [],
}: {
  id: string;
  name: string;
  defaultValue?: string | "";
  usedColors: string[];
}) => {
  const availableColors = colorMenu
    .sort((a, b) => a.label.localeCompare(b.label))
    .filter((item) => !usedColors.includes(item.value));

  const defaultColor =
    colorMenu?.find(
      (item) =>
        item?.value?.trim()?.toUpperCase() ===
        defaultValue?.trim()?.toUpperCase()
    ) ||
    availableColors?.[0] ||
    colorMenu?.[0];

  const [selectedColor, setSelectedColor] = useState<ColorMenu>(defaultColor);

  return (
    <>
      <Autocomplete
        disableClearable
        autoHighlight
        fullWidth
        options={colorMenu}
        size="small"
        onChange={(event, newValue) => setSelectedColor(newValue)}
        value={selectedColor}
        renderOption={(props, option) => (
          <li {...props}>
            <Box display="flex" alignItems="center" gap={1}>
              <Brightness1Icon
                sx={{
                  color: option.value,
                  width: "1.25rem",
                  height: "1.25rem",
                }}
              />
              <Typography variant="body2" color="text.primary">
                {option.label}
              </Typography>
            </Box>
          </li>
        )}
        renderInput={(params) => (
          <TextField
            {...params}
            InputProps={{
              ...params.InputProps,
              startAdornment: (
                <Brightness1Icon
                  sx={{
                    ml: ".25rem",
                    color: selectedColor.value,
                    width: "1.15rem",
                    height: "1.15rem",
                  }}
                />
              ),
            }}
            inputProps={{
              ...params?.inputProps,
              "data-amp-track-id": id,
            }}
          />
        )}
      />
      <input
        type="hidden"
        name={name}
        value={selectedColor.value?.trim()?.toUpperCase()}
      />
    </>
  );
};

const RolesSelectInput = ({
  id,
  name,
  listData,
  defaultValue = "",
}: {
  id: string;
  name: string;
  listData: RoleMenu[];
  defaultValue?: string;
}) => {
  const [value, setSelectedColor] = useState(defaultValue || "");
  const sortedListData = [...listData].sort((a, b) =>
    a.label.localeCompare(b.label)
  );
  const getRoleInfo = (zuids: string) =>
    zuids
      ? sortedListData.filter((item) =>
          zuids.split(",").includes(item.value.trim())
        )
      : [];
  const handleChange = (_: unknown, newValue: RoleMenu[]) =>
    setSelectedColor(newValue.map((item) => item.value).join(","));

  return (
    <>
      <Autocomplete
        multiple
        fullWidth
        options={sortedListData}
        disableCloseOnSelect
        value={getRoleInfo(value)}
        onChange={handleChange}
        size="small"
        getOptionLabel={(option) => option.label}
        renderOption={(props, option, { selected }) => (
          <li {...props}>
            <Checkbox
              size="small"
              disableRipple
              icon={<CheckIcon fontSize="medium" sx={{ opacity: 0 }} />}
              checkedIcon={<CheckIcon fontSize="medium" />}
              checked={selected}
              value={option.value}
              sx={{
                marginRight: "5px",
                position: "absolute",
                left: 0,
              }}
            />
            <Typography variant="body2" sx={{ pl: 4 }}>
              {option.label}
            </Typography>
          </li>
        )}
        renderInput={(params) => (
          <TextField
            {...params}
            inputProps={{
              ...params?.inputProps,
              "data-amp-track-id": id,
            }}
            variant="outlined"
            placeholder={value ? "" : "None"}
          />
        )}
        ChipProps={{
          sx: {
            height: "1.25rem",
            backgroundColor: "transparent",
            outline: "1px solid",
            outlineColor: (theme) => theme.palette.border,
