      <input type="hidden" name={name} value={value?.trim()} />
    </>
  );
};

const validateFormData = (formData: CreateStatusLabel) => {
  const errors: Record<string, string> = {};
  if (!formData.name) errors.name = "Name is required";
  // if (!formData.description) errors.description = "Description is required";
  if (!formData.color) errors.color = "Color is required";
  return errors;
};

const StatusLabelForm: FC<StatusLabelFormProps> = ({
  open,
  onClose,
  labels = [],
  values,
  isDeactivated = false,
}) => {
  const ZUID = values?.ZUID || undefined;
  const [rolesMenuItems, setRolesMenuItems] = useState<RoleMenu[]>([]);
  const {
    isLoading: rolesLoading,
    isFetching,
    data: rolesMenuData,
  } = useGetUsersRolesQuery();

  const [formErrors, setFormErrors] = useState<Record<string, string>>({});
  const dispatch = useDispatch();
  const [createWorkflowStatusLabel, { isLoading: createLabelIsLoading }] =
    useCreateWorkflowStatusLabelMutation();
  const [updateWorkflowStatusLabel, { isLoading: editLabelIsLoading }] =
    useUpdateWorkflowStatusLabelMutation();
  const { openDeactivationDialog, setFocusedLabel } = useFormDialogContext();

  const usedColors = labels.map((label) => label.color);

  const transformRoleValues = (value: string): string[] =>
    value ? value.split(",") : [];

  const handleFormSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = Object.fromEntries(new FormData(e.currentTarget));

    const newStatusLabel: CreateStatusLabel = {
      name: formData.name as string,
      description: (formData.description as string) || "",
      color: formData.color as string,
      allowPublish: formData.allowPublish === "true",
      addPermissionRoles: transformRoleValues(
        formData.addPermissionRoles as string
      ),
      removePermissionRoles: transformRoleValues(
        formData.removePermissionRoles as string
      ),
    };

    const errors = validateFormData(newStatusLabel);
    if (Object.keys(errors).length > 0) {
      setFormErrors(errors);
      return;
    } else {
      setFormErrors({});
    }

    try {
      const response: any = ZUID
        ? await updateWorkflowStatusLabel({ ZUID, payload: newStatusLabel })
        : await createWorkflowStatusLabel(newStatusLabel);

      if (response?.error) {
        throw new Error(response.error.data?.error || "An error occurred.");
      }

      setFocusedLabel(response?.data?.ZUID);
    } catch (error) {
      dispatch(
        notify({
          kind: "error",
          message: `Error: ${
            error instanceof Error
              ? error.message
              : "An unexpected error occurred."
          }`,
        })
      );
    } finally {
      onClose();
    }
  };
  const handleDeactivation = () =>
    openDeactivationDialog({
      ZUID,
      name: values?.name,
      callBack: onClose,
    });

  useEffect(() => {
    if (!open) {
      setFormErrors({});
    }

    if (rolesLoading || isFetching) return;
    const roles =
      rolesMenuData?.map((item) => ({
        label: item?.role?.name as string,
        value: item?.role?.ZUID,
      })) || [];

    const uniqueRoles = Array.from(
      new Map(roles.map((role) => [role.value, role])).values()
    );
    setRolesMenuItems(uniqueRoles);
  }, [rolesLoading, isFetching, rolesMenuData, open]);

  return (
    <Dialog
      open={open}
      fullWidth
      maxWidth="sm"
      PaperProps={{
        component: "form",
        onSubmit: handleFormSubmit,
        sx: { borderRadius: 1 },
      }}
    >
      <DialogTitle>
        <Box display="flex" alignItems="center" gap={1}>
          {!!ZUID && (
            <Brightness1Icon
              sx={{ color: values?.color, width: "1.25rem", height: "1.25rem" }}
            />
          )}
          <Typography variant="h5" fontWeight={700} flexGrow={1}>
            {values?.name ? `Edit ${values.name}` : "Create Status"}
          </Typography>
          <IconButton size="small" onClick={onClose}>
            <CloseRoundedIcon fontSize="small" />
          </IconButton>
        </Box>
      </DialogTitle>
      <DialogContent
        sx={{ p: 0, backgroundColor: "grey.50" }}
        data-cy="status-label-form"
      >
        <Box display="flex" flexDirection="column" gap={3} p={2.5}>
          <FormInputFieldWrapper label="Name" error={formErrors?.name}>
            <OutlinedInput
              name="name"
              defaultValue={values?.name || ""}
              placeholder="e.g. Needs Content Review"
              size="small"
              inputProps={{
                "data-amp-track-id": "workflows-create-status-label-name-input",
              }}
            />
          </FormInputFieldWrapper>
          <FormInputFieldWrapper
            label="Description (optional)"
            description="Describe what this status means in the context of your workflows"
          >
            <OutlinedInput
              name="description"
              defaultValue={values?.description || ""}
              multiline
              minRows={2}
              maxRows={2}
              placeholder="Ready for legal team to review for publishing"
              size="small"
              inputProps={{
                "data-amp-track-id":
                  "workflows-create-status-label-description-input",
              }}
            />
          </FormInputFieldWrapper>
          <FormInputFieldWrapper label="Color" error={formErrors?.color}>
            <ColorSelectInput
              id="workflows-create-status-label-color-select"
              name="color"
              defaultValue={values?.color}
              usedColors={usedColors}
            />
          </FormInputFieldWrapper>
          <FormInputFieldWrapper
            label="Which roles can add this status?"
            description="Users who can add this status will be notified."
          >
            <RolesSelectInput
              id="workflows-create-status-label-addPermissionRoles-select"
              name="addPermissionRoles"
              listData={rolesMenuItems}
              defaultValue={values?.addPermissionRoles?.join(",")}
            />
          </FormInputFieldWrapper>
          <FormInputFieldWrapper
            label="Which roles can remove this status?"
            description="Users who can remove this status will be notified."
          >
            <RolesSelectInput
              id="workflows-create-status-label-removePermissionRoles-select"
              name="removePermissionRoles"
              listData={rolesMenuItems}
              defaultValue={values?.removePermissionRoles?.join(",")}
            />
          </FormInputFieldWrapper>
          <FormControlLabel
            sx={{ display: "flex", alignItems: "start" }}
            control={
              <Checkbox
                data-amp-track-id="workflows-create-status-label-allowPublish-toggle"
                name="allowPublish"
                defaultChecked={values?.allowPublish}
                disableRipple
                color="default"
                onChange={(
                  e: React.ChangeEvent<HTMLInputElement>,
                  checked: boolean
                ) => {
                  e.target.value = checked.toString();
                }}
                sx={{
                  p: 0,
                  ml: 1,
                  color: "action.active",
                  "&.Mui-checked": {
                    color: "primary.main",
                  },
                }}
                slotProps={{
                  input: {
                    "data-amp-track-id":
                      "workflows-create-status-label-allowPublish-toggle",
                  } as SlotProps<
                    "input",
                    CheckboxInputSlotPropsOverrides,
                    CheckboxOwnerState
                  >,
                }}
              />
            }
            label={
              <Box pl={1}>
                <Typography
                  variant="body2"
                  color="text.primary"
                  fontWeight={600}
                >
                  Publishing content items requires this status to be applied.
                </Typography>
                <Typography
                  variant="body2"
                  color="text.secondary"
                  fontWeight={400}
                >
                  This is a global setting and means content items cannot be
                  published unless this status has been applied.
                </Typography>
              </Box>
            }
          />
          {!!ZUID && !isDeactivated && (
            <Box>
              <Button
                data-amp-track-id="workflows-create-status-label-deactivate-button"
                variant="outlined"
                color="inherit"
                onClick={handleDeactivation}
                startIcon={<PauseCircleOutlineRoundedIcon />}
                data-cy="form-deactivate-status-button"
              >
                Deactivate Status
              </Button>
            </Box>
          )}
        </Box>
      </DialogContent>
      <DialogActions sx={{ pt: 2 }}>
        <Button
          data-amp-track-id="workflows-create-status-label-cancel-button"
          onClick={onClose}
          variant="outlined"
          color="inherit"
        >
          Cancel
        </Button>
        <Button
          data-amp-track-id="workflows-create-status-label-submit-button"
          data-cy="status-label-submit-button"
          type="submit"
          variant="contained"
          color="primary"
          loading={createLabelIsLoading || editLabelIsLoading}
          startIcon={<SaveIcon />}
        >
          {ZUID ? "Save" : "Create Status"}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default StatusLabelForm;

import { createContext, useContext, useState, useCallback } from "react";
import {
  StatusLabel,
  StatusLabelQuery,
} from "../../../../../../../../../shell/services/types";

import DeactivationDialog from "./DeactivationDialog";
import StatusLabelForm from "./StatusLabelForm";

// Types for StatusLabelForm and DeactivationDialog
export type OpenStatusLabelFormTypes = {
  labels?: StatusLabelQuery[] | [];
  values?: StatusLabel;
  isDeactivated?: boolean;
};

export type OpenDeactivationDialogTypes = {
  ZUID: string;
  name: string;
  callBack?: () => void;
};

// FormDialogContext Types
export type FormDialogContextTypes = {
  openStatusLabelForm: ({
    values,
    labels,
    isDeactivated,
  }: OpenStatusLabelFormTypes) => void;
  closeStatusLabelForm: () => void;
  openDeactivationDialog: ({
    ZUID,
    name,
    callBack,
  }: OpenDeactivationDialogTypes) => void;
  closeDeactivationDialog: () => void;
  focusedLabel: string | undefined;
  setFocusedLabel: (id: string | undefined) => void;
};

const FormDialogContext = createContext<FormDialogContextTypes | null>(null);

const FormDialogContextProvider = ({
  children,
}: {
  children: React.ReactNode;
}) => {
  const [focusedLabel, setFocusedLabel] = useState<string | undefined>(
    undefined
  );

  // Form dialog states
  const [formIsOpen, setFormIsOpen] = useState<boolean>(false);
  const [formValues, setFormValues] = useState<
    OpenStatusLabelFormTypes | undefined
  >(undefined);

  // Deactivation dialog states
  const [dialogIsOpen, setDialogIsOpen] = useState<boolean>(false);
  const [dialogProps, setDialogProps] = useState<
    OpenDeactivationDialogTypes | undefined
  >(undefined);

  // Handlers for status label form dialog
  const openStatusLabelForm = useCallback(
    ({ values, labels, isDeactivated }: OpenStatusLabelFormTypes) => {
      setFormValues({ values, labels, isDeactivated });
      setFormIsOpen(true);
    },
    []
  );

  const closeStatusLabelForm = useCallback(() => {
    setFormValues(undefined);
    setFormIsOpen(false);
  }, []);

  // Handlers for deactivation dialog
  const openDeactivationDialog = useCallback(
    ({ ZUID, name, callBack }: OpenDeactivationDialogTypes) => {
      setDialogProps({ ZUID, name, callBack });
      setDialogIsOpen(true);
    },
    []
  );

  const closeDeactivationDialog = useCallback(() => {
    setDialogProps(undefined);
    setDialogIsOpen(false);
  }, []);

  return (
    <FormDialogContext.Provider
      value={{
        openStatusLabelForm,
        closeStatusLabelForm,
        openDeactivationDialog,
        closeDeactivationDialog,
        focusedLabel,
        setFocusedLabel,
      }}
    >
      {children}
      <StatusLabelForm
        open={formIsOpen}
        onClose={closeStatusLabelForm}
        labels={formValues?.labels}
        values={formValues?.values}
        isDeactivated={formValues?.isDeactivated}
      />
      <DeactivationDialog
        open={dialogIsOpen}
        onClose={closeDeactivationDialog}
        {...dialogProps}
      />
    </FormDialogContext.Provider>
  );
};

export const useFormDialogContext = () => {
  const context = useContext(FormDialogContext);
  if (context === null) {
    throw new Error(
      "useFormDialogContext must be used within a FormDialogContextProvider"
    );
  }
  return context;
};

export default FormDialogContextProvider;

import { MouseEvent, FC, ReactElement, useState, useCallback } from "react";
import { useDrag, useDrop } from "react-dnd";
import {
  IconButton,
  Menu,
  MenuItem,
  Fade,
  Box,
  Paper,
  Collapse,
  Typography,
  Card,
  CardActions,
  CardContent,
  ListItemIcon,
  Skeleton,
  alpha,
  ClickAwayListener,
} from "@mui/material";
import Brightness1Icon from "@mui/icons-material/Brightness1";
import MoreHorizIcon from "@mui/icons-material/MoreHoriz";
import DriveFileRenameOutlineIcon from "@mui/icons-material/DriveFileRenameOutline";
import PauseCircleOutlineRoundedIcon from "@mui/icons-material/PauseCircleOutlineRounded";
import DragIndicatorRoundedIcon from "@mui/icons-material/DragIndicatorRounded";
import { useFormDialogContext } from "./forms-dialogs";
import { StatusLabel as StatusLabelTypes } from "../../../../../../../../shell/services/types";

export type StatusLabelProps = {
  id: string;
  isFiltered: boolean;
  moveCard?: (id: string, to: number) => void;
  findCard?: (id: string) => { index: number };
  isDeactivated?: boolean;
  onReorder?: () => void;
  isFocused?: boolean;
  data: StatusLabelTypes;
};

export const StatusLabel: FC<StatusLabelProps> = ({
  id,
  isFiltered,
  moveCard,
  findCard,
  isDeactivated,
  onReorder,
  isFocused,
  data,
}: StatusLabelProps) => {
  const { setFocusedLabel, openStatusLabelForm } = useFormDialogContext();

  const originalIndex = isDeactivated ? 0 : findCard?.(id)?.index;

  const [{ isDragging }, drag, preview] = useDrag(
    () => ({
      type: "draggable",
      item: { id, originalIndex },
      collect: (monitor) => ({
        isDragging: monitor.isDragging(),
      }),
      options: {
        dropEffect: "copy",
      },
      end: (item, monitor) => {
        const { id: droppedId, originalIndex } = item;
        const didDrop = monitor.didDrop();
        if (!didDrop) {
          moveCard?.(droppedId, originalIndex);
        }
      },
    }),
    [id, originalIndex, moveCard]
  );

  const [, drop] = useDrop(
    () => ({
      accept: "draggable",
      hover({ id: draggedId }: { id: string; originalIndex: number }) {
        if (draggedId !== id) {
          const { index: overIndex } = findCard?.(id);
          moveCard?.(draggedId, overIndex);
        }
      },
      drop: () => {
        onReorder?.();
      },
    }),
    [findCard, moveCard, onReorder]
  );

  const withClickAwayListener = useCallback(
    (component: ReactElement) => {
      if (isFocused) {
        return (
          <ClickAwayListener onClickAway={() => setFocusedLabel("")}>
            {component}
          </ClickAwayListener>
        );
      }
      return component;
    },
    [isFocused, setFocusedLabel]
  );

  return (
    <Collapse in={!isFiltered}>
      {withClickAwayListener(
        <Card
          data-cy="status-label"
          elevation={0}
          variant="outlined"
          ref={
            isDeactivated ? null : (node) => drop(preview(node as HTMLElement))
          }
          sx={{
            mx: 4,
            my: 1,
            height: "76px",
            display: "flex",
            flexDirection: "row",
            justifyContent: "space-between",
            alignItems: "center",
            pt: 2,
            pr: 2,
            pb: 2,
            pl: 1,
            columnGap: 1.5,
            borderRadius: 2,
            opacity: isDragging ? 0 : isDeactivated ? 0.7 : 1,
            border: "1px solid",
            borderColor: (theme) => theme.palette.border,
            backgroundColor: isFocused
              ? (theme) => alpha(theme.palette.primary.light, 0.1)
              : "background.paper",
          }}
        >
          <Box
            data-cy="status-label-drag-handle"
            component="div"
            ref={isDeactivated ? null : (node) => drag(node as HTMLElement)}
            sx={{
              cursor: isDeactivated ? "default" : "grab",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              flexGrow: 0,
            }}
          >
            <DragIndicatorRoundedIcon color="action" fontSize="small" />
          </Box>

          <Brightness1Icon sx={{ color: data?.color }} fontSize="medium" />

          <CardContent
            sx={{
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              padding: 0,
              flexGrow: 1,
            }}
          >
            <Typography
              variant="h6"
              color="text.primary"
              fontWeight={700}
              lineHeight="22px"
              data-cy="status-label-name"
            >
              {data?.name}
            </Typography>
            <Typography
              variant="subtitle2"
              color="text.secondary"
              lineHeight="20px"
              textOverflow="ellipsis"
              whiteSpace="nowrap"
              fontWeight={400}
            >
              {data?.description}
            </Typography>
          </CardContent>

          <CardActions sx={{ flexGrow: 0, padding: 0 }}>
            <MoreActionsMenu data={data} isDeactivated={isDeactivated} />
          </CardActions>
        </Card>
      )}
    </Collapse>
  );
};

const MoreActionsMenu = ({
  data,
  isDeactivated,
}: {
  data: StatusLabelTypes;
