  useGetAuditsQuery,
  useGetContentItemQuery,
  useGetContentModelQuery,
} from "../../../../shell/services/instance";
import { useSelector } from "react-redux";
import { Typography, Skeleton, Tooltip, Box } from "@mui/material";
