export const OnboardingDialog = ({ onClose }: { onClose: () => void }) => {
  const [step, setStep] = useState(0);
  return (
    <Dialog
      open
      fullWidth
      maxWidth={false}
      data-cy="onboarding-dialog"
      sx={{
        "& .MuiDialog-paper": {
          p: 6,
          width: 736,
          maxWidth: "736px",
          textAlign: "center",
          boxSizing: "border-box",
        },
      }}
    >
      <Box
        component="img"
        width={640}
        height={480}
        src={stepMapping[step].image}
      ></Box>
      <Typography variant="h5" fontWeight={700} mt={4}>
        {stepMapping[step].title}
      </Typography>
      <Typography variant="body1" color="text.secondary" mt={1}>
        {stepMapping[step].description}
      </Typography>
      <MobileStepper
        variant="dots"
        steps={stepMapping.length}
        position="static"
        activeStep={step}
        sx={{
          mt: 3,
          justifyContent: "center",
          "& .MuiMobileStepper-dots": {
            gap: 4,
            alignItems: "center",
          },
          "& .MuiMobileStepper-dot": {
