              width: 12,
              height: 12,
            },
          },
        }}
        backButton={<></>}
        nextButton={<></>}
      />
      <Box sx={{ mt: 3 }} display="flex" justifyContent="center" gap={1.5}>
        {step > 0 && (
          <Button
            variant="outlined"
            color="inherit"
            size="large"
            onClick={() => {
              setStep(step - 1);
            }}
          >
            Back
          </Button>
        )}
        <Button
          variant="contained"
          size="large"
          data-cy="onboarding-next-button"
          onClick={() => {
