// src/engine/navigator.ts
let navigateFn: (to: string, options?: { replace?: boolean }) => void;

export function registerNavigate(fn: typeof navigateFn) {
  navigateFn = fn;
}

export function getNavigate() {
  if (!navigateFn) {
    throw new Error(
      "Navigator not registered – did you forget to call registerNavigate()?"
    );
  }
  return navigateFn;
}

// src/engine/handlers.ts
import { ActionType, PayloadMap } from "./actionTypes";
import { getNavigate } from "./navigator";
import { refRegistry } from "./refRegistry";

export const handlers: Record<ActionType, (payload: any) => Promise<void>> = {
  SET_VALUE: async ({ refKey, value }: any) => {
    const h = refRegistry[refKey].handle;
    if (!h) throw new Error(`No handle for "${refKey}"`);
    h.setValue(value);
  },

  CLICK: async ({ refKey }: any) => {
    const h = refRegistry[refKey].handle;
    if (!h) throw new Error(`No handle for "${refKey}"`);
    h.click?.();
  },

  FOCUS: async ({ refKey }: any) => {
    const h = refRegistry[refKey].handle;
    if (!h) throw new Error(`No handle for "${refKey}"`);
    h.focus?.();
  },

  BLUR: async ({ refKey }: any) => {
    const h = refRegistry[refKey].handle;
    if (!h) throw new Error(`No handle for "${refKey}"`);
    h.blur?.();
  },

  NAVIGATE: async ({ path, replace = false }: PayloadMap["NAVIGATE"]) => {
    const navigate = getNavigate();
    navigate(path, { replace });
  },

  CUSTOM: async ({ refKey, event, data }: any) => {
    const h = refRegistry[refKey].handle;
    if (!h) throw new Error(`No handle for "${refKey}"`);
    h[event]?.(data);
  },
};

import { Action } from "./actionTypes";
import { handlers } from "./handlers";

const queue: Action[] = [];
let processing = false;

// how many milliseconds to wait between actions
let interActionDelayMs = 1500;
export function setInterActionDelay(ms: number) {
  interActionDelayMs = ms;
}

export function enqueueAction(action: Action) {
  queue.push(action);
  processQueue();
}

async function processQueue() {
  if (processing) return;
  processing = true;

  while (queue.length) {
    const { type, payload } = queue.shift()!;
    const fn = handlers[type];

    if (fn) {
      try {
        await fn(payload);

        if (interActionDelayMs > 0) {
          await new Promise((resolve) =>
            setTimeout(resolve, interActionDelayMs)
          );
        }
      } catch (err) {
        console.error(`Error handling action ${type}`, err);
      }
    }
  }

  processing = false;
}

